Object.assign(window.TEM8_DICTIONARY, {"interview":{"media":{"uk":"media/uk/interview__gb_1.mp3","us":"media/us/interview__us_1.mp3","img":["media/ldoce/img/interview.jpg"]},"oxford":{"phon":"ˈɪntəvjuː","pos":"noun","senses":[{"en":"a formal meeting at which somebody is asked questions to see if they are suitable for a particular job, or for a course of study at a college, university, etc.","cn":"面试；面谈","lab":"British English","ex":{"en":"a job interview","cn":"求职面试"}},{"en":"a meeting (often a public one) at which a journalist asks somebody questions in order to find out their opinions","cn":"（常指公开的）记者采访，访谈","ex":{"en":"a television/TV/radio/newspaper interview","cn":"电视／电台／报纸采访"}},{"en":"a private meeting between people when questions are asked and answered","cn":"（私下的）面谈，会谈，晤谈","ex":{"en":"a telephone/phone interview","cn":"电话会谈"}},{"en":"to talk to somebody and ask them questions at a formal meeting to find out if they are suitable for a job, course of study, etc.","cn":"对（某人）进行面试（或面谈）","g":"[transitive, intransitive]","ex":{"en":"The university interviews all potential candidates.","cn":"大学面试所有潜在的候选人。"},"pos":"verb"},{"en":"to talk to somebody and answer questions at a formal meeting to get a job, a place on a course of study, etc.","cn":"接受面试","g":"[intransitive]","ex":{"en":"The website gives you tips on interviewing for colleges.","cn":"这个网站为你提供大学面试的窍门。"},"pos":"verb"},{"en":"to ask somebody questions about their life, opinions, etc., especially on the radio or television or for a newspaper or magazine","cn":"（媒体）采访，访问","g":"[transitive]","ex":{"en":"Next week, I will be interviewing Spielberg about his latest movie.","cn":"下周我将访问斯皮尔伯格，谈论他的最新电影。"},"pos":"verb"},{"en":"to ask somebody questions at a private meeting","cn":"（私下）提问，面谈","g":"[transitive]","ex":{"en":"The police are waiting to interview the injured man.","cn":"警察正等待着向受伤的男子问话。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"面试;面谈","en":"An interview is a formal meeting at which someone is asked questions in order to find out if they are suitable for a job or a course of study.","ex":{"en":"When I went for my first interview for this job I arrived extremely early","cn":"在参加这份工作的初次面试时,我到得非常早。"}},{"pos":"VERB 动词","cn":"对…进行面试","en":"If you are interviewed for a particular job or course of study, someone asks you questions about yourself to find out if you suitable for it.","ex":{"en":"When Wardell was interviewed, he was impressive, and on that basis, he was hired","cn":"沃德尔参加面试的时候给人留下了深刻印象,所以基于这点,他被雇用了。"}},{"pos":"N-COUNT 可数名词","cn":"采访;访谈","en":"An interview is a conversation in which a journalist puts questions to someone such as a famous person or politician.","ex":{"en":"Allan gave an interview to the Chicago Tribune newspaper last month","cn":"艾伦上个月接受了《芝加哥论坛报》的采访。"}},{"pos":"VERB 动词","cn":"采访;访谈","en":"When a journalist interviews someone such as a famous person, they ask them a series of questions.","ex":{"en":"I seized the chance to interview Chris Hani about this issue.","cn":"我抓住机会就这一问题采访了克里斯·哈尼。"}},{"pos":"VERB 动词","cn":"讯问;审讯","en":"When the police interview someone, they ask them questions about a crime that has been committed.","ex":{"en":"The police interviewed the driver, but had no evidence to go on.","cn":"警方讯问了司机,但是没有获得什么有用的证据。"}}]},"examples":[{"en":"Yesterday, in an interview on German television, the minister denied the reports.","cn":"昨天，在德国电视台的采访中，部长否认了那些报道。"},{"en":"( BrE, NAmE ) If you don't interview well you are unlikely to get the job.","cn":"如果面试时表现不好，你很可能不会得到这份工作。"}]},"inhospitable":{"media":{"uk":"media/uk/inhospitable__gb_1.mp3","us":"media/us/inhospitable__us_1.mp3"},"oxford":{"phon":"ˌɪnhɒˈspɪtəbl","pos":"adjective","senses":[{"en":"difficult to stay or live in, especially because there is no shelter from the weather","cn":"不适于居住的；（尤指）无遮蔽处的，荒凉的","ex":{"en":"inhospitable terrain","cn":"荒凉地带"}},{"en":"not giving a friendly or polite welcome to guests","cn":"不殷勤待客的；不好客的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(地方等)不适合居住的","en":"An inhospitable place is unpleasant to live in.","ex":{"en":"...the earth's most inhospitable regions.","cn":"地球上最不适合居住的地区"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不好客的;不友好的","en":"If someone is inhospitable, they do not make people welcome when they visit."}]},"examples":[{"en":"an inhospitable climate","cn":"不宜人的气候"},{"en":"inhospitable terrain","cn":"荒凉地带"}]},"innately":{"oxford":{"phon":"ɪˈneɪtli","pos":"adverb","senses":[{"en":"according to a quality or ability that you are born with","cn":"天生地：根据您天生的素质或能力","ex":{"en":"He believes that humans are innately violent.","cn":"他认为人类天生就有暴力倾向。"}}]},"media":{"uk":"media/uk/innately__gb_1.mp3","us":"media/us/innately__us_1.mp3"},"examples":[{"en":"He believes that humans are innately violent.","cn":"他相信人性本恶。"},{"en":"Children have an innate ability to learn language.","cn":""}]},"in-depth":{"oxford":{"phon":"ˌɪn ˈdepθ","pos":"adjective","senses":[{"en":"very detailed, careful and complete","cn":"深入的；细致的；详尽的","ex":{"en":"an in-depth discussion/study","cn":"深入彻底的讨论／研究"}}]},"media":{"uk":"media/uk/in_depth_1_gb_1.mp3","us":"media/us/in_depth_1_us_1.mp3"},"examples":[{"en":"an in-depth discussion/study","cn":"深入彻底的讨论/研究"}]},"interaction":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a process by which two or more things affect each other","cn":"相互影响﹐相互作用"},{"en":"the activity of talking to other people, working together with them etc","cn":"交流"}]},"examples":[{"en":"Price is determined through the interaction of demand and supply.","cn":"价格是通过供需消长而定的。","src":"ld"},{"en":"the complex interaction between mind and body","cn":"身心之间复杂的相互作用","src":"ld"}],"media":{"uk":"media/uk/interaction__gb_1.mp3","us":"media/us/interaction__us_1.mp3"},"oxford":{"phon":"ˌɪntərˈækʃn","pos":"noun","senses":[{"en":"the act of communicating with somebody, especially while you work, play or spend time with them","cn":"交流；沟通；合作","ex":{"en":"the interaction between performers and their audience","cn":"表演者和观众之间的互动"}},{"en":"if one thing has an interaction with another, or if there is an interaction between two things, the two things have an effect on each other","cn":"相互影响；相互作用","ex":{"en":"the interaction of bacteria with the body’s natural chemistry","cn":"细菌和身体的自然化学成分的相互作用"}}]}},"infinitive":{"oxford":{"phon":"ɪnˈfɪnətɪv","pos":"noun","senses":[{"en":"the basic form of a verb such as be or run. In English, an infinitive is used by itself, for example swim in She can swim (this use is sometimes called the bare infinitive), or with to (the to-infinitive) as in She likes to swim.","cn":"（动词的）不定式（英语中的动词不定式可单独使用，如 She can swim 中的 swim，或带 to，如 She likes to swim）","ex":{"en":"Modal verbs generally take the bare infinitive.","cn":"情态动词通常用不带 to 的不定式。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(动词)原形,不定式(前面常加 to)","en":"The infinitive of a verb is the basic form, for example 'do', 'be', 'take', and 'eat'. The infinitive is often used with 'to' in front of it."}]},"media":{"uk":"media/uk/infinitive__gb_1.mp3","us":"media/us/infinitive__us_1.mp3"}},"intent":{"media":{"uk":"media/uk/intent__gb_1.mp3","us":"media/us/intent__us_1.mp3"},"oxford":{"phon":"ɪnˈtent","pos":"noun","senses":[{"en":"what you intend to do","cn":"意图；意向；目的","ex":{"en":"She denies possessing the drug with intent to supply.","cn":"她否认拥有毒品是为了提供给别人。"}},{"en":"showing strong interest and attention","cn":"热切的；专注的","ex":{"en":"an intent gaze/look","cn":"专注的目光／神情"},"pos":"adjective"},{"en":"determined to do something, especially something that will harm other people","cn":"决心做（尤指伤害他人的事）","lab":"formal","ex":{"en":"They were intent on murder.","cn":"他们存心谋杀。"},"pos":"adjective"},{"en":"giving all your attention to something","cn":"专心；专注","ex":{"en":"I was so intent on my work that I didn't notice the time.","cn":"我专心工作，以致忘了时间。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坚决的;下决心的","en":"If you are intent on doing something, you are eager and determined to do it.","ex":{"en":"The rebels are obviously intent on keeping up the pressure","cn":"叛乱分子显然决心继续施压。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"专心的;专注的","en":"If someone does something in an intent way, they pay great attention to what they are doing.","ex":{"en":"She looked from one intent face to another","cn":"她看着一张张专注的面孔。"}},{"pos":"N-VAR 可变名词","cn":"意图;目的","en":"A person's intent is their intention to do something.","ex":{"en":"...a strong statement of intent on arms control","cn":"决心实施军备控制的有力声明"}},{"pos":"PHRASE 短语","cn":"差不多等于;几乎在一切方面","en":"You say to all intents and purposes to suggest that a situation is not exactly as you describe it but the effect is the same as if it were.","ex":{"en":"To all intents and purposes he was my father.","cn":"他几乎可以称得上是我的父亲。"}}]},"examples":[{"en":"By 1981 the docks had, to all intents and purposes, closed.","cn":"到 1981 年，这些码头几乎等于关闭了。"},{"en":"His intent is clearly not to placate his critics.","cn":"他的目的显然不是要安抚批评他的人。"}]},"infrastructure":{"media":{"uk":"media/uk/infrastructure__gb_1.mp3","us":"media/us/infrastructure__us_1.mp3"},"oxford":{"phon":"ˈɪnfrəstrʌktʃə(r)","pos":"noun","senses":[{"en":"the basic systems and services that are necessary for a country or an organization to run smoothly, for example buildings, transport and water and power supplies","cn":"（国家或机构的）基础设施，基础建设"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(国家、社会、组织赖以行使职能的)基础建设,基础设施","en":"The infrastructure of a country, society, or organization consists of the basic facilities such as transport, communications, power supplies, and buildings, which enable it to function.","ex":{"en":"...investment in infrastructure","cn":"对基础设施的投资"}}]},"examples":[{"en":"infrastructural development","cn":"基础建设的发展"},{"en":"Some countries lack a suitable economic infrastructure.","cn":"一些国家缺乏适当的经济基础设施。"}]},"infuriatingly":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"annoying, especially because something keeps happening that makes you a little angry","cn":""},{"en":"making you very angry and impatient","cn":""}]},"examples":[{"en":"The infuriating thing is that he is always right.","cn":"","src":"ld"}],"media":{"uk":"media/uk/infuriatingly__gb_1.mp3","us":"media/us/infuriatingly__us_1.mp3"},"oxford":{"phon":"ɪnˈfjʊərieɪtɪŋli","pos":"adverb","senses":[{"en":"in a way that makes you extremely angry","cn":"使人极为生气（或愤怒）的","ex":{"en":"to smile infuriatingly","cn":"笑得使人恼火"}}]}},"innovation":{"media":{"uk":"media/uk/innovation__gb_1.mp3","us":"media/us/innovation__us_1.mp3"},"oxford":{"phon":"ˌɪnəˈveɪʃn","pos":"noun","senses":[{"en":"the introduction of new things, ideas or ways of doing something","cn":"（新事物、思想或方法的）创造；创新；改革","g":"[uncountable]","ex":{"en":"an age of technological innovation","cn":"技术革新的时代"}},{"en":"a new idea, way of doing something, etc. that has been introduced or discovered","cn":"新思想；新方法","g":"[countable]","ex":{"en":"technological innovations designed to save energy","cn":"为节约能源而设计的一些新科技"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"新事物;新方法","en":"An innovation is a new thing or a new method of doing something.","ex":{"en":"The vegetarian burger was an innovation which was rapidly exported to Britain.","cn":"素食汉堡是一种迅速传到了英国的新开发食品。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"革新;创新;改革","en":"Innovation is the introduction of new ideas, methods, or things.","ex":{"en":"We must promote originality and encourage innovation.","cn":"我们必须提倡创意,鼓励革新。"}}]},"examples":[{"en":"recent innovations in steel-making technology","cn":"新近的炼钢技术革新"},{"en":"an age of technological innovation","cn":"技术革新的时代"}]},"interpreting":{"oxford":{"phon":"ɪnˈtɜːprɪt","pos":"verb","senses":[{"en":"to explain the meaning of sth","cn":"诠释；说明"},{"en":"to decide that sth has a particular meaning and to understand it in this way","cn":"把 … 理解为；领会"}]}},"institution":{"media":{"uk":"media/uk/institution__gb_1.mp3","us":"media/us/institution__us_1.mp3"},"oxford":{"phon":"ˌɪnstɪˈtjuːʃn","pos":"noun","senses":[{"en":"a large important organization that has a particular purpose, for example a university or bank","cn":"（大学、银行等规模大的）机构","g":"[countable]","ex":{"en":"The deal is backed by one of the country's largest financial institutions.","cn":"这笔交易得到了该国最大的一家金融机构的支持。"}},{"en":"a hospital, prison or other building where people are made to stay and are cared for","cn":"慈善机构；社会福利机构","g":"[countable]","lab":"usually disapproving","ex":{"en":"They had him committed to an institution.","cn":"他们把他委托给一个机构。"}},{"en":"a custom or system that has existed for a long time among a particular group of people","cn":"（由来已久的）风俗习惯，制度","g":"[countable]","ex":{"en":"He claimed this threatened ‘the sacred institution of marriage’.","cn":"他声称此举威胁了“神圣的婚姻传统”。"}},{"en":"the act of starting or introducing something such as a system or a law","cn":"建立；设立；制定","g":"[uncountable]","ex":{"en":"the institution of new safety procedures","cn":"新安全规程的制定"}},{"en":"a person who is well known because they have been in a particular place or job for a long time","cn":"（某地或某工作领域）出名的人","g":"[countable]","lab":"informal, humorous，，","ex":{"en":"You must know him—he's an institution around here!","cn":"你一定认识他，他是这一带的知名人物！"}}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"(大学、教会、银行等)(大型)机构","en":"An institution is a large important organization such as a university, church, or bank.","ex":{"en":"...the Institution of Civil Engineers","cn":"土木工程学院"}},{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"(精神病院、孤儿院等)社会收容机构","en":"An institution is a building where certain people are looked after, for example people who are mentally ill or children who have no parents.","ex":{"en":"He was transferred to Shoal Creek Mental Institution for an indefinite period","cn":"他被转到了肖尔溪精神病院，要在那里无限期地呆下去。"}},{"pos":"N-COUNT 可数名词","cn":"习俗;制度","en":"An institution is a custom or system that is considered an important or typical feature of a particular society or group, usually because it has existed for a long time.","ex":{"en":"I believe in the institution of marriage.","cn":"我相信婚姻制度。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"建立;设立;制定","en":"The institution of a new system is the act of starting it or bringing it in.","ex":{"en":"There was never an official institution of censorship in Albania.","cn":"在阿尔巴尼亚从未设立过官方审查制度。"}}]},"examples":[{"en":"You must know him — he's an institution around here!","cn":"你一定认识他，他是这一带的知名人物！"},{"en":"We want this to be like a home, not an institution.","cn":"我们希望这里像个家，而不像收容所。"}]},"instruction":{"media":{"uk":"media/uk/instruction__gb_1.mp3","us":"media/us/instruction__us_1.mp3"},"oxford":{"phon":"ɪnˈstrʌkʃn","pos":"noun","senses":[{"en":"detailed information on how to do or use something","cn":"用法说明；操作指南","g":"[plural]","ex":{"en":"Follow the instructions on the packet carefully.","cn":"仔细按照包装上的说明操作。"}},{"en":"something that somebody tells you to do","cn":"指示；命令；吩咐","g":"[countable, usually plural]","ex":{"en":"Climbers should always follow the instructions of their guide.","cn":"登山者无论何时都应遵循向导的指示。"}},{"en":"a piece of information that tells a computer to perform a particular operation","cn":"（计算机的）指令","g":"[countable]","ex":{"en":"The chip runs at speeds of up to 100MHz and executes two instructions per clock cycle.","cn":"芯片以100 兆赫的速度运行，每个脉冲周期可以执行两条指令。"}},{"en":"the act of teaching something to somebody","cn":"教授；教导；传授","g":"[uncountable]","lab":"formal","ex":{"en":"Religious instruction is banned in all state schools in the country.","cn":"该国禁止所有公立学校传授宗教教义。"}},{"en":"giving detailed information on how to do or use something (= giving instructions)","cn":"说明用法的；操作指南的","ex":{"en":"an instruction manual","cn":"用法说明"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"指示;命令","en":"An instruction is something that someone tells you to do.","ex":{"en":"Two lawyers were told not to leave the building but no reason for this instruction was given.","cn":"两名律师被告知不得离开大楼,但对这一命令并没有提供任何理由。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"教学;讲授","en":"If someone gives you instruction in a subject or skill, they teach it to you.","ex":{"en":"Each candidate is given instruction in safety","cn":"向每位申请人都讲授了安全知识。"}},{"pos":"N-PLURAL 复数名词","cn":"用法说明;操作指南","en":"Instructions are clear and detailed information on how to do something.","ex":{"en":"Always read the instructions before you start taking the medicine.","cn":"在服药之前一定要先阅读说明书。"}}]},"examples":[{"en":"The plant comes with full instructions on how to care for it.","cn":"这棵植物附有详尽的护养说明。"},{"en":"Follow the instructions on the packet carefully.","cn":"仔细按照包装上的说明操作。"}]},"innate":{"media":{"uk":"media/uk/innate__gb_1.mp3","us":"media/us/innate__us_1.mp3"},"oxford":{"phon":"ɪˈneɪt","pos":"adjective","senses":[{"en":"that you have when you are born","cn":"天生的；先天的；与生俱来的","ex":{"en":"the innate ability to learn","cn":"天生的学习能力"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"天生的;天然的;固有的","en":"An innate quality or ability is one which a person is born with.","ex":{"en":"Americans have an innate sense of fairness.","cn":"美国人有一种天生的公平观。"}}]},"examples":[{"en":"He believes that humans are innately violent.","cn":"他相信人性本恶。"},{"en":"the innate ability to learn","cn":"天生的学习能力"}]},"inject":{"oxford":{"phon":"ɪnˈdʒekt","pos":"verb","senses":[{"en":"to put a drug or other substance into a person’s or an animal’s body using a syringe","cn":"（给…）注射（药物等）","g":"[transitive, intransitive]","ex":{"en":"Adrenaline was injected into the muscle.","cn":"往肌肉里注射了肾上腺素。"}},{"en":"to put a liquid or other substance into something using a syringe or similar instrument","cn":"（给…）注射（液体）","g":"[transitive]","ex":{"en":"The fruit is injected with chemicals to reduce decay.","cn":"水果注入了化学药品以防腐坏。"}},{"en":"to add a particular quality to something","cn":"（给…）添加，增加（某品质）","g":"[transitive]","ex":{"en":"His comments injected a note of humour into the proceedings.","cn":"他的发言给整个活动增添了一丝幽默的气氛。"}},{"en":"to give money to an organization, a project, etc. so that it can function","cn":"（给…）投入（资金）","g":"[transitive]","ex":{"en":"They are refusing to inject any more capital into the industry.","cn":"他们拒绝对这一产业投入更多的资金。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"给…注射","en":"To inject someone with a substance such as a medicine means to put it into their body using a device with a needle called a syringe.","ex":{"en":"His son was injected with strong drugs","cn":"他儿子被注射了烈性麻醉药。"}},{"pos":"VERB 动词","cn":"添加,注入(某种特性)","en":"If you inject a new, exciting, or interesting quality into a situation, you add it.","ex":{"en":"She kept trying to inject a little fun into their relationship","cn":"她一直在设法为他们的关系增添一些情趣。"}},{"pos":"VERB 动词","cn":"投入(金钱或资源)","en":"If you inject money or resources into a business or organization, you provide more money or resources for it.","ex":{"en":"He has injected £5.6 billion into the health service.","cn":"他已经为公共医疗卫生服务投入了 56 亿英镑。"}}]},"media":{"uk":"media/uk/inject__gb_1.mp3","us":"media/us/inject__us_1.mp3"},"examples":[{"en":"His comments injected a note of humour into the proceedings.","cn":"他的发言给整个活动增添了一丝幽默的气氛。"},{"en":"She has been injecting herself with insulin since the age of 16.","cn":"她从 16 岁起就开始自行注射胰岛素。"}]},"insuperable":{"oxford":{"phon":"ɪnˈsuːpərəbl","pos":"adjective","senses":[{"en":"that cannot be dealt with successfully","cn":"无法克服的；难以解决的；不可逾越的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不能克服的;无法逾越的","en":"A problem that is insuperable cannot be dealt with successfully.","ex":{"en":"...an insuperable obstacle to negotiations.","cn":"谈判过程中难以克服的障碍"}}]},"media":{"uk":"media/uk/insuperable__gb_1.mp3","us":"media/us/insuperable__us_1.mp3"},"examples":[{"en":"There were insuperable obstacles , and the plan was abandoned.","cn":"由于存在无法克服的障碍﹐计划被放弃了。"},{"en":"As usual, the hero was facing insuperable odds .","cn":"照例﹐男主角遇到了无法克服的困难。"}]},"indifferent":{"media":{"uk":"media/uk/indifferent__gb_1.mp3","us":"media/us/indifferent__us_1.mp3"},"oxford":{"phon":"ɪnˈdɪfrənt","pos":"adjective","senses":[{"en":"having or showing no interest in somebody/something","cn":"漠不关心；不感兴趣","g":"[not usually before noun]","ex":{"en":"The government cannot afford to be indifferent to public opinion.","cn":"政府不可不关注舆论。"}},{"en":"not very good","cn":"不好的；差的","ex":{"en":"an indifferent meal","cn":"一般的饭食"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不感兴趣的;不关心的;冷淡的","en":"If you accuse someone of being indifferent to something, you mean that they have a complete lack of interest in it.","ex":{"en":"People have become indifferent to the suffering of others.","cn":"人们对别人的痛苦已经变得无动于衷。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(水平或质量)一般的,平庸的，差的","en":"If you describe something or someone as indifferent, you mean that their standard or quality is not very good, and often quite bad.","ex":{"en":"She had starred in several very indifferent movies","cn":"她主演过几部表现非常一般的电影。"}}]},"examples":[{"en":"The festival has the usual mixture of movies — good, bad and indifferent.","cn":"电影节的影片一如既往的良莠不齐，有优秀的、低劣的和一般的。"},{"en":"He shrugged indifferently.","cn":"他满不在乎地耸了耸肩。"}]},"injure":{"oxford":{"phon":"ˈɪndʒə(r)","pos":"verb","senses":[{"en":"to harm yourself or somebody else physically, especially in an accident","cn":"（尤指在事故中）伤害，使受伤","lab":"especially British English","ex":{"en":"He injured his knee playing hockey.","cn":"他打曲棍球时弄伤了膝盖。"}},{"en":"to damage somebody’s reputation, interests, feelings, etc.","cn":"损害，伤害（名誉、利益、感情等）","ex":{"en":"This could seriously injure the company's reputation.","cn":"这会严重损害公司的声誉。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"伤害;使受伤","en":"If you injure a person or animal, you damage some part of their body.","ex":{"en":"A number of bombs have exploded, seriously injuring at least five people","cn":"数个炸弹爆炸,造成至少5人重伤。"}}]},"media":{"uk":"media/uk/injure__gb_1.mp3","us":"media/us/injure__us_1.mp3"},"examples":[{"en":"Don't strain your eyes by reading in poor light.","cn":"别在光线不足的地方看书把眼睛给伤了。"},{"en":"Three people were killed and five injured in the crash.","cn":"撞车事故中有三人死亡，五人受伤。"}]},"insistent":{"media":{"uk":"media/uk/insistent__gb_1.mp3","us":"media/us/insistent__us_1.mp3"},"oxford":{"phon":"ɪnˈsɪstənt","pos":"adjective","senses":[{"en":"demanding something and refusing to accept any opposition or excuses","cn":"坚决要求的；坚持的；固执的","ex":{"en":"She didn't want to go but her brother was insistent.","cn":"她不想去，但她哥哥非得要她去。"}},{"en":"continuing for a long period of time in a way that cannot be ignored","cn":"持续不断的；再三的；反复的","ex":{"en":"insistent demands","cn":"再三的要求"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坚持的;坚决要求的","en":"Someone who is insistent keeps insisting that a particular thing should be done or is the case.","ex":{"en":"The men are very insistent that you leave right away.","cn":"他们坚决要求你立即离开。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(噪音、节奏等)持续的,经久不息的","en":"An insistent noise or rhythm keeps going on for a long time and holds your attention.","ex":{"en":"...the insistent rhythms of the Caribbean and Latin America.","cn":"加勒比海与拉丁美洲经久不息的韵律节拍"}}]},"examples":[{"en":"They were insistent on having a contract for the work.","cn":"他们坚持要就这项工作立一份合同。"},{"en":"She didn't want to go but her brother was insistent.","cn":"她不想去，但她哥哥非得要她去。"}]},"infest":{"media":{"uk":"media/uk/infest__gb_1.mp3","us":"media/us/infest__us_1.mp3"},"oxford":{"phon":"ɪnˈfest","pos":"verb","senses":[{"en":"to exist in large numbers in a particular place, often causing damage or disease","cn":"大量滋生；大批出没于","ex":{"en":"The kitchen was infested with ants.","cn":"厨房里蚂蚁成灾。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(昆虫、老鼠等)大批出没于,侵扰","en":"When creatures such as insects or rats infest plants or a place, they are present in large numbers and cause damage.","ex":{"en":"...pests like aphids which infest cereal crops.","cn":"像蚜虫这样大肆侵害谷物的害虫"}},{"pos":"VERB 动词","cn":"遍布于;充斥","en":"If you say that people or things you disapprove of or regard as dangerous are infesting a place, you mean that there are large numbers of them in that place.","ex":{"en":"Crime and drugs are infesting the inner cities.","cn":"市中心充斥着犯罪与毒品。"}}]},"examples":[{"en":"The kitchen was infested with ants.","cn":"厨房里到处是蚂蚁。"},{"en":"shark-infested waters","cn":"鲨鱼成群的水域"}]},"injuring":{"oxford":{"phon":"ˈɪndʒə(r)","pos":"verb","senses":[{"en":"to harm yourself or sb else physically, especially in an accident （","cn":"尤指在事故中）伤害，使受伤"},{"en":"to damage sb's reputation, pride, etc.","cn":"损害，伤害（名誉、自尊等）"}]}},"intervention":{"media":{"uk":"media/uk/intervention__gb_1.mp3","us":"media/us/intervention__us_1.mp3"},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"干涉;干预","en":"Intervention is the act of intervening in a situation.","ex":{"en":"...the role of the United States and its intervention in the internal affairs of many countries.","cn":"美国扮演的角色以及其对多国内政的干涉"}}]},"examples":[{"en":"calls for government intervention to save the steel industry","cn":"呼吁政府出面挽救钢铁业"},{"en":"armed/military intervention","cn":"武装/军事干涉"}],"oxford":{"phon":"ˌɪntəˈvenʃn","pos":"noun","senses":[{"en":"action taken to improve or help a situation","cn":"出面；介入","ex":{"en":"calls for government intervention to save the steel industry","cn":"呼吁政府出面挽救钢铁业"}},{"en":"action by a country to become involved in the affairs of another country when they have not been asked to do so","cn":"（对他国事务的）介入，干预，干涉行为","lab":"US English","ex":{"en":"armed/military intervention","cn":"武装／军事干涉"}},{"en":"action taken to improve a medical condition or illness","cn":"介入治疗；医疗干预","ex":{"en":"a medical/surgical intervention","cn":"医疗／手术干预"}},{"en":"the act of interrupting somebody when they are speaking in order to say something","cn":"插嘴；打断（别人的话）","ex":{"en":"People resented his repeated interventions in the debate.","cn":"人们讨厌他一再干涉辩论。"}},{"en":"an occasion when a group of people meet to take action with a friend or family member who has an addiction to drugs or alcohol, in order to help them recover","cn":"（对有毒瘾或酒瘾的朋友或家人的）帮助戒毒，帮助戒酒","ex":{"en":"Her daughters staged an intervention.","cn":"她的女儿们介入帮她戒瘾。"}}]}},"infrequently":{"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"not often","cn":"不经常发生地﹐罕见地"},{"en":"fairly often","cn":"经常地"}]},"examples":[{"en":"Jeremy does play cricket, but very infrequently.","cn":"杰里米确实玩板球﹐但次数很少。","src":"ld"},{"en":"The censors changed some names and dialogue and, not infrequently, banned controversial films.","cn":"审查官对电影里的一些名字和对话进行修改﹐并常常禁止有争议的电影发行。","src":"ld"}],"media":{"uk":"media/uk/infrequently__gb_1.mp3","us":"media/us/infrequently__us_1.mp3"},"oxford":{"phon":"ɪnˈfriːkwəntli","pos":"adverb","senses":[{"en":"not very often","cn":"罕有；很少；不常","ex":{"en":"This happens not infrequently (= often).","cn":"这种事常常发生。"}}]}},"interacts":{"oxford":{"phon":"ˌɪntərˈækt","pos":"verb","senses":[{"en":"to communicate with sb, especially while you work, play or spend time with them","cn":"交流；沟通；合作"},{"en":"if one thing interacts with another, or if two things interact , the two things have an effect on each other","cn":"相互影响；相互作用"}]}},"invaluable":{"media":{"uk":"media/uk/invaluable__gb_1.mp3","us":"media/us/invaluable__us_1.mp3"},"oxford":{"phon":"ɪnˈvæljuəbl","pos":"adjective","senses":[{"en":"extremely useful","cn":"极有用的；极宝贵的","ex":{"en":"invaluable information","cn":"宝贵的信息"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"非常宝贵的;极为有用的","en":"If you describe something as invaluable, you mean that it is extremely useful.","ex":{"en":"I was able to gain invaluable experience over that year","cn":"在那一年里我有幸获得了非常宝贵的经验。"}}]},"examples":[{"en":"The research should prove invaluable in the study of children's language.","cn":"这项调查对于儿童语言的研究应极有价值。"},{"en":"The book will be invaluable for students in higher education.","cn":"这本书对于高校学生将有重大价值。"}]},"indefinite":{"oxford":{"phon":"ɪnˈdefɪnət","pos":"adjective","senses":[{"en":"lasting for a period of time that has no fixed end","cn":"无限期的；期限不定的","ex":{"en":"She will be away for the indefinite future.","cn":"她将离开一段时间，期限不定。"}},{"en":"not clearly defined","cn":"模糊不清的；不明确的","ex":{"en":"an indefinite science","cn":"界定不明的科学"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"期限不定的;无限期的","en":"If you describe a situation or period as indefinite, you mean that people have not decided when it will end.","ex":{"en":"The trial was adjourned for an indefinite period.","cn":"审判被无限期推迟。"}},{"pos":"ADJ 形容词","cn":"不明确的;不清楚的","en":"Something that is indefinite is not exact or clear.","ex":{"en":"...at some indefinite time in the future.","cn":"在未来的某个时间"}}]},"media":{"uk":"media/uk/indefinite__gb_1.mp3","us":"media/us/indefinite__us_1.mp3"},"examples":[{"en":"She will be away for the indefinite future.","cn":"她将离开一段时间，期限不定。"},{"en":"an indefinite science","cn":"界定不明的科学"}]},"include":{"media":{"uk":"media/uk/include__gb_1.mp3","us":"media/us/include__us_1.mp3"},"oxford":{"phon":"ɪnˈkluːd","pos":"verb","senses":[{"en":"if one thing includes another, it has the second thing as one of its parts","cn":"包括；包含","ex":{"en":"The tour included a visit to the Science Museum.","cn":"这次游览包括参观科学博物馆。"}},{"en":"to make somebody/something part of something","cn":"使成为…的一部分","ex":{"en":"You should include some examples in your essay.","cn":"你应该在文章里举一些例子。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"包括;包含","en":"If one thing includes another thing, it has the other thing as one of its parts.","ex":{"en":"A good British breakfast always includes sausages","cn":"一顿丰盛的英式早餐总会包括香肠。"}},{"pos":"VERB 动词","cn":"把…列为…的一部分;把…算入","en":"If someone or something is included in a large group, system, or area, they become a part of it or are considered a part of it.","ex":{"en":"I had worked hard to be included in a project like this","cn":"为参与这样的项目,我过去一直努力工作。"}}]},"examples":[{"en":"Representatives from the country were included as observers at the conference.","cn":"这个国家的代表都被列为会议的观察员。"},{"en":"The tour included a visit to the Science Museum.","cn":"这次游览包括参观科学博物馆。"}]},"inclined":{"media":{"uk":"media/uk/inclined__gb_1.mp3","us":"media/us/inclined__us_1.mp3"},"oxford":{"phon":"ɪnˈklaɪnd","pos":"adjective","senses":[{"en":"wanting to do something","cn":"想（做某事）","g":"[not before noun]","ex":{"en":"She was inclined to trust him.","cn":"她愿意相信他。"}},{"en":"tending to do something; likely to do something","cn":"有…倾向；很可能","ex":{"en":"He's inclined to be lazy.","cn":"他喜欢偷懒。"}},{"en":"used when you are expressing an opinion but do not want to express it very strongly","cn":"（温和地表达意见）倾向于同意（或相信、认为等）","ex":{"en":"I'm inclined to agree with you.","cn":"我倾向于同意你的观点。"}},{"en":"having a natural ability for something; preferring to do something","cn":"有（某种）天赋的；宁愿（做某事）的","ex":{"en":"musically/academically inclined children","cn":"有音乐天赋的／喜欢读书的儿童"}},{"en":"sloping; at an angle","cn":"倾斜的；成某角度的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"愿意…的;有…意向的","en":"If you are inclined to behave in a particular way, you often behave in that way, or you want to do so.","ex":{"en":"Nobody felt inclined to argue with Smith","cn":"没人愿意与史密斯争辩。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"倾向于…的;赞成…的","en":"If you say that you are inclined to have a particular opinion, you mean that you hold this opinion but you are not expressing it strongly.","ex":{"en":"I am inclined to think that the ancient Greeks understood this better than we do","cn":"我倾向于认为古希腊人对此比我们了解的更多。"}},{"pos":"ADJ 形容词","cn":"有…天分的;有…天赋的","en":"Someone who is mathematically inclined or artistically inclined, for example, has a natural talent for mathematics or art.","ex":{"en":"Bratby's grandfather had been artistically inclined.","cn":"布拉特比的祖父很有艺术天分。"}}]},"examples":[{"en":"They'll be more inclined to listen if you don't shout.","cn":"你要是不大声嚷叫，他们会更愿意倾听。"},{"en":"There'll be time for a swim if you feel so inclined.","cn":"你要是想游泳的话，还有时间呢。"}]},"initiate":{"oxford":{"phon":"ɪˈnɪʃieɪt","pos":"verb","senses":[{"en":"to make something begin","cn":"开始；发起；创始","lab":"formal","ex":{"en":"to initiate legal proceedings against somebody","cn":"对某人提起诉讼"}},{"en":"to explain something to somebody and/or make them experience it for the first time","cn":"使了解；传授；教…开始尝试","ex":{"en":"Many of them had been initiated into drug use at an early age.","cn":"他们中有很多人在早年就被教会了吸毒。"}},{"en":"to make somebody a member of a particular group, especially as part of a secret ceremony","cn":"（尤指在秘密仪式上）使加入，接纳，吸收","ex":{"en":"Hundreds are initiated into the sect each year.","cn":"每年有好几百人被接纳到这个教派中。"}},{"en":"a person who has been allowed to join a particular group, organization, or religion and is learning its rules and secrets","cn":"新加入某组织（或机构、宗教）的人；新入会的人","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"开始;创始;发起","en":"If you initiate something, you start it or cause it to happen.","ex":{"en":"They wanted to initiate a discussion on economics","cn":"他们想启动一次经济学讨论。"}},{"pos":"VERB 动词","cn":"使初步了解;向…传授基本技巧(或基础知识)","en":"If you initiate someone into something, you introduce them to a particular skill or type of knowledge and teach them about it.","ex":{"en":"He initiated her into the study of other cultures.","cn":"他将她领进了研究其他文化的大门。"}},{"pos":"VERB 动词","cn":"(通过仪式)接纳，使加入","en":"If someone is initiated into something such as a religion, secret society, or social group, they become a member of it by taking part in ceremonies at which they learn its special knowledge or customs.","ex":{"en":"In many societies, young people are formally initiated into their adult roles.","cn":"在很多社会里,年轻人经过正式仪式才算成年。"}},{"pos":"N-COUNT 可数名词","cn":"有初步知识的成员;新入会的人","en":"An initiate is a person who has been accepted as a member by a particular group or club and been taught its secrets and skills.","ex":{"en":"Chen was an initiate of a Chinese spiritual discipline.","cn":"陈是某个中国神学领域的新入门者。"}}]},"media":{"uk":"media/uk/initiate__gb_1.mp3","us":"media/us/initiate__us_1.mp3"},"examples":[{"en":"Many of them had been initiated into drug use at an early age.","cn":"他们中有很多人在早年就被教会了吸毒。"},{"en":"Hundreds are initiated into the sect each year.","cn":"每年有好几百人被接纳到这个教派中。"}]},"instantly":{"media":{"uk":"media/uk/instantly__gb_1.mp3","us":"media/us/instantly__us_1.mp3"},"oxford":{"phon":"ˈɪnstəntli","pos":"adverb","senses":[{"en":"immediately","cn":"立刻；立即；马上","ex":{"en":"Her voice is instantly recognizable.","cn":"她的声音一下子就听出来了。"}}]},"examples":[{"en":"Her voice is instantly recognizable.","cn":"她的声音一下子就听出来了。"},{"en":"The driver was killed instantly.","cn":"司机当场死亡。"}]},"intractable":{"media":{"uk":"media/uk/intractable__gb_1.mp3","us":"media/us/intractable__us_1.mp3"},"oxford":{"phon":"ɪnˈtræktəbl","pos":"adjective","senses":[{"en":"very difficult to deal with","cn":"很难对付（或处理）的","ex":{"en":"Unemployment was proving to be an intractable problem.","cn":"失业证明是个棘手的问题。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难驾驭的;难对付的","en":"Intractable people are very difficult to control or influence.","ex":{"en":"What may be done to reduce the influence of intractable opponents?","cn":"能做些什么来减少那些难缠的反对者的影响呢？"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(问题或情况)棘手的,难处理的","en":"Intractable problems or situations are very difficult to deal with.","ex":{"en":"The economy still faces intractable problems.","cn":"经济仍然面临着一些棘手的问题。"}}]},"examples":[{"en":"the seemingly intractable problem of human greed","cn":"似乎难以解决的人性贪婪问题"}]},"inviting":{"media":{"uk":"media/uk/inviting__gb_1.mp3","us":"media/us/inviting__us_1.mp3"},"oxford":{"phon":"ɪnˈvaɪtɪŋ","pos":"adjective","senses":[{"en":"making you want to do, try, taste, etc. something","cn":"诱人的；吸引人的","ex":{"en":"an inviting smell","cn":"诱人的气味"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"吸引人的;诱人的","en":"If you say that something is inviting, you mean that it has good qualities that attract you or make you want to experience it.","ex":{"en":"The February air was soft, cool, and inviting","cn":"二月的空气柔和、凉爽而怡人。"}}]},"examples":[{"en":"The water looks really inviting.","cn":"水面看上去真诱人。"},{"en":"an inviting smell","cn":"诱人的气味"}]},"infer":{"media":{"uk":"media/uk/infer__gb_1.mp3","us":"media/us/infer__us_1.mp3"},"oxford":{"phon":"ɪnˈfɜː(r)","pos":"verb","senses":[{"en":"to reach an opinion or decide that something is true on the basis of information that is available","cn":"推断；推论；推理","ex":{"en":"Much of the meaning must be inferred from the context.","cn":"大部分含义必须从上下文中推断。"}},{"en":"to suggest indirectly that something is true","cn":"间接地提出；暗示；意指","lab":"non-standard","ex":{"en":"Are you inferring (that) I’m not capable of doing the job?","cn":"你的言外之意是不是我不能胜任这份工作？"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"推断;推定","en":"If you infer that something is the case, you decide that it is true on the basis of information that you already have.","ex":{"en":"I inferred from what she said that you have not been well","cn":"我从她的话语里推断你身体一直不太好。"}},{"pos":"VERB 动词","cn":"暗示,暗指,意味着(许多人认为此用法不正确)","en":"Some people use infer to mean 'imply', but many people consider this use to be incorrect.","ex":{"en":"The police inferred that they found her behaviour rather suspicious.","cn":"警方暗示他们发现她行为非常可疑。"}}]},"examples":[{"en":"Are you inferring (that) I'm not capable of doing the job?","cn":"你的言外之意是不是我不能胜任这份工作？"},{"en":"I inferred from the article that the pilot was responsible for the accident.","cn":"我从这篇文章推断，飞行员应对事故负责。"}]},"introduce":{"media":{"uk":"media/uk/introduce__gb_1.mp3","us":"media/us/introduce__us_1.mp3"},"oxford":{"phon":"ˌɪntrəˈdjuːs","pos":"verb","senses":[{"en":"to tell two or more people who have not met before what each other’s names are; to tell somebody what your name is","cn":"把…介绍（给）；引见；（自我）介绍","lab":"formal","sc":"people","ex":{"en":"Allow me to introduce my mother.","cn":"请允许我介绍我母亲。"}},{"en":"to be the main speaker in a television or radio show, who gives details about the show and who presents the people who are in it; to tell the audience the name of the person who is going to speak or perform","cn":"主持（节目）；介绍（讲演者或演员）","sc":"TV/radio show","ex":{"en":"The next programme will be introduced by Mary David.","cn":"下一个节目由玛丽·戴维主持。"}},{"en":"to mention something for the first time in a piece of writing","cn":"（在写作中）介绍，初次提到","sc":"in a piece of writing","ex":{"en":"Introduce the topic and briefly state your own opinion.","cn":"介绍主题，并简要陈述自己的观点。"}},{"en":"to make somebody learn about something or do something for the first time","cn":"使初次了解；使尝试","sc":"new experience","ex":{"en":"The first lecture introduces students to the main topics of the course.","cn":"第一堂课是让学生了解这门课的主要内容。"}},{"en":"to make something available for use, discussion, etc. for the first time","cn":"推行；实施；采用","sc":"new product/law","ex":{"en":"The company has recently introduced a new warehouse management system.","cn":"该公司最近采用了一种新的仓库管理系统。"}},{"en":"to be the start of something new","cn":"作为（新事物）的开头；使开始；创始","sc":"start","ex":{"en":"Bands from London introduced the craze for this kind of music.","cn":"伦敦的乐队引发了对这种音乐的狂热。"}},{"en":"to bring a plant, an animal or a disease to a place for the first time","cn":"引进（动物或植物）；传入（疾病）","sc":"plant/animal/disease","ex":{"en":"Some new species were introduced accidentally to Australia from Europe.","cn":"有些新物种偶然从欧洲传入了澳大利亚。"}},{"en":"to formally present a new law so that it can be discussed","cn":"将（法案）提交讨论","lab":"specialist","sc":"in parliament","ex":{"en":"to introduce a bill (before Parliament)","cn":"（向议会）提交议案"}},{"en":"to put something into something","cn":"将…放进；添入","lab":"formal","sc":"add","ex":{"en":"Particles of glass had been introduced into the baby food.","cn":"这种婴儿食品中被掺进了玻璃碎屑。"}},{"en":"to cause something to contain errors","cn":"引起错误","sc":"errors","ex":{"en":"Measurement error could have been introduced by respondents' recall errors.","cn":"受访者记忆有误可能引致测量上的误差。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"引进;首次引入;推行","en":"To introduce something means to cause it to enter a place or exist in a system for the first time.","ex":{"en":"The Government has introduced a number of other money-saving moves","cn":"政府已经采取了其他一些省钱的举措。"}},{"pos":"VERB 动词","cn":"介绍;使了解;使初次接触","en":"If you introduce someone to something, you cause them to learn about it or experience it for the first time.","ex":{"en":"He introduced us to the delights of natural food.","cn":"他让我们认识到食用天然食物的乐趣。"}},{"pos":"VERB 动词","cn":"介绍;引荐;使相互认识","en":"If you introduce one person to another, or you introduce two people, you tell them each other's names, so that they can get to know each other. If you introduce yourself to someone, you tell them your name.","ex":{"en":"Tim, may I introduce you to my uncle's secretary, Mary Waller?","cn":"蒂姆,我来介绍一下，这位是我叔叔的秘书玛丽·沃勒。"}},{"pos":"VERB 动词","cn":"为(电视或广播节目)做开场白;主持","en":"The person who introduces a television or radio programme speaks at the beginning of it, and often between the different items in it, in order to explain what the programme or the items are about.","ex":{"en":"'Health Matters' is introduced by Dick Oliver on BBC World Service.","cn":"英国广播公司对外广播频道的“健康动态”节目由迪克·奥利弗主持。"}}]},"examples":[{"en":"‘Kay, this is Steve.’ ‘Yes, I know — we've already introduced ourselves.’ “","cn":"凯，这是史蒂夫。” “是的，我知道，我们已经自己相互介绍了。”"},{"en":"Can I introduce myself? I'm Helen Robins.","cn":"让我来自我介绍一下吧。我叫海伦 · 罗宾斯。"}]},"interventionist":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(政策)干涉主义的，主张干预的","en":"Interventionist policies are policies which show an organization's desire to become involved in a problem or a crisis which does not concern it directly.","ex":{"en":"...the interventionist industrial policy of the Wilson government","cn":"威尔逊政府主张干涉的工业政策"}}]},"media":{"uk":"media/uk/interventionist__gb_1.mp3","us":"media/us/interventionist__us_1.mp3"},"examples":[{"en":"interventionist policies","cn":"干预政策"},{"en":"The UN adopted a more interventionist approach in the region.","cn":"联合国在该地区采取了干预性更强的手段。"}],"oxford":{"phon":"ˌɪntəˈvenʃənɪst","pos":"noun","senses":[{"en":"a person who believes in the policy or practice of a government influencing the economy of its own country, or of becoming involved in the affairs of other countries","cn":"政府干预（政策）","ex":{"en":"liberal/humanitarian interventionists","cn":"自由主义/人道主义干预主义者"}},{"en":"connected with the policy or practice of a government influencing the economy of its own country, or of becoming involved in the affairs of other countries","cn":"政府干预（政策）","ex":{"en":"interventionist policies","cn":"干涉主义政策"},"pos":"adjective"}]}},"inactive":{"media":{"uk":"media/uk/inactive__gb_1.mp3","us":"media/us/inactive__us_1.mp3"},"oxford":{"phon":"ɪnˈæktɪv","pos":"adjective","senses":[{"en":"not doing anything; not active","cn":"无行动的；不活动的；不活跃的","ex":{"en":"Some animals are inactive during the daytime.","cn":"有些动物白天不活动。"}},{"en":"not in use; not working","cn":"未使用的；不运转的","ex":{"en":"an inactive oil well","cn":"闲置的油井"}},{"en":"having no effect","cn":"无作用的；无效的","ex":{"en":"an inactive drug/disease","cn":"失效的药物；非活动性疾病"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无所作为的;不活动的;闲置的","en":"Someone or something that is inactive is not doing anything or is not working.","ex":{"en":"He certainly was not politically inactive","cn":"他政治上当然不是无所作为。"}}]},"examples":[{"en":"The volcano has been inactive for 50 years.","cn":"这座火山处于休眠状态 50 年了。"},{"en":"periods of enforced inactivity and boredom","cn":"被迫无事可做、单调乏味的时期"}]},"invention":{"media":{"uk":"media/uk/invention__gb_1.mp3","us":"media/us/invention__us_1.mp3"},"oxford":{"phon":"ɪnˈvenʃn","pos":"noun","senses":[{"en":"a thing or an idea that has been invented","cn":"发明；创造","g":"[countable]","ex":{"en":"Fax machines were a wonderful invention at the time.","cn":"传真机在当时是一项了不起的发明。"}},{"en":"the act of inventing something","cn":"发明；创造","g":"[uncountable]","ex":{"en":"Such changes have not been seen since the invention of the printing press.","cn":"自从发明了印刷机，这种变革还没有出现过。"}},{"en":"the act of inventing a story or an idea and pretending that it is true; a story invented in this way","cn":"虚构；编造；虚构的故事","g":"[countable, uncountable]","ex":{"en":"This story is apparently a complete invention.","cn":"这个故事显然完全是虚构的。"}},{"en":"the ability to have new and interesting ideas","cn":"创造力；创意","g":"[uncountable]","ex":{"en":"John was full of invention—always making up new dance steps and sequences.","cn":"约翰有丰富的创造力，总能编出新的舞步和连续舞步。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"发明物;创造的事物","en":"An invention is a machine, device, or system that has been invented by someone.","ex":{"en":"It's been a tricky business marketing his new invention","cn":"推广他的新发明一直是件棘手的事情。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"发明;创造","en":"Invention is the act of inventing something that has never been made or used before.","ex":{"en":"More than eight million books were printed within fifty years after the invention of the printing press.","cn":"印刷机发明以后的 50 年间,有 800 多万册图书被印刷。"}},{"pos":"N-VAR 可变名词","cn":"捏造;虚构","en":"If you refer to someone's account of something as an invention, you think that it is untrue and that they have made it up.","ex":{"en":"In these and several other respects, there are many inventions and exaggerations","cn":"在这些方面和其他几个方面都存在许多捏造与夸张之处。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"发明才能;创造能力","en":"Invention is the ability to invent things or to have clever and original ideas.","ex":{"en":"...his great powers of invention.","cn":"他出色的创造才能"}}]},"examples":[{"en":"John was full of invention — always making up new dance steps and sequences.","cn":"约翰有丰富的创造力 — 总能编出新的舞步和连续舞步。"},{"en":"Such changes have not been seen since the invention of the printing press.","cn":"自从发明了印刷机，这种变革再也没有出现过。"}]},"inferiority":{"media":{"uk":"media/uk/inferiority__gb_1.mp3","us":"media/us/inferiority__us_1.mp3"},"oxford":{"phon":"ɪnˌfɪəriˈɒrəti","pos":"noun","senses":[{"en":"the state of not being as good as somebody/something else","cn":"低等；劣等；劣势","ex":{"en":"a sense of inferiority","cn":"自卑感"}}]},"examples":[{"en":"social inferiority","cn":"社会地位低下"},{"en":"a sense of inferiority","cn":"自卑感"}]},"investigation":{"oxford":{"phon":"ɪnˌvestɪˈɡeɪʃn","pos":"noun","senses":[{"en":"an official examination of the facts about a situation, crime, etc.","cn":"（正式的）调查，侦查","lab":"British English","ex":{"en":"a criminal/murder/police investigation","cn":"刑事／凶案／警方调查"}},{"en":"a scientific or academic examination of the facts of a subject or problem","cn":"科学研究；学术研究","ex":{"en":"Further investigation revealed a flaw in this theory.","cn":"继续调查后发现这个理论有一个缺陷。"}}]},"media":{"uk":"media/uk/investigation__gb_1.mp3","us":"media/us/investigation__us_1.mp3"},"examples":[{"en":"an investigation into the spending habits of teenagers","cn":"对十几岁青少年的消费习惯进行的调查研究"},{"en":"The police have completed their investigations into the accident.","cn":"警察已完成对这次事故的调查。"}]},"incredible":{"media":{"uk":"media/uk/incredible__gb_1.mp3","us":"media/us/incredible__us_1.mp3"},"oxford":{"phon":"ɪnˈkredəbl","pos":"adjective","senses":[{"en":"impossible or very difficult to believe","cn":"不能相信的；难以置信的","ex":{"en":"an incredible story","cn":"不可思议的故事"}},{"en":"extremely good","cn":"极好的；精彩的；了不起的","ex":{"en":"The hotel was incredible.","cn":"这家旅馆棒极了。"}},{"en":"extremely large","cn":"极大的；庞大的","lab":"informal","ex":{"en":"an incredible amount of work","cn":"极大量的工作"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"妙极的;惹人喜爱的;了不起的","en":"If you describe something or someone as incredible, you like them very much or are impressed by them, because they are extremely or unusually good.","ex":{"en":"The wildflowers will be incredible after this rain","cn":"这场雨过后,野花会变得美不胜收。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不可思议的;难以置信的","en":"If you say that something is incredible, you mean that it is very unusual or surprising, and you cannot believe it is really true, although it may be.","ex":{"en":"It seemed incredible that people would still want to play football during a war","cn":"在战时人们仍然想踢足球,这似乎不可思议。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"惊人的","en":"You use incredible to emphasize the degree, amount, or intensity of something.","ex":{"en":"We import an incredible amount of cheese from the Continent","cn":"我们从欧洲大陆进口数量惊人的奶酪。"}}]},"examples":[{"en":"It seemed incredible that she had been there a week already.","cn":"真让人难以置信，她已经在那里待了一个星期了。"},{"en":"The hotel was incredible.","cn":"这家旅馆棒极了。"}]},"internet":{"media":{"uk":"media/uk/internet__gb_1.mp3","us":"media/us/internet__us_1.mp3"},"oxford":{"phon":"ˈɪntənet","pos":"noun","senses":[{"en":"an international computer network connecting other networks and computers that allows people to share information around the world","cn":"（国际）互联网；因特网","ex":{"en":"to surf/browse/access the internet","cn":"上网"}}]},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"因特网","en":"The Internet is the computer network which allows computer users to connect with computers all over the world, and which carries e-mail."}]},"examples":[{"en":"You can buy our goods over the Internet.","cn":"可以通过互联网购买我们的货品。"},{"en":"All the rooms have access to the Internet/Internet access.","cn":"所有的房间都可以接入互联网。"}]},"indirectly":{"oxford":{"phon":"ˌɪndəˈrektli","pos":"adverb","senses":[{"en":"not as the main aim, cause or result of something, but in addition to it; not in a direct line or manner","cn":"间接地：不是作为某事物的主要目的，原因或结果，而是除此之外；不以直线或方式","ex":{"en":"The new law will affect us all, directly or indirectly.","cn":"新的法规会直接或间接地影响到我们所有人。"}},{"en":"in a way that is not clear or obvious","cn":"间接地：以不清楚或不明显的方式","ex":{"en":"Trump was referring indirectly to his predecessor, Barack Obama.","cn":"特朗普间接指的是他的前任巴拉克·奥巴马。"}}]},"media":{"uk":"media/uk/indirectly__gb_1.mp3","us":"media/us/indirectly__us_1.mp3"},"examples":[{"en":"The new law will affect us all, directly or indirectly.","cn":"新的法规将直接或间接地影响我们所有的人。"},{"en":"Losing weight is an indirect result of smoking cigarettes.","cn":""}]},"invite":{"oxford":{"phon":"ɪnˈvaɪt","pos":"verb","senses":[{"en":"to ask somebody to come to a social event","cn":"邀请（某人出席社交场合）","lab":"informal or North American English","ex":{"en":"Have you been invited to their party?","cn":"你接到参加他们的聚会的邀请了吗？"}},{"en":"to ask somebody formally to go somewhere or do something; to make a formal or polite request for something","cn":"正式邀请，请求（某人做某事）","lab":"formal","ex":{"en":"The bishop invited representatives from all the parishes in the diocese.","cn":"主教邀请了教区所有堂区的代表。"}},{"en":"to make something, especially something bad or unpleasant, likely to happen","cn":"招致（尤指坏事）","ex":{"en":"Such comments are just inviting trouble.","cn":"这种评论简直是在自找麻烦。"}},{"en":"an invitation","cn":"邀请；请柬","ex":{"en":"Thanks for your invite.","cn":"感谢你的邀请。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"邀请","en":"If you invite someone to something such as a party or a meal, you ask them to come to it.","ex":{"en":"She invited him to her 26th birthday party in New Jersey","cn":"她邀请他去参加她在新泽西举行的 26 岁生日聚会。"}},{"pos":"VERB 动词","cn":"(正式)邀请，请求，要求","en":"If you are invited to do something, you are formally asked or given permission to do it.","ex":{"en":"At a future date, managers will be invited to apply for a management buy-out","cn":"在将来的某天,经理们将受邀进行管理层收购。"}},{"pos":"VERB 动词","cn":"招致;诱发;引发","en":"If something you say or do invites trouble or criticism, it makes trouble or criticism more likely.","ex":{"en":"I realise that an Englishman who generalises about Ireland invites trouble","cn":"我意识到英国人如果对爱尔兰问题加以泛化的话会招惹麻烦。"}},{"pos":"N-COUNT 可数名词","cn":"请柬;请帖","en":"An invite is an invitation to something such as a party or a meal.","ex":{"en":"They haven't got an invite to the wedding.","cn":"他们还没收到参加婚礼的请柬。"}}]},"media":{"uk":"media/uk/invite__gb_1.mp3","us":"media/us/invite__us_1.mp3"},"examples":[{"en":"Successful candidates will be invited for interview next week.","cn":"通过甄别的候选人将获邀于下周参加面试。"},{"en":"Readers are invited to email their comments to us.","cn":"欢迎读者通过电子邮件向我们反馈意见。"}]},"interviewers":{"oxford":{"phon":"ˈɪntəvjuːə(r)","pos":"noun","senses":[{"en":"the person who asks the questions in an interview","cn":"主持面试者；采访者"}]}},"initially":{"media":{"uk":"media/uk/initially__gb_1.mp3","us":"media/us/initially__us_1.mp3"},"oxford":{"phon":"ɪˈnɪʃəli","pos":"adverb","senses":[{"en":"at the beginning","cn":"起初；开始时","ex":{"en":"Initially, the system worked well.","cn":"系统起初运作得很好。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"最初;开始","en":"Initially means soon after the beginning of a process or situation, rather than in the middle or at the end of it.","ex":{"en":"Forecasters say the gales may not be as bad as they initially predicted","cn":"预报员说大风也许不像他们起初预报的那么猛烈。"}}]},"examples":[{"en":"The death toll was initially reported at around 250, but was later revised to 300.","cn":"最初报道死亡人数约 250，后修订为 300。"},{"en":"Initially, the system worked well.","cn":"开始时系统运转良好。"}]},"innovative":{"media":{"uk":"media/uk/innovative__gb_1.mp3","us":"media/us/innovative__us_1.mp3"},"oxford":{"phon":"ˈɪnəveɪtɪv","pos":"adjective","senses":[{"en":"introducing or using new ideas, ways of doing something, etc.","cn":"引进新思想的；采用新方法的；革新的；创新的","ex":{"en":"There will be a prize for the most innovative design.","cn":"将设立一项最具创意设计奖。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"革新的;新颖的","en":"Something that is innovative is new and original.","ex":{"en":"...products which are more innovative than those of their competitors.","cn":"比竞争对手更新颖的产品"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"富有革新精神的","en":"An innovative person introduces changes and new ideas.","ex":{"en":"He was one of the most creative and innovative engineers of his generation.","cn":"他是他那代人当中最富创造性与革新精神的工程师之一。"}}]},"examples":[{"en":"There will be a prize for the most innovative design.","cn":"将设立一项最具创意设计奖。"},{"en":"an innovative approach to language teaching","cn":"创新的语言教学法"}]},"instance":{"media":{"uk":"media/uk/instance__gb_1.mp3","us":"media/us/instance__us_1.mp3"},"oxford":{"phon":"ˈɪnstəns","pos":"noun","senses":[{"en":"a particular example or case of something","cn":"例子；事例；实例","ex":{"en":"The report highlights a number of instances of injustice.","cn":"这篇报告重点列举了一些不公正的实例。"}},{"en":"to give something as an example","cn":"举…为例","ex":{"en":"I refer to the situation instanced above.","cn":"我指的是上面举例的情况。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"PHRASE 短语","cn":"例如;譬如","en":"You use for instance to introduce a particular event, situation, or person that is an example of what you are talking about.","ex":{"en":"There are a number of improvements; for instance, both mouse buttons can now be used","cn":"在许多地方有了改进,例如,鼠标的左右键都可以使用了。"}},{"pos":"N-COUNT 可数名词","cn":"例子;实例;事例","en":"An instance is a particular example or occurrence of something.","ex":{"en":"She cited an instance where their training had been a marvelous help in dealing with problems.","cn":"她举了一个所受训练为解决问题帮了大忙的实例。"}},{"pos":"PHRASE 短语","cn":"首先;第一步","en":"You say in the first instance to mention something that is the first step in a series of actions.","ex":{"en":"In the first instance your child will be seen by an ear, nose and throat specialist","cn":"你的孩子将首先由耳鼻喉专科医生来诊察。"}},{"pos":"PHRASE 短语","cn":"在…的命令(或要求)下","en":"If you do something at someone's instance, you do it because they have ordered or requested you to do it.","ex":{"en":"The rally was organised at the instance of two senior cabinet ministers.","cn":"集会是应两位资深内阁大臣的要求组织的。"}}]},"examples":[{"en":"I would normally suggest taking time off work, but in this instance I'm not sure that would do any good.","cn":"我通常会建议休假，但就这个情况而言，我不敢保证休假会有什么好处。"},{"en":"What would you do, for instance, if you found a member of staff stealing?","cn":"比如说，如果你发现有职员偷东西，你该怎么办？"}]},"interested":{"media":{"uk":"media/uk/interested__gb_1.mp3","us":"media/us/interested__us_1.mp3"},"oxford":{"phon":"ˈɪntrəstɪd","pos":"adjective","senses":[{"en":"giving your attention to something because you enjoy finding out about it or doing it; showing interest in something and finding it exciting","cn":"感兴趣的；关心的；表现出兴趣的","ex":{"en":"He sounded genuinely interested.","cn":"听他的口气，他真的感兴趣。"}},{"en":"in a position to gain from a situation or be affected by it","cn":"有利害关系的；当事人的","ex":{"en":"As an interested party, I was not allowed to vote.","cn":"作为有利害关系的一方，我不得投票。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"感兴趣的;有兴趣的;关心的","en":"If you are interested in something, you think it is important and want to learn more about it or spend time doing it.","ex":{"en":"I thought she might be interested in Paula's proposal","cn":"我觉得她对葆拉的提议可能会感兴趣。"}},{"pos":"ADJ 形容词","cn":"有利害关系的;利益相关的;当事的","en":"An interested party or group of people is affected by or involved in a particular event or situation.","ex":{"en":"All the interested parties eventually agreed to the idea.","cn":"所有利益相关方最终都同意了这一想法。"}}]},"examples":[{"en":"Interested groups will be given three months to give their views on the new development.","cn":"有关团体将有三个月的时间提出他们对新开发项目的看法。"},{"en":"Anyone interested in joining the club should contact us at the address below.","cn":"有意加入俱乐部者请按下面的地址和我们联系。"}]},"instinctive":{"media":{"uk":"media/uk/instinctive__gb_1.mp3","us":"media/us/instinctive__us_1.mp3"},"oxford":{"phon":"ɪnˈstɪŋktɪv","pos":"adjective","senses":[{"en":"based on instinct (= a natural quality that makes somebody/something behave in a particular way), not thought or training","cn":"本能的；直觉的","ex":{"en":"instinctive knowledge","cn":"本能的知识"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"本能的;天性的;直觉的","en":"An instinctive feeling, idea, or action is one that you have or do without thinking or reasoning.","ex":{"en":"It's an absolutely instinctive reaction—if a child falls you pick it up","cn":"这完全是本能的反应——如果一个孩子摔倒了你会把他扶起来。"}}]},"examples":[{"en":"My instinctive reaction was to deny everything.","cn":"我的本能反应是否认一切。"},{"en":"She's an instinctive player.","cn":"她是个天生的运动员。"}]},"inherently":{"oxford":{"phon":"ɪnˈherəntli","pos":"adverb","senses":[{"en":"according to or because of the basic nature of somebody/something","cn":"固有地：根据或由于某人/某物的基本性质而固有地","ex":{"en":"an inherently unworkable system","cn":"从根本上就行不通的体制"}}]},"media":{"uk":"media/uk/inherently__gb_1.mp3","us":"media/us/inherently__us_1.mp3"},"examples":[{"en":"an inherently unworkable system","cn":"根本行不通的体制"},{"en":"I’m afraid the problems you mention are inherent in the system.","cn":""}]},"inexperienced":{"media":{"uk":"media/uk/inexperienced__gb_1.mp3","us":"media/us/inexperienced__us_1.mp3"},"oxford":{"phon":"ˌɪnɪkˈspɪəriənst","pos":"adjective","senses":[{"en":"having little knowledge or experience of something","cn":"缺乏认识（或经验）的","ex":{"en":"inexperienced drivers/staff","cn":"没有经验的司机／职员"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无经验的;缺乏经验的","en":"If you are inexperienced, you have little knowledge or experience of a particular situation or activity.","ex":{"en":"They are inexperienced when it comes to decorating","cn":"说到装修，他们就没有什么经验了。"}}]},"examples":[{"en":"a child too young and inexperienced to recognize danger","cn":"因太年幼无知而意识不到危险的孩子"},{"en":"inexperienced drivers/staff","cn":"没有经验的司机/职员"}]},"indeed":{"media":{"uk":"media/uk/indeed__gb_1.mp3","us":"media/us/indeed__us_1.mp3"},"oxford":{"phon":"ɪnˈdiːd","pos":"adverb","senses":[{"en":"used after very and an adjective or adverb to emphasize a statement, description, etc.","cn":"（用于 very 和形容词或副词之后，强调叙述、描写等）真正地","lab":"especially British English","ex":{"en":"Thank you very much indeed!","cn":"真的很感谢您！"}},{"en":"used to emphasize a positive statement or answer","cn":"（强调肯定的陈述或答复）","ex":{"en":"‘Was he very angry?’ ‘Indeed he was.’","cn":"“他很生气吗？”“的确很生气。”"}},{"en":"used to add information to a statement","cn":"其实；实际上","lab":"formal, especially British English，，","ex":{"en":"I don't mind at all. Indeed, I would be delighted to help.","cn":"我根本不介意。其实，我倒很乐意帮上一把。"}},{"en":"used to show that you are surprised at something or that you find something silly","cn":"（表示惊讶或觉得某事物荒谬）","lab":"informal, especially British English，，","ex":{"en":"A ghost indeed! I've never heard anything so silly.","cn":"鬼！哈哈！我可从没听过这么荒谬的事。"}},{"en":"used when you are repeating a question that somebody has just asked and showing that you do not know the answer","cn":"（重复对方的问题，表示不知道答案）","lab":"informal","ex":{"en":"‘Why did he do it?’ ‘Why indeed?’","cn":"“他为什么那样做？”“是呀，为什么呢？”"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"确实;的确","en":"You use indeed to confirm or agree with something that has just been said.","ex":{"en":"Later, he admitted that the payments had indeed been made","cn":"后来,他承认确实付过款了。"}},{"pos":"ADV 副词","cn":"(表示语气的递进)实际上,其实,确切说来","en":"You use indeed to introduce a further comment or statement which strengthens the point you have already made.","ex":{"en":"We have nothing against diversity; indeed, we want more of it","cn":"我们一点都不抵触多样化;实际上,我们需要多样性更丰富一些。"}},{"pos":"ADV 副词","cn":"(位于句末修饰very或强调某词)确实,实在","en":"You use indeed at the end of a clause to give extra force to the word 'very', or to emphasize a particular word.","ex":{"en":"The engine began to sound very loud indeed","cn":"发动机开始发出极大的声响。"}},{"pos":"ADV 副词","cn":"(重复问题以作强调,尤用于答案未知时)到底,究竟","en":"You can use indeed as a way of repeating a question in order to emphasize it, especially when you do not know the answer.","ex":{"en":"'Now where are the real villains?' — 'Where indeed?'","cn":"“那么那些真正的恶棍在哪里？”——“是啊，到底在哪里？”"}}]},"examples":[{"en":"‘You said you'd help?’ ‘I did indeed — yes.’ “","cn":"你说过你要帮忙？” “是的，我的确说过。”"},{"en":"I don't mind at all. Indeed, I would be delighted to help.","cn":"我根本不介意。其实，我倒很乐意帮上一把。"}]},"incorporate":{"media":{"uk":"media/uk/incorporate__gb_1.mp3","us":"media/us/incorporate__us_1.mp3"},"oxford":{"phon":"ɪnˈkɔːpəreɪt","pos":"verb","senses":[{"en":"to include something so that it forms a part of something","cn":"将…包括在内；包含；吸收；使并入","ex":{"en":"The new car design incorporates all the latest safety features.","cn":"新的汽车设计包括了所有最新的安全配备。"}},{"en":"to create a legally recognized company","cn":"注册成立","g":"[often passive]","lab":"business","ex":{"en":"The company was incorporated in 2008.","cn":"这家公司成立于 2008 年。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"包含;吸收","en":"If one thing incorporates another thing, it includes the other thing.","ex":{"en":"The new cars will incorporate a number of major improvements.","cn":"新款汽车会有若干重大改进。"}},{"pos":"VERB 动词","cn":"把…合并;使并入","en":"If someone or something is incorporated into a large group, system, or area, they become a part of it.","ex":{"en":"The agreement would allow the rebels to be incorporated into a new national police force","cn":"协议将允许把叛军收编入一支新的国家警备部队。"}}]},"examples":[{"en":"The new car design incorporates all the latest safety features.","cn":"新的汽车设计包括了所有最新的安全配备。"},{"en":"We have incorporated all the latest safety features into the design.","cn":"我们在设计中纳入了所有最新的安全装置。"}]},"inhabited":{"oxford":{"phon":"ɪnˈhæbɪtɪd","pos":"adjective","senses":[{"en":"with people or animals living there","cn":"有人居住的；有动物栖居的","ex":{"en":"The island is no longer inhabited.","cn":"这个岛已经没有人居住了。"}}]},"media":{"uk":"media/uk/inhabited__gb_1.mp3","us":"media/us/inhabited__us_1.mp3"},"examples":[{"en":"The building is now inhabited by birds.","cn":"这所建筑物现在有鸟儿栖息。"},{"en":"The island is no longer inhabited.","cn":"这个岛已经没有人居住了。"}]},"inner":{"media":{"uk":"media/uk/inner__gb_1.mp3","us":"media/us/inner__us_1.mp3"},"oxford":{"phon":"ˈɪnə(r)","pos":"adjective","senses":[{"en":"inside; towards or close to the centre of a place","cn":"里面的；向内的；内部的；接近中心的","ex":{"en":"an inner courtyard","cn":"内院"}},{"en":"private and secret; not expressed or shown to other people","cn":"内心的；未表达出来的；隐藏的","ex":{"en":"She doesn't reveal much of her inner self.","cn":"她不大流露她的内心自我。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"内部的;里面的","en":"The inner parts of something are the parts which are contained or are enclosed inside the other parts, and which are closest to the centre.","ex":{"en":"She got up and went into an inner office","cn":"她起身进了里间办公室。"}},{"pos":"ADJ 形容词","cn":"内心的","en":"Your inner feelings are feelings which you have but do not show to other people.","ex":{"en":"Loving relationships will give a child an inner sense of security","cn":"亲昵关系会给予孩子内心一种安全感。"}}]},"examples":[{"en":"She doesn't reveal much of her inner self.","cn":"她不大流露她的内心自我。"},{"en":"inner London","cn":"伦敦市中心区"}]},"interacting":{"oxford":{"phon":"ˌɪntərˈækt","pos":"verb","senses":[{"en":"to communicate with sb, especially while you work, play or spend time with them","cn":"交流；沟通；合作"},{"en":"if one thing interacts with another, or if two things interact , the two things have an effect on each other","cn":"相互影响；相互作用"}]}},"incorrect":{"media":{"uk":"media/uk/incorrect__gb_1.mp3","us":"media/us/incorrect__us_1.mp3"},"oxford":{"phon":"ˌɪnkəˈrekt","pos":"adjective","senses":[{"en":"not accurate or true","cn":"不准确的；不正确的；不真实的","ex":{"en":"incorrect information/spelling","cn":"失实的信息；错误的拼写"}},{"en":"speaking or behaving in a way that does not follow the accepted standards or rules","cn":"（说话或举止）不合规矩的，不当的，不端的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不正确的;错误的;不真实的","en":"Something that is incorrect is wrong and untrue.","ex":{"en":"He denied that his evidence about the telephone call was incorrect","cn":"他否认自己关于电话的证词是虚假的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不适当的;不合适的","en":"Something that is incorrect is not the thing that is required or is most suitable in a particular situation.","ex":{"en":"...injuries caused by incorrect posture.","cn":"由不当姿势造成的损伤"}}]},"examples":[{"en":"His version of what happened is incorrect.","cn":"他对所发生的事情的说法不准确。"},{"en":"incorrect information/spelling","cn":"失实的信息；错误的拼写"}]},"indiscriminate":{"media":{"uk":"media/uk/indiscriminate__gb_1.mp3","us":"media/us/indiscriminate__us_1.mp3"},"oxford":{"phon":"ˌɪndɪˈskrɪmɪnət","pos":"adjective","senses":[{"en":"an indiscriminate action is done without thought about what the result may be, especially when it causes people to be harmed","cn":"随意的；恣意的；不加选择的","ex":{"en":"indiscriminate attacks on motorists by youths throwing stones","cn":"年轻人乱扔石头袭击驾车的人"}},{"en":"acting without careful judgement","cn":"不加分析的；不加判断的","ex":{"en":"She's always been indiscriminate in her choice of friends.","cn":"她一向择友不慎。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不加区别的;不加选择的","en":"If you describe an action as indiscriminate, you are critical of it because it does not involve any careful thought or choice.","ex":{"en":"The indiscriminate use of fertilisers is damaging to the environment.","cn":"乱用化肥会破坏环境。"}}]},"examples":[{"en":"indiscriminate attacks on motorists by youths throwing stones","cn":"年轻人乱扔石头袭击驾车的人"},{"en":"Doctors have been criticized for their indiscriminate use of antibiotics.","cn":"医生被指责滥用抗生素。"}]},"ink":{"media":{"uk":"media/uk/ink__gb_1.mp3","us":"media/us/ink__us_1.mp3"},"oxford":{"phon":"ɪŋk","pos":"noun","senses":[{"en":"coloured liquid for writing, drawing and printing","cn":"墨水；墨汁；油墨","ex":{"en":"written in ink","cn":"用墨水写的"}},{"en":"a tattoo or tattoos (= pictures or designs marked permanently on a person's skin)","cn":"纹身","g":"[countable]","ex":{"en":"She likes to wear clothes that show off her ink.","cn":"她喜欢穿能展示墨水的衣服。"}},{"en":"to cover something with ink so that it can be used for printing","cn":"给…上油墨（以供印刷）","pos":"verb"},{"en":"to sign a document, especially a contract","cn":"签署，签订（合同等）","lab":"North American English, informal，，","ex":{"en":"The group has just inked a $10 million deal.","cn":"这个集团刚刚签订了一份 1 000 万美元的协议。"},"pos":"verb"},{"en":"to mark somebody's skin with a tattoo (= a picture or design marked permanently in ink)","cn":"将花纹刺在⋯上；给⋯文身","ex":{"en":"She has a lizard inked on her right arm.","cn":"她的右臂上纹着一只蜥蜴。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"墨水;油墨","en":"Ink is the coloured liquid used for writing or printing.","ex":{"en":"The letter was handwritten in black ink.","cn":"信是用黑色墨水写的。"}},{"pos":"VERB 动词","cn":"使沾上墨水(或油墨等)","en":"If you ink something, you put ink on it.","ex":{"en":"Ritter took his left hand and inked the fingertips.","cn":"里特伸出左手,在指尖上沾上印油。"}}]},"examples":[{"en":"The group has just inked a $10 million deal.","cn":"这个集团刚刚签订了一份 1 000 万元的协议。"},{"en":"( figurative ) The date for the presentation should have been inked in (= made definite) by now.","cn":"演出的日期现在应该敲定了。"}]},"inclination":{"media":{"uk":"media/uk/inclination__gb_1.mp3","us":"media/us/inclination__us_1.mp3"},"oxford":{"phon":"ˌɪnklɪˈneɪʃn","pos":"noun","senses":[{"en":"a feeling that makes you want to do something","cn":"倾向；意愿","g":"[uncountable, countable]","ex":{"en":"He did not show the slightest inclination to leave.","cn":"他丝毫没有表现出要离开的意思。"}},{"en":"a new way of doing something that is starting to develop","cn":"趋向；趋势","g":"[countable]","ex":{"en":"There is an inclination to treat geography as a less important subject.","cn":"有一种趋向认为地理是一门次要的学科。"}},{"en":"a degree of sloping","cn":"倾斜度","g":"[countable, usually singular, uncountable]","lab":"specialist","ex":{"en":"The panels are placed at an inclination of 45 degrees.","cn":"面板倾斜 45 度放置。"}},{"en":"a small movement downwards, usually of the head","cn":"向下的轻微动作；（通常指）点头","g":"[countable]"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"意向;倾向;爱好","en":"An inclination is a feeling that makes you want to act in a particular way.","ex":{"en":"He had neither the time nor the inclination to think of other things","cn":"他没有时间也不愿意去考虑其他事情。"}}]},"examples":[{"en":"There is an inclination to treat geography as a less important subject.","cn":"有一种趋向认为地理是一门次要的学科。"},{"en":"He was a loner by nature and by inclination.","cn":"他天性不喜交际，且自己也无意于此。"}]},"interruption":{"oxford":{"phon":"ˌɪntəˈrʌpʃn","pos":"noun","senses":[{"en":"something that temporarily stops an activity or a situation; a time when an activity is stopped","cn":"阻断物；中断时间","ex":{"en":"The game continued after a short interruption because of rain.","cn":"比赛因雨短暂中断后继续进行。"}},{"en":"the act of interrupting somebody/something and of stopping them from speaking","cn":"打扰；插嘴；打岔","ex":{"en":"He ignored her interruptions.","cn":"他没有理会她的打岔。"}}]},"media":{"uk":"media/uk/interruption__gb_1.mp3","us":"media/us/interruption__us_1.mp3"},"examples":[{"en":"The birth of her son was a minor interruption to her career.","cn":"她儿子的出生对她的事业造成一个小小的中断。"},{"en":"I managed to work for two hours without interruption.","cn":"我总算连续工作了两小时。"}]},"independently":{"oxford":{"phon":"ˌɪndɪˈpendəntli","pos":"adverb","senses":[{"en":"without being connected with or influenced by something or by each other","cn":"不相关的；不受影响的；无关联的","ex":{"en":"The two departments work independently of each other.","cn":"这两个部门独立运作。"}},{"en":"in a fair way by somebody who is not involved in a situation","cn":"独立地：以公平的方式由不参与情势的人","ex":{"en":"Their stories could not be independently verified.","cn":"他们的故事无法得到独立证实。"}},{"en":"in a confident way without needing help from other people","cn":"自主的；有主见的","ex":{"en":"The students eventually began to think more independently.","cn":"学生们最终开始更加独立思考。"}},{"en":"without relying on somebody else for money or support","cn":"独立地","ex":{"en":"It was the first time that she had lived independently.","cn":"那是她第一次独立生活。"}}]},"media":{"uk":"media/uk/independently__gb_1.mp3","us":"media/us/independently__us_1.mp3"},"examples":[{"en":"It was the first time that she had lived independently.","cn":"那是她第一次独立生活。"},{"en":"The two departments work independently of each other.","cn":"这两个部门独立运作。"}]},"insufficient":{"media":{"uk":"media/uk/insufficient__gb_1.mp3","us":"media/us/insufficient__us_1.mp3"},"oxford":{"phon":"ˌɪnsəˈfɪʃnt","pos":"adjective","senses":[{"en":"not large, strong or important enough for a particular purpose","cn":"不充分的；不足的；不够重要的","ex":{"en":"insufficient time","cn":"时间不够"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不充分的;不足的;缺乏的","en":"Something that is insufficient is not large enough in amount or degree for a particular purpose.","ex":{"en":"He decided there was insufficient evidence to justify criminal proceedings","cn":"他认定证据不充分无法提起刑事诉讼。"}}]},"examples":[{"en":"His salary is insufficient to meet his needs.","cn":"他的薪水不够应付需要。"},{"en":"( technical","cn":"术语 ) : cardiac insufficiency 心功能不全"}]},"interfere":{"media":{"uk":"media/uk/interfere__gb_1.mp3","us":"media/us/interfere__us_1.mp3"},"oxford":{"phon":"ˌɪntəˈfɪə(r)","pos":"verb","senses":[{"en":"to get involved in and try to influence a situation that should not really involve you, in a way that annoys other people","cn":"干涉；干预；介入","ex":{"en":"I wish my mother would stop interfering and let me make my own decisions.","cn":"我希望我母亲不再干预，让我自己拿主意。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"干涉;干预;介入","en":"If you say that someone interferes in a situation, you mean they get involved in it although it does not concern them and their involvement is not wanted.","ex":{"en":"I wish everyone would stop interfering and just leave me alone","cn":"我希望大家都别再来干涉我,让我一个人静一静。"}},{"pos":"VERB 动词","cn":"妨碍;冲突;抵触","en":"Something that interferes with a situation, activity, or process has a damaging effect on it.","ex":{"en":"Drug problems frequently interfered with his work","cn":"吸毒问题频频干扰他的工作。"}}]},"examples":[{"en":"I'd get fired if he found out I'd been interfering with his records.","cn":"要是他发现我把他的唱片捣鼓坏了，我就得被解雇了。"},{"en":"I wish my mother would stop interfering and let me make my own decisions.","cn":"我希望我母亲不再干预，让我自己拿主意。"}]},"instinct":{"media":{"uk":"media/uk/instinct__gb_1.mp3","us":"media/us/instinct__us_1.mp3"},"oxford":{"phon":"ˈɪnstɪŋkt","pos":"noun","senses":[{"en":"a natural quality that makes people and animals tend to behave in a particular way using the knowledge and abilities that they were born with rather than thought or training","cn":"本能；天性","ex":{"en":"She did not seem to have any of the usual maternal instincts.","cn":"她似乎没有任何平常的母性本能。"}},{"en":"a feeling that makes you do something or believe that something is true, even though it is not based on facts or reason","cn":"直觉","ex":{"en":"I've always trusted my instincts in the past.","cn":"过去我一直相信我的直觉。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"本能;天性","en":"Instinct is the natural tendency that a person or animal has to behave or react in a particular way.","ex":{"en":"I didn't have as strong a maternal instinct as some other mothers","cn":"我不像别的母亲那样有那么强烈的母性本能。"}},{"pos":"N-COUNT 可数名词","cn":"天分;天资;天赋的才能","en":"If you have an instinct for something, you are naturally good at it or able to do it.","ex":{"en":"Farmers are increasingly losing touch with their instinct for managing the land","cn":"农民正在逐渐丢失经营土地的本领。"}},{"pos":"N-VAR 可变名词","cn":"本能反应;心里的话","en":"If it is your instinct to do something, you feel that it is right to do it.","ex":{"en":"I should've gone with my first instinct, which was not to do the interview","cn":"我本该听从自己的第一反应,不接受这次采访的。"}},{"pos":"N-VAR 可变名词","cn":"直觉","en":"Instinct is a feeling that you have that something is the case, rather than an opinion or idea based on facts.","ex":{"en":"There is scientific evidence to support our instinct that being surrounded by plants is good for health","cn":"我们觉得周围植物环绕会有益健康,这种直觉有科学证据支持。"}}]},"examples":[{"en":"Even at school, he showed he had an instinct for (= was naturally good at) business.","cn":"他早在求学时期就表现出经商的天赋。"},{"en":"Children do not know by instinct the difference between right and wrong.","cn":"儿童并非生来就会分辨是非。"}]},"inaudible":{"media":{"uk":"media/uk/inaudible__gb_1.mp3","us":"media/us/inaudible__us_1.mp3"},"oxford":{"phon":"ɪnˈɔːdəbl","pos":"adjective","senses":[{"en":"that you cannot hear","cn":"听不见的","ex":{"en":"She spoke in an almost inaudible whisper.","cn":"她低声说话的声音几不可闻。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(声音)听不见的","en":"If a sound is inaudible, you are unable to hear it.","ex":{"en":"His voice was almost inaudible","cn":"他的话音低得几乎听不见。"}}]},"examples":[{"en":"The whistle was inaudible to the human ear.","cn":"这种哨声人耳听不到。"},{"en":"The noise of the wind made her cries inaudible.","cn":"风声盖过了她的叫喊声。"}]},"intended":{"media":{"uk":"media/uk/intended__gb_1.mp3","us":"media/us/intended__us_1.mp3"},"oxford":{"phon":"ɪnˈtendɪd","pos":"adjective","senses":[{"en":"that you are trying to achieve or reach","cn":"意欲达到的；打算的；计划的","g":"[only before noun]","ex":{"en":"the intended purpose","cn":"原来的目的"}},{"en":"planned or designed for somebody/something","cn":"为…打算（或设计）的","ex":{"en":"The book is intended for children.","cn":"这本书是为儿童写的。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"打算中的;预期的;预定的","en":"You use intended to describe the thing you are trying to achieve or person you are trying to affect.","ex":{"en":"The intended target had been a military building","cn":"原定目标是一座军事大楼。"}}]},"examples":[{"en":"The notes are intended as an introduction to the course.","cn":"这些笔记的目的是作为对这门课程的介绍。"},{"en":"This list is not intended to be a complete catalogue.","cn":"这张清单并非要做成一张完整的目录。"}]},"inflected":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an inflected language contains many words which change their form according to their meaning or use 〔","cn":"语言〕屈折变化的"}]},"media":{"uk":"media/uk/inflected__gb_1.mp3","us":"media/us/inflected__us_1.mp3"},"oxford":{"phon":"ɪnˈflektɪd","pos":"adjective","senses":[{"en":"an inflected word has a different ending or spelling according to its grammatical function in a sentence; an inflected language has words that show this feature","cn":"屈折变化；词尾变化","ex":{"en":"an inflected language/form/verb","cn":"屈折语／形式／动词"}}]}},"insurance":{"media":{"uk":"media/uk/insurance__gb_1.mp3","us":"media/us/insurance__us_1.mp3"},"oxford":{"phon":"ɪnˈʃʊərəns","pos":"noun","senses":[{"en":"an arrangement with a company in which you pay them regular amounts of money and they agree to pay the costs, for example, if you die or are ill, or if you lose or damage something","cn":"保险","g":"[uncountable, countable]","lab":"British English","ex":{"en":"health/medical insurance","cn":"健康／医疗保险"}},{"en":"the business of providing people with insurance","cn":"保险业","g":"[uncountable]","ex":{"en":"an insurance broker/company","cn":"保险经纪／公司"}},{"en":"money paid by or to an insurance company","cn":"保险费；保费","g":"[uncountable]","ex":{"en":"to pay insurance on your house","cn":"交住房保险金"}},{"en":"something you do to protect yourself against something bad happening in the future","cn":"（防备不测的）保障措施，安全保证","g":"[uncountable, countable]","ex":{"en":"At that time people had large families as an insurance against some children dying.","cn":"那时人们养的子女很多，以防有孩子夭折。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"保险","en":"Insurance is an arrangement in which you pay money to a company, and they pay money to you if something unpleasant happens to you, for example if your property is stolen or damaged, or if you get a serious illness.","ex":{"en":"The insurance company paid out for the stolen jewellery and silver","cn":"保险公司赔付了遭窃的珠宝和银器。"}},{"pos":"N-VAR 可变名词","cn":"预防措施;安全保证","en":"If you do something as insurance against something unpleasant happening, you do it to protect yourself in case the unpleasant thing happens.","ex":{"en":"The country needs a defence capability as insurance against the unexpected.","cn":"国家需要有一定的防御能力，以应对不可预知的情况。"}}]},"examples":[{"en":"When her husband died, she received £50 000 in insurance.","cn":"她丈夫去世，她得到了一笔 5 万英镑的保险金。"},{"en":"Can you claim for the loss on your insurance?","cn":"你能向你投保的公司要求赔偿这一损失吗？"}]},"influential":{"media":{"uk":"media/uk/influential__gb_1.mp3","us":"media/us/influential__us_1.mp3"},"oxford":{"phon":"ˌɪnfluˈenʃl","pos":"adjective","senses":[{"en":"having a lot of influence on somebody/something","cn":"有很大影响的；有支配力的","ex":{"en":"a highly influential book","cn":"十分有影响力的书"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有影响力的;有权势的","en":"Someone or something that is influential has a lot of influence over people or events.","ex":{"en":"It helps to have influential friends.","cn":"有几个位高权重的朋友很有好处。"}}]},"examples":[{"en":"The committee was influential in formulating government policy on employment.","cn":"委员会左右着政府就业政策的制订。"},{"en":"She is one of the most influential figures in local politics.","cn":"她是本地政坛举足轻重的人物。"}]},"innocent":{"media":{"uk":"media/uk/innocent__gb_1.mp3","us":"media/us/innocent__us_1.mp3"},"oxford":{"phon":"ˈɪnəsnt","pos":"adjective","senses":[{"en":"not guilty of a crime, etc.; not having done something wrong","cn":"无辜的；清白的；无罪的","ex":{"en":"They have imprisoned an innocent man.","cn":"他们监禁了一名无辜的男子。"}},{"en":"suffering harm or being killed because of a crime, war, etc. although not directly involved in it","cn":"无辜受害的；成为牺牲品的","g":"[only before noun]","ex":{"en":"an innocent bystander","cn":"无辜受害的旁观者"}},{"en":"having little experience of the world, especially of sexual matters, or of evil or unpleasant things","cn":"天真无邪的；纯真的","ex":{"en":"At the time I was still an innocent young child.","cn":"那时我还是一个天真烂漫的小孩子。"}},{"en":"not intended to cause harm or upset somebody","cn":"无恶意的；无冒犯之意的","ex":{"en":"It was all innocent fun.","cn":"那不过是些无恶意的玩笑。"}},{"en":"an innocent person, especially a young child","cn":"无辜者，单纯的人（尤指天真无邪的孩子）","pos":"noun"},{"en":"a person involved by chance in a situation, especially a victim of crime or war","cn":"（尤指罪案或战争等的）无辜受害者","ex":{"en":"They are prepared to kill or maim innocents in pursuit of a cause.","cn":"他们为了达到某种目的准备不惜杀害或伤残无辜的受害者。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"清白的;无罪的","en":"If someone is innocent, they did not commit a crime which they have been accused of.","ex":{"en":"He was sure that the man was innocent of any crime","cn":"他确信那个男人没有犯任何罪。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"天真的;幼稚的;不谙世故的","en":"If someone is innocent, they have no experience or knowledge of the more complex or unpleasant aspects of life.","ex":{"en":"They seemed so young and innocent","cn":"他们看起来如此少不更事。"}},{"pos":"ADJ 形容词","cn":"无辜(受害)的","en":"Innocent people are those who are not involved in a crime or conflict, but are injured or killed as a result of it.","ex":{"en":"All those wounded were innocent victims","cn":"所有伤者都是无辜的受害人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"没有恶意的;无冒犯之意的","en":"An innocent question, remark, or comment is not intended to offend or upset people, even if it does so.","ex":{"en":"It was a perfectly innocent question.","cn":"那是个完全没有恶意的问题。"}}]},"examples":[{"en":"‘Oh, Sue went too, did she?’ I asked innocently (= pretending I did not know that this was important). “","cn":"噢，苏也去了，是吗？”我装作若无其事地问。"},{"en":"He was the innocent party (= person) in the breakdown of the marriage.","cn":"他们的婚姻破裂，他是无过错的一方。"}]},"infant":{"media":{"uk":"media/uk/infant__gb_1.mp3","us":"media/us/infant__us_1.mp3"},"oxford":{"phon":"ˈɪnfənt","pos":"noun","senses":[{"en":"a baby or very young child","cn":"婴儿；幼儿","lab":"formal or specialist","ex":{"en":"a nursery for infants under two","cn":"两岁以下婴幼儿的托儿所"}},{"en":"a child at school between the ages of four and seven","cn":"四岁到七岁之间的学童","ex":{"en":"an infant school","cn":"幼儿学校"}},{"en":"designed to be used by infants","cn":"供婴幼儿用的","ex":{"en":"infant formula (= milk for babies)","cn":"婴儿配方奶粉"},"pos":"adjective"},{"en":"new and not yet developed","cn":"初期的；初创期的","ex":{"en":"infant industries","cn":"新兴工业"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"婴儿","en":"An infant is a baby or very young child.","ex":{"en":"...young mums with infants in prams","cn":"用婴儿车推着宝宝的年轻妈妈"}},{"pos":"N-COUNT 可数名词","cn":"(5-7岁的)幼儿","en":"Infants are children between the ages of five and seven, who go to an infant school.","ex":{"en":"You've been my best friend ever since we started in the infants.","cn":"自从我们上幼儿园起，你就是我最好的朋友。"}},{"pos":"ADJ 形容词","cn":"供婴儿用的","en":"Infant means designed especially for very young children.","ex":{"en":"...an infant carrier in the back of a car.","cn":"汽车后部的婴儿座椅"}},{"pos":"ADJ 形容词","cn":"(组织、运动等)初期的,初创的","en":"An infant organization or system is new and has not developed very much.","ex":{"en":"The infant company was based in Germany.","cn":"这家新公司总部在德国。"}}]},"examples":[{"en":"I've known her since we were in the infants (= at infant school).","cn":"从幼儿学校时我就认识她了。"},{"en":"a nursery for infants under two","cn":"两岁以下婴幼儿的托儿所"}]},"institutional":{"oxford":{"phon":"ˌɪnstɪˈtjuːʃənl","pos":"adjective","senses":[{"en":"connected with a large important organization, for example a university or bank","cn":"（大学、银行等）机构的","ex":{"en":"institutional investors","cn":"机构投资者"}},{"en":"in or like a place where people are sent to live and be cared for, for example a hospital, prison or special school","cn":"在或类似人们被送去居住和接受照顾的地方，例如医院、监狱或特殊学校","lab":"sometimes disapproving","ex":{"en":"institutional care","cn":"慈善机构的照顾"}},{"en":"established as part of the normal systems, practices, etc. of an organization, society or culture","cn":"作为组织、社会或文化的正常系统、实践等的一部分而建立","lab":"usually disapproving","ex":{"en":"institutional racism","cn":"系统性种族主义"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(大学、银行、教会等)(大型)机构的;具有机构特征的","en":"Institutional means relating to a large organization, for example a university, bank, or church.","ex":{"en":"NATO remains the United States' chief institutional anchor in Europe","cn":"北大西洋公约组织仍然是美国在欧洲首要的支柱机构。"}},{"pos":"ADJ 形容词","cn":"社会收容机构的","en":"Institutional means relating to a building where people are looked after or held.","ex":{"en":"Outside the protected environment of institutional care he could not survive.","cn":"离开福利机构的照顾，离开这种受保护的环境,他将难以生存下去。"}},{"pos":"ADJ 形容词","cn":"习俗化了的;制度化了的","en":"An institutional value or quality is considered an important and typical feature of a particular society or group, usually because it has existed for a long time.","ex":{"en":"...social and institutional values.","cn":"社会与习俗价值观"}},{"pos":"ADJ 形容词","cn":"根深蒂固的","en":"If someone accuses an organization of institutional racism or sexism, they mean that the organization is deeply racist or sexist and has been so for a long time.","ex":{"en":"...the Macpherson report, which accused the Metropolitan Police of institutional racism.","cn":"指控伦敦警察厅存在根深蒂固的种族主义的麦克弗森报告。"}}]},"media":{"uk":"media/uk/institutional__gb_1.mp3","us":"media/us/institutional__us_1.mp3"},"examples":[{"en":"institutional care","cn":"慈善机构的照顾"},{"en":"institutional investors","cn":"机构投资者"}]},"inevitable":{"media":{"uk":"media/uk/inevitable__gb_1.mp3","us":"media/us/inevitable__us_1.mp3"},"oxford":{"phon":"ɪnˈevɪtəbl","pos":"adjective","senses":[{"en":"that you cannot avoid or prevent","cn":"不可避免的；不能防止的","ex":{"en":"It was an inevitable consequence of the decision.","cn":"那是这个决定的必然后果。"}},{"en":"happening so often that you always expect it","cn":"总会发生的；照例必有的；惯常的","g":"[only before noun]","lab":"often humorous","ex":{"en":"the English and their inevitable cups of tea","cn":"英国人和他们例行的饮茶活动"}},{"en":"something that is certain to happen","cn":"必然发生的事；不可避免的事","g":"[singular]","ex":{"en":"You have to accept the inevitable.","cn":"你得接受必然发生的事。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不可避免的;无法规避的;必然(发生)的","en":"If something is inevitable, it is certain to happen and cannot be prevented or avoided.","ex":{"en":"If the case succeeds, it is inevitable that other trials will follow","cn":"如果该案胜诉,其他审判必然随之而来。"}}]},"examples":[{"en":"The inevitable happened — I forgot my passport.","cn":"逃不掉的事情发生了，我忘了带护照。"},{"en":"A rise in the interest rates seems inevitable.","cn":"提高利率似乎是不可避免的。"}]},"interviewer":{"oxford":{"phon":"ˈɪntəvjuːə(r)","pos":"noun","senses":[{"en":"the person who asks the questions in an interview","cn":"主持面试者；采访者","ex":{"en":"The interviewer made the candidates feel relaxed.","cn":"面试官让应聘者感到轻松。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"采访者;进行面试者","en":"An interviewer is a person who is asking someone questions at an interview."}]},"media":{"uk":"media/uk/interviewer__gb_1.mp3","us":"media/us/interviewer__us_1.mp3"}},"invincibility":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"too strong to be destroyed or defeated","cn":""},{"en":"an invincible belief, attitude etc is extremely strong and cannot be changed","cn":""}]},"examples":[{"en":"Young athletes think of themselves as invincible.","cn":"","src":"ld"}],"media":{"uk":"media/uk/invincibility__gb_1.mp3","us":"media/us/invincibility__us_1.mp3"},"oxford":{"phon":"ɪnˌvɪnsəˈbɪləti","pos":"noun","senses":[{"en":"the quality of being too strong to be defeated or changed","cn":"不可战胜的；不能改变的","ex":{"en":"He had an aura of invincibility.","cn":"他身上有一种无敌的气势。"}}]}},"index-linked":{"oxford":{"phon":"ˌɪndeks ˈlɪŋkt","pos":"adjective","senses":[{"en":"rising in value according to increases in the cost of living","cn":"按生活指数调整的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(养老金或报酬)与通货膨胀(或生活成本)挂钩的","en":"Index-linked pensions or payments change as inflation or the cost of living changes."}]},"media":{"uk":"media/uk/index_linked_1_gb_1.mp3","us":"media/us/index_linked_1_us_1.mp3"}},"innovating":{"oxford":{"phon":"ˈɪnəveɪt","pos":"verb","senses":[{"en":"to introduce new things, ideas, or ways of doing sth","cn":"引入（新事物、思想或方法）；创新；改革"}]}},"in":{"media":{"uk":"media/uk/in__gb_1.mp3","us":"media/us/in__us_1.mp3"},"oxford":{"phon":"ɪn","pos":"preposition","senses":[{"en":"at a point within an area or a space","cn":"在（某范围或空间内的）某一点","ex":{"en":"a country in Africa","cn":"非洲的一个国家"}},{"en":"within the shape of something; surrounded by something","cn":"在（某物的形体或范围）中；在…内；在…中","ex":{"en":"She was lying in bed.","cn":"她躺在床上。"}},{"en":"into something","cn":"进入","ex":{"en":"He dipped his brush in the paint.","cn":"他把毛刷在涂料里蘸了蘸。"}},{"en":"forming the whole or part of something/somebody; contained within something/somebody","cn":"构成…的整体（或部分）；包含在…之内","ex":{"en":"There are 31 days in May.","cn":"五月份有 31 天。"}},{"en":"during a period of time","cn":"在（某段时间）内","ex":{"en":"in 2021","cn":"在 2021 年"}},{"en":"after a particular length of time","cn":"在（某段时间）之后","ex":{"en":"to return in a few minutes/hours/days/months.","cn":"几分钟／几小时／几天／几个月后回来"}},{"en":"for a particular period of time","cn":"在（某段时间）内","ex":{"en":"I haven't seen him in years.","cn":"我有好些年没见过他了。"}},{"en":"wearing something","cn":"穿着；戴着","ex":{"en":"dressed in their best clothes","cn":"穿着他们最好的衣服"}},{"en":"used to describe something that is all around you","cn":"在…的环境中","ex":{"en":"We went out in the rain.","cn":"我们冒雨出去了。"}},{"en":"used to show the language, material, etc. used","cn":"（表示使用的语言、材料等）","ex":{"en":"Say it in English.","cn":"用英语说吧。"}},{"en":"used to show a state or condition","cn":"（表示状态或状况）","ex":{"en":"I'm in love!","cn":"我恋爱了！"}},{"en":"involved in something; taking part in something","cn":"参与；参加","ex":{"en":"to act in a play","cn":"参加演戏"}},{"en":"used to show somebody’s job or profession","cn":"（显示工作或职业）","ex":{"en":"He is in the army.","cn":"他在军队服役。"}},{"en":"used to show the form, shape, arrangement or quantity of something","cn":"（显示某物的形式、形状、安排或数量）","ex":{"en":"a novel in three parts","cn":"分为三部的小说"}},{"en":"used to show the quality or thing that a judgement is being made about","cn":"在…上；在…方面","ex":{"en":"She was not lacking in courage.","cn":"她并不缺乏勇气。"}},{"en":"while doing something; while something is happening","cn":"做…时；…发生时；当…时","ex":{"en":"In attempting to save the child from drowning, she nearly lost her own life.","cn":"她在抢救落水的儿童时，自己差点丧命。"}},{"en":"used to introduce the name of a person who has a particular quality","cn":"（引出具某种品质的人的名字）","ex":{"en":"We're losing a first-rate editor in Jen.","cn":"我们即将失去珍这位一流的编辑。"}},{"en":"used to show a rate or relative amount","cn":"（显示比率或相对数量）","ex":{"en":"a gradient of one in five","cn":"五分之一的坡度"}},{"en":"into an object, an area or a substance","cn":"进入","ex":{"en":"She opened the door and went in.","cn":"她打开门进去了。"},"pos":"adverb"},{"en":"contained within an object, an area or a substance","cn":"在里面；在内","ex":{"en":"We were locked in.","cn":"我们被锁在里面了。"},"pos":"adverb"},{"en":"at home or at a place of work","cn":"在家里；在工作单位","ex":{"en":"Nobody was in when we called.","cn":"我们打电话过去时没有人在。"},"pos":"adverb"},{"en":"at the place where people can get on or off, for example the station","cn":"在车站；在停靠站","ex":{"en":"The bus is due in (= it should arrive) at six.","cn":"公共汽车应该在六点钟到站。"},"pos":"adverb"},{"en":"received","cn":"收到；被投递到","ex":{"en":"Applications must be in by April 30.","cn":"申请务必于 4 月 30 日之前寄到。"},"pos":"adverb"},{"en":"at or towards its highest point on land","cn":"上涨；在最高点","ex":{"en":"Is the tide coming in or going out?","cn":"是在涨潮还是在落潮？"},"pos":"adverb"},{"en":"elected","cn":"当选","ex":{"en":"Several new councillors got in at the last election.","cn":"几位新政务委员在最近一轮选举中当选。"},"pos":"adverb"},{"en":"if a team or team member is in, they are batting","cn":"轮上击球","pos":"adverb"},{"en":"if the ball is in, it has landed inside the line","cn":"（球）落在界内","ex":{"en":"Her serve was just in.","cn":"她发的球刚好落在界内。"},"pos":"adverb"},{"en":"popular and fashionable","cn":"流行的；时髦的","ex":{"en":"Purple is the in colour this spring.","cn":"紫色是今年春天的流行色。"},"pos":"adjective"},{"en":"inch","cn":"英寸","ex":{"en":"Height: 6ft 2in.","cn":"高：6 英尺 2 英寸。"},"pos":"abbreviation"},{"en":"not; the opposite of","cn":"不；非；相反的","ex":{"en":"infinite","cn":"无限的"},"pos":"prefix"},{"en":"to put into the condition mentioned","cn":"使置于某状况","ex":{"en":"inflame","cn":"使愤怒"},"pos":"prefix"},{"en":"an activity in which many people take part","cn":"很多人参加的活动","ex":{"en":"a sit-in","cn":"静坐示威"},"pos":"combining form"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"在…里;在…之内","en":"Someone or something that is in something else is enclosed by it or surrounded by it. If you put something in a container, you move it so that it is enclosed by the container.","ex":{"en":"He was in his car.","cn":"他坐在他的车里。"}},{"pos":"PREP 介词","cn":"在(某处)","en":"If something happens in a place, it happens there.","ex":{"en":"We spent a few days in a hotel","cn":"我们在一家宾馆住了几天。"}},{"pos":"ADV 副词","cn":"在家;在办公室","en":"If you are in, you are present at your home or place of work.","ex":{"en":"My flatmate was in at the time","cn":"我的舍友当时在房间里。"}},{"pos":"ADV 副词","cn":"进;入","en":"When someone comes in, they enter a room or building.","ex":{"en":"She looked up anxiously as he came in","cn":"他进来的时候,她焦虑不安地抬起头来看了看。"}},{"pos":"ADV 副词","cn":"(火车)进站;(轮船、飞机)抵港","en":"If a train, boat, or plane has come in or is in, it has arrived at a station, port, or airport.","ex":{"en":"We'd be watching every plane coming in from Melbourne","cn":"我们会密切注意从墨尔本飞来的每架飞机。"}},{"pos":"ADV 副词","cn":"(潮)在上涨","en":"When the sea or tide comes in, the sea moves towards the shore rather than away from it.","ex":{"en":"She thought of the tide rushing in, covering the wet sand","cn":"她想象潮汐涌来,淹没潮湿的沙滩。"}},{"pos":"PREP 介词","cn":"在(橱窗)里面","en":"Something that is in a window, especially a shop window, is just behind the window so that you can see it from outside.","ex":{"en":"The light in the window went out","cn":"橱窗里的灯熄灭了。"}},{"pos":"PREP 介词","cn":"在(镜子)之中","en":"When you see something in a mirror, the mirror shows an image of it.","ex":{"en":"I couldn't bear to see my reflection in the mirror","cn":"我不忍看镜子里自己的样子。"}},{"pos":"PREP 介词","cn":"穿着;戴着","en":"If you are dressed in a piece of clothing, you are wearing it.","ex":{"en":"He was a big man, smartly dressed in a suit and tie.","cn":"他身材高大，穿着西服打着领带，非常帅气。"}},{"pos":"PREP 介词","cn":"(包裹)在…之中;(覆盖)在…之下","en":"Something that is covered or wrapped in something else has that thing over or round its surface.","ex":{"en":"His legs were covered in mud.","cn":"他的腿上满是泥浆。"}},{"pos":"PREP 介词","cn":"(裂缝或洞)在…表面上","en":"If there is something such as a crack or hole in something, there is a crack or hole on its surface.","ex":{"en":"There was a deep crack in the ceiling above him.","cn":"在他头顶的天花板上有一道很深的裂缝。"}},{"pos":"PREP 介词","cn":"在(书、电影、戏剧、图片)之中","en":"If something is in a book, film, play, or picture, you can read it or see it there.","ex":{"en":"Don't stick too precisely to what it says in the book.","cn":"不要过分拘泥于书上所说的。"}},{"pos":"PREP 介词","cn":"参加(演出、比赛等)","en":"If you are in something such as a play or a race, you are one of the people taking part.","ex":{"en":"Alf offered her a part in the play he was directing","cn":"阿尔夫在他导演的戏中给她安排了一个角色。"}},{"pos":"PREP 介词","cn":"在(团体、收藏)当中","en":"Something that is in a group or collection is a member of it or part of it.","ex":{"en":"The New England team are the worst in the league.","cn":"新英格兰队是联盟中最差的队。"}},{"pos":"PREP 介词","cn":"在(学科、活动领域)方面","en":"You use in to specify a general subject or field of activity.","ex":{"en":"...those working in the defence industry.","cn":"国防工业领域从业者"}},{"pos":"PREP 介词","cn":"在(特定年、月等);在…期间","en":"If something happens in a particular year, month, or other period of time, it happens during that time.","ex":{"en":"...that early spring day in April 1949","cn":"1949 年4月早春的那一天"}},{"pos":"PREP 介词","cn":"在(某一情形、形势)之中","en":"If something happens in a particular situation, it happens while that situation is going on.","ex":{"en":"His father had been badly wounded in the last war.","cn":"在上次战争中，他的父亲受了重伤。"}},{"pos":"PREP 介词","cn":"花费…时间","en":"If you do something in a particular period of time, that is how long it takes you to do it.","ex":{"en":"He walked two hundred and sixty miles in eight days.","cn":"他在8天里走了260英里的路。"}},{"pos":"PREP 介词","cn":"在(一段时间)之后","en":"If something will happen in a particular length of time, it will happen after that length of time.","ex":{"en":"I'll have some breakfast ready in a few minutes","cn":"几分钟后我就能做点儿早饭出来。"}},{"pos":"PREP 介词","cn":"在(某一年龄段)之中","en":"You use in to indicate roughly how old someone is. For example, if someone is in their fifties, they are between 50 and 59 years old.","ex":{"en":"...young people in their twenties.","cn":"20多岁的年轻人"}},{"pos":"PREP 介词","cn":"以(或按)…的数量","en":"You use in to indicate roughly how many people or things do something.","ex":{"en":"...men who came there in droves","cn":"成群结队到那里的人"}},{"pos":"PREP 介词","cn":"(表示比率、比例、概率)在…之中","en":"You use in to express a ratio, proportion, or probability.","ex":{"en":"Last year, one in five boys left school without a qualification","cn":"去年，五分之一的男孩没有获得资格证书就离校了。"}},{"pos":"PREP 介词","cn":"(表示目前状态、形势)处于…中","en":"If something or someone is in a particular state or situation, that is their present state or situation.","ex":{"en":"The economy was in trouble","cn":"经济处于困境中。"}},{"pos":"PREP 介词","cn":"带着，充满(某种情感或愿望)","en":"You use in to indicate the feeling or desire which someone has when they do something, or which causes them to do it.","ex":{"en":"Simpson looked at them in surprise","cn":"辛普森惊讶地看着他们。"}},{"pos":"PREP 介词","cn":"(性格、能力)在…身上","en":"If a particular quality or ability is in you, you naturally have it.","ex":{"en":"Violence is not in his nature","cn":"他天性温和。"}},{"pos":"PREP 介词","cn":"(特定品质)在…之中","en":"You use in when saying that someone or something has a particular quality.","ex":{"en":"He had all the qualities I was looking for in a partner","cn":"他具有我要找的伴侣应该具备的所有品质。"}},{"pos":"PREP 介词","cn":"以…方式(表达)","en":"You use in to indicate how someone is expressing something.","ex":{"en":"Information is given to the patient verbally and in writing.","cn":"用口头和书面的形式向病人提供信息。"}},{"pos":"PREP 介词","cn":"(表示排列或形状)成一排/呈球形","en":"You use in in expressions such as in a row or in a ball to describe the arrangement or shape of something.","ex":{"en":"The cards need to be laid out in two rows","cn":"这些卡片需要排成两行。"}},{"pos":"PREP 介词","cn":"以(…颜色)的","en":"If something is in a particular colour, it has that colour.","ex":{"en":"...white flowers edged in pink","cn":"粉边白花"}},{"pos":"PREP 介词","cn":"在(某一特征、方面)上","en":"You use in to specify which feature or aspect of something you are talking about.","ex":{"en":"The movie is nearly two hours in length","cn":"这部电影时长近两个小时。"}},{"pos":"ADJ 形容词","cn":"时髦的;流行的;受欢迎的","en":"If you say that something is in, or is the in thing, you mean it is fashionable or popular.","ex":{"en":"A few years ago jogging was the in thing","cn":"几年前慢跑很流行。"}},{"pos":"PREP 介词","cn":"(与现在分词连用)在…过程中","en":"You use in with a present participle to indicate that when you do something, something else happens as a result.","ex":{"en":"In working with others, you find out more about yourself.","cn":"在与别人一起工作的过程中,你会进一步认识你自己。"}},{"pos":"PHRASE 短语","cn":"肯定会经历;注定遭受","en":"If you say that someone is in for a shock or a surprise, you mean that they are going to experience it.","ex":{"en":"You might be in for a shock at the sheer hard work involved","cn":"所做工作之艰辛可能会让你大吃一惊。"}},{"pos":"PHRASE 短语","cn":"对…怀有仇恨;伺机报复…","en":"If someone has it in for you, they dislike you and try to cause problems for you.","ex":{"en":"The other kids had it in for me.","cn":"其他的孩子对我怀恨在心。"}},{"pos":"PREP-PHRASE 短语介词","cn":"卷入;参与","en":"If you are in on something, you are involved in it or know about it.","ex":{"en":"I don't know. I wasn't in on that particular argument","cn":"我不知道。我没有参与那一争论。"}},{"pos":"PHRASE 短语","cn":"与…友好相处;深得…的欢心","en":"If you are in with a person or group, they like you and accept you, and are likely to help you."},{"pos":"PHR-CONJ-SUBORD","cn":"因为;原因是","en":"You use in that to introduce an explanation of a statement you have just made.","ex":{"en":"I'm lucky in that I've got four sisters.","cn":"我很幸运，因为我有4个姐姐。"}},{"pos":"PHRASE 短语","cn":"复杂详情;底细","en":"The ins and outs of a situation are all the detailed points and facts about it.","ex":{"en":"...the ins and outs of high finance","cn":"大宗金融交易的详情"}}]},"examples":[{"en":"People flocked in their thousands to see her.","cn":"现场聚集了数以千计的人争相目睹她的丰采。"},{"en":"The kids were playing by the river and one of them fell in.","cn":"孩子们在河边玩耍时，其中一个突然落水了。"}]},"insects":{"oxford":{"phon":"ˈɪnsekt","pos":"noun","senses":[{"en":"any small creature with six legs and a body divided into three parts. Insects usually also have wings. Ants , bees and flies are all insects.","cn":"昆虫"}]},"media":{"img":["media/pic/insects_comp.jpg"]}},"interpreted":{"oxford":{"phon":"ɪnˈtɜːprɪt","pos":"verb","senses":[{"en":"to explain the meaning of sth","cn":"诠释；说明"},{"en":"to decide that sth has a particular meaning and to understand it in this way","cn":"把 … 理解为；领会"}]}},"intonation":{"oxford":{"phon":"ˌɪntəˈneɪʃn","pos":"noun","senses":[{"en":"the rise and fall of the voice in speaking, especially as this affects the meaning of what is being said","cn":"语调","g":"[uncountable, countable]","lab":"phonetics","ex":{"en":"intonation patterns","cn":"语调类型"}},{"en":"the quality of playing or singing exactly in tune","cn":"（演奏或唱歌中的）音准","g":"[uncountable]","lab":"music","ex":{"en":"The violin’s intonation was poor.","cn":"这个小提琴的调音不准。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"语调;声调","en":"Your intonation is the way that your voice rises and falls as you speak.","ex":{"en":"His voice had a very slight German intonation.","cn":"他说话稍微带一点儿德国腔。"}}]},"media":{"uk":"media/uk/intonation__gb_1.mp3","us":"media/us/intonation__us_1.mp3"},"examples":[{"en":"In English, some questions have a rising intonation.","cn":"英语中有些疑问句使用升调。"},{"en":"intonation patterns","cn":"语调类型"}]},"individual":{"media":{"uk":"media/uk/individual__gb_1.mp3","us":"media/us/individual__us_1.mp3"},"oxford":{"phon":"ˌɪndɪˈvɪdʒuəl","pos":"noun","senses":[{"en":"a person considered separately rather than as part of a group","cn":"个人","ex":{"en":"The competition is open to both teams and individuals.","cn":"团队和个人均可参加比赛。"}},{"en":"a single member of a class of things","cn":"个体；（群体中的）一员","ex":{"en":"They live in a group or as individuals, depending on the species.","cn":"它们或群居，或独居，因物种而异。"}},{"en":"a person who is original and very different from others","cn":"与众不同的人；有个性的人","ex":{"en":"She's grown into quite an individual.","cn":"她已经长成了一个相当有个性的人。"}},{"en":"a person of a particular type, especially a strange one","cn":"某种类型的人；（尤指）古怪的人","lab":"informal, usually disapproving，，","ex":{"en":"an odd-looking individual","cn":"模样怪异的人"}},{"en":"considered separately rather than as part of a group","cn":"单独的；个别的","g":"[only before noun]","ex":{"en":"We interviewed each individual member of the community.","cn":"我们采访了社区中的每个成员。"},"pos":"adjective"},{"en":"connected with one person; designed for one person","cn":"一个人的；供一人用的","g":"[only before noun]","ex":{"en":"respect for individual freedom","cn":"对个人自由的尊重"},"pos":"adjective"},{"en":"typical of one particular person or thing in a way that is different from others","cn":"独特的；与众不同的","lab":"usually approving","ex":{"en":"a highly individual style of dress","cn":"十分有个性的衣着风格"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"个别的;单独的","en":"Individual means relating to one person or thing, rather than to a large group.","ex":{"en":"They wait for the group to decide rather than making individual decisions","cn":"他们等待团体作决定而不是各自作出决定。"}},{"pos":"N-COUNT 可数名词","cn":"个体;个人","en":"An individual is a person.","ex":{"en":"...anonymous individuals who are doing good things within our community.","cn":"一些在我们社区内做好事却不留名的个人"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"独特的;有个性的","en":"If you describe someone or something as individual, you mean that you admire them because they are very unusual and do not try to imitate other people or things.","ex":{"en":"It was really all part of her very individual personality","cn":"那其实都是她独特个性的表现。"}}]},"examples":[{"en":"The minister refused to comment on individual cases.","cn":"那位部长拒绝对个别情况发表评论。"},{"en":"She's grown into quite an individual.","cn":"她已经长成了一个相当有个性的人。"}]},"indicate":{"media":{"uk":"media/uk/indicate__gb_1.mp3","us":"media/us/indicate__us_1.mp3"},"oxford":{"phon":"ˈɪndɪkeɪt","pos":"verb","senses":[{"en":"to show that something is true or exists","cn":"表明；显示","g":"[transitive]","sc":"show","ex":{"en":"Initial tests indicate the presence of oxygen.","cn":"初步检测显示该处有氧气。"}},{"en":"to be a sign of something; to show that something is possible or likely","cn":"象征；暗示","g":"[transitive]","sc":"suggest","ex":{"en":"A red sky at night often indicates fine weather the next day.","cn":"夜空呈红色往往预兆第二天天气晴朗。"}},{"en":"to mention something, especially in an indirect way","cn":"暗示；间接提及；示意","g":"[transitive]","sc":"mention","ex":{"en":"In his letter he indicated to us (that) he was willing to cooperate.","cn":"他在信中向我们透露他愿意合作。"}},{"en":"to make somebody notice somebody/something, especially by pointing or moving your head","cn":"指示；指出","g":"[transitive]","lab":"formal","sc":"point to","ex":{"en":"‘What are they doing here?’ he asked, indicating her bags in the hallway.","cn":"“他们在这里做什么？”他指着走廊上她的行李问道。"}},{"en":"to represent information without using words","cn":"显示（信息）；标示","g":"[transitive]","lab":"formal","sc":"give information","ex":{"en":"Arrows indicate the direction of flow.","cn":"箭头标明流动方向。"}},{"en":"to give information in writing","cn":"写明；注出","g":"[transitive]","lab":"formal","sc":"give information","ex":{"en":"You are allowed 20 kg of baggage unless indicated otherwise on your ticket.","cn":"除非票上另有注明，否则行李限携 20 公斤。"}},{"en":"to show a particular measurement","cn":"显示（量度）","g":"[transitive]","sc":"show measurement","ex":{"en":"When the temperature gauge indicates 90°F or more, turn off the engine.","cn":"当温度计显示 90 华氏度或以上时，关闭发动机。"}},{"en":"to show that your vehicle is going to change direction, by using lights or your arm","cn":"（用灯光或手臂）打行车转向信号","g":"[intransitive, transitive]","lab":"British English","sc":"in vehicle","ex":{"en":"Always indicate before moving into another lane.","cn":"开入其他车道前一定要打转向灯。"}},{"en":"to be necessary or recommended","cn":"有必要；被建议","g":"[transitive, usually passive]","lab":"formal","sc":"be recommended","ex":{"en":"A course of chemotherapy was indicated.","cn":"建议进行化疗。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"表明;说明","en":"If one thing indicates another, the first thing shows that the second is true or exists.","ex":{"en":"A survey of retired people has indicated that most are independent and enjoying life","cn":"对退休人员的调查表明，大部分人都自食其力,享受生活。"}},{"pos":"VERB 动词","cn":"暗示","en":"If you indicate an opinion, an intention, or a fact, you mention it in an indirect way.","ex":{"en":"Mr Rivers has indicated that he may resign","cn":"里弗斯先生暗示他可能会辞职。"}},{"pos":"VERB 动词","cn":"指示;指出","en":"If you indicate something to someone, you show them where it is, especially by pointing to it.","ex":{"en":"He indicated a chair. 'Sit down.'","cn":"他指着一把椅子说，“坐下。”"}},{"pos":"VERB 动词","cn":"是…的标志;象征;反映","en":"If one thing indicates something else, it is a sign of that thing.","ex":{"en":"Dreams can help indicate your true feelings","cn":"梦可以反映你的真实感情。"}},{"pos":"VERB 动词","cn":"(仪器等)指示，显示","en":"If a technical instrument indicates something, it shows a measurement or reading.","ex":{"en":"The needles that indicate your height are at the top right-hand corner","cn":"显示你身高的指针在右上角。"}},{"pos":"VERB 动词","cn":"(驾车时)打转向灯指示转弯","en":"When drivers indicate, they make lights flash on one side of their vehicle to show that they are going to turn in that direction.","ex":{"en":"He told us when to indicate and when to change gear.","cn":"他告诉我们何时打转向灯、何时换挡。"}}]},"examples":[{"en":"Kingston-upon-Thames, as the name indicates, is situated on the banks of the Thames.","cn":"泰晤士河畔金斯顿区，正如其名称所示，位于泰晤士河畔。"},{"en":"Our results indicate how misleading it could be to rely on this method.","cn":"我们的结果表明，依赖这种方法可能产生多么严重的误导。"}]},"informs":{"oxford":{"phon":"ɪnˈfɔːm","pos":"verb","senses":[{"en":"to tell sb about sth, especially in an official way","cn":"知会；通知；通告"},{"en":"to find out information about sth","cn":"了解；熟悉"}]}},"institute":{"media":{"uk":"media/uk/institute__gb_1.mp3","us":"media/us/institute__us_1.mp3"},"oxford":{"phon":"ˈɪnstɪtjuːt","pos":"noun","senses":[{"en":"an organization that has a particular purpose, especially one that is connected with education or a particular profession; the building used by this organization","cn":"（教育、专业等）机构，机构建筑","ex":{"en":"The report was compiled by Germany's five leading economic research institutes.","cn":"该报告由德国五家领先的经济研究机构编制。"}},{"en":"to introduce a system, policy, etc. or start a process","cn":"建立，制定（体系、政策等）；开始；实行","ex":{"en":"The new management intends to institute a number of changes.","cn":"新任管理层打算实行一些改革。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"机构;协会;研究院;学院","en":"An institute is an organization set up to do a particular type of work, especially research or teaching. You can also use institute to refer to the building the organization occupies.","ex":{"en":"...the National Cancer Institute.","cn":"国家癌症研究所"}},{"pos":"VERB 动词","cn":"建立(体系等);制定(规章等);开始;开创","en":"If you institute a system, rule, or course of action, you start it.","ex":{"en":"We will institute a number of measures to better safeguard the public","cn":"我们将实施一系列措施来更好地保护公众安全。"}}]},"examples":[{"en":"The new management intends to institute a number of changes.","cn":"新任管理部门打算实行一些改革。"},{"en":"the Institute of Chartered Accountants （","cn":"英国皇家）特许会计师协会"}]},"interactivity":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"the sets of programs that tell a computer what to do","cn":""},{"en":"a set of instructions used to tell a computer what to do","cn":""}]},"examples":[{"en":"interactive teaching methods such as role playing","cn":"","src":"ld"},{"en":"the museum’s interactive exhibits","cn":"","src":"ld"}],"media":{"uk":"media/uk/interactivity__gb_1.mp3","us":"media/us/interactivity__us_1.mp3"},"oxford":{"phon":"ˌɪntərækˈtɪvəti","pos":"noun","senses":[{"en":"the fact of allowing information to be passed continuously and in both directions between a computer or other device and the person who uses it","cn":"交互式的；人机对话的；互动的","lab":"computing","ex":{"en":"You can also add interactivity to your website free of charge.","cn":"您还可以免费为您的网站添加互动功能。"}},{"en":"the fact of people working together and having an influence on each other","cn":"合作的；相互影响的；互相配合的","ex":{"en":"globalization and relatively high levels of interactivity across continents","cn":"全球化和各大洲相对较高水平的互动性"}}]}},"instructions":{"oxford":{"phon":"ɪnˈstrʌkʃn","pos":"noun","senses":[{"en":"detailed information on how to do or use sth","cn":"用法说明；操作指南"},{"en":"something that sb tells you to do","cn":"指示；命令；吩咐"}]},"media":{"uk":"media/uk/instruction__gb_1.mp3","us":"media/us/instruction__us_1.mp3"}},"including":{"media":{"uk":"media/uk/including__gb_1.mp3","us":"media/us/including__us_1.mp3"},"oxford":{"phon":"ɪnˈkluːdɪŋ","pos":"preposition","senses":[{"en":"having something as part of a group or set","cn":"包括…在内","ex":{"en":"I've got three days' holiday including New Year's Day.","cn":"包括元旦在内我有三天假。"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"(表示示例)包括","en":"You use including to introduce examples of people or things that are part of the group of people or things that you are talking about.","ex":{"en":"Stars including Joan Collins are expected to attend.","cn":"包括琼·柯林斯在内的明星们,届时预计会参加。"}}]},"examples":[{"en":"Six people were killed in the riot, including a policeman.","cn":"暴乱中有六人死亡，包括一名警察。"},{"en":"It's £7.50, not including tax.","cn":"共计 7.50 英镑，不含税款。"}]},"incorrectly":{"oxford":{"phon":"ˌɪnkəˈrektli","pos":"adverb","senses":[{"en":"in a way that is not accurate or true","cn":"不准确的；不正确的；不真实的","ex":{"en":"an incorrectly addressed letter","cn":"地址有误的信件"}},{"en":"in the wrong way; not as it should be","cn":"错误地：错误地 不是应该的","ex":{"en":"Fireworks can be very dangerous if used incorrectly.","cn":"如果使用不当，烟花可能非常危险。"}}]},"media":{"uk":"media/uk/incorrectly__gb_1.mp3","us":"media/us/incorrectly__us_1.mp3"},"examples":[{"en":"an incorrectly addressed letter","cn":"地址有误的信件"},{"en":"The information you gave us was incorrect.","cn":""}]},"interdisciplinary":{"oxford":{"phon":"ˌɪntədɪsəˈplɪnəri","pos":"adjective","senses":[{"en":"involving different areas of knowledge or study","cn":"多学科的；跨学科的","ex":{"en":"interdisciplinary research","cn":"跨学科研究"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"学科间的;涉及若干学科的;跨学科的","en":"Interdisciplinary means involving more than one academic subject.","ex":{"en":"...interdisciplinary courses combining psychology, philosophy and linguistics.","cn":"综合了心理学、哲学与语言学的跨学科课程"}}]},"media":{"uk":"media/uk/interdisciplinary__gb_1.mp3","us":"media/us/interdisciplinary__us_1.mp3"},"examples":[{"en":"interdisciplinary research","cn":"跨学科研究"},{"en":"an interdisciplinary approach","cn":"跨学科方法"}]},"inlet":{"media":{"uk":"media/uk/inlet__gb_1.mp3","us":"media/us/inlet__us_1.mp3"},"oxford":{"phon":"ˈɪnlet","pos":"noun","senses":[{"en":"a narrow area of water that stretches into the land from the sea or a lake, or between islands","cn":"（海、湖伸向陆地或岛屿间的）小湾，水湾","ex":{"en":"a narrow/sheltered/shallow inlet","cn":"狭窄/隐蔽/浅的入口"}},{"en":"an opening through which liquid, air or gas can enter a machine","cn":"（液体、空气或气体进入机器的）入口，进口","lab":"specialist","ex":{"en":"a fuel inlet","cn":"燃料进口"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(海或湖伸向陆地的狭长)水湾，小湾，小港","en":"An inlet is a narrow strip of water which goes from a sea or lake into the land.","ex":{"en":"...a sheltered inlet.","cn":"避风的小港湾"}},{"pos":"N-COUNT 可数名词","cn":"(机器上液体的)进口,入口","en":"An inlet is a part of a machine through which a flow of liquid enters.","ex":{"en":"...a blocked water inlet.","cn":"被堵死的入水孔"}}]},"examples":[{"en":"a fuel inlet","cn":"燃料进口"},{"en":"There are several sheltered inlets along the coast.","cn":"沿着海岸线有几处有天然屏障的水湾。"}]},"increasingly":{"media":{"uk":"media/uk/increasingly__gb_1.mp3","us":"media/us/increasingly__us_1.mp3"},"oxford":{"phon":"ɪnˈkriːsɪŋli","pos":"adverb","senses":[{"en":"more and more all the time","cn":"越来越多地；不断增加地","ex":{"en":"Tourism is playing an increasingly important role in the region's economy","cn":"旅游业在该地区经济中发挥着越来越重要的作用"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"渐增地;越来越多地","en":"You can use increasingly to indicate that a situation or quality is becoming greater in intensity or more common.","ex":{"en":"He was finding it increasingly difficult to make decisions","cn":"他发现越来越难以作出决定。"}}]},"examples":[{"en":"Increasingly, training is taking place in the office rather than outside it.","cn":"越来越多的职场培训在工作场所举行，而不是出外培训。"},{"en":"It is becoming increasingly clear that this problem will not be easily solved.","cn":"越来越明显的是，这个问题不会轻易解决。"}]},"internship":{"oxford":{"phon":"ˈɪntɜːnʃɪp","pos":"noun","senses":[{"en":"a period of time during which a student or new graduate gets practical experience in a job, for example during the summer holiday","cn":"（学生或毕业生的）实习期","ex":{"en":"an internship at a television station","cn":"在电视台的实习期"}},{"en":"a job that an advanced student of medicine, whose training is nearly finished, does in a hospital to get further practical experience","cn":"（医科学生的）实习工作","lab":"North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"实习岗位;实习期","en":"An internship is the position held by an intern, or the period of time when someone is an intern."}]},"media":{"uk":"media/uk/internship__gb_1.mp3","us":"media/us/internship__us_1.mp3"},"examples":[{"en":"an internship at a television station","cn":"在电视台的实习期"}]},"invulnerable":{"media":{"uk":"media/uk/invulnerable__gb_1.mp3","us":"media/us/invulnerable__us_1.mp3"},"oxford":{"phon":"ɪnˈvʌlnərəbl","pos":"adjective","senses":[{"en":"that cannot be harmed or defeated","cn":"不会受伤害的；打不败的","ex":{"en":"to be in an invulnerable position","cn":"立于不败之地"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不会受伤害的;刀枪不入的;攻不破的","en":"If someone or something is invulnerable, they cannot be harmed or damaged.","ex":{"en":"Many daughters assume that their mothers are invulnerable.","cn":"很多女儿都认为她们的母亲无比坚强。"}}]},"examples":[{"en":"The submarine is invulnerable to attack while at sea.","cn":"潜艇在海上是不会受到攻击的。"},{"en":"to be in an invulnerable position","cn":"立于不败之地"}]},"insensible":{"oxford":{"phon":"ɪnˈsensəbl","pos":"adjective","senses":[{"en":"unable to feel something or react to it","cn":"（对某事物）无感觉，无反应能力，麻木","g":"[not before noun]","ex":{"en":"insensible to pain/cold","cn":"感觉不到疼痛／冷"}},{"en":"not aware of a situation or of something that might happen","cn":"未察觉；意识不到","g":"[not before noun]","ex":{"en":"They were not insensible of the risks.","cn":"他们对这些危险并非没有意识。"}},{"en":"unconscious as the result of injury, illness, etc.","cn":"失去知觉；昏迷","ex":{"en":"He drank himself insensible.","cn":"他喝酒醉得不省人事。"}}]},"media":{"uk":"media/uk/insensible__gb_1.mp3","us":"media/us/insensible__us_1.mp3"},"examples":[{"en":"They were not insensible of the risks.","cn":"他们对这些危险并非没有意识。"},{"en":"He drank himself insensible.","cn":"他喝酒醉得不省人事。"}]},"indoors":{"media":{"uk":"media/uk/indoors__gb_1.mp3","us":"media/us/indoors__us_1.mp3"},"oxford":{"phon":"ˌɪnˈdɔːz","pos":"adverb","senses":[{"en":"inside or into a building","cn":"在室内；进入户内","ex":{"en":"I prefer to stay indoors in this really hot weather.","cn":"在这么热的天气里我更喜欢待在室内。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"在室内;在屋里","en":"If something happens indoors, it happens inside a building.","ex":{"en":"Since she was indoors, she had not been wearing a coat","cn":"由于她在室内,就没有穿外套。"}}]},"examples":[{"en":"Many herbs can be grown indoors.","cn":"很多香草植物能在室内种植。"},{"en":"to go/stay indoors","cn":"进入/留在屋里"}]},"intelligible":{"oxford":{"phon":"ɪnˈtelɪdʒəbl","pos":"adjective","senses":[{"en":"that can be easily understood","cn":"易懂的；容易理解的","ex":{"en":"His lecture was readily intelligible to all the students.","cn":"他的讲课学生们都能轻松地听懂。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可理解的;明白易懂的","en":"Something that is intelligible can be understood.","ex":{"en":"The language of Darwin was intelligible to experts and non-experts alike","cn":"达尔文的语言无论对专家还是非专业人士而言都明白易懂。"}}]},"media":{"uk":"media/uk/intelligible__gb_1.mp3","us":"media/us/intelligible__us_1.mp3"},"examples":[{"en":"His lecture was readily intelligible to all the students.","cn":"他的讲课学生们都能轻松地听懂。"},{"en":"His reply was barely intelligible.","cn":"他的回答几乎让人听不懂。"}]},"indifference":{"media":{"uk":"media/uk/indifference__gb_1.mp3","us":"media/us/indifference__us_1.mp3"},"oxford":{"phon":"ɪnˈdɪfrəns","pos":"noun","senses":[{"en":"a lack of interest, feeling or reaction towards somebody/something","cn":"漠不关心；冷淡；不感兴趣；无动于衷","g":"[uncountable, singular]","ex":{"en":"his total indifference to what people thought of him","cn":"他对别人怎么看他丝毫不在乎的态度"}},{"en":"lack of importance","cn":"无关紧要","g":"[uncountable]","lab":"formal","ex":{"en":"This cannot be regarded as a matter of indifference.","cn":"这事不能视为无关紧要。"}},{"en":"the fact of being average or not very good","cn":"平庸；普通","g":"[uncountable]","ex":{"en":"the indifference of the midfield players","cn":"中场球员的平庸"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"不感兴趣;不关心;冷淡","en":"If you accuse someone of indifference to something, you mean that they have a complete lack of interest in it.","ex":{"en":"...his callous indifference to the plight of his son.","cn":"他对儿子所处困境的无情漠视"}}]},"examples":[{"en":"his total indifference to what people thought of him","cn":"他对别人怎么看他丝毫不在乎的态度"},{"en":"What she said is a matter of complete indifference to me.","cn":"她的话对于我来说完全无关紧要。"}]},"infected":{"media":{"uk":"media/uk/infected__gb_1.mp3","us":"media/us/infected__us_1.mp3"},"oxford":{"phon":"ɪnˈfektɪd","pos":"adjective","senses":[{"en":"affected by harmful bacteria, a virus, etc.","cn":"受（有害细菌、病毒等）感染的","ex":{"en":"The wound from the dog bite had become infected.","cn":"狗咬的伤口感染了。"}},{"en":"affected by a computer virus","cn":"感染电脑病毒的","lab":"computing","ex":{"en":"an infected PC","cn":"中了病毒的个人电脑"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(地方等)受(微生物或细菌)污染的","en":"An infected place is one where germs or bacteria are causing a disease to spread among people or animals.","ex":{"en":"In heavily infected areas, half the population become blind.","cn":"在受污染严重的地区,有一半人口失明。"}}]},"examples":[{"en":"The wound from the dog bite had become infected.","cn":"狗咬的伤口感染了。"},{"en":"an infected water supply","cn":"受污染的供水系统"}]},"invests":{"oxford":{"phon":"ɪnˈvest","pos":"verb","senses":[{"en":"to buy property, shares in a company, etc. in the hope of making a profit","cn":"投资"},{"en":"to spend money on sth in order to make it better or more successful （","cn":"把资金）投入"}]},"media":{"uk":"media/uk/invest__gb_1.mp3","us":"media/us/invest__us_1.mp3"}},"incidents":{"oxford":{"phon":"ˈɪnsɪdənt","pos":"noun","senses":[{"en":"something that happens, especially sth unusual or unpleasant","cn":"发生的事情（尤指不寻常的或讨厌的）"},{"en":"a serious or violent event, such as a crime, an accident or an attack","cn":"严重事件，暴力事件（如犯罪、事故、袭击等）"}]}},"interactive":{"media":{"uk":"media/uk/interactive__gb_1.mp3","us":"media/us/interactive__us_1.mp3"},"oxford":{"phon":"ˌɪntərˈæktɪv","pos":"adjective","senses":[{"en":"that allows information to be passed continuously and in both directions between a computer or other device and the person who uses it","cn":"交互式的；人机对话的；互动的","lab":"computing","ex":{"en":"interactive displays/video","cn":"交互式显示屏／视频"}},{"en":"that involves people working together and having an influence on each other","cn":"合作的；相互影响的；互相配合的","ex":{"en":"The school believes in interactive teaching methods.","cn":"这所学校推崇互动教学法。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"交互的;人机对话的","en":"An interactive computer program or television system is one which allows direct communication between the user and the machine.","ex":{"en":"This will make videogames more interactive than ever.","cn":"这将使电子游戏的互动性更胜以往。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"互动的;互相交流的","en":"If you describe a group of people or their activities as interactive, you mean that the people communicate with each other.","ex":{"en":"...flexible, interactive teaching in the classroom.","cn":"课堂上灵活互动的教学"}}]},"examples":[{"en":"The school believes in interactive teaching methods.","cn":"这所学校推崇互动教学法。"},{"en":"interactive systems/video","cn":"交互式系统/视频"}]},"input":{"media":{"uk":"media/uk/input__gb_1.mp3","us":"media/us/input__us_1.mp3"},"oxford":{"phon":"ˈɪnpʊt","pos":"noun","senses":[{"en":"time, knowledge, ideas, etc. that you put into work, a project, etc. in order to make it succeed; the act of putting something in","cn":"投入资源（指时间、知识、思想等）；投入；输入","g":"[countable, uncountable]","ex":{"en":"I'd appreciate your input on this.","cn":"我将感激你在这方面的投入。"}},{"en":"the act of putting information into a computer; the information that you put in","cn":"输入；输入的信息","g":"[uncountable]","lab":"computing","ex":{"en":"data input","cn":"数据输入"}},{"en":"a place or means for electricity, data, etc. to enter a machine or system","cn":"（电、数据等的）输入端","g":"[countable]","lab":"specialist","ex":{"en":"an input lead","cn":"输入引线"}},{"en":"to put information into a computer","cn":"输入（信息）","ex":{"en":"to input text/data/figures","cn":"把文本／数据／数字输入计算机"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"投入物(指信息、资源等)","en":"Input consists of information or resources that a group or project receives.","ex":{"en":"We listen to our employees and value their input","cn":"我们听取员工的想法,重视他们的意见和建议。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"输入信息","en":"Input is information that is put into a computer."},{"pos":"VERB 动词","cn":"输入(信息)","en":"If you input information into a computer, you feed it in, for example by typing it on a keyboard.","ex":{"en":"All this information had to be input onto the computer.","cn":"所有这些信息都必须输入计算机。"}}]},"examples":[{"en":"This program accepts input from most word processors.","cn":"这个程序可接受大多数文字处理系统输入的信息。"},{"en":"Her specialist input to the discussions has been very useful.","cn":"她在这些讨论中提供的专家建议很有助益。"}]},"intrepid":{"media":{"uk":"media/uk/intrepid__gb_1.mp3","us":"media/us/intrepid__us_1.mp3"},"oxford":{"phon":"ɪnˈtrepɪd","pos":"adjective","senses":[{"en":"very brave; not afraid of danger or difficulties","cn":"勇敢的；无畏的","ex":{"en":"Traders and missionaries often proved themselves to be intrepid explorers.","cn":"商人和传教士经常证明自己是勇敢的探险家。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"勇敢的;无畏的","en":"An intrepid person acts in a brave way.","ex":{"en":"...an intrepid space traveller.","cn":"无畏的太空旅行者"}}]},"examples":[{"en":"an intrepid explorer","cn":"勇敢的探险家"},{"en":"intrepid explorers","cn":"勇敢的探险家"}]},"infancy":{"media":{"uk":"media/uk/infancy__gb_1.mp3","us":"media/us/infancy__us_1.mp3"},"oxford":{"phon":"ˈɪnfənsi","pos":"noun","senses":[{"en":"the time when a child is a baby or very young","cn":"婴儿期；幼儿期","ex":{"en":"to die in infancy","cn":"婴儿夭折"}},{"en":"the early development of something","cn":"初期；初创期","ex":{"en":"a time when the cinema was still in its infancy","cn":"电影业刚刚起步的时期"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"婴儿期;幼年","en":"Infancy is the period of your life when you are a very young child.","ex":{"en":"...minute details of Deborah's infancy.","cn":"德博拉幼年生活的详尽细节"}},{"pos":"N-UNCOUNT 不可数名词","cn":"初期;初创阶段","en":"If something is in its infancy, it is new and has not developed very much.","ex":{"en":"Computing science was still in its infancy.","cn":"计算科学仍然处于初期阶段。"}}]},"examples":[{"en":"a time when the cinema was still in its infancy","cn":"电影业尚处于初创的时期"},{"en":"to die in infancy","cn":"婴儿夭折"}]},"injured":{"oxford":{"phon":"ˈɪndʒəd","pos":"adjective","senses":[{"en":"physically hurt; having an injury","cn":"受伤的；有伤的","ex":{"en":"His injured leg prevented him from walking.","cn":"他的腿受伤了，没法走路。"}},{"en":"the people injured in an accident, a battle, etc.","cn":"受伤的人；伤员；伤兵","g":"[plural]","ex":{"en":"Ambulances took the injured to a nearby hospital.","cn":"救护车把伤者送到了附近的一所医院。"}},{"en":"upset or offended because something unfair has been done","cn":"委屈的；受到伤害的","ex":{"en":"an injured look/tone","cn":"委屈的样子／语调"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"受伤的;有伤的","en":"An injured person or animal has physical damage to part of their body, usually as a result of an accident or fighting.","ex":{"en":"The other injured man had a superficial stomach wound","cn":"另一名受伤男子是腹部的皮外伤。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(感情)受到伤害的","en":"If you have injured feelings, you feel upset because you believe someone has been unfair or unkind to you.","ex":{"en":"...a look of injured pride.","cn":"自尊心受到伤害的表情"}}]},"media":{"uk":"media/uk/injured__gb_1.mp3","us":"media/us/injured__us_1.mp3"},"examples":[{"en":"Ambulances took the injured to a nearby hospital.","cn":"救护车把伤者送到了附近的一所医院。"},{"en":"Carter is playing in place of the injured O'Reilly.","cn":"卡特替代受伤的奥赖利上场比赛。"}]},"incontinence":{"oxford":{"phon":"ɪnˈkɒntɪnəns","pos":"noun","senses":[{"en":"the lack of ability to control the bladder and bowels","cn":"失禁"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(大便或小便)失禁","en":"Incontinence is the inability to prevent urine or faeces coming out of your body.","ex":{"en":"Incontinence is not just a condition of old age.","cn":"大小便失禁不仅仅是一种老年病。"}}]},"media":{"uk":"media/uk/incontinence__gb_1.mp3","us":"media/us/incontinence__us_1.mp3"},"examples":[{"en":"Many of our patients are incontinent.","cn":"我们很多病人都有失禁现象。"}]},"innovate":{"oxford":{"phon":"ˈɪnəveɪt","pos":"verb","senses":[{"en":"to introduce new things, ideas or ways of doing something","cn":"引入（新事物、思想或方法）；创新；改革","ex":{"en":"We must constantly adapt and innovate to ensure success in a growing market.","cn":"我们必须不时地适应并创新，以确保在不断扩大的市场中取得成功。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"革新;创新;改革","en":"To innovate means to introduce changes and new ideas in the way something is done or made.","ex":{"en":"...his constant desire to innovate and experiment.","cn":"他不断进行创新和实验的渴望"}}]},"media":{"uk":"media/uk/innovate__gb_1.mp3","us":"media/us/innovate__us_1.mp3"},"examples":[{"en":"We must constantly adapt and innovate to ensure success in a growing market.","cn":"我们必须不时地适应并创新，以确保在不断扩大的市场中取得成功。"},{"en":"to innovate new products","cn":"创造新产品"}]},"inadvertently":{"media":{"uk":"media/uk/inadvertently__gb_1.mp3","us":"media/us/inadvertently__us_1.mp3"},"oxford":{"phon":"ˌɪnədˈvɜːtntli","pos":"adverb","senses":[{"en":"by accident; without intending to","cn":"无意地；不经意地","ex":{"en":"We had inadvertently left without paying the bill.","cn":"我们无意之中未付账就离开了。"}}]},"examples":[{"en":"We had inadvertently left without paying the bill.","cn":"我们无意之中未付账就离开了。"},{"en":"an inadvertent omission","cn":"不经意的疏忽"}]},"inherent":{"media":{"uk":"media/uk/inherent__gb_1.mp3","us":"media/us/inherent__us_1.mp3"},"oxford":{"phon":"ɪnˈherənt","pos":"adjective","senses":[{"en":"that is a basic or permanent part of somebody/something and that cannot be removed","cn":"固有的；内在的","ex":{"en":"the difficulties inherent in a study of this type","cn":"这类研究本身的困难"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"内在的;固有的;生来就有的","en":"The inherent qualities of something are the necessary and natural parts of it.","ex":{"en":"Stress is an inherent part of dieting.","cn":"节食必定会带来压力。"}}]},"examples":[{"en":"Violence is inherent in our society.","cn":"在我们的社会中暴力是难免的。"},{"en":"an inherent weakness in the design of the machine","cn":"机器设计中的内在缺陷"}]},"institutionalized":{"media":{"uk":"media/uk/institutionalized__gb_1.mp3","us":"media/us/institutionalized__us_1.mp3"},"oxford":{"phon":"ˌɪnstɪˈtjuːʃənəlaɪzd","pos":"adjective","senses":[{"en":"that has become established as part of the normal systems, practices, etc. of an organization, society or culture","cn":"约定俗成的；成惯例的","lab":"usually disapproving","ex":{"en":"institutionalized racism","cn":"由来已久的种族偏见"}},{"en":"not able to live and think independently because they have spent so long in an institution such as a hospital or prison","cn":"（因长期坐牢﹑待在精神病院等而）无法适应外界生活的","ex":{"en":"institutionalized patients","cn":"失去自理能力的病人"}}]},"examples":[{"en":"institutionalized racism","cn":"由来已久的种族偏见"},{"en":"institutionalized patients","cn":"失去自理能力的病人"}]},"indulge":{"media":{"uk":"media/uk/indulge__gb_1.mp3","us":"media/us/indulge__us_1.mp3"},"oxford":{"phon":"ɪnˈdʌldʒ","pos":"verb","senses":[{"en":"to allow yourself to have or do something that you like, especially something that is considered bad for you","cn":"沉湎，沉迷，沉溺（于…）","g":"[intransitive, transitive]","ex":{"en":"They went into town to indulge in some serious shopping.","cn":"他们进城去大肆购物。"}},{"en":"to satisfy a particular desire, interest, etc.","cn":"满足（欲望、兴趣等）","g":"[transitive]","ex":{"en":"The inheritance enabled him to indulge his passion for art.","cn":"这笔遗产使他能够尽情投入他热爱的艺术。"}},{"en":"to be too generous in allowing somebody to have or do whatever they like","cn":"放纵；听任","g":"[transitive]","ex":{"en":"She did not believe in indulging the children with presents.","cn":"她认为不能惯着孩子们要什么就给什么。"}},{"en":"to take part in an activity, especially one that is illegal","cn":"参加，参与（尤指违法活动）","g":"[intransitive]"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(使自己)沉迷;放纵(自己)","en":"If you indulge in something or if you indulge yourself, you allow yourself to have or do something that you know you will enjoy.","ex":{"en":"Only rarely will she indulge in a glass of wine","cn":"她只是偶尔才喝杯红酒,让自己享受一下。"}},{"pos":"VERB 动词","cn":"纵容;迁就;娇惯","en":"If you indulge someone, you let them have or do what they want, even if this is not good for them.","ex":{"en":"He did not agree with indulging children.","cn":"他反对纵容娇惯孩子。"}}]},"examples":[{"en":"The inheritance enabled him to indulge his passion for art.","cn":"这笔遗产使他能够尽情投入他热爱的艺术。"},{"en":"She did not believe in indulging the children with presents.","cn":"她认为不能惯着孩子们要什么就给什么。"}]},"informing":{"oxford":{"phon":"ɪnˈfɔːm","pos":"verb","senses":[{"en":"to tell sb about sth, especially in an official way","cn":"知会；通知；通告"},{"en":"to find out information about sth","cn":"了解；熟悉"}]}},"invent":{"oxford":{"phon":"ɪnˈvent","pos":"verb","senses":[{"en":"to produce or design something that has not existed before","cn":"发明；创造","ex":{"en":"Who invented the steam engine?","cn":"谁发明了蒸汽机？"}},{"en":"to say or describe something that is not true, especially in order to trick people","cn":"编造；捏造；虚构","ex":{"en":"What excuse did he invent this time?","cn":"他这次编了什么借口？"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"发明;创造;首创","en":"If you invent something such as a machine or process, you are the first person to think of it or make it.","ex":{"en":"He invented the first electric clock","cn":"他发明了第一个电动机械钟。"}},{"pos":"VERB 动词","cn":"编造;捏造;虚构","en":"If you invent a story or excuse, you try to make other people believe that it is true when in fact it is not.","ex":{"en":"I stood still, trying to invent a plausible excuse.","cn":"我站着不动,试图编个说得过去的借口。"}}]},"media":{"uk":"media/uk/invent__gb_1.mp3","us":"media/us/invent__us_1.mp3"},"examples":[{"en":"Many children invent an imaginary friend.","cn":"很多儿童都有一个假想朋友。"},{"en":"What excuse did he invent this time?","cn":"他这次编了什么借口？"}]},"into":{"media":{"uk":"media/uk/into__gb_1.mp3","us":"media/us/into__us_1.mp3"},"oxford":{"phon":"ˈɪntə","pos":"preposition","senses":[{"en":"to a position in or inside something","cn":"到…里面；进入","lab":"figurative","ex":{"en":"Come into the house.","cn":"进屋里来吧。"}},{"en":"in the direction of something","cn":"朝；向；对着","ex":{"en":"Speak clearly into the microphone.","cn":"清楚地对着麦克风讲话。"}},{"en":"to a point at which you hit somebody/something","cn":"撞上；碰上","ex":{"en":"The truck crashed into a parked car.","cn":"卡车撞上了一辆停放着的汽车。"}},{"en":"to a point during a period of time","cn":"到（一段时间的某一点）","ex":{"en":"She carried on working late into the night.","cn":"她一直工作到了深夜。"}},{"en":"used to show a change in state","cn":"（表示状态的变化）","ex":{"en":"The fruit can be made into jam.","cn":"这种水果可以制成果酱。"}},{"en":"used to show the result of an action","cn":"（表示行动的结果）","ex":{"en":"He was shocked into a confession of guilt.","cn":"他被吓得认罪了。"}},{"en":"about or in connection with something","cn":"关于；有关","ex":{"en":"an inquiry into safety procedures","cn":"关于安全程序的调查"}},{"en":"used when you are dividing numbers","cn":"（用于除数）除","ex":{"en":"3 into 24 is 8.","cn":"24 除以 3 等于 8。"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"(放)到…里面","en":"If you put one thing into another, you put the first thing inside the second.","ex":{"en":"Combine the remaining ingredients and put them into a dish","cn":"把剩下的配料调和好，放到一个盘子里。"}},{"pos":"PREP 介词","cn":"进入(地方、车辆)","en":"If you go into a place or vehicle, you move from being outside it to being inside it.","ex":{"en":"I have no idea how he got into Iraq","cn":"我不知道他是怎样进入伊拉克的。"}},{"pos":"PREP 介词","cn":"(打破或损坏表面而)进入,插入","en":"If one thing goes into another, the first thing moves from the outside to the inside of the second thing, by breaking or damaging the surface of it.","ex":{"en":"Flavell had accidentally discharged a pistol, firing it into the ceiling","cn":"弗拉维尔不小心扳动了一把手枪的扳机，子弹射入了天花板。"}},{"pos":"PREP 介词","cn":"(融)入;(渗)入;(进)入","en":"If one thing gets into another, the first thing enters the second and becomes part of it.","ex":{"en":"Poisonous smoke had got into the water supply","cn":"毒烟已经进入供水系统。"}},{"pos":"PREP 介词","cn":"(碰)上;(撞)上","en":"If you are walking or driving a vehicle and you bump into something or crash into something, you hit it accidentally.","ex":{"en":"A train plowed into the barrier at the end of the platform","cn":"火车撞上了月台尽头的栅栏。"}},{"pos":"PREP 介词","cn":"(穿)上;(换)上","en":"When you get into a piece of clothing, you put it on.","ex":{"en":"She could change into a different outfit in two minutes","cn":"她能在两分钟内换上一套不同的行头。"}},{"pos":"PREP 介词","cn":"进入(…状态)","en":"If someone or something gets into a particular state, they start being in that state.","ex":{"en":"He had too much time on his hands and that caused him to get into trouble","cn":"他手头时间太富裕了,反倒为他惹来了麻烦。"}},{"pos":"PREP 介词","cn":"(说服某人)去做…","en":"If you talk someone into doing something, you persuade them to do it.","ex":{"en":"Gerome tried to talk her into taking an apartment in Paris.","cn":"杰罗姆试图说服她在巴黎买一套公寓。"}},{"pos":"PREP 介词","cn":"成为;转变为","en":"If something changes into something else, it then has a new form, shape, or nature.","ex":{"en":"...his attempt to turn a nasty episode into a joke.","cn":"他想把一段很不愉快的插曲变成一则笑话的尝试"}},{"pos":"PREP 介词","cn":"(分)成;(撕)成","en":"If something is cut or split into a number of pieces or sections, it is divided so that it becomes several smaller pieces or sections.","ex":{"en":"Sixteen teams are taking part, divided into four groups","cn":"有16个队参加,分为4组。"}},{"pos":"PREP 介词","cn":"关于;涉及","en":"An investigation into a subject or event is concerned with that subject or event.","ex":{"en":"The concert will raise funds for research into Aids","cn":"这场音乐会将为艾滋病研究筹集资金。"}},{"pos":"PREP 介词","cn":"进入,转向(某一职业、行业)","en":"If you move or go into a particular career or business, you start working in it.","ex":{"en":"In the early 1990s, it was easy to get into the rental business","cn":"20 世纪 90 年代早期,进入租赁行业很容易。"}},{"pos":"PREP 介词","cn":"持续到，进入(时间段)","en":"If something continues into a period of time, it continues until after that period of time has begun.","ex":{"en":"He had three children, and lived on into his sixties","cn":"他有3个孩子,已经60多岁了。"}},{"pos":"PREP 介词","cn":"对…很感兴趣;极喜欢","en":"If you are very interested in something and like it very much, you can say that you are into it.","ex":{"en":"I'm into electronics myself.","cn":"我本身对电子很感兴趣。"}}]},"examples":[{"en":"By the time he'd fixed the leak, I was into him for $500.","cn":"他补好漏洞时，我就该付给他 500 元。"},{"en":"Driving into the sun, we had to shade our eyes.","cn":"面向太阳开车，我们只好遮挡着眼睛。"}]},"incredibly":{"media":{"uk":"media/uk/incredibly__gb_1.mp3","us":"media/us/incredibly__us_1.mp3"},"oxford":{"phon":"ɪnˈkredəbli","pos":"adverb","senses":[{"en":"extremely","cn":"极端地；极其","ex":{"en":"It was all incredibly difficult.","cn":"这一切都极为困难。"}},{"en":"in a way that is very difficult to believe","cn":"令人难以置信","ex":{"en":"Incredibly, she had no idea what was going on.","cn":"令人难以置信的是，她当时对发生的事一无所知。"}}]},"examples":[{"en":"Incredibly, she had no idea what was going on.","cn":"令人难以置信的是，她当时对发生的事一无所知。"},{"en":"incredibly lucky/stupid/difficult/beautiful","cn":"极其幸运/愚蠢/困难/美丽"}]},"inferior":{"oxford":{"phon":"ɪnˈfɪəriə(r)","pos":"adjective","senses":[{"en":"not good or not as good as somebody/something else","cn":"较差的；次的；比不上…的","ex":{"en":"of inferior quality","cn":"劣质的"}},{"en":"of lower rank; lower","cn":"级别低的；较低的","g":"[usually before noun]","lab":"formal","ex":{"en":"an inferior officer","cn":"下级军官"}},{"en":"a person who is not as good as somebody else; a person who is lower in rank or status","cn":"不如别人的人；级别（或地位）低的人","ex":{"en":"She considered everyone her intellectual inferior.","cn":"她认为谁都不如她聪明。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(质量等)差的,次的","en":"Something that is inferior is not as good as something else.","ex":{"en":"The cassettes were of inferior quality","cn":"那些磁带质量较差。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(地位、能力等)低等的,低于…的;下级的","en":"If one person is regarded as inferior to another, they are regarded as less important because they have less status or ability.","ex":{"en":"He preferred the company of those who were intellectually inferior to himself.","cn":"他喜欢与那些智力水平不如他的人共处。"}}]},"media":{"uk":"media/uk/inferior__gb_1.mp3","us":"media/us/inferior__us_1.mp3"},"examples":[{"en":"Modern music is often considered inferior to that of the past.","cn":"现代音乐常被认为不如过去的。"},{"en":"to make sb feel inferior","cn":"使某人自惭形秽"}]},"incentivize":{"media":{"uk":"media/uk/incentivize__gb_1.mp3","us":"media/us/incentivize__us_2.mp3"},"oxford":{"phon":"ɪnˈsentɪvaɪz","pos":"verb","senses":[{"en":"to encourage somebody to behave in a particular way by offering them a reward","cn":"激励；奖励","ex":{"en":"ways to incentivize innovation","cn":"奖励创新的途径"}}]},"examples":[{"en":"You need to incentivize your existing customers to stay with you.","cn":"你得奖励并留住现有客户。"},{"en":"ways to incentivize innovation","cn":"奖掖鼓励创新的途径"}]},"intimate":{"media":{"uk":"media/uk/intimate__gb_1.mp3","us":"media/us/intimate__us_1.mp3"},"oxford":{"phon":"ˈɪntɪmət","pos":"adjective","senses":[{"en":"having a close and friendly relationship","cn":"亲密的；密切的","ex":{"en":"intimate friends","cn":"密友"}},{"en":"private and personal, often in a sexual way","cn":"个人隐私的（常指性方面的）","ex":{"en":"The article revealed intimate details about his family life.","cn":"文章披露了他的家庭生活中的隐私。"}},{"en":"encouraging close, friendly relationships, sometimes of a sexual nature","cn":"宜于密切关系的；温馨的；便于有性关系的","ex":{"en":"an intimate restaurant","cn":"幽静温馨的餐厅"}},{"en":"very detailed","cn":"详尽的","ex":{"en":"an intimate knowledge of the English countryside","cn":"对英格兰乡村的透彻了解"}},{"en":"very close","cn":"紧密的；密切的","ex":{"en":"an intimate connection between class and educational success","cn":"社会阶层和优良教育之间的密切联系"}},{"en":"having a sexual relationship with somebody","cn":"有性关系的；暧昧的","lab":"formal or law"},{"en":"to let somebody know what you think or mean","cn":"表示；透露","ex":{"en":"He has already intimated to us his intention to retire.","cn":"他已经向我们透露了他退休的打算。"},"pos":"verb"},{"en":"a close personal friend","cn":"密友；至交；知己","ex":{"en":"He was a wartime minister and intimate of Churchill.","cn":"他是战时部长，也是丘吉尔的密友。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"亲密的;密切的","en":"If you have an intimate friendship with someone, you know them very well and like them a lot.","ex":{"en":"I discussed with my intimate friends whether I would immediately have a baby.","cn":"我与密友们讨论是否我要马上生孩子。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有恋爱关系的;有性关系的","en":"If two people are in an intimate relationship, they are involved with each other in a loving or sexual way.","ex":{"en":"I just won't discuss my intimate relationships.","cn":"我就是不想讨论我的恋爱关系。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"个人的;私下的;隐私的","en":"An intimate conversation or detail, for example, is very personal and private.","ex":{"en":"He wrote about the intimate details of his family life","cn":"他写到了关于他家庭生活的一些不为人知的细节。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"宁静怡人的;温馨的","en":"If you use intimate to describe an occasion or the atmosphere of a place, you like it because it is quiet and pleasant, and seems suitable for close conversations between friends.","ex":{"en":"...an intimate candlelit dinner for two.","cn":"温馨的二人烛光晚餐"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(联系)密切的，紧密的","en":"An intimate connection between ideas or organizations, for example, is a very strong link between them.","ex":{"en":"...an intimate connection between madness and wisdom","cn":"疯狂与智慧的密切关联"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"深刻的;详尽的;精通的","en":"An intimate knowledge of something is a deep and detailed knowledge of it.","ex":{"en":"He surprised me with his intimate knowledge of Kierkegaard and Schopenhauer.","cn":"他对克尔恺郭尔与叔本华的深刻了解让我很吃惊。"}},{"pos":"VERB 动词","cn":"暗示;提示","en":"If you intimate something, you say it in an indirect way.","ex":{"en":"He went on to intimate that he was indeed contemplating a shake-up of the company","cn":"他继续暗示他确实在考虑对公司进行一次大改组。"}}]},"examples":[{"en":"He knew an intimate little bar where they would not be disturbed.","cn":"他知道一处适合幽会的小酒吧，他们在那里不会受到打扰。"},{"en":"He has already intimated to us his intention to retire.","cn":"他已经向我们透露了他要退休的打算。"}]},"investment":{"media":{"uk":"media/uk/investment__gb_1.mp3","us":"media/us/investment__us_1.mp3"},"oxford":{"phon":"ɪnˈvestmənt","pos":"noun","senses":[{"en":"the act of investing money in something","cn":"投资","g":"[uncountable]","ex":{"en":"foreign/private investment","cn":"外国／私人投资"}},{"en":"the money that you invest, or the thing that you invest in","cn":"投资额；投资物","g":"[countable, uncountable]","lab":"North American English","ex":{"en":"a minimum investment of $10 000","cn":"1 万美元的最低投资额"}},{"en":"a thing that is worth buying because it will be useful or helpful","cn":"值得买的东西；有用的投资物","g":"[countable]","ex":{"en":"A microwave is a good investment.","cn":"微波炉值得买。"}},{"en":"the act of giving time or effort to a particular task in order to make it successful","cn":"（时间、精力的）投入","g":"[uncountable, countable]","ex":{"en":"The project has demanded considerable investment of time and effort.","cn":"该项目已让我们投入了相当多的时间和精力。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"投资","en":"Investment is the activity of investing money.","ex":{"en":"He said the government must introduce tax incentives to encourage investment","cn":"他说政府必须推出税收激励政策来鼓励投资。"}},{"pos":"N-VAR 可变名词","cn":"投资金额;投资物","en":"An investment is an amount of money that you invest, or the thing that you invest it in.","ex":{"en":"...an investment of twenty-eight million pounds","cn":"2,800万英镑的投资金额"}},{"pos":"N-COUNT 可数名词","cn":"有用的投资物;值得买的东西","en":"If you describe something you buy as an investment, you mean that it will be useful, especially because it will help you to do a task more cheaply or efficiently.","ex":{"en":"When selecting boots, fine, quality leather will be a wise investment","cn":"在挑选长筒靴的时候,购买上等的好皮靴将是明智的选择。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(时间、精力的)投入","en":"Investment of time or effort is the spending of time or effort on something in order to make it a success.","ex":{"en":"I worry about this big investment of time and effort.","cn":"我担心投入这么多时间与精力却不起作用。"}}]},"examples":[{"en":"The project has demanded considerable investment of time and effort.","cn":"该项目已让我们投入了相当多的时间和精力。"},{"en":"This country needs investment in education.","cn":"这个国家需要对教育进行投资。"}]},"indefinable":{"media":{"uk":"media/uk/indefinable__gb_1.mp3","us":"media/us/indefinable__us_1.mp3"},"oxford":{"phon":"ˌɪndɪˈfaɪnəbl","pos":"adjective","senses":[{"en":"difficult or impossible to define or explain","cn":"难以定义的；无法解释的","ex":{"en":"She has that indefinable something that makes an actress a star.","cn":"她具备了那种使演员成为明星的说不出的特质。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"难以确切表达的;难以确定的;模糊不清的","en":"An indefinable quality or feeling cannot easily be described.","ex":{"en":"There was something indefinable in her eyes","cn":"她的眼神里有种难以确定的东西。"}}]},"examples":[{"en":"She has that indefinable something that makes an actress a star.","cn":"她具备了那种使演员成为明星的说不出的特质。"},{"en":"She felt an indefinable sadness.","cn":"她感到一种难以名状的悲伤。"}]},"inquire":{"media":{"uk":"media/uk/inquire__gb_1.mp3","us":"media/us/inquire__us_1.mp3"},"collins":{"senses":[{"pos":"VERB 动词","cn":"询问;查询;打听","en":"If you inquire about something, you ask for information about it.","ex":{"en":"'Is something wrong?' he enquired","cn":"“有什么不对劲吗?”他问道。"}},{"pos":"VERB 动词","cn":"调查;查究","en":"If you inquire into something, you investigate it carefully.","ex":{"en":"Inspectors were appointed to inquire into the affairs of the company.","cn":"督查员受委派调查该公司的事务。"}},{"pos":"","cn":"","en":"相关词组：inquire after"}]},"examples":[{"en":"‘Why are you doing that?’ the boy inquired. “","cn":"你为什么这么做？”男孩问道。"},{"en":"I am writing to inquire about your advertisement in ‘The Times’.","cn":"贵方在《泰晤士报》刊登广告﹐特此致函问询。"}],"oxford":{"phon":"ɪnˈkwaɪə(r)","pos":"verb","senses":[{"en":"to ask somebody for some information","cn":"询问；打听","ex":{"en":"I called the school to inquire about the application process.","cn":"我给学校打电话询问申请流程。"}}]}},"interact":{"oxford":{"phon":"ˌɪntərˈækt","pos":"verb","senses":[{"en":"to communicate with somebody, especially while you work, play or spend time with them","cn":"交流；沟通；合作","g":"[intransitive]","ex":{"en":"Teachers have a limited amount of time to interact with each child.","cn":"教师和每个孩子沟通的时间有限。"}},{"en":"if one thing interacts with another, or if two things interact, the two things have an effect on each other","cn":"相互影响；相互作用","g":"[intransitive]","ex":{"en":"Perfume interacts with the skin's natural chemicals.","cn":"香水和皮肤的天然化学物质相互作用。"}}]},"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"相互交流;相互沟通","en":"When people interact with each other or interact, they communicate as they work or spend time together.","ex":{"en":"While the other children interacted and played together, Ted ignored them.","cn":"当别的孩子相互交流、一起玩耍的时候,泰德对他们不予理睬。"}},{"pos":"VERB 动词","cn":"(人与计算机或计算机与其他机器之间)交互作用，互动","en":"When people interact with computers, or when computers interact with other machines, information or instructions are exchanged.","ex":{"en":"Millions of people want new, simplified ways of interacting with a computer","cn":"数以百万计的人们想要新的简化方式实现人机交互。"}},{"pos":"V-RECIP 相互动词","cn":"相互作用;相互影响","en":"When one thing interacts with another or two things interact, the two things affect each other's behaviour or condition.","ex":{"en":"You have to understand how cells interact","cn":"你必须明白细胞是怎样相互作用的。"}}]},"media":{"uk":"media/uk/interact__gb_1.mp3","us":"media/us/interact__us_1.mp3"},"examples":[{"en":"Perfume interacts with the skin's natural chemicals.","cn":"香水和皮肤的天然化学物质相互作用。"},{"en":"the interaction of bacteria with the body's natural chemistry","cn":"细菌和身体的天然化学变化的相互作用"}]},"inseparable":{"media":{"uk":"media/uk/inseparable__gb_1.mp3","us":"media/us/inseparable__us_1.mp3"},"oxford":{"phon":"ɪnˈseprəbl","pos":"adjective","senses":[{"en":"not able to be separated","cn":"（与某事物）不可分离的，分不开的","ex":{"en":"Our economic fortunes are inseparable from those of Europe.","cn":"我们的经济命运和欧洲的息息相关。"}},{"en":"if people are inseparable, they spend most of their time together and are very good friends","cn":"形影不离的","ex":{"en":"As children, Laura and I were inseparable.","cn":"小时候，劳拉和我形影不离。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不可分割的;分不开的","en":"If one thing is inseparable from another, the things are so closely connected that they cannot be considered separately.","ex":{"en":"He firmly believes liberty is inseparable from social justice","cn":"他坚信自由与社会正义是不可分的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"形影不离的","en":"If you say that two people are inseparable, you are emphasizing that they are very good friends and spend a great deal of time together.","ex":{"en":"She and Kristin were inseparable.","cn":"她和克里斯廷形影不离。"}}]},"examples":[{"en":"Our economic fortunes are inseparable from those of Europe.","cn":"我们的经济命运和欧洲的息息相关。"},{"en":"Our lives were inseparably linked.","cn":"我们的生活息息相通。"}]},"inhibition":{"media":{"uk":"media/uk/inhibition__gb_1.mp3","us":"media/us/inhibition__us_1.mp3"},"oxford":{"phon":"ˌɪnhɪˈbɪʃn","pos":"noun","senses":[{"en":"a shy or nervous feeling that stops you from expressing your real thoughts or feelings","cn":"拘谨；拘束感","g":"[countable, uncountable]","ex":{"en":"The children were shy at first, but soon lost their inhibitions.","cn":"孩子们起初很羞涩，但很快就放开了。"}},{"en":"the act of limiting or preventing a process or an action","cn":"阻止；抑制；禁止","g":"[uncountable]","lab":"formal","ex":{"en":"the inhibition of growth","cn":"对生长的抑制"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"顾虑;禁忌","en":"Inhibitions are feelings of fear or embarrassment that make it difficult for you to behave naturally.","ex":{"en":"The whole point about dancing is to stop thinking and lose all your inhibitions","cn":"跳舞讲求的就是停止思考,完全放开。"}}]},"examples":[{"en":"The children were shy at first, but soon lost their inhibitions.","cn":"孩子们起初很羞涩，但很快就放开了。"},{"en":"She had no inhibitions about making her opinions known.","cn":"她敢于公开地谈论自己的想法。"}]},"inspirational":{"media":{"uk":"media/uk/inspirational__gb_1.mp3","us":"media/us/inspirational__us_1.mp3"},"oxford":{"phon":"ˌɪnspəˈreɪʃənl","pos":"adjective","senses":[{"en":"providing exciting new ideas; making somebody want to create something, especially in art, literature or music","cn":"启发灵感的；鼓舞人心的","ex":{"en":"an inspirational leader","cn":"有感召力的领袖"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有启发性的;有启示作用的;有鼓舞力量的","en":"Something that is inspirational provides you with inspiration.","ex":{"en":"Gandhi was an inspirational figure","cn":"甘地是富有感召力的人物。"}}]},"examples":[{"en":"an inspirational leader","cn":"有感召力的领袖"},{"en":"Jones proved an inspirational figure in Welsh rugby.","cn":"事实证明﹐琼斯是威尔士橄榄球的灵魂人物。"}]},"ineffectiveness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something or someone that is inefficient does not work as well as they should or could, in a way that wastes time, money, or effort","cn":""},{"en":"a person or organization that is ineffectual is not able to get things done because they are not good enough or do not have a strong character","cn":""}]},"examples":[{"en":"The chemical was almost totally ineffective in killing the weeds.","cn":"","src":"ld"},{"en":"Various drugs have proved ineffective against the virus.","cn":"","src":"ld"}],"media":{"uk":"media/uk/ineffectiveness__gb_1.mp3","us":"media/us/ineffectiveness__us_1.mp3"},"oxford":{"phon":"ˌɪnɪˈfektɪvnəs","pos":"noun","senses":[{"en":"the fact that something does not produce the intended result or a successful result","cn":"无效；不起作用","ex":{"en":"the ineffectiveness of western medicine in treating this illness","cn":"西医治疗这种病无效"}}]}},"involve":{"media":{"uk":"media/uk/involve__gb_1.mp3","us":"media/us/involve__us_1.mp3"},"oxford":{"phon":"ɪnˈvɒlv","pos":"verb","senses":[{"en":"if a situation, an event or an activity involves something, that thing is an important or necessary part or result of it","cn":"包含；需要；有…的部分（或结果）","lab":"formal","ex":{"en":"Any investment involves an element of risk.","cn":"任何投资都有一定的风险。"}},{"en":"if a situation, an event or an activity involves somebody/something, they take part in it or are affected by it","cn":"牵涉；牵连；影响","ex":{"en":"There was a serious incident involving a group of youths.","cn":"有一起涉及一群年轻人的严重事件。"}},{"en":"to make somebody take part in something","cn":"使参与；使加入","ex":{"en":"We want to involve as many people as possible in the celebrations.","cn":"我们希望参加庆典的人越多越好。"}},{"en":"to say or do something to show that somebody took part in something, especially a crime","cn":"表明（某人参与了犯罪等）","ex":{"en":"His confession involved a number of other politicians in the affair.","cn":"他的供词供出其他一些政治人物也涉及此事。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"需要;包含","en":"If a situation or activity involves something, that thing is a necessary part or consequence of it.","ex":{"en":"Running a kitchen involves a great deal of discipline and speed","cn":"料理好厨房需要把一切都安排得规规矩矩，且要讲求速度。"}},{"pos":"VERB 动词","cn":"牵涉;涉及","en":"If a situation or activity involves someone, they are taking part in it.","ex":{"en":"If there was a cover-up, it involved people at the very highest levels of government.","cn":"如果有人想要隐瞒实情,那其中就涉及政府部门最高层的人物。"}},{"pos":"VERB 动词","cn":"使陷入;使卷入","en":"If you say that someone involves themselves in something, you mean that they take part in it, often in a way that is unnecessary or unwanted.","ex":{"en":"I seem to have involved myself in something I don't understand.","cn":"我似乎卷入了一件我并不知情的事情当中。"}},{"pos":"VERB 动词","cn":"使参与;使介入","en":"If you involve someone else in something, you get them to take part in it.","ex":{"en":"Noel and I do everything together, he involves me in everything","cn":"我和诺埃尔什么事情都一起做,他让我参与所有的事。"}},{"pos":"VERB 动词","cn":"使承担;使面对","en":"If one thing involves you in another thing, especially something unpleasant or inconvenient, the first thing causes you to do or deal with the second.","ex":{"en":"A late booking may involve you in extra cost","cn":"预订晚了的话你可能要额外多花钱。"}}]},"examples":[{"en":"His confession involved a number of other politicians in the affair.","cn":"他的自白供出其他一些政治人物也涉及此事。"},{"en":"The test will involve answering questions about a photograph.","cn":"考试将包括回答一些关于一张照片的问题。"}]},"inconsiderate":{"oxford":{"phon":"ˌɪnkənˈsɪdərət","pos":"adjective","senses":[{"en":"not giving enough thought to other people’s feelings or needs","cn":"不为别人着想的；不体谅别人的；考虑不周的","ex":{"en":"inconsiderate behaviour","cn":"考虑不周的行为"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不体谅别人的;不替别人着想的","en":"If you accuse someone of being inconsiderate, you mean that they do not take enough care over how their words or actions will affect other people.","ex":{"en":"Motorists were criticised for being inconsiderate to pedestrians.","cn":"开车的人因不考虑行人而受到指责。"}}]},"media":{"uk":"media/uk/inconsiderate__gb_1.mp3","us":"media/us/inconsiderate__us_1.mp3"},"examples":[{"en":"It was inconsiderate of you not to call.","cn":"你连个电话也不打，不够体谅人。"},{"en":"inconsiderate behaviour","cn":"考虑不周的行为"}]},"intense":{"media":{"uk":"media/uk/intense__gb_1.mp3","us":"media/us/intense__us_1.mp3"},"oxford":{"phon":"ɪnˈtens","pos":"adjective","senses":[{"en":"very great; very strong","cn":"很大的；十分强烈的","ex":{"en":"We were all suffering in the intense heat.","cn":"我们都深受酷热之苦。"}},{"en":"serious and often involving a lot of action in a short period of time","cn":"严肃紧张的；激烈的","ex":{"en":"There is intense competition for the top jobs.","cn":"高层职位的竞争非常激烈。"}},{"en":"having or showing very strong feelings, opinions or thoughts about somebody/something","cn":"有强烈感情（或意见、想法）的；尖锐的；热切的","ex":{"en":"an intense look","cn":"热切的神情"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"强烈的;剧烈的;极度的","en":"Intense is used to describe something that is very great or extreme in strength or degree.","ex":{"en":"He was sweating from the intense heat","cn":"高温酷热让他大汗淋漓。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"认真的;集中的;紧张的","en":"If you describe an activity as intense, you mean that it is very serious and concentrated, and often involves doing a great deal in a short time.","ex":{"en":"The battle for third place was intense","cn":"第三名的争夺紧张激烈。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(目光)有穿透力的，洞悉一切的","en":"If you describe the way someone looks at you as intense, you mean that they look at you very directly and seem to know what you are thinking or feeling.","ex":{"en":"I felt so self-conscious under Luke's mother's intense gaze","cn":"在卢克母亲审视的目光下,我感到极不自在。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"热情的;热切的;激动的","en":"If you describe a person as intense, you mean that they appear to concentrate very hard on everything that they do, and they feel and show their emotions in a very extreme way.","ex":{"en":"I know he's an intense player, but he does enjoy what he's doing","cn":"我知道他是个拼命三郎,但他确实喜欢自己所做的事。"}}]},"examples":[{"en":"The President is under intense pressure to resign.","cn":"总统承受着沉重的辞职压力。"},{"en":"It was a period of intense activity.","cn":"那是活动激烈的时期。"}]},"invites":{"oxford":{"phon":"ɪnˈvaɪt","pos":"verb","senses":[{"en":"to ask sb to come to a social event","cn":"邀请"},{"en":"( formal ) to ask sb formally to go somewhere or do sth （","cn":"正式）邀请，请求，要求"}]}},"inability":{"oxford":{"phon":"ˌɪnəˈbɪləti","pos":"noun","senses":[{"en":"the fact of not being able to do something","cn":"无能；无力；不能","ex":{"en":"the government’s inability to provide basic services","cn":"政府在提供基本服务方面的无能"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"无能;无力;不能","en":"If you refer to someone's inability to do something, you are referring to the fact that they are unable to do it.","ex":{"en":"Her inability to concentrate could cause an accident.","cn":"她无法集中精力可能会导致事故。"}}]},"media":{"uk":"media/uk/inability__gb_1.mp3","us":"media/us/inability__us_1.mp3"},"examples":[{"en":"Some families go without medical treatment because of their inability to pay.","cn":"有些家庭因无力支付医疗费用而得不到医治。"},{"en":"the government's inability to provide basic services","cn":"政府在提供基本服务方面的无能"}]},"infuse":{"media":{"uk":"media/uk/infuse__gb_1.mp3","us":"media/us/infuse__us_1.mp3"},"oxford":{"phon":"ɪnˈfjuːz","pos":"verb","senses":[{"en":"to make somebody/something have a particular quality","cn":"使具有，注入（某特性）","g":"[transitive]","lab":"formal","ex":{"en":"Her novels are infused with sadness.","cn":"她的小说充满哀伤。"}},{"en":"to have an effect on all parts of something","cn":"全面影响","g":"[transitive]","lab":"formal","ex":{"en":"Politics infuses all aspects of our lives.","cn":"政治影响着我们生活的各个方面。"}},{"en":"if you infuse herbs, etc. or they infuse, you put them in hot water until the taste has passed into the water","cn":"泡制（草药等）；泡；沏","g":"[transitive, intransitive]"},{"en":"to slowly put a drug or other substance into a person’s vein","cn":"输注（药物等）","g":"[transitive]","lab":"medical"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"把…注入;灌输","en":"To infuse a quality into someone or something, or to infuse them with a quality, means to fill them with it.","ex":{"en":"Many of the girls seemed to be infused with excitement on seeing the snow","cn":"看到雪,许多女孩似乎一下子变得兴奋起来。"}},{"pos":"VERB 动词","cn":"使充满","en":"If a quality infuses something, every part of that thing has that quality.","ex":{"en":"A strange spirit infused the place.","cn":"那个地方散发着一种奇特的气质。"}},{"pos":"V-ERG 及物/不及物动词","cn":"浸渍;泡(茶);泡制(草药)","en":"If you infuse things such as tea leaves or herbs, or allow them to infuse, you put them in hot water for some time so that the water absorbs their flavour. You can also infuse things in other liquids.","ex":{"en":"...teas made by infusing the roots of herbs","cn":"浸泡草药根沏成的茶水"}}]},"examples":[{"en":"Politics infuses all aspects of our lives.","cn":"政治影响着我们生活的各个方面。"},{"en":"Her novels are infused with sadness.","cn":"她的小说充满哀伤。"}]},"invincible":{"media":{"uk":"media/uk/invincible__gb_1.mp3","us":"media/us/invincible__us_1.mp3"},"oxford":{"phon":"ɪnˈvɪnsəbl","pos":"adjective","senses":[{"en":"too strong to be defeated or changed","cn":"不可战胜的；坚不可摧的；难以改变的","ex":{"en":"The team seemed invincible.","cn":"这个队似乎战无不胜。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不可战胜的;所向披靡的","en":"If you describe an army or sports team as invincible, you believe that they cannot be defeated.","ex":{"en":"When Sotomayor is on form he is virtually invincible.","cn":"索托马约尔状态好时几乎无人可敌。"}},{"pos":"ADJ 形容词","cn":"(信念、态度)不可动摇的，不可改变的","en":"If someone has an invincible belief or attitude, it cannot be changed.","ex":{"en":"He also had an invincible faith in the medicinal virtues of garlic.","cn":"他同时也对大蒜的医学功效深信不疑。"}}]},"examples":[{"en":"an invincible belief in his own ability","cn":"对他自己的能力坚定不移的信念"},{"en":"The team seemed invincible.","cn":"这个队似乎战无不胜。"}]},"intact":{"media":{"uk":"media/uk/intact__gb_1.mp3","us":"media/us/intact__us_1.mp3"},"oxford":{"phon":"ɪnˈtækt","pos":"adjective","senses":[{"en":"complete and not damaged","cn":"完好无损；完整","ex":{"en":"Most of the house remains intact even after two hundred years.","cn":"即使过了两百年，这房子的大部分还保持完好。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"完整无缺的;未受损伤的","en":"Something that is intact is complete and has not been damaged or changed.","ex":{"en":"Most of the cargo was left intact after the explosion","cn":"大部分货物在爆炸发生后都完好无损。"}}]},"examples":[{"en":"Most of the house remains intact even after two hundred years.","cn":"即使过了两百年，这房子的大部分还保持完好。"},{"en":"He emerged from the trial with his reputation intact.","cn":"他受审获释，名誉丝毫未受损害。"}]},"instant":{"media":{"uk":"media/uk/instant__gb_1.mp3","us":"media/us/instant__us_1.mp3"},"oxford":{"phon":"ˈɪnstənt","pos":"adjective","senses":[{"en":"happening immediately","cn":"立即的；立刻的；瞬间的","g":"[usually before noun]","ex":{"en":"This account gives you instant access to your money.","cn":"这个账户让你随时调动款项。"}},{"en":"that can be made quickly and easily, usually by adding hot water","cn":"速食的；即食的；速溶的；方便的","g":"[only before noun]","ex":{"en":"instant coffee","cn":"速溶咖啡"}},{"en":"a very short period of time","cn":"瞬间；片刻","g":"[countable, usually singular]","ex":{"en":"I'll be back in an instant.","cn":"我马上就回来。"},"pos":"noun"},{"en":"a particular point in time","cn":"某一时刻","g":"[countable, usually singular]","ex":{"en":"At that (very) instant, the door opened.","cn":"就在那时，门开了。"},"pos":"noun"},{"en":"coffee that can be made quickly and easily by adding hot water","cn":"速溶咖啡","g":"[uncountable]","lab":"informal","ex":{"en":"Do you want some coffee? Is instant OK?","cn":"你想喝点咖啡吗？即时可以吗？"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"瞬息;顷刻;刹那","en":"An instant is an extremely short period of time.","ex":{"en":"For an instant, Catherine was tempted to flee","cn":"有那么一会儿,凯瑟琳很想逃跑。"}},{"pos":"N-SING 单数名词","cn":"(某一)时刻","en":"If you say that something happens at a particular instant, you mean that it happens at exactly the time you have been referring to, and you are usually suggesting that it happens quickly or immediately.","ex":{"en":"At that instant the museum was plunged into total darkness","cn":"就在那时,博物馆陷入了一片漆黑。"}},{"pos":"PHR-CONJ-SUBORD","cn":"一…(就)","en":"To do something the instant something else happens means to do it immediately.","ex":{"en":"I had bolted the door the instant I had seen the bat.","cn":"我一看到蝙蝠就把门闩上了。"}},{"pos":"ADJ 形容词","cn":"立即的;即刻的","en":"You use instant to describe something that happens immediately.","ex":{"en":"Mr Porter's book was an instant hit","cn":"波特先生的书一经推出便大受欢迎。"}},{"pos":"ADJ 形容词","cn":"(食品)已配制好的，调制快速方便的，速溶的","en":"Instant food is food that you can prepare very quickly, for example by just adding water.","ex":{"en":"...instant coffee.","cn":"速溶咖啡"}}]},"examples":[{"en":"This account gives you instant access to your money.","cn":"这个账户让你随时调动款项。"},{"en":"Just for an instant I thought he was going to refuse.","cn":"刹那间我以为他会拒绝。"}]},"instead":{"media":{"uk":"media/uk/instead__gb_1.mp3","us":"media/us/instead__us_1.mp3"},"oxford":{"phon":"ɪnˈsted","pos":"adverb","senses":[{"en":"in the place of somebody/something","cn":"代替；顶替；反而；却","ex":{"en":"Lee was ill so I went instead.","cn":"李病了，所以我代他去了。"}}]},"collins":{"senses":[{"pos":"PREP-PHRASE 短语介词","cn":"代替…;而不是…","en":"If you do one thing instead of another, you do the first thing and not the second thing, as the result of a choice or a change of behaviour.","ex":{"en":"She had to spend nearly four months away from him that summer, instead of the usual two","cn":"那个夏天她被迫离开他将近四个月而不是通常的两个月。"}},{"pos":"ADV 副词","cn":"作为替代;反而;相反地","en":"If you do not do something, but do something else instead, you do the second thing and not the first thing, as the result of a choice or a change of behaviour.","ex":{"en":"He reached for the wine but did not drink, pushed it, instead, across the table towards Joanna","cn":"他伸手拿酒却没有喝,而是把它推给了坐在桌子对面的乔安娜。"}}]},"examples":[{"en":"She said nothing, preferring instead to save her comments till later.","cn":"她什么也没说，而是想稍后再作评论。"},{"en":"He didn't reply. Instead, he turned on his heel and left the room.","cn":"他没有回答，反而转身离开了房间。"}]},"interactions":{"oxford":{"phon":"ˌɪntərˈækt","pos":"verb","senses":[{"en":"to communicate with sb, especially while you work, play or spend time with them","cn":"交流；沟通；合作"},{"en":"if one thing interacts with another, or if two things interact , the two things have an effect on each other","cn":"相互影响；相互作用"}]}},"ingenious":{"media":{"uk":"media/uk/ingenious__gb_1.mp3","us":"media/us/ingenious__us_1.mp3"},"oxford":{"phon":"ɪnˈdʒiːniəs","pos":"adjective","senses":[{"en":"very suitable for a particular purpose and resulting from clever new ideas","cn":"精巧的；新颖独特的；巧妙的","ex":{"en":"an ingenious device/invention/experiment","cn":"巧妙的装置／发明／实验"}},{"en":"having a lot of clever new ideas and good at inventing things","cn":"心灵手巧的；机敏的；善于创造发明的","ex":{"en":"an ingenious cook","cn":"心灵手巧的厨师"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"巧妙的;制作精巧的;新颖独特的","en":"Something that is ingenious is very clever and involves new ideas, methods, or equipment.","ex":{"en":"...a truly ingenious invention","cn":"真正有创意的发明"}}]},"examples":[{"en":"She's very ingenious when it comes to finding excuses.","cn":"她很善于找借口。"},{"en":"ingenious ways of saving energy","cn":"节约能源的巧妙方法"}]},"instrument":{"oxford":{"phon":"ˈɪnstrəmənt","pos":"noun","senses":[{"en":"an object used for producing musical sounds, for example a piano or a drum","cn":"乐器","ex":{"en":"to play an instrument","cn":"演奏乐器"}},{"en":"a tool or device used for a particular task, especially for specialist or scientific work","cn":"器械；仪器；器具","ex":{"en":"surgical/optical/scientific instruments","cn":"外科／光学／科学仪器"}},{"en":"a device used for measuring speed, distance, temperature, etc. in a vehicle or on a machine","cn":"（车辆、机器的）仪器，仪表","ex":{"en":"data gathered by instruments aboard the satellite","cn":"卫星上的仪器收集的数据"}},{"en":"something that is used by somebody in order to achieve something; a person or thing that makes something happen","cn":"促成某事的人（或事物）；手段","lab":"formal","ex":{"en":"The law is not the best instrument for dealing with family matters.","cn":"法律并不是处理家庭问题的最佳方法。"}},{"en":"a person who is used and controlled by somebody/something that is more powerful","cn":"受利用（或控制）的人；工具","lab":"formal","ex":{"en":"an instrument of fate","cn":"受命运摆布的人"}},{"en":"a formal legal document","cn":"文据；正式法律文件","lab":"law","ex":{"en":"credit instruments issued by banks","cn":"银行发行的信贷工具"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"器械;器具","en":"An instrument is a tool or device that is used to do a particular task, especially a scientific task.","ex":{"en":"...a thin tube-like optical instrument.","cn":"试管状的细长光学仪器"}},{"pos":"N-COUNT 可数名词","cn":"乐器","en":"A musical instrument is an object such as a piano, guitar, or flute, which you play in order to produce music.","ex":{"en":"Learning a musical instrument introduces a child to an understanding of music.","cn":"学一门乐器能引导孩子了解音乐。"}},{"pos":"N-COUNT 可数名词","cn":"仪器;仪表","en":"An instrument is a device that is used for making measurements of something such as speed, height, or sound, for example on a ship or plane or in a car.","ex":{"en":"...crucial instruments on the control panel.","cn":"控制面板上的重要仪表"}},{"pos":"N-COUNT 可数名词","cn":"工具;手段;被他人利用的人","en":"Something that is an instrument for achieving a particular aim is used by people to achieve that aim.","ex":{"en":"The veto has been a traditional instrument of diplomacy for centuries.","cn":"几个世纪以来否决权一直是外交上惯用的手段。"}}]},"media":{"uk":"media/uk/instrument__gb_1.mp3","us":"media/us/instrument__us_1.mp3","img":["media/ldoce/img/instrument_surgical.jpg"]},"examples":[{"en":"The law is not the best instrument for dealing with family matters.","cn":"法律并不是处理家庭问题的最佳方法。"},{"en":"Is he learning an instrument?","cn":"他在学习演奏乐器吗？"}]},"insight":{"media":{"uk":"media/uk/insight__gb_1.mp3","us":"media/us/insight__us_1.mp3"},"oxford":{"phon":"ˈɪnsaɪt","pos":"noun","senses":[{"en":"an understanding of what something is like","cn":"洞悉；了解","g":"[countable, uncountable]","ex":{"en":"There are many valuable insights in her book.","cn":"她的书中有许多宝贵的见解。"}},{"en":"the ability to see and understand the truth about people or situations","cn":"洞察力；领悟","g":"[uncountable]","lab":"approving","ex":{"en":"He has insight, vision and a deep humanity.","cn":"他有洞察力、远见和深厚的人性。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"洞悉;深入了解;深刻见解","en":"If you gain insight or an insight into a complex situation or problem, you gain an accurate and deep understanding of it.","ex":{"en":"The project would give scientists new insights into what is happening to the earth's atmosphere","cn":"该项目将使科学家对地球大气层的状况有更新的深入了解。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"洞察力","en":"If someone has insight, they are able to understand complex situations.","ex":{"en":"He was a man with considerable insight.","cn":"他是个富有洞察力的人。"}}]},"examples":[{"en":"The book gives us fascinating insights into life in Mexico.","cn":"这本书生动地表现了墨西哥的生活。"},{"en":"With a flash of insight I realized what the dream meant.","cn":"我突然明白了这个梦意味着什么。"}]},"interest":{"media":{"uk":"media/uk/interest__gb_1.mp3","us":"media/us/interest__us_1.mp3"},"oxford":{"phon":"ˈɪntrəst","pos":"noun","senses":[{"en":"the feeling that you have when you want to know or learn more about somebody/something","cn":"兴趣；关注","g":"[uncountable, singular]","sc":"wanting to know more","ex":{"en":"Her research has generated interest around the world.","cn":"她的研究引起了全世界的兴趣。"}},{"en":"the quality that something has when it attracts somebody’s attention or makes them want to know more about it","cn":"引人关注的性质；吸引力；趣味","g":"[uncountable]","sc":"attraction","ex":{"en":"There are many places of interest near the city.","cn":"这座城市附近有许多有意思的地方。"}},{"en":"an activity or a subject that you enjoy and that you spend time doing or studying","cn":"业余爱好","g":"[countable]","sc":"hobby","ex":{"en":"Her main interests are music and tennis.","cn":"她的主要爱好是音乐和网球。"}},{"en":"the extra money that you pay back when you borrow money or that you receive when you invest money","cn":"利息","g":"[uncountable]","lab":"finance","sc":"money","ex":{"en":"to pay interest on a loan","cn":"付贷款利息"}},{"en":"a good result or an advantage for somebody/something","cn":"好处；利益","g":"[countable, usually plural, uncountable]","sc":"advantage","ex":{"en":"The union is working to protect the interests of its members.","cn":"工会致力于保护其成员的利益。"}},{"en":"a share in a business or company and its profits","cn":"（企业或公司的）股份；权益；股权","g":"[countable, usually plural]","sc":"share in business","ex":{"en":"She has business interests in France.","cn":"她在法国拥有企业权益。"}},{"en":"a connection with something that affects your attitude to it, especially because you may benefit from it in some way","cn":"利害关系；利益关系","g":"[countable, uncountable]","sc":"connection","ex":{"en":"I should, at this point, declare my interest.","cn":"到了这个时候，我应该申明我的利益关系。"}},{"en":"a group of people who are in the same business or who share the same aims that they want to protect","cn":"同行；同业；利害与共者；利益团体","g":"[countable, usually plural]","sc":"group of people","ex":{"en":"powerful farming interests","cn":"强大的农民团体"}},{"en":"to attract your attention and make you feel interested; to make yourself give your attention to something","cn":"使感兴趣；使关注","ex":{"en":"Politics doesn't interest me.","cn":"我对政治不感兴趣。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"兴趣;兴味;关注","en":"If you have an interest in something, you want to learn or hear more about it.","ex":{"en":"There has been a lively interest in the elections in the last two weeks","cn":"近两周来选举受到了热烈关注。"}},{"pos":"N-COUNT 可数名词","cn":"爱好","en":"Your interests are the things that you enjoy doing.","ex":{"en":"Encourage your child in her interests and hobbies even if they're things that you know little about","cn":"要鼓励孩子的兴趣爱好，即使你对它们所知甚少。"}},{"pos":"VERB 动词","cn":"使感兴趣;引起…的关注","en":"If something interests you, it attracts your attention so that you want to learn or hear more about it or continue doing it.","ex":{"en":"That passage interested me because it seems to parallel very closely what you're doing in the novel","cn":"那一段引起了我的关注，因为它似乎与你在小说里所采用的手法非常相似。"}},{"pos":"VERB 动词","cn":"劝诱;说服(某人)做(某事)","en":"If you are trying to persuade someone to buy or do something, you can say that you are trying to interest them in it.","ex":{"en":"In the meantime I can't interest you in a new car, I suppose?","cn":"那么我想这时候我不能说服您买辆新车了？"}},{"pos":"N-COUNT 可数名词","cn":"利益;福利","en":"If something is in the interests of a particular person or group, it will benefit them in some way.","ex":{"en":"Did those directors act in the best interests of their club?","cn":"那些董事行事时是以他们俱乐部的最大利益为出发点吗？"}},{"pos":"N-COUNT 可数名词","cn":"利益相关者;利益集团","en":"You can use interests to refer to groups of people who you think use their power or money to benefit themselves.","ex":{"en":"The government accused unnamed 'foreign interests' of inciting the trouble","cn":"政府不指名地谴责“外国利益集团”煽动骚乱。"}},{"pos":"N-COUNT 可数名词","cn":"权益;股权;产权","en":"A person or organization that has interests in a company or in a particular type of business owns shares in this company or this type of business.","ex":{"en":"Her other business interests include a theme park in Scandinavia and hotels in the West Country.","cn":"她其他的公司股权包括斯堪的纳维亚的一个主题游乐园和英格兰西南部的几家酒店。"}},{"pos":"N-COUNT 可数名词","cn":"利害关系","en":"If a person, country, or organization has an interest in a possible event or situation, they want that event or situation to happen because they are likely to benefit from it.","ex":{"en":"The West has an interest in promoting democratic forces in Eastern Europe","cn":"东欧民主力量的发展与西方国家利害攸关。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"利息","en":"Interest is extra money that you receive if you have invested a sum of money. Interest is also the extra money that you pay if you have borrowed money or are buying something on credit.","ex":{"en":"Does your current account pay interest?","cn":"你的活期账户有利息吗？"}},{"pos":"PHRASE 短语","cn":"为了（或符合)…的利益;有助于","en":"If you do something in the interests of a particular result or situation, you do it in order to achieve that result or maintain that situation. to have someone's interests at heart→see: ;","ex":{"en":"...a call for all businessmen to work together in the interests of national stability.","cn":"呼吁所有商人为了国家稳定而团结协作"}}]},"examples":[{"en":"His main interest is football (= he watches and reads about football, and may or may not play it).","cn":"他的主要业余爱好是足球（他看足球赛和阅读有关足球的消息，但不一定踢足球）。"},{"en":"Organizations have an interest in ensuring that employee motivation is high.","cn":"各机构皆知获利之道在于确保员工士气高昂。"}]},"industrialized":{"media":{"uk":"media/uk/industrialized__gb_1.mp3","us":"media/us/industrialized__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"工业化的","en":"An industrialized area or place is one which has a lot of industries.","ex":{"en":"Industrialized countries must reduce carbon dioxide emissions.","cn":"工业化国家必须减少二氧化碳的排放。"}}]},"examples":[{"en":"an industrialized country","cn":"工业化国家"}],"oxford":{"phon":"ɪnˈdʌstriəlaɪzd","pos":"adjective","senses":[{"en":"that has a lot of industries","cn":"工业化：有很多行业","ex":{"en":"an industrialized country","cn":"工业化国家"}}]}},"inflexion":{"oxford":{"phon":"ɪnˈflekʃn","pos":"noun","senses":[{"en":"a change in the form of a word, especially the ending, according to its grammatical function in a sentence （","cn":"尤指词尾的）屈折变化"},{"en":"a change in how high or low your voice is as you are speaking","cn":"语调的抑扬变化"}]},"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"media":{"uk":"media/ldoce/hwd/bre/c/inflexion0205.mp3","us":"media/ldoce/hwd/ame/9/ld41inflexion.mp3"}},"interrupted":{"oxford":{"phon":"ˌɪntəˈrʌpt","pos":"verb","senses":[{"en":"to say or do sth that makes sb stop what they are saying or doing","cn":"插嘴；打扰；打岔"},{"en":"to stop sth for a short time","cn":"使暂停；使中断"}]},"media":{"uk":"media/uk/interrupt__gb_1.mp3","us":"media/us/interrupt__us_1.mp3"}},"integrate":{"media":{"uk":"media/uk/integrate__gb_1.mp3","us":"media/us/integrate__us_1.mp3"},"oxford":{"phon":"ˈɪntɪɡreɪt","pos":"verb","senses":[{"en":"to combine two or more things so that they work together; to combine with something else in this way","cn":"（使）合并，成为一体","g":"[intransitive, transitive]","ex":{"en":"These programs will integrate with your existing software.","cn":"这些程序会和你原有的软件整合起来。"}},{"en":"to become or make somebody become accepted as a member of a social group, especially when they come from a different culture","cn":"（使）加入，融入群体","g":"[intransitive, transitive]","ex":{"en":"They have not made any effort to integrate with the local community.","cn":"他们完全没有尝试融入本地社区。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)加入;(使)融入","en":"If someone integrates into a social group, or is integrated into it, they behave in such a way that they become part of the group or are accepted into it.","ex":{"en":"He didn't integrate successfully into the Italian way of life","cn":"他没有顺利地融入到意大利的生活方式中。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(种族)融合;使取消种族隔离","en":"When races integrate or when schools and organizations are integrated, people who are black or belong to ethnic minorities can join white people in their schools and organizations.","ex":{"en":"Schools came to us because they wanted to integrate","cn":"学校来向我们寻求帮助是因为他们想让不同种族的学生得到平等待遇。"}},{"pos":"V-RECIP-ERG","cn":"(使)(与…)成为一体;(使)结合;(使)合并","en":"If you integrate one thing with another, or one thing integrates with another, the two things become closely linked or form part of a whole idea or system. You can also say that two things integrate .","ex":{"en":"Integrating the pound with other European currencies could cause difficulties","cn":"把英镑与欧洲其他货币合并会引发许多难题。"}}]},"examples":[{"en":"The policy is to integrate children with special needs into ordinary schools.","cn":"这项政策旨在使有特殊需要的儿童融入普通学校。"},{"en":"These programs will integrate with your existing software.","cn":"这些程序会和你原有的软件整合起来。"}]},"interfering":{"oxford":{"phon":"ˌɪntəˈfɪərɪŋ","pos":"adjective","senses":[{"en":"involving yourself in an annoying way in other people’s private lives","cn":"干涉他人私生活的；管闲事的","ex":{"en":"She's an interfering busybody!","cn":"她是个好管闲事的人！"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"好干涉的;爱管闲事的","en":"If you describe someone as interfering, you are criticizing them because they try to get involved in other people's affairs or to give them advice, especially when the advice is not wanted.","ex":{"en":"When she was a child she had regarded her mother as an interfering busybody.","cn":"当她还是个孩子的时候,她觉得母亲是个管事婆。"}}]},"media":{"uk":"media/uk/interfering__gb_1.mp3","us":"media/us/interfering__us_1.mp3"},"examples":[{"en":"She's an interfering busybody!","cn":"她是个好管闲事的人！"}]},"investigative":{"oxford":{"phon":"ɪnˈvestɪɡətɪv","pos":"adjective","senses":[{"en":"involving examining an event or a situation to find out the truth","cn":"调查研究的；侦查的","ex":{"en":"The article was an excellent piece of investigative journalism.","cn":"这是一篇优秀的调查研究报道。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(尤指新闻工作)调查性的","en":"Investigative work, especially journalism, involves investigating things.","ex":{"en":"The paper has earned respect for its investigative journalism.","cn":"这份报纸的调查性新闻报道为其赢得了尊敬。"}}]},"media":{"uk":"media/uk/investigative__gb_1.mp3","us":"media/us/investigative__us_1.mp3"},"examples":[{"en":"The article was an excellent piece of investigative journalism.","cn":"这是一篇优秀的调查研究报道。"},{"en":"The police have full investigatory powers.","cn":"警察拥有调查全权。"}]},"interestingly":{"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"有趣的是;令人关注的是;想不到的是","en":"You use interestingly to introduce a piece of information that you think is interesting or unexpected.","ex":{"en":"Interestingly enough, a few weeks later, Benjamin remarried","cn":"有意思的是,几个星期以后,本杰明又结婚了。"}}]},"media":{"uk":"media/uk/interestingly__gb_1.mp3","us":"media/us/interestingly__us_1.mp3"},"examples":[{"en":"Interestingly, there are very few recorded cases of such attacks.","cn":"有意思的是，记录在案的此类袭击事件很少。"},{"en":"Interestingly, none of their three children ever married.","cn":"有趣的是﹐他们的三个孩子都一直没有结婚。"}],"oxford":{"phon":"ˈɪntrəstɪŋli","pos":"adverb","senses":[{"en":"in a way that attracts your attention because it is special, exciting or unusual","cn":"有趣的；有吸引力的","ex":{"en":"Interestingly, there are very few recorded cases of such attacks.","cn":"耐人寻味的是，这种袭击事件记录在案的非常少。"}}]}},"intimacy":{"media":{"uk":"media/uk/intimacy__gb_1.mp3","us":"media/us/intimacy__us_1.mp3"},"oxford":{"phon":"ˈɪntɪməsi","pos":"noun","senses":[{"en":"the state of having a close personal relationship with somebody","cn":"亲密；密切；关系密切","g":"[uncountable, singular]","ex":{"en":"She isn't capable of real intimacy.","cn":"她不能与人真正亲密相处。"}},{"en":"a private and comfortable atmosphere","cn":"僻静舒适的气氛","g":"[uncountable]","ex":{"en":"The room had a peaceful sense of intimacy about it.","cn":"房间有一种宁静舒适的气氛。"}},{"en":"a thing that a person says or does to somebody that they know very well","cn":"亲密的言语（或行为）","g":"[countable, usually plural]"},{"en":"sexual activity, especially an act of sexual intercourse","cn":"性行为；（尤指）性交","g":"[uncountable]","lab":"formal or law"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"亲密;密切","en":"Intimacy between two people is a very close personal relationship between them.","ex":{"en":"...a means of achieving intimacy with another person.","cn":"与别人建立亲密关系的途径"}},{"pos":"N-UNCOUNT 不可数名词","cn":"性;性关系","en":"You sometimes use intimacy to refer to sex or a sexual relationship.","ex":{"en":"Her sunburn made intimacy too painful","cn":"她的皮肤晒伤了，使得想要亲热一下都变得很痛苦。"}},{"pos":"N-COUNT 可数名词","cn":"亲昵的言语(或行为)","en":"Intimacies are things that you say or do to someone you have a very close personal relationship with.","ex":{"en":"...the intimacies of a love scene.","cn":"恋爱场面的亲昵行为"}}]},"examples":[{"en":"a close sense of intimacy between parent and child","cn":"父母和孩子之间的亲密感"},{"en":"She thought back over the intimacies they’d shared and the plans they’d made.","cn":"她回想起他们之间曾经有过的亲密言行以及他们设想的计划。"}]},"inevitably":{"media":{"uk":"media/uk/inevitably__gb_1.mp3","us":"media/us/inevitably__us_1.mp3"},"oxford":{"phon":"ɪnˈevɪtəbli","pos":"adverb","senses":[{"en":"as is certain to happen","cn":"不可避免地；必然地","ex":{"en":"Inevitably, the press exaggerated the story.","cn":"新闻界照例又夸大了这件事。"}},{"en":"as you would expect","cn":"意料之中","lab":"often humorous","ex":{"en":"Inevitably, it rained on the day of the wedding.","cn":"果然不出所料，婚礼的那天下起了雨。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"不可避免地;必然(发生)地","en":"If something will inevitably happen, it is certain to happen and cannot be prevented or avoided.","ex":{"en":"Technological changes will inevitably lead to unemployment","cn":"技术变革必然会导致失业。"}}]},"examples":[{"en":"Inevitably, it rained on the day of the wedding.","cn":"果然不出所料，婚礼的那天下起了雨。"},{"en":"Inevitably, the press exaggerated the story.","cn":"新闻界照例又夸大了这件事。"}]},"inventing":{"oxford":{"phon":"ɪnˈvent","pos":"verb","senses":[{"en":"to produce or design sth that has not existed before","cn":"发明；创造"},{"en":"to say or describe sth that is not true, especially in order to trick people","cn":"编造；捏造；虚构"}]}},"insert":{"oxford":{"phon":"ɪnˈsɜːt","pos":"verb","senses":[{"en":"to put something into something else or between two things","cn":"插入；嵌入","ex":{"en":"Insert coins into the slot and press for a ticket.","cn":"把硬币放进投币口，按钮取票。"}},{"en":"to add something to a piece of writing","cn":"（在文章中）插入，添加内容","ex":{"en":"Position the cursor where you want to insert a word.","cn":"把光标移到你想插入字词的地方。"}},{"en":"an extra section added to a book, newspaper or magazine, especially to advertise something","cn":"（书报的）插页，广告附加页","ex":{"en":"an 8-page insert on the new car models","cn":"附加的 8 页新型汽车广告"},"pos":"noun"},{"en":"something that is put inside something else, or added to something else","cn":"插入物；添加物","ex":{"en":"These inserts fit inside any style of shoe.","cn":"这些鞋垫适合任何式样的鞋。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"插入;嵌入","en":"If you insert an object into something, you put the object inside it.","ex":{"en":"He took a small key from his pocket and slowly inserted it into the lock","cn":"他从口袋里掏出一把小钥匙,慢慢地插到锁眼里。"}},{"pos":"VERB 动词","cn":"(在文章或讲话中)插入，添加","en":"If you insert a comment into a piece of writing or a speech, you include it.","ex":{"en":"They joined with the monarchists to insert a clause calling for a popular vote on the issue.","cn":"他们与君主主义者联手添加了一个条款,呼吁对该议题进行全民投票。"}},{"pos":"N-COUNT 可数名词","cn":"插入物;(尤指夹在书刊中的)活页广告","en":"An insert is something that is inserted somewhere, especially an advertisement on a piece of paper that is placed between the pages of a book or magazine."}]},"media":{"uk":"media/uk/insert__gb_1.mp3","us":"media/us/insert__us_1.mp3"},"examples":[{"en":"They inserted a tube in his mouth to help him breathe.","cn":"他们在他嘴里插了根导管帮助他呼吸。"},{"en":"Position the cursor where you want to insert a word.","cn":"把光标移到你想插入字词的地方。"}]},"increase":{"media":{"uk":"media/uk/increase__gb_1.mp3","us":"media/us/increase__us_1.mp3"},"oxford":{"phon":"ɪnˈkriːs","pos":"verb","senses":[{"en":"to become greater in amount, number, value, etc.; to make something greater in amount, number, value, etc.","cn":"（使）增长，增多，增加","ex":{"en":"Costs have increased significantly.","cn":"成本大幅增加了。"}},{"en":"a rise in the amount, number or value of something","cn":"增长；增多；增加","ex":{"en":"price/tax/wage increases","cn":"价格／税额／工资的上涨"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"增加;增大;增长","en":"If something increases or you increase it, it becomes greater in number, level, or amount.","ex":{"en":"The population continues to increase","cn":"人口继续增长。"}},{"pos":"N-COUNT 可数名词","cn":"增加;增大;增长","en":"If there is an increase in the number, level, or amount of something, it becomes greater.","ex":{"en":"...a sharp increase in productivity","cn":"生产率的大幅提高"}},{"pos":"PHRASE 短语","cn":"正在增加;不断增长","en":"If something is on the increase, it is happening more often or becoming greater in number or intensity.","ex":{"en":"Crime is on the increase.","cn":"犯罪活动在不断增多。"}}]},"examples":[{"en":"The population has increased from 1.2 million to 1.8 million.","cn":"人口已从 120 万增加到了 180 万。"},{"en":"increasing levels of carbon dioxide in the earth's atmosphere","cn":"地球大气层中日益增多的二氧化碳含量"}]},"innuendo":{"media":{"uk":"media/uk/innuendo__gb_1.mp3","us":"media/us/innuendo__us_1.mp3"},"oxford":{"phon":"ˌɪnjuˈendəʊ","pos":"noun","senses":[{"en":"an indirect remark about somebody/something, usually suggesting something bad or rude; the use of remarks like this","cn":"暗指；影射","ex":{"en":"innuendoes about her private life","cn":"对她私生活含沙射影的指责"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"影射;暗讽","en":"Innuendo is indirect reference to something rude or unpleasant.","ex":{"en":"The report was based on rumours, speculation, and innuendo.","cn":"这份报告建立在谣言、臆断和含沙射影的基础之上。"}}]},"examples":[{"en":"The song is full of sexual innuendo.","cn":"那首歌充满了性的暗示。"},{"en":"innuendoes about her private life","cn":"对她私生活含沙射影的指责"}]},"invited":{"oxford":{"phon":"ɪnˈvaɪt","pos":"verb","senses":[{"en":"to ask sb to come to a social event","cn":"邀请"},{"en":"( formal ) to ask sb formally to go somewhere or do sth （","cn":"正式）邀请，请求，要求"}]}},"income":{"media":{"uk":"media/uk/income__gb_1.mp3","us":"media/us/income__us_1.mp3"},"oxford":{"phon":"ˈɪnkʌm","pos":"noun","senses":[{"en":"the money that a person, a region, a country, etc. earns from work, from investing money, from business, etc.","cn":"收入；收益；所得","lab":"informal","ex":{"en":"Average household income fell slightly.","cn":"平均家庭收入略有下降。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"收入;所得;收益","en":"A person's or organization's income is the money that they earn or receive, as opposed to the money that they have to spend or pay out. →see usage note at:","ex":{"en":"Many families on low incomes will be unable to afford to buy their own home","cn":"许多低收入家庭将会买不起自己的房子。"}}]},"examples":[{"en":"They receive a proportion of their income from the sale of goods and services.","cn":"他们一部分的收入来自出售货品和各种服务所得。"},{"en":"Tourism is a major source of income for the area.","cn":"旅游业是这个地区的主要收入来源。"}]},"infiltration":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to secretly collect information about an enemy government","cn":""},{"en":"the collecting of political, military, or industrial secrets from another country or organization","cn":""}]},"examples":[{"en":"Police attempts to infiltrate neo-Nazi groups were largely unsuccessful.","cn":"","src":"ld"},{"en":"Rebel forces have been infiltrating into the country.","cn":"","src":"ld"}],"media":{"uk":"media/uk/infiltration__gb_1.mp3","us":"media/us/infiltration__us_1.mp3"},"oxford":{"phon":"ˌɪnfɪlˈtreɪʃn","pos":"noun","senses":[{"en":"the act of entering a place or an organization secretly, especially in order to get information that can be used against it","cn":"（使）悄悄进入，潜入","g":"[uncountable, countable]","ex":{"en":"the infiltration of terrorists from across the border","cn":"恐怖分子的越境渗透"}},{"en":"the process of passing slowly into something","cn":"渗入；渗透","g":"[uncountable]","ex":{"en":"the infiltration of rain into the soil","cn":"雨水渗入土壤"}}]}},"industry":{"media":{"uk":"media/uk/industry__gb_1.mp3","us":"media/us/industry__us_1.mp3"},"oxford":{"phon":"ˈɪndəstri","pos":"noun","senses":[{"en":"the production of goods from raw materials, especially in factories","cn":"工业；生产制造","g":"[uncountable]","ex":{"en":"the needs of British industry","cn":"英国工业的需求"}},{"en":"the people and activities involved in producing a particular thing, or in providing a particular service","cn":"行业","g":"[countable]","lab":"figurative","ex":{"en":"the steel/oil/auto industry","cn":"钢铁／石油／汽车工业"}},{"en":"the quality of working hard","cn":"勤奋；勤劳","g":"[uncountable]","lab":"formal","ex":{"en":"We were impressed by their industry.","cn":"他们的勤奋给我们留下深刻印象。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"工业","en":"Industry is the work and processes involved in collecting raw materials, and making them into products in factories.","ex":{"en":"British industry suffers through insufficient investment in research.","cn":"研究投入不足让英国工业深受其害。"}},{"pos":"N-COUNT 可数名词","cn":"行业","en":"A particular industry consists of all the people and activities involved in making a particular product or providing a particular service.","ex":{"en":"...the motor vehicle and textile industries.","cn":"汽车业与纺织业"}},{"pos":"N-COUNT 可数名词","cn":"产业;声势浩大的活动","en":"If you refer to a social or political activity as an industry, you are criticizing it because you think it involves a lot of people in unnecessary or useless work.","ex":{"en":"Some Afro-Caribbeans are rejecting the whole race relations industry","cn":"一些加勒比黑人在抵制整个种族关系运动。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"勤劳;勤奋","en":"Industry is the fact of working very hard.","ex":{"en":"No one doubted his ability, his industry or his integrity.","cn":"没人怀疑他的能力、勤奋和正直。"}}]},"examples":[{"en":"We were impressed by their industry.","cn":"他们的勤奋给我们留下深刻印象。"},{"en":"She got a job in industry.","cn":"她找了份工厂里的工作。"}]},"investigator":{"media":{"uk":"media/uk/investigator__gb_1.mp3","us":"media/us/investigator__us_1.mp3"},"oxford":{"phon":"ɪnˈvestɪɡeɪtə(r)","pos":"noun","senses":[{"en":"a person who examines a situation such as an accident or a crime to find out the truth","cn":"调查者；侦查员","ex":{"en":"air safety investigators","cn":"飞行安全调查人员"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"调查者;(尤指)从事调查的人，侦察员","en":"An investigator is someone who carries out investigations, especially as part of their job."}]},"examples":[{"en":"a private investigator (= a detective )","cn":"私人侦探"},{"en":"air safety investigators","cn":"飞行安全调查人员"}]},"industrial":{"media":{"uk":"media/uk/industrial__gb_1.mp3","us":"media/us/industrial__us_1.mp3"},"oxford":{"phon":"ɪnˈdʌstriəl","pos":"adjective","senses":[{"en":"connected with industry","cn":"工业的；产业的","ex":{"en":"an industrial dispute","cn":"劳资纠纷"}},{"en":"used by industries","cn":"用于工业的","ex":{"en":"industrial chemicals","cn":"工业用化学品"}},{"en":"having many industries","cn":"有很多产业的；工业发达的","ex":{"en":"an industrial city/town","cn":"工业城市／城镇"}},{"en":"very great in extent or amount","cn":"大规模的；大量的","ex":{"en":"They had made industrial quantities of food.","cn":"他们做了极大量的食物。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"工业的;产业的","en":"You use industrial to describe things which relate to or are used in industry.","ex":{"en":"...industrial machinery and equipment.","cn":"工业机械与设备"}},{"pos":"ADJ 形容词","cn":"工业高度发达的;工业化的","en":"An industrial city or country is one in which industry is important or highly developed.","ex":{"en":"...ministers from leading western industrial countries.","cn":"西方工业大国的部长们"}}]},"examples":[{"en":"They had made industrial quantities of food (= a lot).","cn":"他们生产了大量的食品。"},{"en":"industrial chemicals","cn":"工业用化学制品"}]},"incurably":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a chronic illness continues for a very long time or is permanent","cn":""},{"en":"a terminal illness is one that cannot be cured, and the person who has it will die from it","cn":""}]},"examples":[{"en":"She has a rare, incurable disease.","cn":"","src":"ld"}],"media":{"uk":"media/uk/incurably__gb_1.mp3","us":"media/us/incurably__us_1.mp3"},"oxford":{"phon":"ɪnˈkjʊərəbli","pos":"adverb","senses":[{"en":"in a way that cannot be cured","cn":"不能治愈的","ex":{"en":"incurably ill","cn":"病入膏肓"}},{"en":"in a way that cannot be changed","cn":"不可逆地；不可撤销地","ex":{"en":"incurably romantic","cn":"无可救药地浪漫"}}]}},"introduction":{"media":{"uk":"media/uk/introduction__gb_1.mp3","us":"media/us/introduction__us_1.mp3"},"oxford":{"phon":"ˌɪntrəˈdʌkʃn","pos":"noun","senses":[{"en":"the first part of a book or speech that gives a general idea of what is to follow","cn":"序言；引言；导论","g":"[countable, uncountable]","sc":"of book/speech","ex":{"en":"a book with an excellent introduction and notes","cn":"有精彩前言和注释的书"}},{"en":"the act of making one person formally known to another or a group of others, in which you tell them the person's name","cn":"（正式的）介绍，引见","g":"[countable]","sc":"of people","ex":{"en":"Introductions were made and the conversation started to flow.","cn":"大家相互介绍后开始交谈。"}},{"en":"the act of bringing something into use or existence for the first time, or of bringing something to a place for the first time","cn":"初次投入使用；采用；引进；推行","g":"[uncountable]","sc":"bringing into use/to a place","ex":{"en":"the introduction of new manufacturing methods","cn":"新制造方法的采用"}},{"en":"a thing that is brought into use or introduced to a place for the first time","cn":"新采用（或新引进）的事物","g":"[countable]","sc":"bringing into use/to a place","ex":{"en":"The book lists plants suitable for the British flower garden, among them many new introductions.","cn":"这本书列出了适合英国花园种植的花草，其中有很多新引进的品种。"}},{"en":"a person’s first experience of something","cn":"初次经历；首次体验","g":"[singular]","sc":"first experience","ex":{"en":"This album was my first introduction to modern jazz.","cn":"这张专辑让我初次接触了现代爵士乐。"}},{"en":"a book or course for people beginning to study a subject","cn":"初级读物；入门课程","g":"[countable]","sc":"to subject","ex":{"en":"‘Global Politics: An Introduction’","cn":"《全球政治学导论》"}},{"en":"a short section at the beginning of a piece of music","cn":"前奏","g":"[countable]","lab":"music","sc":"in music","ex":{"en":"an eight-bar introduction","cn":"有八个小节的前奏"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"引言;序言;导论","en":"The introduction to a book or talk is the part that comes at the beginning and tells you what the rest of the book or talk is about.","ex":{"en":"Ellen Malos, in her introduction to 'The Politics of Housework', provides a summary of the debates.","cn":"埃伦·马洛斯在她为《家务政治学》一书所作的序言中对这些争论进行了总结。"}},{"pos":"N-COUNT 可数名词","cn":"入门书;初阶读物","en":"If you refer to a book as an introduction to a particular subject, you mean that it explains the basic facts about that subject.","ex":{"en":"On balance, the book is a friendly, down-to-earth introduction to physics.","cn":"总而言之,这是一本通俗而务实的物理入门书。"}},{"pos":"N-COUNT 可数名词","cn":"外来品;新引进的东西","en":"You can refer to a new product as an introduction when it becomes available in a place for the first time.","ex":{"en":"There are two among their recent introductions that have greatly impressed me.","cn":"在他们最近引进的东西里面有两样给我留下了非常深刻的印象。"}},{"pos":"PHRASE 短语","cn":"众所周知;无需介绍","en":"If you say that someone or something needs no introduction, you mean that they are so well known that everyone knows who or what they are.","ex":{"en":"Michael Jackson, of course, needs no introduction.","cn":"迈克尔·杰克逊,当然,众所周知。"}}]},"examples":[{"en":"The book lists plants suitable for the British flower garden, among them many new introductions.","cn":"这本书列出了适合英国花园种植的花草，其中有很多新引进的品种。"},{"en":"the 1 000th anniversary of the introduction of Christianity to Russia","cn":"基督教传入俄罗斯 1 000 周年的纪念"}]},"ineffective":{"media":{"uk":"media/uk/ineffective__gb_1.mp3","us":"media/us/ineffective__us_1.mp3"},"oxford":{"phon":"ˌɪnɪˈfektɪv","pos":"adjective","senses":[{"en":"not achieving what you want to achieve; not having any effect","cn":"无效果的；不起作用的；不奏效的","ex":{"en":"The new drug was ineffective.","cn":"新药不起作用。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不起作用的;无效果的;无效率的","en":"If you say that something is ineffective, you mean that it has no effect on a process or situation.","ex":{"en":"Economic reform will continue to be painful and ineffective","cn":"经济改革仍将举步维艰,毫无成效。"}}]},"examples":[{"en":"The law proved ineffective in dealing with the problem.","cn":"事实证明这条法规未能真正解决问题。"},{"en":"The new drug was ineffective.","cn":"新药不起作用。"}]},"inappropriate":{"media":{"uk":"media/uk/inappropriate__gb_1.mp3","us":"media/us/inappropriate__us_1.mp3"},"oxford":{"phon":"ˌɪnəˈprəʊpriət","pos":"adjective","senses":[{"en":"not suitable or appropriate in a particular situation","cn":"不适当的；不合适的","ex":{"en":"inappropriate behaviour/language","cn":"不恰当的行为／语言"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不适用的;不适合的","en":"Something that is inappropriate is not useful or suitable for a particular situation or purpose.","ex":{"en":"The industry is inappropriate to the region's present and future needs","cn":"该行业不适合该地区当前和未来的需要。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不得体的;不合时宜的","en":"If you say that someone's speech or behaviour in a particular situation is inappropriate, you are criticizing it because you think it is not suitable for that situation.","ex":{"en":"I feel the remark was inappropriate for such a serious issue","cn":"我认为对如此严肃的问题来说,该评论不合时宜。"}}]},"examples":[{"en":"She was inappropriately dressed for a funeral.","cn":"她的穿着不适合参加葬礼。"},{"en":"It would be inappropriate for me to comment.","cn":"由我评论并不恰当。"}]},"incurable":{"media":{"uk":"media/uk/incurable__gb_1.mp3","us":"media/us/incurable__us_1.mp3"},"oxford":{"phon":"ɪnˈkjʊərəbl","pos":"adjective","senses":[{"en":"that cannot be cured","cn":"不能治愈的","ex":{"en":"an incurable disease/illness","cn":"不治之症"}},{"en":"that cannot be changed","cn":"不能改变的；无法矫正的","ex":{"en":"She's an incurable optimist.","cn":"她是个不可救药的乐天派。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(疾病)无法治愈的，不可医治的","en":"If someone has an incurable disease, they cannot be cured of it.","ex":{"en":"He is suffering from an incurable skin disease.","cn":"他患有无法根治的皮肤病。"}},{"pos":"ADJ 形容词","cn":"无法改变的;无可救药的","en":"You can use incurable to indicate that someone has a particular quality or attitude and will not change.","ex":{"en":"Poor old William is an incurable romantic","cn":"可怜的老威廉是个无可救药的浪漫主义者。"}}]},"examples":[{"en":"She's an incurable optimist.","cn":"她是个不可救药的乐天派。"},{"en":"incurably ill/romantic","cn":"病入膏肓；浪漫至极"}]},"injustice":{"media":{"uk":"media/uk/injustice__gb_1.mp3","us":"media/us/injustice__us_1.mp3"},"oxford":{"phon":"ɪnˈdʒʌstɪs","pos":"noun","senses":[{"en":"the fact of a situation being unfair and of people not being treated equally; an unfair act or an example of unfair treatment","cn":"不公正，不公平（的对待或行为）","ex":{"en":"We are committed to fighting against poverty and injustice.","cn":"我们致力于消除贫困和不公正。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"非正义;不公平;不公正","en":"Injustice is a lack of fairness in a situation.","ex":{"en":"They'll continue to fight injustice","cn":"他们将继续与不公平现象作斗争。"}},{"pos":"PHRASE 短语","cn":"不公正地评判;不公正地对待","en":"If you say that someone has done you an injustice, you mean that they have been unfair in the way that they have judged you or treated you.","ex":{"en":"The article does them both an injustice.","cn":"那篇文章对他们俩都不公。"}}]},"examples":[{"en":"We may have been doing him an injustice. This work is good.","cn":"我们可能冤枉他了。这工作干得不错。"},{"en":"The report exposes the injustices of the system.","cn":"报告揭露了这个制度的种种不公正。"}]},"invitation":{"media":{"uk":"media/uk/invitation__gb_1.mp3","us":"media/us/invitation__us_1.mp3"},"oxford":{"phon":"ˌɪnvɪˈteɪʃn","pos":"noun","senses":[{"en":"a spoken or written request to somebody to do something or to go somewhere","cn":"（口头或书面的）邀请","g":"[countable]","ex":{"en":"to issue/extend an invitation","cn":"发出／致送邀请"}},{"en":"the act of inviting somebody or of being invited","cn":"邀请；获得邀请","g":"[uncountable]","ex":{"en":"He produced an official letter of invitation.","cn":"他出示了一封正式邀请函。"}},{"en":"a card or piece of paper that you use to invite somebody to something","cn":"请柬；请帖","g":"[countable]","ex":{"en":"We've already sent out the invitations.","cn":"我们已经发出了请柬。"}},{"en":"something that encourages somebody to do something or encourages something to happen, usually something bad","cn":"鼓动；（尤指）怂恿，招致","g":"[countable, usually singular]","ex":{"en":"Leaving the doors unlocked is an open invitation to burglars.","cn":"出门不上锁无异于开门揖盗。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"邀请","en":"An invitation is a written or spoken request to come to an event such as a party, a meal, or a meeting.","ex":{"en":"...an invitation to lunch","cn":"共进午餐的邀请"}},{"pos":"N-COUNT 可数名词","cn":"请帖;请柬","en":"An invitation is the card or paper on which an invitation is written or printed.","ex":{"en":"Hundreds of invitations are being sent out this week.","cn":"本周将寄出数百份请柬。"}},{"pos":"N-SING 单数名词","cn":"诱因;招致…的行为","en":"If you believe that someone's action is likely to have a particular result, especially a bad one, you can refer to the action as an invitation to that result.","ex":{"en":"...a war that most liberal Democrats regarded as an invitation to disaster","cn":"一场大部分自由民主党人认为会招致灾难的战争"}}]},"examples":[{"en":"I have an open invitation (= not restricted to a particular date) to visit my friend in Japan.","cn":"我在日本的朋友邀请我随时去看他。"},{"en":"A concert was held at the invitation of the mayor.","cn":"在市长的邀请下举办了一场音乐会。"}]},"intensive":{"media":{"uk":"media/uk/intensive__gb_1.mp3","us":"media/us/intensive__us_1.mp3"},"oxford":{"phon":"ɪnˈtensɪv","pos":"adjective","senses":[{"en":"involving a lot of work or activity done in a short time","cn":"短时间内集中紧张进行的；密集的","ex":{"en":"an intensive language course","cn":"速成语言课程"}},{"en":"complete and extremely detailed; done with a lot of care","cn":"彻底的；十分细致的","ex":{"en":"His disappearance has been the subject of intensive investigation.","cn":"他失踪一事一直是大力调查的重点。"}},{"en":"aimed at producing as much food as possible using as little land or as little money as possible","cn":"集约的","ex":{"en":"Traditionally reared animals grow more slowly than those reared under intensive farming conditions.","cn":"按传统方式饲养的家畜比集约饲养的长得慢。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"加强的;集中的;密集的","en":"Intensive activity involves concentrating a lot of effort or people on one particular task in order to try to achieve a great deal in a short time.","ex":{"en":"...several days and nights of intensive negotiations","cn":"几天几夜紧锣密鼓的谈判"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"集约(经营)的;精耕细作的","en":"Intensive farming involves producing as many crops or animals as possible from your land, usually with the aid of chemicals.","ex":{"en":"Elsewhere large areas have been drained and levelled for industry or intensive farming.","cn":"在别处,大片区域被抽干了水或铲平了地，以作为工业或集约化农业用地。"}}]},"examples":[{"en":"Traditionally reared animals grow more slowly than those reared under intensive farming conditions.","cn":"按传统方式饲养的家畜比集约饲养的长得慢。"},{"en":"His disappearance has been the subject of intensive investigation.","cn":"他的失踪一直是大力调查的重点。"}]},"interviewing":{"oxford":{"phon":"ˈɪntəvjuːɪŋ","pos":"noun","senses":[{"en":"the activity of asking somebody questions in an interview","cn":"主持面试者；采访者","ex":{"en":"interviewing techniques","cn":"面试技巧"}}]},"media":{"uk":"media/uk/interviewing__gb_1.mp3","us":"media/us/interviewing__us_1.mp3"},"examples":[{"en":"The research involves in-depth interviewing.","cn":"这一调查包括深入的采访。"},{"en":"interviewing techniques","cn":"面谈技巧"}]},"invariably":{"media":{"uk":"media/uk/invariably__gb_1.mp3","us":"media/us/invariably__us_1.mp3"},"oxford":{"phon":"ɪnˈveəriəbli","pos":"adverb","senses":[{"en":"always","cn":"始终如一地；一贯地","ex":{"en":"This acute infection of the brain is almost invariably fatal.","cn":"这种急性大脑传染病几乎总是导致死亡。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"不变地;总是;始终如一地","en":"If something invariably happens or is invariably true, it always happens or is always true.","ex":{"en":"They almost invariably get it wrong","cn":"他们几乎总是理解错。"}}]},"examples":[{"en":"This acute infection of the brain is almost invariably fatal.","cn":"这种急性大脑传染病几乎总是导致死亡。"},{"en":"Invariably the reply came back, ‘Not now!’","cn":"答复无例外地又是：“现在不行！”"}]},"increases":{"oxford":{"phon":"ɪnˈkriːs","pos":"verb","senses":[{"en":"to become or to make sth greater in amount, number, value, etc. （","cn":"使）增长，增多；增加"},{"en":"a rise in the amount, number or value of sth","cn":"增长；增多；增加"}]},"media":{"uk":"media/uk/increase__gb_1.mp3","us":"media/us/increase__us_1.mp3"}},"international":{"media":{"uk":"media/uk/international__gb_1.mp3","us":"media/us/international__us_1.mp3"},"oxford":{"phon":"ˌɪntəˈnæʃnəl","pos":"adjective","senses":[{"en":"connected with or involving two or more countries","cn":"国际的；多国的","lab":"US English","ex":{"en":"international trade/law","cn":"国际贸易；国际法"}},{"en":"used by people of many different countries","cn":"国际化的；面向国际的","ex":{"en":"large international hotels","cn":"大型国际酒店"}},{"en":"a sports competition involving teams from two countries","cn":"国际体育比赛","lab":"British English","ex":{"en":"the France-Scotland rugby international","cn":"法国对苏格兰的国际橄榄球赛"},"pos":"noun"},{"en":"a player who takes part in a sports competition against another country","cn":"参加国际比赛的国家队选手","lab":"British English","ex":{"en":"a former swimming international","cn":"前国际游泳比赛选手"},"pos":"noun"},{"en":"a person from a foreign country","cn":"外国人","lab":"North American English","ex":{"en":"an English course for internationals","cn":"为外国人开设的英语课程"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"国际的;国际上的","en":"International means between or involving different countries.","ex":{"en":"...an international agreement against exporting arms to that country.","cn":"禁止向该国出口武器的国际协定"}},{"pos":"N-COUNT 可数名词","cn":"国际比赛","en":"In sport, an international is a game that is played between teams representing two different countries.","ex":{"en":"...the midweek international against England.","cn":"周三对抗英格兰的国际比赛"}},{"pos":"N-COUNT 可数名词","cn":"国际比赛选手;国家队队员","en":"An international is a member of a country's sports team.","ex":{"en":"...a former England international.","cn":"前英格兰国手"}}]},"examples":[{"en":"a pianist with an international reputation","cn":"饮誉国际的钢琴家"},{"en":"international trade/law/sport","cn":"国际贸易；国际法；国际体育运动"}]},"integration":{"media":{"uk":"media/uk/integration__gb_1.mp3","us":"media/us/integration__us_1.mp3"},"oxford":{"phon":"ˌɪntɪˈɡreɪʃn","pos":"noun","senses":[{"en":"the act or process of combining two or more things so that they work together","cn":"结合；整合；一体化","g":"[uncountable, countable]","ex":{"en":"The aim is to promote closer economic integration.","cn":"目的是进一步促进经济一体化。"}},{"en":"the act or process of mixing people who have previously been separated, usually because of colour, race, religion, etc.","cn":"（不同肤色、种族、宗教信仰等的人的）混合，融合","g":"[uncountable]","lab":"British English","ex":{"en":"racial integration in schools","cn":"学校对不同种族学生的接纳"}}]},"examples":[{"en":"The aim is to promote closer economic integration.","cn":"目的是进一步促进经济一体化。"},{"en":"His music is an integration of tradition and new technology.","cn":"他的音乐结合了传统和新技术。"}]},"indispensable":{"oxford":{"phon":"ˌɪndɪˈspensəbl","pos":"adjective","senses":[{"en":"too important to be without","cn":"不可或缺的；必不可少的","ex":{"en":"Cars have become an indispensable part of our lives.","cn":"汽车已成了我们生活中必不可少的一部分。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"必不可少的;不可或缺的","en":"If you say that someone or something is indispensable, you mean that they are absolutely essential and other people or things cannot function without them.","ex":{"en":"She was becoming indispensable to him.","cn":"他已变得越来越离不开她了。"}}]},"media":{"uk":"media/uk/indispensable__gb_1.mp3","us":"media/us/indispensable__us_1.mp3"},"examples":[{"en":"Cars have become an indispensable part of our lives.","cn":"汽车已成了我们生活中必不可少的一部分。"},{"en":"She made herself indispensable to the department.","cn":"她成为这个部门不可缺少的一分子。"}]},"indian":{"media":{"uk":"media/uk/indian__gb_1.mp3","us":"media/us/indian__us_1.mp3"},"oxford":{"phon":"ˈɪndiən","pos":"noun","senses":[{"en":"a person from India or whose family comes from India","cn":"印度人","ex":{"en":"There are around 1.5 million British Indians in the UK.","cn":"英国约有 150 万英属印度人。"}},{"en":"a member of one of the indigenous (= original) peoples of America, especially North America","cn":"（美洲）印第安人","lab":"old-fashioned, sometimes offensive，，"},{"en":"a Native Canadian who is not Inuit or Metis","cn":"（非因纽特人或米提人的）加拿大土著；加拿大印第安人","lab":"Canadian English"},{"en":"of or connected with India or with the subcontinent that includes India, Pakistan and Bangladesh","cn":"印度人","ex":{"en":"Indian farmers","cn":"印度农民"},"pos":"adjective"},{"en":"of or connected with any of the indigenous (= original) peoples of America, especially North America","cn":"（美洲）印第安人的","lab":"old-fashioned, sometimes offensive，，","pos":"adjective"},{"en":"of or connected with Native Canadians who are not Inuit or Metis","cn":"（非因纽特人或米提人的）加拿大土著；加拿大印第安人","lab":"Canadian English","pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"印度的;印度人的;印度文化的","en":"Indian means belonging or relating to India, or to its people or culture.","ex":{"en":"...the Indian government.","cn":"印度政府"}},{"pos":"N-COUNT 可数名词","cn":"印度人","en":"An Indian is an Indian citizen, or a person of Indian origin.","ex":{"en":"...a study of Indians and Pakistanis living in Southall.","cn":"对生活在绍索尔的印度人和巴基斯坦人的研究"}},{"pos":"N-COUNT 可数名词","cn":"印第安人(现在通常称作Native Americans)","en":"Indians are the people who lived in North, South, or Central America before Europeans arrived, or people related to them. The usual name for them now is Native Americans .","ex":{"en":"The South American Indians have been cooking and eating potatoes for well over two thousand years.","cn":"南美印第安人烹调食用土豆已有2000多年的历史了。"}}]},"examples":[{"en":"Do you fancy going out for an Indian?","cn":"你想出去吃印度菜吗？"}]},"incentive":{"media":{"uk":"media/uk/incentive__gb_1.mp3","us":"media/us/incentive__us_1.mp3"},"oxford":{"phon":"ɪnˈsentɪv","pos":"noun","senses":[{"en":"something that encourages you to do something","cn":"激励；刺激；鼓励","g":"[countable, uncountable]","ex":{"en":"There is no incentive for people to save fuel.","cn":"没有鼓励人们节约燃料的措施。"}},{"en":"a payment or concession (= a reduction in the amount of money that has to be paid) that encourages somebody to do something","cn":"激励奖金；激励性减免优惠","g":"[countable]","ex":{"en":"tax incentives to encourage savings","cn":"鼓励储蓄的税收措施"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"刺激;激励;奖励","en":"If something is an incentive to do something, it encourages you to do it.","ex":{"en":"There is little or no incentive to adopt such measures","cn":"几乎没有什么激励政策来促使人们采取这些措施。"}}]},"examples":[{"en":"There is no incentive for people to save fuel.","cn":"没有鼓励人们节约燃料的措施。"},{"en":"tax incentives to encourage savings","cn":"鼓励储蓄的税收措施"}]},"instability":{"oxford":{"phon":"ˌɪnstəˈbɪləti","pos":"noun","senses":[{"en":"the quality or state of being likely to change or fail suddenly","cn":"不稳定；不稳固","ex":{"en":"political and economic instability","cn":"政治和经济的不稳定"}},{"en":"a mental condition in which somebody’s behaviour is likely to change suddenly","cn":"（精神的）不稳定状态，变化无常","ex":{"en":"mental/emotional instability","cn":"精神／情绪的不稳定"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"不稳定(性);不稳固(性)","en":"Instability is the quality of being unstable.","ex":{"en":"...unpopular policies, which resulted in social discontent and political instability.","cn":"导致社会不满与政治不稳定的不得人心的政策"}}]},"media":{"uk":"media/uk/instability__gb_1.mp3","us":"media/us/instability__us_1.mp3"},"examples":[{"en":"political and economic instability","cn":"政治和经济的不稳定"},{"en":"mental/emotional instability","cn":"精神/情绪的不稳定"}]},"inland":{"media":{"uk":"media/uk/inland__gb_1.mp3","us":"media/us/inland__us_1.mp3"},"oxford":{"phon":"ˌɪnˈlænd","pos":"adverb","senses":[{"en":"in or towards the middle of a country; away from the coast","cn":"向（或在）内陆；向（或在）内地","ex":{"en":"The town lies a few kilometres inland.","cn":"这个城镇位于内陆几公里处。"}},{"en":"located in or near the middle of a country, not near the edge or on the coast","cn":"（在）内陆的；（在）内地的","ex":{"en":"inland areas","cn":"内陆地区"},"pos":"adjective"},{"en":"taking place within one country, not between different countries","cn":"国内的","lab":"especially British English","ex":{"en":"inland trade","cn":"国内贸易"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"在内地(或内陆);向内地(或内陆)","en":"If something is situated inland, it is away from the coast, towards or near the middle of a country. If you go inland, you go away from the coast, towards the middle of a country.","ex":{"en":"The vast majority live further inland","cn":"大部分人住在更远的内地。"}},{"pos":"ADJ 形容词","cn":"内地的;内陆的","en":"Inland areas, lakes, and places are not on the coast, but in or near the middle of a country.","ex":{"en":"...a rather quiet inland town.","cn":"颇为宁静的内陆城镇"}}]},"examples":[{"en":"The town lies a few kilometres inland.","cn":"这个城镇位于内陆几公里处。"},{"en":"We travelled further inland the next day.","cn":"我们第二天继续向内陆行进。"}]},"incline":{"media":{"uk":"media/uk/incline__gb_1.mp3","us":"media/us/incline__us_1.mp3"},"oxford":{"phon":"ɪnˈklaɪn","pos":"verb","senses":[{"en":"to tend to think or behave in a particular way; to make somebody do this","cn":"（使）倾向于，有…的趋势","g":"[intransitive, transitive]","ex":{"en":"I incline to the view that we should take no action at this stage.","cn":"我倾向于认为我们在这个阶段不应采取行动。"}},{"en":"to bend your head forward, especially as a sign of agreement, welcome, etc.","cn":"点头（尤指以示同意、欢迎等）","g":"[transitive]","ex":{"en":"He inclined his head in acknowledgement.","cn":"他点头承认。"}},{"en":"to lean or slope in a particular direction; to make something lean or slope","cn":"（使）倾斜","g":"[intransitive, transitive]","ex":{"en":"The land inclined gently towards the shore.","cn":"地面缓缓向海岸倾斜。"}},{"en":"a slope","cn":"斜坡；倾斜；斜度","ex":{"en":"a steep/slight incline","cn":"陡坡；缓坡"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)倾向;(使)趋向","en":"If you incline to think or act in a particular way, or if something inclines you to it, you are likely to think or act in that way.","ex":{"en":"I incline to the view that he is right.","cn":"我倾向于认为他是正确的。"}},{"pos":"VERB 动词","cn":"点(头)","en":"If you incline your head, you bend your neck so that your head is leaning forward.","ex":{"en":"Jack inclined his head very slightly.","cn":"杰克轻轻点了点头。"}},{"pos":"N-COUNT 可数名词","cn":"斜坡;斜面","en":"An incline is land that slopes at an angle.","ex":{"en":"He came to a halt at the edge of a steep incline.","cn":"他在一个陡坡边上停住了。"}}]},"examples":[{"en":"I incline to the view that we should take no action at this stage.","cn":"我倾向于认为我们在这个阶段不应采取行动。"},{"en":"The government is more effective than we incline to think.","cn":"政府比我们所惯常以为的要有成效。"}]},"inflection":{"oxford":{"phon":"ɪnˈflekʃn","pos":"noun","senses":[{"en":"a change in the form of a word, especially the ending, according to its grammatical function in a sentence","cn":"（尤指词尾的）屈折变化"},{"en":"a change in how high or low your voice is as you are speaking","cn":"语调的抑扬变化","ex":{"en":"She spoke slowly and without inflection.","cn":"她说得很慢, 声调没有抑扬变化"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"变音;转调;语调的抑扬变化","en":"An inflection in someone's voice is a change in its tone or pitch as they are speaking.","ex":{"en":"The man's voice was devoid of inflection","cn":"那人的声音缺少抑扬变化。"}},{"pos":"N-VAR 可变名词","cn":"(词形的)屈折变化;屈折形式","en":"In grammar, an inflection is a change in the form of a word that shows its grammatical function, for example a change that makes a noun plural or makes a verb into the past tense."}]},"media":{"uk":"media/uk/inflection__gb_1.mp3","us":"media/us/inflection__us_1.mp3"}},"infection":{"oxford":{"phon":"ɪnˈfekʃn","pos":"noun","senses":[{"en":"the act or process of causing or getting a disease","cn":"传染；感染","g":"[uncountable]","ex":{"en":"to cause/prevent infection","cn":"引起／预防感染"}},{"en":"an illness that is caused by bacteria or a virus and that affects one part of the body","cn":"（身体某部位的）感染；传染病","g":"[countable]","ex":{"en":"an ear/a chest infection","cn":"耳朵／胸部感染"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"传染病;感染","en":"An infection is a disease caused by germs or bacteria.","ex":{"en":"Ear infections are common in pre-school children","cn":"耳部感染在学前儿童中很常见。"}}]},"media":{"uk":"media/uk/infection__gb_1.mp3","us":"media/us/infection__us_1.mp3"},"examples":[{"en":"to increase the risk of infection","cn":"增加传染的危险"},{"en":"to be exposed to infection","cn":"暴露于易受感染的环境"}]},"inexpensive":{"oxford":{"phon":"ˌɪnɪkˈspensɪv","pos":"adjective","senses":[{"en":"not costing a lot of money","cn":"不昂贵的","ex":{"en":"a relatively inexpensive hotel","cn":"相对廉价的旅馆"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"花费不多的;价钱不贵的","en":"Something that is inexpensive does not cost very much.","ex":{"en":"...a variety of good inexpensive restaurants.","cn":"许多价钱实惠的餐馆"}}]},"media":{"uk":"media/uk/inexpensive__gb_1.mp3","us":"media/us/inexpensive__us_1.mp3"},"examples":[{"en":"a relatively inexpensive hotel","cn":"相对廉价的旅馆"},{"en":"a good selection of inexpensive wines","cn":"可供选择的各种价格公道的葡萄酒"}]},"initiated":{"oxford":{"phon":"ɪˈnɪʃieɪt","pos":"verb","senses":[{"en":"( formal ) to make sth begin","cn":"开始；发起；创始"},{"en":"to explain sth to sb and/or make them experience it for the first time","cn":"使了解；传授；教 … 开始尝试"}]}},"interesting":{"media":{"uk":"media/uk/interesting__gb_1.mp3","us":"media/us/interesting__us_1.mp3"},"oxford":{"phon":"ˈɪntrəstɪŋ","pos":"adjective","senses":[{"en":"attracting your attention because it is/they are special, exciting or unusual","cn":"有趣的；有吸引力的","ex":{"en":"The article raises several interesting questions.","cn":"这篇文章提出了几个有趣的问题。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有趣的;令人感兴趣的","en":"If you find something interesting, it attracts your attention, for example because you think it is exciting or unusual.","ex":{"en":"It was interesting to be in a different environment","cn":"到一个全新的环境中是很有意思的。"}}]},"examples":[{"en":"Interestingly, there are very few recorded cases of such attacks.","cn":"有意思的是，记录在案的此类袭击事件很少。"},{"en":"I find it interesting that she claims not to know him.","cn":"她声称不认识他，我觉得真是耐人寻味。"}]},"inequality":{"media":{"uk":"media/uk/inequality__gb_1.mp3","us":"media/us/inequality__us_1.mp3"},"oxford":{"phon":"ˌɪnɪˈkwɒləti","pos":"noun","senses":[{"en":"the unfair difference between groups of people in society, when some have more wealth, status or opportunities than others","cn":"不平等；不平衡；不平均","lab":"British English","ex":{"en":"We need to tackle inequality of opportunity wherever we find it.","cn":"无论我们在哪里发现机会不平等，我们都需要解决它。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(社会地位、财富、机会等)不平等，不均等","en":"Inequality is the difference in social status, wealth, or opportunity between people or groups.","ex":{"en":"People are concerned about social inequality","cn":"人们很关注社会不平等问题。"}}]},"examples":[{"en":"economic inequalities between different areas","cn":"不同地区间的经济不平衡落差"},{"en":"inequality of opportunity","cn":"机会的不均"}]},"indirect":{"oxford":{"phon":"ˌɪndəˈrekt","pos":"adjective","senses":[{"en":"happening not as the main aim, cause or result of a particular action, but in addition to it","cn":"间接的；附带的","ex":{"en":"the indirect effects of the war","cn":"战争的间接后果"}},{"en":"not done directly; done through somebody/something else","cn":"非亲自做的；由别人经手的","ex":{"en":"territories under the indirect control of the British","cn":"英国间接控制的领地"}},{"en":"avoiding saying something in a clear and obvious way","cn":"闪烁其词的；拐弯抹角的","ex":{"en":"The comment was an indirect attack on the prime minister.","cn":"这番评论婉转地批评了首相。"}},{"en":"not going in a straight line","cn":"迂回的；弯曲的","ex":{"en":"an indirect route","cn":"迂回的路线"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"间接的;非直接的","en":"An indirect result or effect is not caused immediately and obviously by a thing or person, but happens because of something else that they have done.","ex":{"en":"Businesses are feeling the indirect effects from the recession that's going on elsewhere","cn":"企业感受到了别处经济衰退带来的间接影响。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(路线、行程等)迂回的，非直达的","en":"An indirect route or journey does not use the shortest or easiest way between two places.","ex":{"en":"The goods went by a rather indirect route.","cn":"这些货物运输时走了一条非常迂回的路线。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(话语或信息)含蓄的,拐弯抹角的","en":"Indirect remarks and information suggest something or refer to it, without actually mentioning it or stating it clearly.","ex":{"en":"His remarks amounted to an indirect appeal for economic aid","cn":"他的话相当于拐弯抹角地请求经济援助。"}}]},"media":{"uk":"media/uk/indirect__gb_1.mp3","us":"media/us/indirect__us_1.mp3"},"examples":[{"en":"The new law will affect us all, directly or indirectly.","cn":"新的法规将直接或间接地影响我们所有的人。"},{"en":"There would be some benefit, however indirect, to the state.","cn":"国家会得到一些利益，不管有多少。"}]},"influence":{"media":{"uk":"media/uk/influence__gb_1.mp3","us":"media/us/influence__us_1.mp3"},"oxford":{"phon":"ˈɪnfluəns","pos":"noun","senses":[{"en":"the effect that somebody/something has on the way a person thinks or behaves or on the way that something works or develops","cn":"影响；作用","g":"[uncountable, countable]","ex":{"en":"His early work shows the influence of Cézanne and Matisse.","cn":"他的早期作品显示了塞尚和马蒂斯的影响。"}},{"en":"the power that somebody/something has to make somebody/something behave in a particular way","cn":"支配力；控制力；影响力","g":"[uncountable]","ex":{"en":"He worked his way into a position of power and influence in the city.","cn":"他通过自己的努力在这座城市中获得了权力和影响力。"}},{"en":"a person or thing that affects the way a person behaves and thinks","cn":"（对…）有影响的人（或事物）","g":"[countable]","ex":{"en":"She draws on her diverse cultural influences to express herself.","cn":"她利用多元文化的影响来表达自己。"}},{"en":"to have an effect on the way that somebody behaves or thinks, especially by giving them an example to follow","cn":"影响；对…起作用","ex":{"en":"His writings have influenced the lives of millions.","cn":"他的作品影响了千百万人的一生。"},"pos":"verb"},{"en":"to have an effect on a particular situation and the way that it develops","cn":"支配；左右","ex":{"en":"A number of social factors influence life expectancy.","cn":"人的预期寿命受到若干社会因素的制约。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"势力;权势;影响力;支配力","en":"Influence is the power to make other people agree with your opinions or do what you want.","ex":{"en":"As Hugh grew older, she had less influence and couldn't control him","cn":"休慢慢长大,她的影响力变小了,无法再控制他了。"}},{"pos":"VERB 动词","cn":"影响;左右;支配","en":"If you influence someone, you use your power to make them agree with you or do what you want.","ex":{"en":"He is trying to improperly influence a witness","cn":"他在试图误导证人。"}},{"pos":"N-COUNT 可数名词","cn":"影响;作用","en":"To have an influence on people or situations means to affect what they do or what happens.","ex":{"en":"Van Gogh had a major influence on the development of modern painting","cn":"凡·高对现代绘画的发展有着重大影响。"}},{"pos":"VERB 动词","cn":"影响;对…起作用","en":"If someone or something influences a person or situation, they have an effect on that person's behaviour or that situation.","ex":{"en":"We became the best of friends and he influenced me deeply","cn":"我们成了最好的朋友,他深深地影响了我。"}},{"pos":"N-COUNT 可数名词","cn":"有影响的人(或事物)","en":"Someone or something that is a good or bad influence on people has a good or bad effect on them.","ex":{"en":"I thought Sue would be a good influence on you","cn":"我认为苏能对你产生良好影响。"}},{"pos":"PHRASE 短语","cn":"在…影响之下;在…控制之下","en":"If you are under the influence of someone or something, you are being affected or controlled by them.","ex":{"en":"I fell under the influence of a history master","cn":"我当时深受一位历史老师的影响。"}},{"pos":"PHRASE 短语","cn":"喝醉;(吸食毒品后)处于迷幻状态","en":"If someone is under the influence, their mind is affected by alcohol or drugs.","ex":{"en":"Police charged the man with driving under the influence","cn":"警方指控那名男子酒后驾车。"}}]},"examples":[{"en":"His first music teacher was a major influence in his life.","cn":"他的第一位音乐老师是他一生中对他影响非常大的人。"},{"en":"She could probably exert her influence with the manager and get you a job.","cn":"她很有可能对经理施展她的影响力，给你弄份工作。"}]},"independence":{"oxford":{"phon":"ˌɪndɪˈpendəns","pos":"noun","senses":[{"en":"freedom from political control by other countries","cn":"独立","ex":{"en":"Cuba gained independence from Spain in 1898.","cn":"引发独立的一次殖民危机"}},{"en":"the time when a country gains freedom from political control by another country","cn":"独立（之日）","ex":{"en":"independence celebrations","cn":"独立纪念庆典"}},{"en":"the freedom to organize your own life, make your own decisions, etc. without needing help from other people","cn":"自主；自立","ex":{"en":"He values his independence.","cn":"他珍惜他的独立自主。"}},{"en":"a US city in the state of Missouri. President Harry S Truman lived there, and his official library and museum can be visited. The international office of the Reorganized Church of Jesus Christ of Latter Day Saints is also there. In the 1830s and 1840s, people began their journeys west on the Santa Fe Trail and the Oregon Trail from Independence.","cn":"独立性：密苏里州的美国城市。哈里·杜鲁门（Harry S Truman）总统住在那里，可以参观他的官方图书馆和博物馆。重组的耶稣基督后期圣徒教会的国际办公室也在那里。在1830年代和1840年代，人们从独立开始在圣达菲步道和俄勒冈步道向西行驶。","pos":""}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(国家的)独立,自主","en":"If a country has or gains independence, it has its own government and is not ruled by any other country.","ex":{"en":"In 1816, Argentina declared its independence from Spain.","cn":"1816年,阿根廷宣布脱离西班牙正式独立。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(人的)独立,自立","en":"Someone's independence is the fact that they do not rely on other people.","ex":{"en":"He was afraid of losing his independence.","cn":"他害怕失去自己的独立性。"}}]},"media":{"uk":"media/uk/independence__gb_1.mp3","us":"media/us/independence__us_1.mp3"},"examples":[{"en":"Cuba gained independence from Spain in 1898.","cn":"古巴于 1898 年脱离西班牙而获得独立。"},{"en":"He values his independence.","cn":"他珍惜他的独立自主。"}]},"information":{"media":{"uk":"media/uk/information__gb_1.mp3","us":"media/us/information__us_1.mp3"},"oxford":{"phon":"ˌɪnfəˈmeɪʃn","pos":"noun","senses":[{"en":"facts or details about somebody/something","cn":"信息；消息；情报；资料","ex":{"en":"a piece of information","cn":"一则消息"}},{"en":"a phone service that you can use to find out a person's phone number","cn":"电话号码查询台","lab":"North American English, informal，，"},{"en":"data that is processed, stored or sent by a computer","cn":"（计算机上的）数据，信息","ex":{"en":"Algorithms are essential to the way computers process information.","cn":"算法对计算机处理信息至关重要。"}},{"en":"what is represented by a particular arrangement or sequence of things","cn":"（特定排列或顺序所代表的）信息","ex":{"en":"the transfer of genetic information from DNA to RNA","cn":"遗传信息从脱氧核糖核酸到核糖核酸的传递"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"消息;资料;情报","en":"Information about someone or something consists of facts about them.","ex":{"en":"Pat refused to give her any information about Sarah","cn":"帕特拒绝向她提供任何关于萨拉的消息。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(计算机程序储存和使用的)数据,资料","en":"Information consists of the facts and figures that are stored and used by a computer program.","ex":{"en":"Pictures are scanned into a form of digital information that computers can recognize.","cn":"照片被扫描成某种电脑可以识别的数字资料。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"问讯处;信息台","en":"Information is a service which you can telephone to find out someone's telephone number."}]},"examples":[{"en":"For further information on the diet, write to us at this address.","cn":"欲知规定饮食的详情，请按这个地址给我们写信。"},{"en":"This leaflet is produced for the information of (= to inform) our customers.","cn":"这张传单是为向我们的顾客提供信息而印制的。"}]},"inescapably":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an inescapable fact or situation is one that you cannot avoid or ignore","cn":""}]},"examples":[{"en":"She didn’t want to confront the inescapable fact that she would have to sell the house.","cn":"","src":"ld"},{"en":"The inescapable conclusion is that he was murdered by someone in his own family.","cn":"","src":"ld"}],"media":{"uk":"media/uk/inescapably__gb_1.mp3","us":"media/us/inescapably__us_1.mp3"},"oxford":{"phon":"ˌɪnɪˈskeɪpəbli","pos":"adverb","senses":[{"en":"in a way that you cannot avoid or ignore","cn":"不可避免的；逃避不了的；不能忽视的","ex":{"en":"A catastrophe must inescapably result from this tactic.","cn":"这种策略必然导致灾难。"}}]}},"instruments":{"oxford":{"phon":"ˈɪnstrəmənt","pos":"noun","senses":[{"en":"a tool or device used for a particular task, especially for delicate or scientific work","cn":"器械；仪器；器具"},{"en":"a device used for measuring speed, distance, temperature, etc. in a vehicle or on a piece of machinery （","cn":"车辆、机器的）仪器，仪表"}]}},"intending":{"oxford":{"phon":"ɪnˈtend","pos":"verb","senses":[{"en":"to have a plan, result or purpose in your mind when you do sth","cn":"打算；计划；想要"},{"en":"( rather formal ) to plan that sth should have a particular meaning","cn":"意指"}]},"media":{"uk":"media/uk/intend__gb_1.mp3","us":"media/us/intend__us_1.mp3"}},"informally":{"oxford":{"phon":"ɪnˈfɔːməli","pos":"adverb","senses":[{"en":"in a relaxed and friendly way; in a way that does not follow strict rules of how to behave or do something","cn":"不拘礼节的；友好随便的；非正规的","ex":{"en":"They told me informally (= not officially) that I had got the job.","cn":"他们非正式地通知我，说我获得聘用了。"}},{"en":"if you are dressed informally, you are wearing clothes that are suitable for wearing at home or when relaxing rather than for a special or an official occasion","cn":"日常的；随便的"}]},"media":{"uk":"media/uk/informally__gb_1.mp3","us":"media/us/informally__us_1.mp3"},"examples":[{"en":"They told me informally (= not officially) that I had got the job.","cn":"他们非正式地告诉我说，我得到了那份工作。"},{"en":"to dress informally","cn":"穿着便服"}]},"injuries":{"oxford":{"phon":"ˈɪndʒəri","pos":"noun","senses":[{"en":"harm done to a person's or an animal's body, for example in an accident （","cn":"对躯体的）伤害，损伤"},{"en":"( law","cn":"律 ) damage to a person's feelings （对感情的）伤害，挫伤"}]}},"inaccessibility":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"impossible to reach","cn":""},{"en":"difficult or impossible to reach","cn":""}]},"examples":[{"en":"In winter, the villages are inaccessible by road.","cn":"","src":"ld"},{"en":"A long flight of stairs made the center inaccessible to disabled visitors.","cn":"","src":"ld"}],"media":{"uk":"media/uk/inaccessibility__gb_1.mp3","us":"media/us/inaccessibility__us_1.mp3"},"oxford":{"phon":"ˌɪnækˌsesəˈbɪləti","pos":"noun","senses":[{"en":"the fact of being impossible to reach or to get","cn":"难以达到的；不可得到的","ex":{"en":"the inaccessibility of the island","cn":"该岛交通不便"}},{"en":"the fact of being difficult to understand or appreciate","cn":"难以接近：难以理解或欣赏","ex":{"en":"the inaccessibility of much of his writing","cn":"他的大部分作品难以理解"}}]}},"involved":{"media":{"uk":"media/uk/involved__gb_1.mp3","us":"media/us/involved__us_1.mp3"},"oxford":{"phon":"ɪnˈvɒlvd","pos":"adjective","senses":[{"en":"taking part in something; being part of something or connected with something","cn":"参与；作为一部分；有关联","g":"[not before noun]","ex":{"en":"Some people tried to stop the fight but I didn't want to get involved.","cn":"有人设法阻止打斗，但我不想牵涉进去。"}},{"en":"giving a lot of time or attention to somebody/something","cn":"耗费很多时间；关注","g":"[not usually before noun]","ex":{"en":"She was deeply involved with the local hospital.","cn":"她曾全心投入当地医院。"}},{"en":"having a close personal relationship with somebody","cn":"关系密切","g":"[not usually before noun]","ex":{"en":"They're not romantically involved.","cn":"他们之间没有爱情关系。"}},{"en":"complicated and difficult to understand","cn":"复杂难解的","ex":{"en":"an involved plot","cn":"复杂的情节"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"卷入的;参与的;与…有密切关联的","en":"If you are involved in a situation or activity, you are taking part in it or have a strong connection with it.","ex":{"en":"If she were involved in business, she would make a strong chief executive","cn":"如果她投身商业的话,她会是一个很有能力的总裁。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"专心于…的;忙于…的","en":"If you are involved in something, you give a lot of time, effort, or attention to it.","ex":{"en":"The family were deeply involved in Jewish culture.","cn":"这家人非常注重学习犹太文化。"}},{"pos":"ADJ 形容词","cn":"包含的;涉及的","en":"The things involved in something such as a job or system are the necessary parts or consequences of it.","ex":{"en":"We believe the time and hard work involved in completing such an assignment are worthwhile","cn":"我们认为完成这项任务所必须付出的时间与辛苦都是值得的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"复杂难懂的;棘手的;难处理的","en":"If a situation or activity is involved, it has a lot of different parts or aspects, often making it difficult to understand, explain, or do.","ex":{"en":"The operations can be quite involved, requiring many procedures.","cn":"手术可能非常复杂,需要对多处进行手术。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"关系暧昧的;有情爱关系的","en":"If one person is involved with another, especially someone they are not married to, they are having a sexual or romantic relationship.","ex":{"en":"He became romantically involved with a married woman.","cn":"他与一位已婚妇女产生了恋情。"}}]},"examples":[{"en":"We need to examine all the costs involved in the project first.","cn":"我们首先应该仔细考虑所有与这一项目有关的费用。"},{"en":"Some people tried to stop the fight but I didn't want to get involved.","cn":"有人设法阻止打斗，但我不想牵涉进去。"}]},"insured":{"media":{"uk":"media/uk/insured__gb_1.mp3","us":"media/us/insured__us_1.mp3"},"oxford":{"phon":"ɪnˈʃʊəd","pos":"adjective","senses":[{"en":"having insurance","cn":"被保险的","ex":{"en":"Was the vehicle insured?","cn":"那辆车上保险了吗？"}},{"en":"the person who has made an agreement with an insurance company and who receives money if, for example, they are ill or if they lose or damage something","cn":"被保险人","lab":"law"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"被保险人;受保人","en":"The insured is the person who is insured by a particular policy.","ex":{"en":"Once the insured has sold his policy, he naturally loses all rights to it.","cn":"一旦被保险人卖出保单,他就自然失去了上面所有的权利。"}}]},"examples":[{"en":"You're not insured to drive our car.","cn":"你开我们的车不在保险范围内。"},{"en":"Was the vehicle insured?","cn":"那辆车上保险了吗？"}]},"infinite":{"media":{"uk":"media/uk/infinite__gb_1.mp3","us":"media/us/infinite__us_1.mp3"},"oxford":{"phon":"ˈɪnfɪnət","pos":"adjective","senses":[{"en":"very great; impossible to measure","cn":"极大的；无法衡量的","lab":"ironic","ex":{"en":"an infinite variety of plants","cn":"数不清的植物种类"}},{"en":"without limits; without end","cn":"无限的；无穷尽的","ex":{"en":"an infinite universe","cn":"无垠的宇宙"}},{"en":"something that has no end","cn":"无限的事物；无穷尽的事物","pos":"noun"},{"en":"God","cn":"上帝","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"极多的;极度的","en":"If you describe something as infinite, you are emphasizing that it is extremely great in amount or degree.","ex":{"en":"...an infinite variety of landscapes","cn":"变化万千的风景"}},{"pos":"ADJ 形容词","cn":"无限的;无穷的;无边的","en":"Something that is infinite has no limit, end, or edge.","ex":{"en":"...an infinite number of atoms","cn":"无穷多的原子"}}]},"examples":[{"en":"( ironic ) The company in its infinite wisdom decided to close the staff restaurant (= they thought it was a good thing to do, but nobody else agreed).","cn":"公司以无比的智慧关掉了职工食堂。"},{"en":"The company in its infinite wisdom decided to close the staff restaurant (= they thought it was a good thing to do, but nobody else agreed).","cn":""}]},"infinitely":{"media":{"uk":"media/uk/infinitely__gb_1.mp3","us":"media/us/infinitely__us_1.mp3"},"oxford":{"phon":"ˈɪnfɪnətli","pos":"adverb","senses":[{"en":"very much","cn":"非常","ex":{"en":"Your English is infinitely better than my German.","cn":"你的英语比我的德语好太多了。"}},{"en":"extremely; with no limit","cn":"极其；无限地","ex":{"en":"Human beings are infinitely adaptable.","cn":"人类的适应力是无限的。"}}]},"examples":[{"en":"Your English is infinitely better than my German.","cn":"你的英语比我的德语好太多了。"},{"en":"Human beings are infinitely adaptable.","cn":"人类的适应力是无限的。"}]},"invisible":{"media":{"uk":"media/uk/invisible__gb_1.mp3","us":"media/us/invisible__us_1.mp3"},"oxford":{"phon":"ɪnˈvɪzəbl","pos":"adjective","senses":[{"en":"that cannot be seen","cn":"看不见的；隐形的","lab":"figurative","ex":{"en":"a wizard who could make himself invisible","cn":"能隐身的术士"}},{"en":"connected with a service that a country provides, such as banks or tourism, rather than goods","cn":"无形的（与服务而非商品有关）","lab":"economics","ex":{"en":"invisible earnings","cn":"无形收益"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"看不见的;隐形的","en":"If you describe something as invisible, you mean that it cannot be seen, for example because it is transparent, hidden, or very small.","ex":{"en":"The lines were so finely etched as to be invisible from a distance","cn":"线条被蚀刻得如此精细，在远处看都看不见。"}},{"pos":"ADJ 形容词","cn":"无形的","en":"You can use invisible when you are talking about something that cannot be seen but has a definite effect. In this sense, invisible is often used before a noun which refers to something that can usually be seen.","ex":{"en":"Parents fear they might overstep these invisible boundaries","cn":"父母担心他们可能会逾越这些无形的界限。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"被人忽视的;不为人注意的","en":"If you say that you feel invisible, you are complaining that you are being ignored by other people. If you say that a particular problem or situation is invisible, you are complaining that it is not being considered or dealt with.","ex":{"en":"It was strange, how invisible a clerk could feel","cn":"一名办事员会感到如此受人忽视，令人觉得不可思议。"}},{"pos":"ADJ 形容词","cn":"(故事中的人或事物)隐身的，隐形的","en":"In stories, invisible people or things have a magic quality which makes people unable to see them.","ex":{"en":"...The Invisible Man.","cn":"《隐形人》"}},{"pos":"ADJ 形容词","cn":"(收入)非贸易的,无形的","en":"In economics, invisible earnings are the money that a country makes as a result of services such as banking and tourism, rather than by producing goods.","ex":{"en":"Tourism is Britain's single biggest invisible export","cn":"旅游业是英国最大的一项无形输出。"}},{"pos":"N-PLURAL 复数名词","cn":"无形服务业(如银行业、旅游业)","en":"Invisibles are services such as banking and tourism, which provide a country's invisible earnings."}]},"examples":[{"en":"He looked at me and nodded, almost invisibly.","cn":"他看着我点了点头，几乎让人看不出来。"},{"en":"She felt invisible in the crowd.","cn":"她觉得自己淹没在人群中。"}]},"integrated":{"media":{"uk":"media/uk/integrated__gb_1.mp3","us":"media/us/integrated__us_1.mp3"},"oxford":{"phon":"ˈɪntɪɡreɪtɪd","pos":"adjective","senses":[{"en":"in which many different parts are closely connected and work successfully together","cn":"各部分密切协调的；综合的；完整统一的","ex":{"en":"an integrated programme of patient care","cn":"患者护理综合计划"}},{"en":"including people from different races, sexes, religions, etc., especially ones who have previously been separated","cn":"包括来自不同种族、性别、宗教等的人，尤其是以前被分居的人","ex":{"en":"an integrated school","cn":"融合学校（接纳不同种族和宗教信仰等的学生）"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(机构)取消种族隔离的，平等对待的","en":"An integrated institution is intended for use by all races or religious groups.","ex":{"en":"We believe that pupils of integrated schools will have more tolerant attitudes.","cn":"我们相信在取消种族隔离的学校就读的学生会有更宽容的态度。"}}]},"examples":[{"en":"an integrated school (= attended by students of all races and religions)","cn":"混合学校（招收不同种族和宗教信仰的学生）"},{"en":"an integrated transport system (= including buses, trains, taxis, etc.)","cn":"综合联运体系"}]},"injection":{"media":{"uk":"media/uk/injection__gb_1.mp3","us":"media/us/injection__us_1.mp3"},"oxford":{"phon":"ɪnˈdʒekʃn","pos":"noun","senses":[{"en":"an act of injecting somebody with a drug or other substance","cn":"注射","g":"[countable, uncountable]","lab":"British English","ex":{"en":"to give somebody an injection","cn":"给某人打针"}},{"en":"a large sum of money that is spent to help improve a situation, business, etc.","cn":"大量资金的投入","g":"[countable]","ex":{"en":"The theatre faces closure unless it gets an urgent cash injection.","cn":"剧院面临着倒闭，除非有大笔救急现金投入。"}},{"en":"an act of forcing a liquid or other substance into something","cn":"（液体的）注入，喷入","g":"[uncountable, countable]","ex":{"en":"a fuel injection system","cn":"燃油注入装置"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"注射;打针","en":"If you have an injection, a doctor or nurse puts a medicine into your body using a device with a needle called a syringe.","ex":{"en":"They gave me an injection to help me sleep","cn":"他们给我打了一针帮助我入睡。"}},{"pos":"N-COUNT 可数名词","cn":"(金钱或资源的)投入","en":"An injection of money or resources into an organization is the act of providing it with more money or resources, to help it become more efficient or profitable.","ex":{"en":"An injection of cash is needed to fund some of these projects","cn":"需要现金投入来资助这其中的一些项目。"}}]},"examples":[{"en":"The theatre faces closure unless it gets an urgent cash injection.","cn":"剧院面临着倒闭，除非有大笔救急现金投入。"},{"en":"He was treated with penicillin injections.","cn":"他接受了青霉素注射。"}]},"injury":{"oxford":{"phon":"ˈɪndʒəri","pos":"noun","senses":[{"en":"harm done to a person’s or an animal’s body, for example in an accident","cn":"（对躯体的）伤害，损伤","g":"[countable, uncountable]","lab":"British English, informal，，","ex":{"en":"Two people sustained minor injuries.","cn":"两人受轻伤。"}},{"en":"damage to a person’s feelings","cn":"（对感情的）伤害，挫伤","g":"[uncountable]","lab":"law","ex":{"en":"Damages may be awarded for emotional injury.","cn":"可能会判处精神伤害赔偿。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"伤害;损伤","en":"An injury is damage done to a person's or an animal's body. →see usage note at:","ex":{"en":"Four police officers sustained serious injuries in the explosion","cn":"4名警官在爆炸中受重伤。"}},{"pos":"N-VAR 可变名词","cn":"(感情、名誉上的)伤害,损害","en":"If someone suffers injury to their feelings, they are badly upset by something. If they suffer injury to their reputation, their reputation is seriously harmed.","ex":{"en":"She was awarded £3,500 for injury to her feelings.","cn":"她判得 3,500 英镑精神损失赔偿。"}},{"pos":"","cn":"","en":"to add insult to injury→see: ;"}]},"media":{"uk":"media/uk/injury__gb_1.mp3","us":"media/us/injury__us_1.mp3"},"examples":[{"en":"( BrE ) ( informal ) Don't do that. You'll do yourself an injury (= hurt yourself).","cn":"别那样做。你会把自己弄伤的。"},{"en":"Two players are out of the team because of injury.","cn":"两名队员因伤退出了比赛。"}]},"interpret":{"oxford":{"phon":"ɪnˈtɜːprət","pos":"verb","senses":[{"en":"to explain the meaning of something","cn":"诠释；说明","g":"[transitive]","ex":{"en":"The students were asked to interpret the poem.","cn":"学生们被要求诠释那首诗的意义。"}},{"en":"to decide that something has a particular meaning and to understand it in this way","cn":"把…理解为；领会","g":"[transitive]","ex":{"en":"I didn't know whether to interpret her silence as acceptance or refusal.","cn":"我不知该把她的沉默看作接受还是拒绝。"}},{"en":"to translate one language into another as it is spoken","cn":"口译；传译","g":"[intransitive, transitive]","ex":{"en":"He took me with him to interpret in case no one spoke English.","cn":"他带我一起去翻译，以防没人说英语。"}},{"en":"to perform a piece of music, a role in a play, etc. in a way that shows your feelings about its meaning","cn":"演绎（按自己的感觉演奏音乐或表现角色）","g":"[transitive]","ex":{"en":"He interpreted the role with a lot of humour.","cn":"他把这个角色演绎得十分幽默。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"解释;说明;阐释","en":"If you interpret something in a particular way, you decide that this is its meaning or significance.","ex":{"en":"The whole speech might well be interpreted as a coded message to the Americans","cn":"整个演讲完全可以看成是在向美国人传递编码信息。"}},{"pos":"VERB 动词","cn":"口译","en":"If you interpret what someone is saying, you translate it immediately into another language.","ex":{"en":"The chambermaid spoke little English, so her husband came with her to interpret","cn":"女服务员几乎不会说英语,因此她丈夫跟着来给她做翻译。"}}]},"media":{"uk":"media/uk/interpret__gb_1.mp3","us":"media/us/interpret__us_1.mp3"},"examples":[{"en":"She couldn't speak much English so her children had to interpret for her.","cn":"她讲不了几句英语，所以她的孩子们得给她翻译。"},{"en":"I didn't know whether to interpret her silence as acceptance or refusal.","cn":"我不知该把她的沉默看作是接受还是拒绝。"}]},"intelligence":{"media":{"uk":"media/uk/intelligence__gb_1.mp3","us":"media/us/intelligence__us_1.mp3"},"oxford":{"phon":"ɪnˈtelɪdʒəns","pos":"noun","senses":[{"en":"the ability to learn, understand and think in a logical way about things; the ability to do this well","cn":"智力；才智；智慧","ex":{"en":"a person of high/average/low intelligence","cn":"智力高的／一般的／低下的人"}},{"en":"secret information that is collected, for example about a foreign country, especially one that is an enemy; the people that collect this information","cn":"（尤指关于敌国的）情报；情报人员","ex":{"en":"the head of military intelligence","cn":"军事情报主管"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"聪颖;智慧;灵性","en":"Intelligence is the quality of being intelligent or clever.","ex":{"en":"She's a woman of exceptional intelligence.","cn":"她是个有着非凡智慧的女子。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"智力;智能","en":"Intelligence is the ability to think, reason, and understand instead of doing things automatically or by instinct.","ex":{"en":"Nerve cells, after all, do not have intelligence of their own.","cn":"毕竟,神经细胞自身并没有智力。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"情报;谍报","en":"Intelligence is information that is gathered by the government or the army about their country's enemies and their activities.","ex":{"en":"She first moved into the intelligence services 22 years ago","cn":"22年前她初次进入情报部门。"}}]},"examples":[{"en":"He didn't even have the intelligence to call for an ambulance.","cn":"他连呼叫救护车的头脑都没有。"},{"en":"a person of high/average/low intelligence","cn":"智力高的/一般的/低下的人"}]},"interference":{"media":{"uk":"media/uk/interference__gb_1.mp3","us":"media/us/interference__us_1.mp3"},"oxford":{"phon":"ˌɪntəˈfɪərəns","pos":"noun","senses":[{"en":"the act of getting involved in and trying to influence a situation that should not really involve you, in a way that annoys other people","cn":"干涉；干预；介入","ex":{"en":"They resent foreign interference in the internal affairs of their country.","cn":"他们憎恶外人干涉他们国家的内政。"}},{"en":"interruption of a radio signal by another signal on a similar wavelength, causing extra noise that is not wanted","cn":"（无线电信号的）干扰"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"干涉;干预;介入","en":"Interference by a person or group is their unwanted or unnecessary involvement in something.","ex":{"en":"The parliament described the decree as interference in the republic's internal affairs","cn":"议会形容此法令为对共和国内政的干涉。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(电波的)干扰","en":"When there is interference, a radio signal is affected by other radio waves or electrical activity so that it cannot be received properly.","ex":{"en":"...electrical interference","cn":"电子干扰"}}]},"examples":[{"en":"They resent foreign interference in the internal affairs of their country.","cn":"他们憎恶对他们国家内政的外来干涉。"},{"en":"I resent his interference in my work.","cn":"我讨厌他干预我的工作。"}]},"infectious":{"oxford":{"phon":"ɪnˈfekʃəs","pos":"adjective","senses":[{"en":"an infectious disease can be passed easily from one person to another, especially through air or water","cn":"传染性的，感染的（尤指经由空气或水传染的）","lab":"figurative","ex":{"en":"Flu is highly infectious.","cn":"流感非常容易传染。"}},{"en":"if a person or an animal is infectious, they have a disease that can be spread to others","cn":"患有传染病；有传染力","g":"[not usually before noun]","ex":{"en":"I'm still infectious.","cn":"我还处在传染期。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"传染的;传染性的","en":"A disease that is infectious can be caught by being near a person who has it.","ex":{"en":"...infectious diseases such as measles","cn":"类似麻疹这样的传染病"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有感染力的;易传播的","en":"If a feeling is infectious, it spreads to other people.","ex":{"en":"She radiates an infectious enthusiasm for everything she does","cn":"她做任何事情都充满一种极富感染力的热情。"}}]},"media":{"uk":"media/uk/infectious__gb_1.mp3","us":"media/us/infectious__us_1.mp3"},"examples":[{"en":"Flu is highly infectious.","cn":"流感的传染性很高。"},{"en":"I'm still infectious.","cn":"我还处在传染期。"}]},"inadequate":{"media":{"uk":"media/uk/inadequate__gb_1.mp3","us":"media/us/inadequate__us_1.mp3"},"oxford":{"phon":"ɪnˈædɪkwət","pos":"adjective","senses":[{"en":"not enough; not good enough","cn":"不充分的；不足的；不够的","ex":{"en":"inadequate supplies","cn":"供应短缺"}},{"en":"not able, or not confident enough, to deal with a situation","cn":"不胜任的；缺乏信心的","ex":{"en":"I felt totally inadequate as a parent.","cn":"我觉得我作为父亲（或母亲）完全不称职。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不充分的;不足的;不够好的","en":"If something is inadequate, there is not enough of it or it is not good enough.","ex":{"en":"Supplies of food and medicines are inadequate","cn":"食物和药品供应不足。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不够格的;不能胜任的;不适合的","en":"If someone feels inadequate, they feel that they do not have the qualities and abilities necessary to do something or to cope with life in general.","ex":{"en":"I still feel inadequate, useless and mixed up","cn":"我仍然感到自己能力不够,毫无用处,整个儿一团糟。"}}]},"examples":[{"en":"I felt totally inadequate as a parent.","cn":"我觉得我作为父亲（或母亲）完全不称职。"},{"en":"The system is inadequate for the tasks it has to perform.","cn":"这个系统要完成它的任务还不够完善。"}]},"inter":{"media":{"uk":"media/uk/inter__gb_1.mp3","us":"media/us/inter__us_1.mp3"},"oxford":{"phon":"ɪnˈtɜː(r)","pos":"verb","senses":[{"en":"to bury a dead person","cn":"埋葬（遗体）","ex":{"en":"The princess was interred on an island in the middle of a lake.","cn":"公主被埋葬在湖中央的一个岛上。"}},{"en":"between; from one to another","cn":"在…之间；从此到彼；相互","ex":{"en":"interface","cn":"界面"},"pos":"prefix"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"埋葬","en":"When a dead person is interred, they are buried.","ex":{"en":"...the spot where his bones were originally interred.","cn":"他的骸骨起初埋葬的地点"}}]}},"insignificant":{"oxford":{"phon":"ˌɪnsɪɡˈnɪfɪkənt","pos":"adjective","senses":[{"en":"not big or valuable enough to be considered important","cn":"微不足道的；无足轻重的","ex":{"en":"an insignificant difference","cn":"微不足道的差别"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不重要的;无足轻重的","en":"Something that is insignificant is unimportant, especially because it is very small.","ex":{"en":"In 1949 Bonn was a small, insignificant city.","cn":"1949 年时波恩还是个无足轻重的小城市。"}}]},"media":{"uk":"media/uk/insignificant__gb_1.mp3","us":"media/us/insignificant__us_1.mp3"},"examples":[{"en":"Her own problems paled into insignificance beside this terrible news.","cn":"跟这个可怕的消息相比，她自己的问题显得无关紧要了。"},{"en":"The levels of chemicals in the river are not insignificant.","cn":"河水中的化学物质含量不容忽视。"}]},"intend":{"media":{"uk":"media/uk/intend__gb_1.mp3","us":"media/us/intend__us_1.mp3"},"oxford":{"phon":"ɪnˈtend","pos":"verb","senses":[{"en":"to have a plan, result or purpose in your mind when you do something","cn":"打算；计划；想要","g":"[intransitive, transitive]","lab":"British English","ex":{"en":"We finished later than we had intended.","cn":"我们完成时已超出原定时间。"}},{"en":"to plan that something should have a particular meaning","cn":"意指","g":"[transitive]","lab":"rather formal","ex":{"en":"What exactly did you intend by that remark?","cn":"你那句话到底想说什么？"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"想要;打算;计划","en":"If you intend to do something, you have decided or planned to do it.","ex":{"en":"She intends to do A levels and go to university","cn":"她计划先参加高级考试，然后去读大学。"}},{"pos":"VERB 动词","cn":"准备,预留(作某种用途或给某人用)","en":"If something is intended for a particular purpose, it has been planned to fulfil that purpose. If something is intended for a particular person, it has been planned to be used by that person or to affect them in some way.","ex":{"en":"This money is intended for the development of the tourist industry","cn":"这笔钱准备用于旅游业的开发。"}},{"pos":"VERB 动词","cn":"意指;意思是","en":"If you intend a particular idea or feeling in something that you say or do, you want to express it or want it to be understood.","ex":{"en":"He didn't intend any sarcasm","cn":"他没有任何讽刺的意思。"}}]},"examples":[{"en":"The writer clearly intends his readers to identify with the main character.","cn":"作者显然想使读者能与主人公产生共鸣。"},{"en":"We finished later than we had intended.","cn":"我们完成时已超出原定时间。"}]},"investigate":{"media":{"uk":"media/uk/investigate__gb_1.mp3","us":"media/us/investigate__us_1.mp3"},"oxford":{"phon":"ɪnˈvestɪɡeɪt","pos":"verb","senses":[{"en":"to carefully examine the facts of a situation, an event, a crime, etc. to find out the truth about it or how it happened","cn":"调查，侦查（某事）","g":"[intransitive, transitive]","lab":"informal","ex":{"en":"The FBI has been called in to investigate.","cn":"联邦调查局奉命进行调查。"}},{"en":"to try to find out information about somebody’s character, activities, etc.","cn":"调查（某人）","g":"[transitive]","ex":{"en":"This is not the first time he has been investigated by the police for fraud.","cn":"这不是警方第一次调查他是否有欺诈行为。"}},{"en":"to find out information and facts about a subject or problem by study or research","cn":"研究；调查","g":"[transitive]","ex":{"en":"The study investigates the effects of feeding a high energy diet to cows.","cn":"这项研究调查了给奶牛喂高能量饲料的效果。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"调查;审查","en":"If someone, especially an official, investigates an event, situation, or claim, they try to find out what happened or what is the truth.","ex":{"en":"Gas officials are investigating the cause of an explosion which badly damaged a house in Hampshire","cn":"煤气系统的官员正在调查一起瓦斯爆炸的起因,这起事故严重毁坏了汉普郡的一所房屋。"}}]},"examples":[{"en":"The research investigates how foreign speakers gain fluency.","cn":"这项研究旨在调查讲外语的人如何增加流利程度。"},{"en":"Police are investigating possible links between the murders.","cn":"警察正在调查这些谋杀案之间可能存在的关联。"}]},"interrupt":{"media":{"uk":"media/uk/interrupt__gb_1.mp3","us":"media/us/interrupt__us_1.mp3"},"oxford":{"phon":"ˌɪntəˈrʌpt","pos":"verb","senses":[{"en":"to say or do something that makes somebody stop what they are saying or doing","cn":"插嘴；打扰；打岔","g":"[intransitive, transitive]","lab":"formal","ex":{"en":"Sorry to interrupt, but there's someone to see you.","cn":"对不起打扰一下，有人要见你。"}},{"en":"to stop something for a short time","cn":"使暂停；使中断","g":"[transitive]","ex":{"en":"The game was interrupted several times by rain.","cn":"比赛因下雨中断了几次。"}},{"en":"to stop a line, surface, view, etc. from being even or continuous","cn":"阻断，遮挡（连续线条、平面、景色等）","g":"[transitive]","ex":{"en":"There were no other buildings to interrupt the view of the valley.","cn":"没有别的建筑物遮挡住观赏山谷的视线。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"打断(某人)","en":"If you interrupt someone who is speaking, you say or do something that causes them to stop.","ex":{"en":"Turkin tapped him on the shoulder. 'Sorry to interrupt, Colonel.'","cn":"图尔金拍拍他的肩膀。“不好意思打断您一下,上校。”"}},{"pos":"VERB 动词","cn":"中止;中断;使暂时停止","en":"If someone or something interrupts a process or activity, they stop it for a period of time.","ex":{"en":"He has rightly interrupted his holiday in Spain to return to London","cn":"他马上中止了在西班牙的度假回到伦敦。"}},{"pos":"VERB 动词","cn":"遮挡;阻断","en":"If something interrupts a line, surface, or view, it stops it from being continuous or makes it look irregular.","ex":{"en":"Taller plants interrupt the views from the house.","cn":"稍高些的植物遮挡了房内的视线。"}}]},"examples":[{"en":"We interrupt this programme to bring you an important news bulletin.","cn":"我们暂停本节目，插播重要新闻。"},{"en":"Sorry to interrupt, but there's someone to see you.","cn":"对不起打扰一下，有人要见你。"}]},"informal":{"oxford":{"phon":"ɪnˈfɔːml","pos":"adjective","senses":[{"en":"relaxed and friendly; not following strict rules of how to behave or do something","cn":"不拘礼节的；友好随便的；非正规的","ex":{"en":"an informal atmosphere","cn":"友好轻松的气氛"}},{"en":"suitable for normal conversation and writing to friends rather than for serious speech and letters","cn":"非正式的；口语体的","ex":{"en":"an informal expression","cn":"非正式用语"}},{"en":"suitable for wearing at home or when relaxing rather than for a special or an official occasion","cn":"日常的；随便的","ex":{"en":"I changed into more informal clothes.","cn":"我换上了比较休闲的衣服。"}},{"en":"done by individuals on a small scale, especially unofficially or illegally","cn":"小规模的（尤指不正式的或非法的）","ex":{"en":"the informal economy/sector","cn":"地下经济"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(言辞或行为)非正式的，亲切随便的","en":"Informal speech or behaviour is relaxed and friendly rather than serious, very correct, or official.","ex":{"en":"She is refreshingly informal","cn":"她不拘礼节,让人耳目一新。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(场合等)非正式的,随意的","en":"An informal situation is one which is relaxed and friendly and not very serious or official.","ex":{"en":"I would like it to be an informal occasion","cn":"我希望把它办得不那么正式。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(衣服)非正式场合穿的,休闲的","en":"Informal clothes are casual and suitable for wearing when you are relaxing, but not on formal occasions.","ex":{"en":"Most of the time Jenny needs informal clothes","cn":"大部分时间珍妮需要休闲服装。"}},{"pos":"ADJ 形容词","cn":"非正式的;非正规的","en":"You use informal to describe something that is done unofficially or casually without planning.","ex":{"en":"The two leaders will retire to Camp David for informal discussions.","cn":"两位领导人将到戴维营进行非正式讨论。"}}]},"media":{"uk":"media/uk/informal__gb_1.mp3","us":"media/us/informal__us_1.mp3"},"examples":[{"en":"They told me informally (= not officially) that I had got the job.","cn":"他们非正式地告诉我说，我得到了那份工作。"},{"en":"Discussions are held on an informal basis within the department.","cn":"讨论限于在本部门内非正式地进行。"}]},"inaccessible":{"media":{"uk":"media/uk/inaccessible__gb_1.mp3","us":"media/us/inaccessible__us_1.mp3"},"oxford":{"phon":"ˌɪnækˈsesəbl","pos":"adjective","senses":[{"en":"difficult or impossible to reach, get or use","cn":"难以达到的；不可得到的；难以使用的","ex":{"en":"They live in a remote area, inaccessible except by car.","cn":"他们住在一处偏远地区，只能开车去。"}},{"en":"difficult to understand or appreciate","cn":"难以理解的","ex":{"en":"The language of teenagers is often completely inaccessible to adults.","cn":"青少年的语言成人往往完全听不懂。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"达不到的;难到达的;不可(或不易)进入的","en":"An inaccessible place is very difficult or impossible to reach.","ex":{"en":"...the remote, inaccessible areas of the Andes rainforests.","cn":"偏僻遥远、难以到达的安第斯雨林地区"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"见不到的;不可使用的;买不到的","en":"If something is inaccessible, you are unable to see, use, or buy it.","ex":{"en":"Ninety-five per cent of its magnificent collection will remain inaccessible to the public","cn":"其中 95% 的顶级收藏品仍不会向公众开放。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难懂的;无法理解的","en":"Someone or something that is inaccessible is difficult or impossible to understand or appreciate.","ex":{"en":"A lot of contemporary music is virtually inaccessible.","cn":"许多当代音乐几乎难以理解。"}}]},"examples":[{"en":"They live in a remote area, inaccessible except by car.","cn":"他们住在一处偏远地区，只能开车去。"},{"en":"The temple is now inaccessible to the public.","cn":"这个寺庙现在不对公众开放了。"}]},"interval":{"oxford":{"phon":"ˈɪntəvl","pos":"noun","senses":[{"en":"a period of time between two events","cn":"（时间上的）间隔，间隙，间歇","ex":{"en":"The interval between major earthquakes might be 200 years.","cn":"大地震之间的间隔时间可能有 200 年。"}},{"en":"a short period of time separating parts of a play, film or concert","cn":"（戏剧、电影或音乐会的）幕间休息，休息时间","lab":"British English","ex":{"en":"There will be an interval of 20 minutes after the second act.","cn":"第二幕结束后将休息 20 分钟。"}},{"en":"a short period during which something different happens from what is happening the rest of the time","cn":"（其他事情）穿插出现的间隙","g":"[usually plural]","lab":"British English","ex":{"en":"She's delirious, but has lucid intervals.","cn":"她神志昏乱，但有时清醒。"}},{"en":"a difference in pitch (= how high or low a note sounds) between two notes","cn":"音程","lab":"music","ex":{"en":"an interval of one octave","cn":"一个八度音程"}},{"en":"an activity in interval training","cn":"间歇训练中的一项活动","ex":{"en":"You can do intervals by alternating power walking with easy jogging.","cn":"您可以通过交替步行和轻松慢跑来进行间歇训练。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(事件、日期之间的)间隔","en":"An interval between two events or dates is the period of time between them.","ex":{"en":"The ferry service has restarted after an interval of 12 years","cn":"时隔12年之后，轮渡服务又重新开通了。"}},{"pos":"N-COUNT 可数名词","cn":"幕间休息;中场休息","en":"An interval during a film, concert, show, or game is a short break between two of the parts.","ex":{"en":"During the interval, wine was served","cn":"幕间休息时有葡萄酒供应。"}},{"pos":"N-COUNT 可数名词","cn":"音程","en":"In music, an interval is the difference in pitch between two musical notes."},{"pos":"PHRASE 短语","cn":"每隔一段时间;时而","en":"If something happens at intervals, it happens several times with gaps or pauses in between.","ex":{"en":"She woke him for his medicines at intervals throughout the night.","cn":"她夜里每隔一段时间就叫他起来服药。"}},{"pos":"PHRASE 短语","cn":"以…的间距;每隔…远的距离","en":"If things are placed at particular intervals, there are spaces of a particular size between them.","ex":{"en":"Several red and white barriers marked the road at intervals of about a mile","cn":"路上设有几处红白相间的路障，相互间隔约一英里。"}}]},"media":{"uk":"media/uk/interval__gb_1.mp3","us":"media/us/interval__us_1.mp3"},"examples":[{"en":"The interval between major earthquakes might be 200 years.","cn":"大地震之间的间隔时间可能有 200 年。"},{"en":"Buses to the city leave at regular intervals.","cn":"开往城里的公共汽车每隔一定时间发出一班。"}]},"interviewee":{"oxford":{"phon":"ˌɪntəvjuːˈiː","pos":"noun","senses":[{"en":"the person who answers the questions in an interview","cn":"参加面试者；接受采访者"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"被采访者;被面试者","en":"An interviewee is a person who is being interviewed."}]},"media":{"uk":"media/uk/interviewee__gb_1.mp3","us":"media/us/interviewee__us_1.mp3"}},"insular":{"media":{"uk":"media/uk/insular__gb_2.mp3","us":"media/us/insular__us_1.mp3"},"oxford":{"phon":"ˈɪnsjələ(r)","pos":"adjective","senses":[{"en":"only interested in your own country, ideas, etc. and not in those from outside","cn":"只关心本国利益的；思想褊狭的；保守的","lab":"disapproving","ex":{"en":"The British are often accused of being insular.","cn":"英国人常被指责为思想褊狭。"}},{"en":"having little contact with other people","cn":"孤立的；不与人交往的","lab":"usually disapproving","ex":{"en":"people living restricted and sometimes insular existences","cn":"生活受限制、有时与世隔绝的人们"}},{"en":"connected with an island or islands","cn":"海岛的；岛屿的","lab":"specialist","ex":{"en":"the coastal and insular areas","cn":"沿海和岛屿区域"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"孤立的;保守的;思想狭隘的","en":"If you say that someone is insular, you are being critical of them because they are unwilling to meet new people or to consider new ideas.","ex":{"en":"...the old image of the insular, xenophobic Brit.","cn":"孤立保守而又恐外的英国人的旧有形象"}}]},"examples":[{"en":"The British are often accused of being insular.","cn":"英国人常被指责为思想褊狭。"},{"en":"the coastal and insular areas","cn":"沿海和岛屿区域"}]},"intercourse":{"media":{"uk":"media/uk/intercourse__gb_1.mp3","us":"media/us/intercourse__us_1.mp3"},"oxford":{"phon":"ˈɪntəkɔːs","pos":"noun","senses":[{"en":"the physical activity of sex, usually describing the act of a man putting his penis inside a woman’s vagina","cn":"性交；性行为","lab":"formal","ex":{"en":"The prosecution stated that intercourse had occurred on several occasions.","cn":"控方称发生过数次性交。"}},{"en":"communication between people, countries, etc.","cn":"（人、国家等之间的）往来，交往，交际","lab":"old-fashioned","ex":{"en":"the importance of social intercourse between different age groups","cn":"不同年龄段的人之间社交的重要性"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"性交;交媾","en":"Intercourse is the act of having sex.","ex":{"en":"...sexual intercourse","cn":"性交"}},{"pos":"N-UNCOUNT 不可数名词","cn":"交际;交往;往来","en":"Social intercourse is communication between people as they spend time together.","ex":{"en":"There was social intercourse between the old and the young.","cn":"老年人与年轻人之间有社会交往。"}}]},"examples":[{"en":"the importance of social intercourse between different age groups","cn":"不同年龄段的人之间交往的重要性"},{"en":"The prosecution stated that intercourse had occurred on several occasions.","cn":"控方称发生过数次性行为。"}]},"interpersonal":{"oxford":{"phon":"ˌɪntəˈpɜːsənl","pos":"adjective","senses":[{"en":"connected with relationships between people","cn":"人际关系的；人际的","ex":{"en":"interpersonal skills","cn":"人际交往技巧"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"人际的;人与人之间的","en":"Interpersonal means relating to relationships between people.","ex":{"en":"...problems in interpersonal relationships","cn":"人际关系问题"}}]},"media":{"uk":"media/uk/interpersonal__gb_1.mp3","us":"media/us/interpersonal__us_1.mp3"},"examples":[{"en":"interpersonal skills","cn":"人际交往技巧"},{"en":"interpersonal communication","cn":"人际沟通"}]},"intention":{"oxford":{"phon":"ɪnˈtenʃn","pos":"noun","senses":[{"en":"what you intend or plan to do; your aim","cn":"打算；计划；意图；目的","ex":{"en":"I have no intention of going to the wedding.","cn":"我无意去参加婚礼。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"意图;目的;打算","en":"An intention is an idea or plan of what you are going to do.","ex":{"en":"Beveridge announced his intention of standing for parliament","cn":"贝弗里奇宣布他打算竞选议员。"}},{"pos":"PHRASE 短语","cn":"不想/很想;不打算/一心打算","en":"If you say that you have no intention of doing something, you are emphasizing that you are not going to do it. If you say that you have every intention of doing something, you are emphasizing that you intend to do it.","ex":{"en":"We have no intention of buying American jets","cn":"我们无意购买美国喷气式飞机。"}}]},"media":{"uk":"media/uk/intention__gb_1.mp3","us":"media/us/intention__us_1.mp3"},"examples":[{"en":"The original intention was to devote three months to the project.","cn":"最初的计划是在这个项目上投入三个月的时间。"},{"en":"I did it with the best (of) intentions (= meaning to help), but I only succeeded in annoying them.","cn":"我的原意是要帮忙，却惹得他们生气了。"}]},"internal":{"media":{"uk":"media/uk/internal__gb_1.mp3","us":"media/us/internal__us_1.mp3"},"oxford":{"phon":"ɪnˈtɜːnl","pos":"adjective","senses":[{"en":"connected with the inside of something","cn":"内部的；里面的","g":"[only before noun]","ex":{"en":"the internal structure of a building","cn":"大楼的内部结构"}},{"en":"connected with the inside of your body","cn":"体内的","g":"[only before noun]","ex":{"en":"internal organs","cn":"内脏"}},{"en":"involving or affecting only the people who are part of a particular organization rather than people from outside it","cn":"（机构）内部的","g":"[usually before noun]","ex":{"en":"The company has launched an internal investigation into the claims.","cn":"该公司对这些索赔要求展开了内部调查。"}},{"en":"connected with a country’s own affairs rather than those that involve other countries","cn":"内政的；国内的","g":"[only before noun]","ex":{"en":"He accused the US of trying to interfere in his country's internal affairs.","cn":"他指责美国试图干涉他国内政。"}},{"en":"coming from within a thing itself rather than from outside it","cn":"本身的；自身的","ex":{"en":"a theory that lacks internal consistency (= whose parts are not in agreement with each other)","cn":"自相矛盾的理论"}},{"en":"happening or existing in your mind","cn":"内心的；头脑中的","ex":{"en":"She struggled with her own internal conflicts.","cn":"她内心纠结，左右为难。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"国内的;内政的;(组织)内部的","en":"Internal is used to describe things that exist or happen inside a country or organization.","ex":{"en":"The country stepped up internal security","cn":"该国加强了国内安保。"}},{"pos":"ADJ 形容词","cn":"体内的;(物体或场所)内部的","en":"Internal is used to describe things that exist or happen inside a particular person, object, or place.","ex":{"en":"...massive internal bleeding","cn":"体内大出血"}}]},"examples":[{"en":"Some photos contain internal evidence (= fashions, transport, etc.) that may help to date them.","cn":"有些照片自身就含有确定拍摄日期的佐证。"},{"en":"The new posts were only advertised internally.","cn":"新职位仅限于内部招聘。"}]},"indignant":{"media":{"uk":"media/uk/indignant__gb_1.mp3","us":"media/us/indignant__us_1.mp3"},"oxford":{"phon":"ɪnˈdɪɡnənt","pos":"adjective","senses":[{"en":"feeling or showing anger and surprise because you think that you have been treated unfairly","cn":"愤慨的；愤怒的；义愤的","lab":"especially North American English","ex":{"en":"an indignant letter/look","cn":"愤慨的信／神情"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"愤怒的;愤慨的","en":"If you are indignant, you are shocked and angry, because you think that something is unjust or unfair.","ex":{"en":"He is indignant at suggestions that they were secret agents","cn":"有人暗示他们可能是特务,这让他非常气愤。"}}]},"examples":[{"en":"‘I'm certainly not asking him!’ she retorted indignantly. “","cn":"我绝对不是在问他！”她愤然反驳说。"},{"en":"She was very indignant at the way she had been treated.","cn":"她对于自己受到的待遇大为光火。"}]},"inflation":{"media":{"uk":"media/uk/inflation__gb_1.mp3","us":"media/us/inflation__us_1.mp3"},"oxford":{"phon":"ɪnˈfleɪʃn","pos":"noun","senses":[{"en":"a fall in the value of money and a general increase in prices; the rate at which this happens","cn":"通货膨胀；通胀率","ex":{"en":"the fight against rising inflation","cn":"对抗不断升高的通货膨胀"}},{"en":"a general rise in the level of something that is awarded","cn":"上升；上涨","lab":"disapproving","ex":{"en":"the gross inflation of executive salaries","cn":"领导层薪酬的暴涨"}},{"en":"the act or process of filling something with air or gas","cn":"充气","ex":{"en":"life jackets with an automatic inflation device","cn":"有自动充气装置的救生衣"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"通货膨胀","en":"Inflation is a general increase in the prices of goods and services in a country.","ex":{"en":"...rising unemployment and high inflation.","cn":"不断增长的失业人数与高通货膨胀"}}]},"examples":[{"en":"Wage increases must be in line with inflation.","cn":"工资的增长必须与通货膨胀一致。"},{"en":"Inflation is currently running at 3%.","cn":"当前的通货膨胀率为 3%。"}]},"interrupts":{"oxford":{"phon":"ˌɪntəˈrʌpt","pos":"verb","senses":[{"en":"to say or do sth that makes sb stop what they are saying or doing","cn":"插嘴；打扰；打岔"},{"en":"to stop sth for a short time","cn":"使暂停；使中断"}]},"media":{"uk":"media/uk/interrupt__gb_1.mp3","us":"media/us/interrupt__us_1.mp3"}},"intellectual":{"media":{"uk":"media/uk/intellectual__gb_1.mp3","us":"media/us/intellectual__us_1.mp3"},"oxford":{"phon":"ˌɪntəˈlektʃuəl","pos":"adjective","senses":[{"en":"connected with or using a person’s ability to think in a logical way and understand things","cn":"智力的；脑力的；理智的","g":"[usually before noun]","ex":{"en":"Gifted children typically show great intellectual curiosity and a wide range of interests.","cn":"天才儿童通常表现出极大的求知欲和广泛的兴趣。"}},{"en":"well educated and enjoying activities in which you have to think seriously about things","cn":"有才智的；智力发达的","ex":{"en":"She's very intellectual.","cn":"她很聪慧。"}},{"en":"a person who is well educated and enjoys activities in which they have to think seriously about things","cn":"知识分子；脑力劳动者","ex":{"en":"He was a leading intellectual of his day.","cn":"他是那个时代杰出的知识分子。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"智力的;脑力的;理智的","en":"Intellectual means involving a person's ability to think and to understand ideas and information.","ex":{"en":"High levels of lead could damage the intellectual development of children","cn":"铅含量过高会损害儿童的智力发展。"}},{"pos":"N-COUNT 可数名词","cn":"知识分子;脑力劳动者","en":"An intellectual is someone who spends a lot of time studying and thinking about complicated ideas.","ex":{"en":"...teachers, artists and other intellectuals.","cn":"教师、艺术家和其他知识分子"}}]},"examples":[{"en":"She's very intellectual.","cn":"她很聪慧。"},{"en":"intellectually challenging","cn":"考验智慧的"}]},"initiative":{"media":{"uk":"media/uk/initiative__gb_1.mp3","us":"media/us/initiative__us_1.mp3"},"oxford":{"phon":"ɪˈnɪʃətɪv","pos":"noun","senses":[{"en":"a new plan for dealing with a particular problem or for achieving a particular purpose","cn":"倡议；新方案","g":"[countable]","ex":{"en":"a United Nations peace initiative","cn":"联合国的和平倡议"}},{"en":"the ability to decide and act on your own without waiting for somebody to tell you what to do","cn":"主动性；积极性；自发性","g":"[uncountable]","ex":{"en":"He said I was lazy and had no initiative.","cn":"他说我懒，没有主动性。"}},{"en":"the power or opportunity to act and gain an advantage before other people do","cn":"主动权；首先行动的机会","g":"[singular]","ex":{"en":"to seize/regain the initiative","cn":"掌握先机；重获主动权"}},{"en":"(in some states of the US) a process by which ordinary people can suggest a new law by signing a petition","cn":"（美国某些州的）公民立法提案程序","g":"[countable, uncountable]","ex":{"en":"a ballot initiative to establish a local minimum wage","cn":"制定当地最低工资的公民立法提案程序"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"积极的行动;倡议","en":"An initiative is an important act or statement that is intended to solve a problem.","ex":{"en":"Government initiatives to help young people have been inadequate","cn":"政府在积极帮助年轻人方面做得还不够。"}},{"pos":"N-SING 单数名词","cn":"主动权","en":"In a fight or contest, if you have the initiative, you are in a better position than your opponents to decide what to do next.","ex":{"en":"We have the initiative; we intend to keep it","cn":"我们拥有主动权;我们不打算放弃它。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"主动性;积极性;进取心","en":"If you have initiative, you have the ability to decide what to do next and to do it, without needing other people to tell you what to do.","ex":{"en":"She was disappointed by his lack of initiative.","cn":"她对他缺少进取心感到失望。"}},{"pos":"PHRASE 短语","cn":"采取主动;首先采取行动","en":"If you take the initiative in a situation, you are the first person to act, and are therefore able to control the situation.","ex":{"en":"We must take the initiative in the struggle to end the war","cn":"为尽早结束战争,我们必须抢先行动。"}}]},"examples":[{"en":"You won't get much help. You'll have to use your initiative.","cn":"你不会得到多少帮助的。你得自己想办法。"},{"en":"It was up to the US to take the initiative in repairing relations.","cn":"在修复关系方面应由美国采取主动。"}]},"instructive":{"media":{"uk":"media/uk/instructive__gb_1.mp3","us":"media/us/instructive__us_1.mp3"},"oxford":{"phon":"ɪnˈstrʌktɪv","pos":"adjective","senses":[{"en":"giving a lot of useful information","cn":"富有教益的；增长知识的","ex":{"en":"It was a most instructive experience.","cn":"那是使人获益良多的经历。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"增进知识的;有教育意义的;有启发性的","en":"Something that is instructive gives useful information.","ex":{"en":"It's instructive to compare his technique with Alan Bennett's.","cn":"把他的手法与艾伦·贝内特进行比较很富启发意义。"}}]},"examples":[{"en":"It is instructive to see how other countries are tackling the problem.","cn":"了解别的国家如何处理这个问题是具有启发性的。"},{"en":"a most instructive experience","cn":"获益良多的经历"}]},"inuit":{"media":{"uk":"media/uk/inuit__gb_1.mp3","us":"media/us/inuit__us_1.mp3"},"oxford":{"phon":"ˈɪnjuɪt","pos":"noun","senses":[{"en":"a member of an indigenous people from northern Canada and parts of Greenland and Alaska. The name is sometimes also wrongly used to refer to people from Siberia and S and W Alaska.","cn":"来自加拿大北部以及格陵兰岛和阿拉斯加部分地区的土著人民的成员。这个名字有时也被错误地用来指代来自西伯利亚和阿拉斯加南部和西部的人。"},{"en":"the language of the Inuit people","cn":"因纽特语","g":"[uncountable]"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"因纽特人(加拿大东部地区和格陵兰岛原住居民的后裔)","en":"The Inuit are a race of people descended from the original people of Eastern Canada and Greenland."}]}},"instinctively":{"oxford":{"phon":"ɪnˈstɪŋktɪvli","pos":"adverb","senses":[{"en":"by using instinct (= a natural quality that makes somebody/something behave in a particular way) rather than thought or training","cn":"本能地：通过使用本能，而不是思想或训练","ex":{"en":"He knew instinctively that something was wrong.","cn":"他凭直觉知道出事了。"}}]},"media":{"uk":"media/uk/instinctively__gb_1.mp3","us":"media/us/instinctively__us_1.mp3"},"examples":[{"en":"He knew instinctively that something was wrong.","cn":"他凭直觉知道出事了。"},{"en":"a mother’s instinctive love","cn":""}]},"interventions":{"media":{"uk":"media/uk/intervention__gb_1.mp3","us":"media/us/intervention__us_1.mp3"}},"inspiration":{"media":{"uk":"media/uk/inspiration__gb_1.mp3","us":"media/us/inspiration__us_1.mp3"},"oxford":{"phon":"ˌɪnspəˈreɪʃn","pos":"noun","senses":[{"en":"the process that takes place when somebody sees or hears something that causes them to have exciting new ideas or makes them want to create something, especially in art, music or literature","cn":"灵感","g":"[uncountable]","ex":{"en":"Dreams can be a rich source of inspiration for an artist.","cn":"梦境有可能是艺术家灵感的丰富源泉。"}},{"en":"a person or thing that is the reason why somebody creates or does something","cn":"启发灵感的人（或事物）；使人产生动机的人（或事物）","g":"[countable, usually singular]","ex":{"en":"He says my sister was the inspiration for his heroine.","cn":"他说我姐姐是他的女主人公的原型。"}},{"en":"a person or thing that makes you want to be better, more successful, etc.","cn":"鼓舞人心的人（或事物）","g":"[countable, usually singular]","ex":{"en":"Her charity work is an inspiration to us all.","cn":"她的慈善工作激励着我们所有人。"}},{"en":"a sudden good idea","cn":"（突然想到的）好主意，妙计","g":"[countable, usually singular, uncountable]","ex":{"en":"He had an inspiration: he'd give her a dog for her birthday.","cn":"他突然想到一个好主意，他要送她一条狗作为生日礼物。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"灵感;启示;启发","en":"Inspiration is a feeling of enthusiasm you get from someone or something, which gives you new and creative ideas.","ex":{"en":"My inspiration comes from poets like Baudelaire and Jacques Prévert","cn":"我的灵感源于像波德莱尔和雅克·普雷韦这样的诗人。"}},{"pos":"N-SING 单数名词","cn":"激励(者);鼓舞(者)","en":"If you describe someone or something good as an inspiration, you mean that they make you or other people want to do or achieve something.","ex":{"en":"Powell's unusual journey to high office is an inspiration to millions","cn":"鲍威尔升任高官的不寻常历程对数以百万计的人都是一个激励。"}},{"pos":"N-SING 单数名词","cn":"灵感来源;原型","en":"If something or someone is the inspiration for a particular book, work of art, or action, they are the source of the ideas in it or act as a model for it.","ex":{"en":"India's myths and songs are the inspiration for her books","cn":"印度的神话与歌曲是她那些书的灵感来源。"}},{"pos":"N-COUNT 可数名词","cn":"妙计;好办法","en":"If you suddenly have an inspiration, you suddenly think of an idea of what to do or say.","ex":{"en":"Alison had an inspiration.","cn":"艾莉森有了条妙计。"}}]},"examples":[{"en":"He had an inspiration: he'd give her a dog for her birthday.","cn":"他突然想到一个好主意，他要送她一条狗作为生日礼物。"},{"en":"Looking for inspiration for a new dessert? Try this recipe.","cn":"正在寻找制作新式甜食的灵感吗？试试这份食谱吧。"}]},"indo-european":{"oxford":{"phon":"ˌɪndəʊ jʊərəˈpiːən","pos":"adjective","senses":[{"en":"of or connected with the family of languages spoken in most of Europe and parts of western Asia (including English, French, Latin, Greek, Russian and Hindi)","cn":"印欧语系的（指欧洲大部分地区和西亚的部分地区的语言谱系，包括英语、法语、拉丁语、希腊语、俄语和印地语）"}]},"media":{"uk":"media/uk/indo_european_1_gb_1.mp3","us":"media/us/indo_european_1_us_1.mp3"}},"incident":{"oxford":{"phon":"ˈɪnsɪdənt","pos":"noun","senses":[{"en":"something that happens, especially something unusual or unpleasant","cn":"发生的事情（尤指不寻常的或讨厌的）","g":"[countable]","ex":{"en":"His bad behaviour was just an isolated incident.","cn":"他的不良行为只是个别事件。"}},{"en":"a serious or violent event, such as a crime, an accident or an attack","cn":"严重事件，暴力事件（如犯罪、事故、袭击等）","g":"[countable, uncountable]","ex":{"en":"a violent/serious incident","cn":"暴力／严重事件"}},{"en":"a disagreement between two countries, often involving military forces","cn":"（两国间的）摩擦，冲突；（常指）军事冲突","g":"[countable]","ex":{"en":"a border/diplomatic incident","cn":"边境／外交冲突"}},{"en":"touching or hitting a surface","cn":"入射的","ex":{"en":"The technology relies on a beam of incident light passing through a prism.","cn":"该技术依赖于穿过棱镜的入射光束。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"事件;事故","en":"An incident is something that happens, often something that is unpleasant.","ex":{"en":"These incidents were the latest in a series of disputes between the two nations","cn":"这些事件是两国一系列争端中最近发生的几起。"}}]},"media":{"uk":"media/uk/incident__gb_1.mp3","us":"media/us/incident__us_1.mp3"},"examples":[{"en":"His bad behaviour was just an isolated incident.","cn":"他的不良行为只是个别事件。"},{"en":"There was a shooting incident near here last night.","cn":"昨夜这附近发生了枪击事件。"}]},"injecting":{"oxford":{"phon":"ɪnˈdʒekt","pos":"verb","senses":[{"en":"to put a drug or other substance into a person's or an animal's body using a syringe （","cn":"给 … ）注射（药物等）"},{"en":"to put a liquid into sth using a syringe or similar instrument （","cn":"给 … ）注射（液体）"}]}},"initial":{"media":{"uk":"media/uk/initial__gb_1.mp3","us":"media/us/initial__us_1.mp3"},"oxford":{"phon":"ɪˈnɪʃl","pos":"adjective","senses":[{"en":"happening at the beginning; first","cn":"最初的；开始的；第一的","ex":{"en":"There is an initial payment of £60 followed by ten instalments of £25.","cn":"首期付款60英镑，接下来还有十次25英镑的分期付款。"}},{"en":"the first letter of a person’s first name","cn":"（名字的）首字母","g":"[countable]","ex":{"en":"‘What initial is it, Mrs Owen?’ ‘It's J, J for Jane.’","cn":"“首字母是什么，欧文太太？”“是 J，Jane 的 J。”"},"pos":"noun"},{"en":"the first letters of all the names of a person or thing","cn":"（全名的）首字母","g":"[plural]","ex":{"en":"John Fitzgerald Kennedy was often known by his initials JFK.","cn":"人们常以姓名的首字母 JFK 称约翰·菲茨杰拉德·肯尼迪。"},"pos":"noun"},{"en":"to mark or sign something with your initials","cn":"用姓名的首字母作标记（或签名）于","ex":{"en":"Please initial each page and sign in the space provided.","cn":"请在每一页写上姓名首字母并在规定的空白处签字。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"开始的;最初的","en":"You use initial to describe something that happens at the beginning of a process.","ex":{"en":"The initial reaction has been excellent","cn":"初期的反应非常好。"}},{"pos":"N-COUNT 可数名词","cn":"(姓名的)首字母(例如 Michael Dennis Stocks 的首字母缩写为 M.D.S.)","en":"Initials are the capital letters which begin each word of a name. For example, if your full name is Michael Dennis Stocks, your initials will be M.D.S.","ex":{"en":"...a silver Porsche car with her initials JB on the side.","cn":"车身有她姓名缩写JB的银色保时捷跑车"}},{"pos":"VERB 动词","cn":"用姓名的首字母签名于","en":"If someone initials an official document, they write their initials on it, for example to show that they have seen it or that they accept or agree with it.","ex":{"en":"Would you mind initialing this voucher?","cn":"请在凭单上用首字母签名。"}}]},"examples":[{"en":"John Fitzgerald Kennedy was often known by his initials JFK.","cn":"人们常以姓名的首字母 JFK 称约翰 · 菲茨杰拉德 · 肯尼迪。"},{"en":"‘What initial is it, Mrs Owen?’ ‘It's J, J for Jane.’ “","cn":"首字母是什么，欧文太太？” “是 J，Jane 的 J。”"}]},"intolerable":{"media":{"uk":"media/uk/intolerable__gb_1.mp3","us":"media/us/intolerable__us_1.mp3"},"oxford":{"phon":"ɪnˈtɒlərəbl","pos":"adjective","senses":[{"en":"so bad or difficult that you cannot tolerate it; completely unacceptable","cn":"无法忍受的；不能容忍的；完全不可接受的","ex":{"en":"an intolerable burden/situation","cn":"无法承受的负担；不能容忍的情况"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不能忍受的;无法容忍的","en":"If you describe something as intolerable, you mean that it is so bad or extreme that no one can bear it or tolerate it.","ex":{"en":"They felt this would put intolerable pressure on them","cn":"他们觉得这会给他们带来无法承受的压力。"}}]},"examples":[{"en":"The heat was intolerable.","cn":"炎热让人受不了。"},{"en":"an intolerable burden/situation","cn":"无法承受的负担；不能容忍的情况"}]},"interior":{"media":{"uk":"media/uk/interior__gb_1.mp3","us":"media/us/interior__us_1.mp3"},"oxford":{"phon":"ɪnˈtɪəriə(r)","pos":"noun","senses":[{"en":"the inside part of something","cn":"内部；里面","g":"[countable, usually singular]","ex":{"en":"the interior of a building/a car","cn":"楼房／汽车的内部"}},{"en":"the central part of a country or continent that is a long way from the coast","cn":"内陆；内地；腹地","g":"[singular]","ex":{"en":"an expedition into the interior of Australia","cn":"深入澳大利亚腹地的探险"}},{"en":"a country’s own affairs rather than those that involve other countries","cn":"（国家的）内政，内务","g":"[singular]","ex":{"en":"the Department/Minister of the Interior","cn":"内政部；内政大臣"}},{"en":"connected with the inside part of something","cn":"内部的；里面的","ex":{"en":"interior walls","cn":"内墙"},"pos":"adjective"},{"en":"connected with the central part of a country or continent that is a long way from the coast","cn":"内陆的；内地的；腹地的","ex":{"en":"the interior jungle regions","cn":"内陆丛林地区"},"pos":"adjective"},{"en":"connected with a country's own affairs rather than those that involve other countries","cn":"（国家）内政的，内务的","ex":{"en":"the interior minister","cn":"内务部长"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"内部","en":"The interior of something is the inside part of it.","ex":{"en":"The interior of the house was furnished with heavy, old-fashioned pieces","cn":"房子里摆放着笨重的旧式家具。"}},{"pos":"ADJ 形容词","cn":"(建筑物、车辆等)内部的","en":"You use interior to describe something that is inside a building or vehicle.","ex":{"en":"The interior walls were painted green","cn":"内墙漆成了绿色。"}},{"pos":"N-SING 单数名词","cn":"内地;腹地;内陆","en":"The interior of a country or continent is the central area of it.","ex":{"en":"...a 5-day hike into the interior.","cn":"为期 5 天、深入内地的远足"}},{"pos":"ADJ 形容词","cn":"国内的;内政的;内务的","en":"A country's interior minister, ministry, or department deals with affairs within that country, such as law and order.","ex":{"en":"The French Interior Minister has intervened in a scandal over the role of a secret police force.","cn":"法国内政部长对一起涉及秘密警察部队所扮演角色的丑闻进行了干预。"}},{"pos":"N-SING 单数名词","cn":"内政","en":"A country's minister or ministry of the interior deals with affairs within that country, such as law and order.","ex":{"en":"An official from the Ministry of the Interior said six people had died.","cn":"内政部的一位官员说已有 6 人丧生。"}},{"pos":"ADJ 形容词","cn":"内心的;心灵的","en":"Interior thoughts or processes go on inside someone's head and are not expressed aloud.","ex":{"en":"She depicted the interior life of human beings, and particularly their moral stresses and strains.","cn":"她描写人类的内心生活,尤其是他们所承受的道德压力。"}}]},"examples":[{"en":"an expedition into the interior of Australia","cn":"深入澳大利亚腹地的探险"},{"en":"the interior of a building/a car","cn":"楼房/汽车的内部"}]},"intelligent":{"media":{"uk":"media/uk/intelligent__gb_1.mp3","us":"media/us/intelligent__us_1.mp3"},"oxford":{"phon":"ɪnˈtelɪdʒənt","pos":"adjective","senses":[{"en":"good at learning, understanding and thinking in a logical way about things; showing this ability","cn":"有才智的；悟性强的；聪明的","lab":"especially North American English","ex":{"en":"a highly intelligent child","cn":"非常聪明的孩子"}},{"en":"able to understand and learn things","cn":"有智力的；有理解和学习能力的","ex":{"en":"Elephants are intelligent creatures and enjoy interacting with humans.","cn":"大象是聪明的动物，喜欢与人类互动。"}},{"en":"able to store information and use it in new situations","cn":"智能的","lab":"computing","ex":{"en":"intelligent robots/algorithms","cn":"智能机器人／算法"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"聪颖的;有才智的;有灵性的","en":"A person or animal that is intelligent has the ability to think, understand, and learn things quickly and well.","ex":{"en":"Susan's a very bright and intelligent woman who knows her own mind.","cn":"苏珊是个非常聪明、有主见的女子。"}},{"pos":"ADJ 形容词","cn":"能思维的;智能的","en":"Something that is intelligent has the ability to think and understand instead of doing things automatically or by instinct.","ex":{"en":"An intelligent computer will be an indispensable diagnostic tool for doctors.","cn":"智能计算机将成为医生不可或缺的诊断工具。"}}]},"examples":[{"en":"That was a smart career move.","cn":"那是个人事业发展上的明智之举。"},{"en":"How clever of you to work it out!","cn":"你解决了这个问题真是太聪明了。"}]},"inflatable":{"media":{"uk":"media/uk/inflatable__gb_1.mp3","us":"media/us/inflatable__us_1.mp3"},"oxford":{"phon":"ɪnˈfleɪtəbl","pos":"adjective","senses":[{"en":"needing to be filled with air or gas before you use it","cn":"需充气的","ex":{"en":"an inflatable mattress","cn":"充气垫"}},{"en":"an inflatable boat","cn":"充气小艇","pos":"noun"},{"en":"a large object made of plastic or rubber and filled with air or gas, used for children to play on, or as an advertisement for something","cn":"充气玩具；大型充气宣传品","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"可吹胀的;可充气的;可膨胀的","en":"An inflatable object is one that you fill with air when you want to use it.","ex":{"en":"...an inflatable dinghy","cn":"一艘充气式橡皮筏"}},{"pos":"N-COUNT 可数名词","cn":"可充气物品(尤指小船)","en":"An inflatable is an inflatable object, especially a small boat."}]},"examples":[{"en":"an inflatable mattress","cn":"充气垫"}]},"innovators":{"oxford":{"phon":"ˈɪnəveɪt","pos":"verb","senses":[{"en":"to introduce new things, ideas, or ways of doing sth","cn":"引入（新事物、思想或方法）；创新；改革"}]}},"invest":{"media":{"uk":"media/uk/invest__gb_1.mp3","us":"media/us/invest__us_1.mp3"},"oxford":{"phon":"ɪnˈvest","pos":"verb","senses":[{"en":"to buy property, shares in a company, etc. in the hope of making a profit","cn":"投资","g":"[intransitive, transitive]","ex":{"en":"Now is a good time to invest.","cn":"现在是投资的好时机。"}},{"en":"to spend money on something in order to make it better or more successful","cn":"（把资金）投入","g":"[intransitive, transitive]","ex":{"en":"The company plans to invest still further.","cn":"该公司计划进一步投资。"}},{"en":"to spend time, energy, effort, etc. on something that you think is good or useful","cn":"投入（时间、精力等）","g":"[transitive]","ex":{"en":"She had invested all her adult life in the relationship.","cn":"她把成年后的时间全用于维护那段关系。"}},{"en":"to give somebody power or authority, especially as part of their job","cn":"授予，给予（权力等）","g":"[transitive]","lab":"formal","ex":{"en":"The new position invested her with a good deal of responsibility.","cn":"新职位赋予她重大的责任。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"投资","en":"If you invest in something, or if you invest a sum of money, you use your money in a way that you hope will increase its value, for example by paying it into a bank, or buying shares or property.","ex":{"en":"They intend to invest directly in shares","cn":"他们打算直接投资股票。"}},{"pos":"VERB 动词","cn":"出资;资助","en":"When a government or organization invests in something, it gives or lends money for a purpose that it considers useful or profitable.","ex":{"en":"...the British government's failure to invest in an integrated transport system.","cn":"英国政府未能给综合交通系统的建设投入资金"}},{"pos":"VERB 动词","cn":"购买;买进","en":"If you invest in something useful, you buy it, because it will help you to do something more efficiently or more cheaply.","ex":{"en":"The company invested thousands in an electronic order-control system","cn":"公司耗资数千购买了一套电子订单管理系统。"}},{"pos":"VERB 动词","cn":"投入(时间、精力)","en":"If you invest time or energy in something, you spend a lot of time or energy on something that you consider to be useful or likely to be successful.","ex":{"en":"I would rather invest time in Rebecca than in the kitchen.","cn":"我宁愿把时间花在丽贝卡身上也不愿花在厨房里。"}},{"pos":"VERB 动词","cn":"赋予，使具有(某种特征)","en":"If you say that someone or something is invested with a particular quality, you mean that they seem to have that quality.","ex":{"en":"The buildings are invested with a nation's history","cn":"这些建筑承载着一个国家的历史。"}},{"pos":"VERB 动词","cn":"授予(某人权力、责任)","en":"To invest someone with rights or responsibilities means to give them those rights or responsibilities legally or officially.","ex":{"en":"The constitution had invested him with certain powers.","cn":"宪法授予他某些权力。"}}]},"examples":[{"en":"The college is to invest $2 million in a new conference hall.","cn":"这所学院计划投入 200 万元建造新的会议大厅。"},{"en":"In his time managing the club he has invested millions on new players.","cn":"他在管理俱乐部期间投入了几百万培养新运动员。"}]},"inside":{"media":{"uk":"media/uk/inside__gb_1.mp3","us":"media/us/inside__us_1.mp3"},"oxford":{"phon":"ˌɪnˈsaɪd","pos":"preposition","senses":[{"en":"on or to the inner part of something/somebody; within something/somebody","cn":"在（或向）…内；在（或向）…里","lab":"figurative","ex":{"en":"Go inside the house.","cn":"进屋里吧。"}},{"en":"in less than the amount of time mentioned","cn":"少于（某时间）","ex":{"en":"The job is unlikely to be finished inside (of) a year.","cn":"这项工作不大可能在一年之内完成。"}},{"en":"on or to the inside","cn":"在（或向）里面","lab":"figurative","ex":{"en":"She shook it to make sure there was nothing inside.","cn":"她把它晃了晃，以确定里面没有东西。"},"pos":"adverb"},{"en":"in prison","cn":"在监狱里；被监禁","lab":"informal","ex":{"en":"He was sentenced to three years inside.","cn":"他被判三年监禁。"},"pos":"adverb"},{"en":"the inner part, side or surface of something","cn":"里面；内部；内侧","g":"[countable, usually singular]","ex":{"en":"The inside of the box was blue.","cn":"盒子的内面呈蓝色。"},"pos":"noun"},{"en":"the part of a road nearest the edge, that is used by slower vehicles","cn":"（靠近路边的）慢车道","g":"[singular]","ex":{"en":"He tried to overtake on the inside.","cn":"他试图从慢车道超车。"},"pos":"noun"},{"en":"the part of a curved road or track nearest to the middle or shortest side of the curve","cn":"（道路或跑道拐弯处的）内侧，里道，内圈","g":"[singular]","ex":{"en":"The French runner is coming up fast on the inside.","cn":"法国的赛跑选手正从内圈迅速赶上来。"},"pos":"noun"},{"en":"a person’s stomach and bowels","cn":"（人的）肠胃，内脏","g":"[plural]","lab":"informal","ex":{"en":"She was so nervous, her insides were like jelly.","cn":"她紧张得六神无主。"},"pos":"noun"},{"en":"forming the inner part of something; not on the outside","cn":"内部的；里面的","lab":"British English","ex":{"en":"the inside pages of a newspaper","cn":"报纸的内页"},"pos":"adjective"},{"en":"known or done by somebody in a group or an organization","cn":"从内部了解到的；内线干的","ex":{"en":"inside information","cn":"内部情报"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"在…里面;在…内侧(或内部)","en":"Something or someone that is inside a place, container, or object is in it or is surrounded by it.","ex":{"en":"Inside the passport was a folded slip of paper","cn":"护照里面有张折起的纸片。"}},{"pos":"N-COUNT 可数名词","cn":"里面;内侧;内部","en":"The inside of something is the part or area that its sides surround or contain.","ex":{"en":"The doors were locked from the inside","cn":"门从里面锁上了。"}},{"pos":"ADV 副词","cn":"在监狱里;在坐牢","en":"You can say that someone is inside when they are in prison.","ex":{"en":"He's been inside three times.","cn":"他进过三次监狱。"}},{"pos":"ADJ 形容词","cn":"(马路车道)靠近路边的，慢(道)的","en":"On a wide road, the inside lane is the one which is closest to the edge of the road.","ex":{"en":"I was driving up at seventy miles an hour on the inside lane on the motorway.","cn":"我在高速公路的慢道上以每小时 70 英里的速度行驶。"}},{"pos":"ADJ 形容词","cn":"(消息等)内部的,内幕的","en":"Inside information is obtained from someone who is involved in a situation and therefore knows a lot about it.","ex":{"en":"Sloane used inside diplomatic information to make himself rich","cn":"斯隆利用外交内幕消息发了财。"}},{"pos":"PREP 介词","cn":"在(组织)内部","en":"If you are inside an organization, you belong to it.","ex":{"en":"75 percent of chief executives come from inside the company","cn":"75% 的行政总裁来自公司内部。"}},{"pos":"N-PLURAL 复数名词","cn":"内脏;(尤指)胃","en":"Your insides are your internal organs, especially your stomach."},{"pos":"ADV 副词","cn":"在心里","en":"If you say that someone has a feeling inside, you mean that they have it but have not expressed it.","ex":{"en":"There is nothing left inside—no words, no anger, no tears","cn":"整颗心都空了——没有语言,没有愤怒,没有眼泪。"}},{"pos":"PREP 介词","cn":"在(某段时间)之内;不到","en":"If you do something inside a particular time, you do it before the end of that time.","ex":{"en":"They should have everything working inside an hour","cn":"他们应该会在一个小时之内使一切运转起来。"}},{"pos":"PHRASE 短语","cn":"里朝外地;翻面地","en":"If something such as a piece of clothing is inside out, the part that is normally inside now faces outwards.","ex":{"en":"Her umbrella blew inside out.","cn":"她的伞被风吹得翻转了。"}},{"pos":"PHRASE 短语","cn":"彻底地;完全地","en":"If you say that you know something or someone inside out, you are emphasizing that you know them extremely well.","ex":{"en":"He knew the game inside out","cn":"他对比赛非常熟悉。"}},{"pos":"PHRASE 短语","cn":"颠倒;相反","en":"If you say that something has been turned inside out, you mean that it is the opposite of what you expect or think it should be.","ex":{"en":"Edinburgh is an American city turned inside out: the rich in the middle, the poor around the outside","cn":"爱丁堡与美国城市相反：富人住在中心,穷人住在周边。"}}]},"examples":[{"en":"For years we had little knowledge of what life was like inside China.","cn":"以往很多年我们对于中国国内的生活情况所知甚少。"},{"en":"( figurative ) Inside most of us is a small child screaming for attention.","cn":"我们大多数人的内心都藏着一个呼求关注的小孩。"}]},"ins":{"oxford":{"phon":"ɪn","pos":"preposition","senses":[{"en":"at a point within an area or a space","cn":"在（某范围或空间内的）某一点"},{"en":"within the shape of sth; surrounded by sth","cn":"在（某物的形体或范围）中；在 … 内；在 … 中"}]},"media":{"uk":"media/uk/in__gb_1.mp3","us":"media/us/in__us_1.mp3"}},"intentionally":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"use this about things that you do or say deliberately","cn":""},{"en":"use this about things that you do or say deliberately, especially about things that are wrong or illegal","cn":""}]},"examples":[{"en":"I did trip him, but it wasn’t intentional.","cn":"","src":"ld"}],"media":{"uk":"media/uk/intentionally__gb_1.mp3","us":"media/us/intentionally__us_1.mp3"},"oxford":{"phon":"ɪnˈtenʃənəli","pos":"adverb","senses":[{"en":"deliberately","cn":"夸张的；夸张法的","ex":{"en":"She would never intentionally hurt anyone.","cn":"她决不会故意伤害任何人。"}}]}},"insistence":{"media":{"uk":"media/uk/insistence__gb_1.mp3","us":"media/us/insistence__us_1.mp3"},"oxford":{"phon":"ɪnˈsɪstəns","pos":"noun","senses":[{"en":"an act of demanding or saying something clearly and refusing to accept any opposition or excuses","cn":"坚决要求；坚持；固执","ex":{"en":"At her insistence, the matter was dropped.","cn":"在她的坚持下，这件事被搁置了。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"坚持;坚决要求;坚称","en":"Someone's insistence on something is the fact that they insist that it should be done or insist that it is the case.","ex":{"en":"...Raeder's insistence that naval uniform be worn","cn":"雷德坚决要求穿海军制服"}}]},"examples":[{"en":"At her insistence, the matter was dropped.","cn":"在她的坚持下，这件事被搁置了。"},{"en":"their insistence on strict standards of behaviour","cn":"他们对严格行为规范的坚决主张"}]},"interstate":{"oxford":{"phon":"ˈɪntəsteɪt","pos":"adjective","senses":[{"en":"between states, especially in the US","cn":"（尤指美国）州与州之间的，州际的","ex":{"en":"interstate commerce","cn":"州际贸易"}},{"en":"a wide road, with at least two lanes in each direction, where traffic can travel fast for long distances across many states. You can only enter and leave interstates at special ramps.","cn":"州际公路","ex":{"en":"We were driving down the interstate.","cn":"我们正驱车顺州际公路而行。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(尤指美国)州际的，州与州之间的","en":"Interstate means between states, especially the states of the United States.","ex":{"en":"...interstate highways.","cn":"州际公路"}},{"pos":"N-COUNT 可数名词","cn":"(美国)州际公路","en":"In the United States, an interstate is a major road linking states.","ex":{"en":"We were driving along Interstate 280, toward my home in Woodside.","cn":"我们正驾车沿280号州际公路往我在伍德赛德的家行驶。"}}]},"media":{"uk":"media/uk/interstate__gb_1.mp3","us":"media/us/interstate__us_1.mp3"},"examples":[{"en":"interstate commerce","cn":"州际贸易"}]},"intervals":{"oxford":{"phon":"ˈɪntəvl","pos":"noun","senses":[{"en":"a period of time between two events （","cn":"时间上的）间隔，间隙，间歇"},{"en":"a short period of time separating parts of a play, film/movie or concert （","cn":"戏剧、电影或音乐会的）幕间休息，休息时间"}]}},"inspire":{"media":{"uk":"media/uk/inspire__gb_1.mp3","us":"media/us/inspire__us_1.mp3"},"oxford":{"phon":"ɪnˈspaɪə(r)","pos":"verb","senses":[{"en":"to give somebody the desire, confidence or enthusiasm to do something well","cn":"激励；鼓舞","ex":{"en":"The actors' enthusiasm inspired the kids.","cn":"演员们的热情鼓舞着孩子们。"}},{"en":"to give somebody the idea for something, especially something artistic or that shows imagination","cn":"赋予灵感；引起联想；启发思考","ex":{"en":"The choice of decor was inspired by a trip to India.","cn":"选用这种装饰格调是从一次印度之行中得到的启发。"}},{"en":"to make somebody have a particular feeling or emotion","cn":"使产生（感觉或情感）","ex":{"en":"Henry did not inspire confidence as a figure of authority.","cn":"亨利没有给人身为一个权威人物的感觉。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"激励;鼓舞;驱使","en":"If someone or something inspires you to do something new or unusual, they make you want to do it.","ex":{"en":"These herbs will inspire you to try out all sorts of exotic-flavoured dishes!","cn":"这些香草会激发你去品尝各种异国风味的菜肴！"}},{"pos":"VERB 动词","cn":"启发;使产生灵感和热情","en":"If someone or something inspires you, they give you new ideas and a strong feeling of enthusiasm.","ex":{"en":"Jimi Hendrix inspired a generation of guitarists.","cn":"吉米·亨德里克斯启发了整整一代吉他演奏者。"}},{"pos":"VERB 动词","cn":"作为…的为灵感来源;是…的原型","en":"If a book, work of art, or action is inspired by something, that thing is the source of the idea for it.","ex":{"en":"The book was inspired by a real person, namely Tamara de Treaux.","cn":"那本书的灵感源于一个真实人物,即塔玛拉·德特罗。"}},{"pos":"VERB 动词","cn":"激起，唤起(某种感情或反应)","en":"Someone or something that inspires a particular emotion or reaction in people makes them feel this emotion or reaction.","ex":{"en":"The car's performance quickly inspires confidence.","cn":"该汽车的性能会很快唤起驾驶者的信心。"}}]},"examples":[{"en":"His superb play inspired the team to a thrilling 5–0 win.","cn":"他的出色表现使球队士气大振，以 5:0 大获全胜。"},{"en":"By visiting schools, the actors hope to inspire children to put on their own productions.","cn":"演员希望通过访问学校鼓励孩子们演出自己的作品。"}]},"intolerably":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to be unable to accept an unpleasant situation","cn":""},{"en":"to be unable to accept an unpleasant situation without becoming angry or upset, especially when someone's behaviour is not fair or reasonable","cn":""}]},"media":{"uk":"media/uk/intolerably__gb_1.mp3","us":"media/us/intolerably__us_1.mp3"},"oxford":{"phon":"ɪnˈtɒlərəbli","pos":"adverb","senses":[{"en":"in a way that is so bad or difficult that you cannot tolerate it; in a completely unacceptable way","cn":"无法忍受的；不能容忍的；完全不可接受的","ex":{"en":"intolerably hot","cn":"热得无法忍受"}}]}},"invented":{"oxford":{"phon":"ɪnˈvent","pos":"verb","senses":[{"en":"to produce or design sth that has not existed before","cn":"发明；创造"},{"en":"to say or describe sth that is not true, especially in order to trick people","cn":"编造；捏造；虚构"}]}},"introduces":{"oxford":{"phon":"ˌɪntrəˈdjuːs","pos":"verb","senses":[{"en":"to tell two or more people who have not met before what each other's names are; to tell sb what your name is","cn":"把 … 介绍（给）；引见；（自我）介绍"},{"en":"to be the main speaker in a television or radio show, who gives details about the show and who presents the people who are in it; to tell the audience the name of the person who is going to speak or perform","cn":"主持（节目）；介绍（讲演者或演员）"}]},"media":{"uk":"media/uk/introduce__gb_1.mp3","us":"media/us/introduce__us_1.mp3"}},"inform":{"oxford":{"phon":"ɪnˈfɔːm","pos":"verb","senses":[{"en":"to tell somebody about something, especially in an official way","cn":"知会；通知；通告","ex":{"en":"The government took this decision without consulting Parliament or informing the public.","cn":"政府作出这个决定前既没有咨询议会，也没有告知公众。"}},{"en":"to find out information about something","cn":"了解；熟悉","ex":{"en":"We need time to inform ourselves thoroughly of the problem.","cn":"我们需要时间对这个问题有个透彻的了解。"}},{"en":"to have an influence on something","cn":"对…有影响","lab":"formal","ex":{"en":"Religion informs every aspect of their lives.","cn":"宗教影响着他们生活的各个方面。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"通知;告知","en":"If you inform someone of something, you tell them about it.","ex":{"en":"They would inform him of any progress they had made","cn":"他们会把他们取得的任何进步都告诉他。"}},{"pos":"VERB 动词","cn":"告发;检举","en":"If someone informs on a person, they give information about the person to the police or another authority, which causes the person to be suspected or proved guilty of doing something bad.","ex":{"en":"Somebody must have informed on us","cn":"肯定有人告发我们了。"}},{"pos":"VERB 动词","cn":"赋(思想或特质)于;渗透入","en":"If a situation or activity is informed by an idea or a quality, that idea or quality is very noticeable in it.","ex":{"en":"All great songs are informed by a certain sadness and tension","cn":"所有很棒的歌曲都透着某种悲伤和张力。"}}]},"media":{"uk":"media/uk/inform__gb_1.mp3","us":"media/us/inform__us_1.mp3"},"examples":[{"en":"We need time to inform ourselves thoroughly of the problem.","cn":"我们需要时间对这个问题有个透彻的了解。"},{"en":"I have been reliably informed (= somebody I trust has told me) that the couple will marry next year.","cn":"我得到可靠消息说他们俩明年结婚。"}]},"introductory":{"media":{"uk":"media/uk/introductory__gb_1.mp3","us":"media/us/introductory__us_1.mp3"},"oxford":{"phon":"ˌɪntrəˈdʌktəri","pos":"adjective","senses":[{"en":"written or said at the beginning of something as an introduction to what follows","cn":"序言的；引导的；介绍的","ex":{"en":"introductory chapters/paragraphs/remarks","cn":"序篇；引言段；开场白"}},{"en":"intended as an introduction to a subject or an activity for people who have never done it before","cn":"入门的；初步的","ex":{"en":"introductory courses/lectures","cn":"基础课程／讲座"}},{"en":"offered for a short time only, when a product is first on sale","cn":"（新产品）试销的","ex":{"en":"a special introductory price of just $10","cn":"仅 10 美元的优惠上市价"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"引言的;导论的;介绍性的","en":"An introductory remark, talk, or part of a book gives a small amount of general information about a particular subject, often before a more detailed explanation.","ex":{"en":"...an introductory course in religion and theology.","cn":"宗教与神学入门课程"}},{"pos":"ADJ 形容词","cn":"(新品)促销的，特惠的","en":"An introductory offer or price on a new product is something such as a free gift or a low price that is meant to attract new customers.","ex":{"en":"...just out on the shelves at an introductory price of £2.99.","cn":"刚刚以2.99英镑的新品促销价上架"}}]},"examples":[{"en":"a special introductory price of just $10","cn":"仅 10 元的优惠上市价"},{"en":"This introductory offer is for three days only.","cn":"本试销优惠只为期三天。"}]},"index":{"oxford":{"phon":"ˈɪndeks","pos":"noun","senses":[{"en":"a list of names or topics that are referred to in a book, etc., usually arranged at the end of a book in alphabetical order or listed in a separate file or book","cn":"索引","ex":{"en":"Look it up in the index.","cn":"在索引中查找。"}},{"en":"a box of cards with information on them, arranged in alphabetical order","cn":"卡片目录（或索引）","lab":"British English"},{"en":"a system that shows the level of prices and wages, etc. so that they can be compared with those of a previous date","cn":"（物价和工资等的）指数","ex":{"en":"the cost-of-living index","cn":"生活费用指数"}},{"en":"a sign or measure that something else can be judged by","cn":"标志；指标；表征；量度","ex":{"en":"The number of new houses being built is a good index of a country's prosperity.","cn":"在建新房屋的数量是国家繁荣程度的一个可靠指标。"}},{"en":"the small number written above a larger number to show how many times that number must be multiplied by itself. In the equation 42 = 16, the number 2 is an index.","cn":"指数（如在等式 42 = 16 中，2 是指数）","g":"[plural]","lab":"mathematics"},{"en":"to make an index of documents, the contents of a book, etc.; to add something to a list of this type","cn":"为…编索引；将…编入索引","ex":{"en":"All publications are indexed by subject and title.","cn":"所有出版物都按学科和名称编索引。"},"pos":"verb"},{"en":"to link wages, etc. to the level of prices of food, clothing, etc. so that they both increase at the same rate","cn":"将（工资等）与（物价水平等）挂钩；使指数化","g":"[usually passive]","ex":{"en":"The basic state pension is indexed to inflation.","cn":"国家基本养老金与通货膨胀挂钩。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"指数","en":"An index is a system by which changes in the value of something and the rate at which it changes can be recorded, measured, or interpreted.","ex":{"en":"...the UK retail price index.","cn":"英国零售价格指数"}},{"pos":"N-COUNT 可数名词","cn":"索引","en":"An index is an alphabetical list that is printed at the back of a book and tells you on which pages important topics are referred to.","ex":{"en":"Curiously, the word 'gay' does not occur in the index","cn":"奇怪的是,gay这个词没有出现在索引当中。"}},{"pos":"VERB 动词","cn":"为(书等)编索引","en":"If you index a book or a collection of information, you make an alphabetical list of the items in it.","ex":{"en":"This vast archive has been indexed and made accessible to researchers","cn":"这个存量巨大的档案室的所有文件都已编了索引,可供研究人员使用。"}},{"pos":"VERB 动词","cn":"使(与…)相应挂钩;使指数化","en":"If a quantity or value is indexed to another, a system is arranged so that it increases or decreases whenever the other one increases or decreases.","ex":{"en":"Minimum pensions and wages are to be indexed to inflation.","cn":"最低养老金和最低工资要与通货膨胀挂钩。"}},{"pos":"N-COUNT 可数名词","cn":"标志;迹象;指标","en":"If one thing is an index of another, it indicates what the other thing will be like.","ex":{"en":"Weeds are an index to the character of the soil.","cn":"杂草是反映土壤特征的一个指标。"}},{"pos":"N-COUNT 可数名词","cn":"(数学中的)指数","en":"In mathematics, indices are the little numbers that show how many times you must multiply a number by itself. In the equation 32 = 9, the number 2 is an index."}]},"media":{"uk":"media/uk/index__gb_1.mp3","us":"media/us/index__us_1.mp3"},"examples":[{"en":"Author and subject indexes are available on a library database.","cn":"作者索引和学科索引可在图书馆的数据库中找到。"},{"en":"The number of new houses being built is a good index of a country's prosperity.","cn":"新建房屋的数量是国家繁荣的一个可靠指标。"}]},"independent":{"media":{"uk":"media/uk/independent__gb_1.mp3","us":"media/us/independent__us_1.mp3"},"oxford":{"phon":"ˌɪndɪˈpendənt","pos":"adjective","senses":[{"en":"having its own government","cn":"独立的；自主的；自治的","sc":"country","ex":{"en":"an independent state/nation/country","cn":"独立国家"}},{"en":"confident and free to do things without needing help from other people","cn":"自主的；有主见的","sc":"person","ex":{"en":"Going away to college has made me much more independent.","cn":"离家上大学使我变得独立自主得多。"}},{"en":"having or earning enough money so that you do not have to rely on somebody else for help","cn":"自立的；自食其力的","sc":"person","ex":{"en":"It was important to me to be financially independent of my parents.","cn":"在经济上不依赖父母，这对我很重要。"}},{"en":"done or given by somebody who is not involved in a situation and so is able to judge it fairly","cn":"不相干的人所做的（或提供的）；公正的；无偏见的","sc":"separate","ex":{"en":"an independent inquiry/review/investigation","cn":"独立的调查"}},{"en":"not connected with or influenced by something; not connected with each other","cn":"不相关的；不受影响的；无关联的","sc":"separate","ex":{"en":"The police force should be independent of direct government control.","cn":"警方应该不受政府的直接控制。"}},{"en":"supported by private money rather than government money","cn":"私营的","sc":"organization/worker","ex":{"en":"independent television","cn":"私营电视台"}},{"en":"not employed or controlled by a company; not created by a big company","cn":"不受雇于公司的；非大公司制作的","sc":"organization/worker","ex":{"en":"She was hired to do the work as an independent contractor.","cn":"她受聘以独立承包人的身份来做这项工作。"}},{"en":"not representing or belonging to a particular political party","cn":"无党派的；独立的","sc":"politician","ex":{"en":"an independent candidate","cn":"独立候选人"}},{"en":"a member of parliament, candidate, etc. who does not belong to a particular political party","cn":"无党派议员（或候选人等）","ex":{"en":"She's standing as an independent at the next election.","cn":"她将以独立人士身份参加下次选举。"},"pos":"noun"},{"en":"a person who runs their own small business and is not employed or controlled by a company","cn":"独立经营者","ex":{"en":"It's getting tougher and tougher for independents in the music business.","cn":"对于音乐行业的独立人士来说，处境变得越来越艰难。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"相互独立的;彼此不关联的","en":"If one thing or person is independent of another, they are separate and not connected, so the first one is not affected or influenced by the second.","ex":{"en":"Your questions should be independent of each other","cn":"你的问题应该彼此无关。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自立的;不需外援的","en":"If someone is independent, they do not need help or money from anyone else.","ex":{"en":"Phil was now much more independent of his parents","cn":"菲尔现在不那么依赖父母了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(国家)独立的","en":"Independent countries and states are not ruled by other countries but have their own government.","ex":{"en":"...a fully independent state","cn":"一个完全独立的国家"}},{"pos":"ADJ 形容词","cn":"(组织)独立的，不受他人控制的","en":"An independent organization or other body is one that controls its own finances and operations, rather than being controlled by someone else.","ex":{"en":"...an independent television station.","cn":"独立电视台"}},{"pos":"ADJ 形容词","cn":"(学校)私立的","en":"An independent school does not receive money from the government or local council, but from the fees paid by its students' parents or from charities.","ex":{"en":"He taught chemistry at a leading independent school.","cn":"他在一所重点私立中学教化学。"}},{"pos":"ADJ 形容词","cn":"(调查、意见)独立的，不偏不倚的","en":"An independent inquiry or opinion is one that involves people who are not connected with a particular situation, and should therefore be fair.","ex":{"en":"The government ordered an independent inquiry into the affair","cn":"政府下令对该事件进行独立调查。"}},{"pos":"ADJ 形容词","cn":"无党派的","en":"An independent politician is one who does not represent any political party.","ex":{"en":"There's been a late surge of support for an independent candidate.","cn":"最近一位无党派候选人的支持率迅速上升。"}}]},"examples":[{"en":"Two independent research bodies reached the same conclusions.","cn":"两个彼此不相关的研究部门得出了同样的结论。"},{"en":"Mozambique became independent in 1975.","cn":"莫桑比克于 1975 年获得独立。"}]},"intrinsic":{"media":{"uk":"media/uk/intrinsic__gb_1.mp3","us":"media/us/intrinsic__us_1.mp3"},"oxford":{"phon":"ɪnˈtrɪnzɪk","pos":"adjective","senses":[{"en":"belonging to or part of the real nature of something/somebody","cn":"固有的；内在的；本身的","ex":{"en":"the intrinsic value of education","cn":"教育的固有价值"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"内在的;本身的;固有的","en":"If something has intrinsic value or intrinsic interest, it is valuable or interesting because of its basic nature or character, and not because of its connection with other things.","ex":{"en":"The paintings have no intrinsic value except as curiosities","cn":"这些油画除了作为古董，本身没有什么内在价值。"}}]},"examples":[{"en":"Small local shops are intrinsic to the town's character.","cn":"本地的一些小店铺是这个镇的基本特点。"},{"en":"These tasks were repetitive, lengthy and lacking any intrinsic interest.","cn":"这些作业重复冗长，本质上缺乏趣味。"}]},"integrity":{"media":{"uk":"media/uk/integrity__gb_1.mp3","us":"media/us/integrity__us_1.mp3"},"oxford":{"phon":"ɪnˈteɡrəti","pos":"noun","senses":[{"en":"the quality of being honest and having strong moral principles","cn":"诚实正直","ex":{"en":"personal/professional/artistic integrity","cn":"个人的／职业上的／艺术家的诚实正直"}},{"en":"the state of being whole and not divided","cn":"完整；完好","lab":"formal","ex":{"en":"to respect the territorial integrity of the nation","cn":"尊重该国的领土完整"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"正直;诚实","en":"If you have integrity, you are honest and firm in your moral principles.","ex":{"en":"I have always regarded him as a man of integrity","cn":"我一直认为他正直诚实。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"完整;完全;完善","en":"The integrity of something such as a group of people or a text is its state of being a united whole.","ex":{"en":"Separatist movements are a threat to the integrity of the nation.","cn":"分离主义运动对国家统一是个威胁。"}}]},"examples":[{"en":"to respect the territorial integrity of the nation","cn":"尊重该国的领土完整"},{"en":"personal/professional/artistic integrity","cn":"个人的/职业上的/艺术家的诚实正直"}]},"individuality":{"media":{"uk":"media/uk/individuality__gb_1.mp3","us":"media/us/individuality__us_1.mp3"},"oxford":{"phon":"ˌɪndɪˌvɪdʒuˈæləti","pos":"noun","senses":[{"en":"the qualities that make somebody/something different from other people or things","cn":"个性；个人（或个体）特征","ex":{"en":"She expresses her individuality through her clothes.","cn":"她通过穿着表现个性。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"独特性;个性;个人特征","en":"The individuality of a person or thing consists of the qualities that make them different from other people or things.","ex":{"en":"People should be free to express their individuality","cn":"人们应该能自由表达他们的个性。"}}]},"examples":[{"en":"She expresses her individuality through her clothes.","cn":"她从穿着上表现出她的个性。"},{"en":"We like our staff to show their individuality rather than wear a uniform.","cn":"我们喜欢员工穿出个性﹐而不是穿制服。"}]},"inspector":{"oxford":{"phon":"ɪnˈspektə(r)","pos":"noun","senses":[{"en":"an officer of middle rank in the police force","cn":"（警察）巡官","ex":{"en":"Inspector Maggie Forbes","cn":"玛吉·福布斯巡官"}},{"en":"a person whose job is to visit schools, factories, etc. to check that rules are being obeyed and that standards are acceptable","cn":"检查员；视察员；巡视员","ex":{"en":"a school/health/safety inspector","cn":"督学；卫生／安全检查员"}},{"en":"(in the UK) a person whose job is to check tickets on a bus or train","cn":"（公共汽车或火车上的）查票员"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"检查员;视察员;督察员","en":"An inspector is a person, usually employed by a government agency, whose job is to find out whether people are obeying official regulations.","ex":{"en":"The mill was finally shut down by state safety inspectors.","cn":"工厂终于遭国家安全检查员关闭了。"}},{"pos":"N-COUNT; N-TITLE; N-VOC可数名词；头衔名词；称呼名词","cn":"(英国警察中职位低于警司高于巡佐的)巡官,督察","en":"In Britain, an inspector is an officer in the police who is higher in rank than a sergeant and lower in rank than a superintendent.","ex":{"en":"Last week gunmen attacked Mogadishu airport killing a police inspector","cn":"上周持枪歹徒袭击了摩加迪沙机场，杀死了一名警察巡官。"}},{"pos":"N-COUNT; N-TITLE; N-VOC可数名词；头衔名词；称呼名词","cn":"(美国警察中仅次于总警监的)督察长","en":"In the United States, an inspector is an officer in the police who is next in rank to a superintendent or police chief.","ex":{"en":"...San Francisco police inspector Tony Camileri.","cn":"旧金山警察局督察长托尼·卡米莱里"}}]},"media":{"uk":"media/uk/inspector__gb_1.mp3","us":"media/us/inspector__us_1.mp3"},"examples":[{"en":"a school/health/safety, etc. inspector","cn":"督学；卫生、安全等检查员"},{"en":"Inspector Maggie Forbes","cn":"玛吉 · 福布斯巡官"}]},"insect":{"oxford":{"phon":"ˈɪnsekt","pos":"noun","senses":[{"en":"any small creature with six legs and a body divided into three parts. Insects usually also have wings. Ants, bees and flies are all insects.","cn":"昆虫","ex":{"en":"Most birds spend most of the day eating insects.","cn":"大多数鸟类一天的大部分时间都在吃昆虫。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"昆虫;虫","en":"An insect is a small animal that has six legs. Most insects have wings. Ants, flies, butterflies, and beetles are all insects."}]},"media":{"img":["media/pic/insects_comp.jpg","media/thumb/ant.jpg"],"uk":"media/uk/insect__gb_1.mp3","us":"media/us/insect__us_1.mp3"},"examples":[{"en":"insect repellent (= a chemical that keeps insects away)","cn":"驱虫剂"},{"en":"insect species","cn":"昆虫种类"}]},"inspired":{"media":{"uk":"media/uk/inspired__gb_1.mp3","us":"media/us/inspired__us_1.mp3"},"oxford":{"phon":"ɪnˈspaɪəd","pos":"adjective","senses":[{"en":"having excellent qualities or abilities; produced with the help of inspiration","cn":"品质优秀的；能力卓越的；借助于灵感创作的","ex":{"en":"an inspired performance","cn":"精彩的演出"}},{"en":"used with nouns, adjectives and adverbs to show how something has been influenced","cn":"（与名词、形容词以及副词连用）受…影响的","ex":{"en":"politically inspired killings","cn":"政治性的谋杀事件"}}]},"examples":[{"en":"an inspired choice/guess (= one that is right but based on feelings rather than knowledge)","cn":"得自灵感的选择/猜测"},{"en":"politically-inspired killings","cn":"政治性的谋杀事件"}]},"inefficient":{"media":{"uk":"media/uk/inefficient__gb_1.mp3","us":"media/us/inefficient__us_1.mp3"},"oxford":{"phon":"ˌɪnɪˈfɪʃnt","pos":"adjective","senses":[{"en":"not doing a job well and not making the best use of time, money, energy, etc.","cn":"效率低的；能力差的；浪费的","ex":{"en":"an inefficient heating system","cn":"效率不佳的暖气系统"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无效率的;无能的","en":"Inefficient people, organizations, systems, or machines do not use time, energy, or other resources in the best way.","ex":{"en":"Their communication systems are inefficient in the extreme.","cn":"他们的通讯系统效率非常差。"}}]},"examples":[{"en":"inefficient use of time and energy","cn":"时间和精力的浪费"},{"en":"inefficiencies in the system","cn":"这个系统中的低效率现象"}]},"includes":{"oxford":{"phon":"ɪnˈkluːd","pos":"verb","senses":[{"en":"( not used in the progressive tenses","cn":"不用于进行时 ) if one thing includes another, it has the second thing as one of its parts 包括；包含"},{"en":"to make sb/sth part of sth","cn":"使成为 … 的一部分"}]}},"interviewed":{"oxford":{"phon":"ˈɪntəvjuː","pos":"noun","senses":[{"en":"a formal meeting at which sb is asked questions to see if they are suitable for a particular job, or for a course of study at a college, university, etc.","cn":"面试；面谈"},{"en":"a meeting (often a public one) at which a journalist asks sb questions in order to find out their opinions （","cn":"常指公开的）记者采访，访谈"}]}},"indications":{"oxford":{"phon":"ˌɪndɪˈkeɪʃn","pos":"noun","senses":[{"en":"a remark or sign that shows that sth is happening or what sb is thinking or feeling","cn":"表明；标示；显示；象征"}]}},"insists":{"oxford":{"phon":"ɪnˈsɪst","pos":"verb","senses":[{"en":"to demand that sth happens or that sb agrees to do sth","cn":"坚决要求；坚持"},{"en":"to say firmly that sth is true, especially when other people do not believe you","cn":"坚持说；固执己见"}]}},"influences":{"oxford":{"phon":"ˈɪnfluəns","pos":"noun","senses":[{"en":"the effect that sb/sth has on the way a person thinks or behaves or on the way that sth works or develops","cn":"影响；作用"},{"en":"the power that sb/sth has to make sb/sth behave in a particular way","cn":"支配力；控制力；影响力"}]}},"inadequacies":{"oxford":{"phon":"ɪnˈædɪkwəsi","pos":"noun","senses":[{"en":"the state of not being enough or good enough","cn":"不充分；不足；不够"},{"en":"a state of not being able or confident to deal with a situation","cn":"不胜任；缺乏信心"}]}},"introductions":{"oxford":{"phon":"ˌɪntrəˈdʌkʃn","pos":"noun","senses":[{"en":"the act of bringing sth into use or existence for the first time, or of bringing sth to a place for the first time","cn":"初次投入使用；采用；引进；推行"},{"en":"a thing that is brought into use or introduced to a place for the first time","cn":"新采用（或新引进）的事物"}]}},"instituted":{"oxford":{"phon":"ˈɪnstɪtjuːt","pos":"noun","senses":[{"en":"an organization that has a particular purpose, especially one that is connected with education or a particular profession; the building used by this organization （","cn":"教育、专业等）机构，机构建筑"},{"en":"( formal ) to introduce a system, policy, etc. or start a process","cn":"建立，制订（体系、政策等）；开始；实行"}]}},"initiatives":{"oxford":{"phon":"ɪˈnɪʃətɪv","pos":"noun","senses":[{"en":"a new plan for dealing with a particular problem or for achieving a particular purpose","cn":"倡议；新方案"},{"en":"the ability to decide and act on your own without waiting for sb to tell you what to do","cn":"主动性；积极性；自发性"}]}},"institutions":{"oxford":{"phon":"ˌɪnstɪˈtjuːʃn","pos":"noun","senses":[{"en":"a large important organization that has a particular purpose, for example, a university or bank （","cn":"大学、银行等规模大的）机构"},{"en":"( usually disapproving ) a building where people with special needs are taken care of, for example because they are old or mentally ill","cn":"慈善机构；社会福利机构"}]}},"introducing":{"oxford":{"phon":"ˌɪntrəˈdjuːs","pos":"verb","senses":[{"en":"to tell two or more people who have not met before what each other's names are; to tell sb what your name is","cn":"把 … 介绍（给）；引见；（自我）介绍"},{"en":"to be the main speaker in a television or radio show, who gives details about the show and who presents the people who are in it; to tell the audience the name of the person who is going to speak or perform","cn":"主持（节目）；介绍（讲演者或演员）"}]}},"introduced":{"oxford":{"phon":"ˌɪntrəˈdjuːs","pos":"verb","senses":[{"en":"to tell two or more people who have not met before what each other's names are; to tell sb what your name is","cn":"把 … 介绍（给）；引见；（自我）介绍"},{"en":"to be the main speaker in a television or radio show, who gives details about the show and who presents the people who are in it; to tell the audience the name of the person who is going to speak or perform","cn":"主持（节目）；介绍（讲演者或演员）"}]}},"inputs":{"oxford":{"phon":"ˈɪnpʊt","pos":"noun","senses":[{"en":"time, knowledge, ideas, etc. that you put into work, a project, etc. in order to make it succeed; the act of putting sth in","cn":"投入资源（指时间、知识、思想等）；投入；输入"},{"en":"( computing","cn":"计 ) the act of putting information into a computer; the information that you put in 输入；输入的信息"}]}},"inferred":{"oxford":{"phon":"ɪnˈfɜː(r)","pos":"verb","senses":[{"en":"to reach an opinion or decide that sth is true on the basis of information that is available","cn":"推断；推论；推理"},{"en":"( non-standard ) to suggest indirectly that sth is true","cn":"间接地提出；暗示；意指"}]}},"investments":{"oxford":{"phon":"ɪnˈvestmənt","pos":"noun","senses":[{"en":"the act of investing money in sth","cn":"投资"},{"en":"the money that you invest, or the thing that you invest in","cn":"投资额；投资物"}]}},"intermingled":{"oxford":{"phon":"ˌɪntəˈmɪŋɡl","pos":"verb","senses":[{"en":"to mix people, ideas, colours, etc. together; to be mixed in this way","cn":"使（人、思想、色彩等）混合"}]}},"installing":{"oxford":{"phon":"ɪnˈstɔːl","pos":"verb","senses":[{"en":"to fix equipment or furniture into position so that it can be used","cn":"安装；设置"},{"en":"to put a new program into a computer","cn":"安装，建立（程序）"}]}},"innovations":{"oxford":{"phon":"ˌɪnəˈveɪʃn","pos":"noun","senses":[{"en":"the introduction of new things, ideas or ways of doing sth （","cn":"新事物、思想或方法的）创造；创新；改革"},{"en":"a new idea, way of doing sth, etc. that has been introduced or discovered","cn":"新思想；新方法"}]}},"incentives":{"oxford":{"phon":"ɪnˈsentɪv","pos":"noun","senses":[{"en":"something that encourages you to do sth","cn":"激励；刺激；鼓励"}]}},"involves":{"oxford":{"phon":"ɪnˈvɒlv","pos":"verb","senses":[{"en":"if a situation, an event or an activity involves sth, that thing is an important or necessary part or result of it","cn":"包含；需要；使成为必然部分（或结果）"},{"en":"if a situation, an event or an activity involves sb/sth, they take part in it or are affected by it","cn":"牵涉；牵连；影响"}]}},"interests":{"oxford":{"phon":"ˈɪntrəst","pos":"noun","senses":[{"en":"the feeling that you have when you want to know or learn more about sb/sth","cn":"兴趣；关注"},{"en":"the quality that sth has when it attracts sb's attention or makes them want to know more about it","cn":"引人关注的性质；吸引力；趣味"}]}},"indulged":{"oxford":{"phon":"ɪnˈdʌldʒ","pos":"verb","senses":[{"en":"to allow yourself to have or do sth that you like, especially sth that is considered bad for you","cn":"沉湎，沉迷，沉溺（于 … ）"},{"en":"to satisfy a particular desire, interest, etc.","cn":"满足（欲望、兴趣等）"}]}},"involving":{"oxford":{"phon":"ɪnˈvɒlv","pos":"verb","senses":[{"en":"if a situation, an event or an activity involves sth, that thing is an important or necessary part or result of it","cn":"包含；需要；使成为必然部分（或结果）"},{"en":"if a situation, an event or an activity involves sb/sth, they take part in it or are affected by it","cn":"牵涉；牵连；影响"}]}},"incomes":{"oxford":{"phon":"ˈɪnkʌm","pos":"noun","senses":[{"en":"the money that a person, a region, a country, etc. earns from work, from investing money, from business, etc.","cn":"收入；收益；所得"}]}},"incursions":{"oxford":{"phon":"ɪnˈkɜːʃn","pos":"noun","senses":[{"en":"a sudden attack on a place by foreign armies, etc.","cn":"突然入侵；突然侵犯；袭击"},{"en":"the sudden appearance of sth in a particular area of activity that is either not expected or not wanted （","cn":"意外的）搅扰，介入"}]}},"included":{"oxford":{"phon":"ɪnˈkluːdɪd","pos":"adjective","senses":[{"en":"contained as part of something","cn":"包括在内","ex":{"en":"all of Europe (Britain included)","cn":"整个欧洲（包括英国）"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(强调部分构成)包括在内的","en":"You use included to emphasize that a person or thing is part of the group of people or things that you are talking about.","ex":{"en":"All of us, myself included, had been totally committed to the Party","cn":"我们大家,包括我本人在内,一直都对党绝对忠诚。"}}]},"media":{"uk":"media/ldoce/hwd/bre/e/included0205.mp3","us":"media/ldoce/hwd/ame/a/included.mp3"},"examples":[{"en":"Everyone has to go to the dentist, you included.","cn":"每个人都得去看牙医﹐包括你在内。"}]},"influenced":{"oxford":{"phon":"ˈɪnfluəns","pos":"noun","senses":[{"en":"the effect that sb/sth has on the way a person thinks or behaves or on the way that sth works or develops","cn":"影响；作用"},{"en":"the power that sb/sth has to make sb/sth behave in a particular way","cn":"支配力；控制力；影响力"}]}},"indicated":{"oxford":{"phon":"ˈɪndɪkeɪt","pos":"verb","senses":[{"en":"to show that sth is true or exists","cn":"表明；标示；显示"},{"en":"to be a sign of sth; to show that sth is possible or likely","cn":"象征；暗示"}]}},"intruders":{"oxford":{"phon":"ɪnˈtruːdə(r)","pos":"noun","senses":[{"en":"a person who enters a building or an area illegally","cn":"闯入者；侵入者"},{"en":"a person who is somewhere where they are not wanted","cn":"不受欢迎的人；不速之客"}]}},"induced":{"oxford":{"phon":"ɪnˈdjuːs","pos":"verb","senses":[{"en":"( formal ) to persuade or influence sb to do sth","cn":"劝说；诱使"},{"en":"( formal ) to cause sth","cn":"引起；导致"}]}},"interpolated":{"oxford":{"phon":"ɪnˈtɜːpəleɪt","pos":"verb","senses":[{"en":"to make a remark that interrupts a conversation","cn":"插话；插嘴"},{"en":"to add sth to a piece of writing （","cn":"在文章中）插入，添加内容"}]}},"infrastructures":{"oxford":{"phon":"ˈɪnfrəstrʌktʃə(r)","pos":"noun","senses":[{"en":"the basic systems and services that are necessary for a country or an organization to run smoothly, for example buildings, transport and water and power supplies （","cn":"国家或机构的）基础设施，基础建设"}]}},"infuriated":{"oxford":{"phon":"ɪnˈfjʊərieɪt","pos":"verb","senses":[{"en":"to make sb extremely angry","cn":"使极为生气；使大怒；激怒"}]}},"indicates":{"oxford":{"phon":"ˈɪndɪkeɪt","pos":"verb","senses":[{"en":"to show that sth is true or exists","cn":"表明；标示；显示"},{"en":"to be a sign of sth; to show that sth is possible or likely","cn":"象征；暗示"}]}},"investing":{"oxford":{"phon":"ɪnˈvest","pos":"verb","senses":[{"en":"to buy property, shares in a company, etc. in the hope of making a profit","cn":"投资"},{"en":"to spend money on sth in order to make it better or more successful （","cn":"把资金）投入"}]}},"inventions":{"oxford":{"phon":"ɪnˈvenʃn","pos":"noun","senses":[{"en":"a thing or an idea that has been invented","cn":"发明（物）；创造"},{"en":"the act of inventing sth","cn":"发明；创造"}]}},"industries":{"oxford":{"phon":"ˈɪndəstri","pos":"noun","senses":[{"en":"the production of goods from raw materials, especially in factories","cn":"工业；生产制造"},{"en":"the people and activities involved in producing a particular thing, or in providing a particular service","cn":"行业"}]}},"inhabits":{"oxford":{"phon":"ɪnˈhæbɪt","pos":"verb","senses":[{"en":"( formal ) to live in a particular place","cn":"居住在；栖居于"}]}},"increasing":{"oxford":{"phon":"ɪnˈkriːs","pos":"verb","senses":[{"en":"to become or to make sth greater in amount, number, value, etc. （","cn":"使）增长，增多；增加"},{"en":"a rise in the amount, number or value of sth","cn":"增长；增多；增加"}]},"media":{"uk":"media/ldoce/hwd/bre/b/increase_v0205.mp3","us":"media/ldoce/hwd/ame/7/l3increase.mp3"},"examples":[{"en":"The population increased dramatically in the first half of the century.","cn":""},{"en":"political tensions that might increase the likelihood of war","cn":""}]},"intellectuals":{"oxford":{"phon":"ˌɪntəˈlektʃuəl","pos":"adjective","senses":[{"en":"connected with or using a person's ability to think in a logical way and understand things","cn":"智力的；脑力的；理智的"},{"en":"well educated and enjoying activities in which you have to think seriously about things","cn":"有才智的；智力发达的"}]}},"investors":{"oxford":{"phon":"ɪnˈvestə(r)","pos":"noun","senses":[{"en":"a person or an organization that invests money in sth","cn":"投资者；投资机构"}]}},"inquiry":{"oxford":{"phon":"ɪnˈkwaɪəri","pos":"noun","senses":[{"en":"an official process to find out the cause of something or to find out information about something","cn":"调查；查究；查问","g":"[countable]","lab":"British English","ex":{"en":"a murder inquiry","cn":"谋杀案调查"}},{"en":"a request for information about somebody/something; a question about somebody/something","cn":"询问；打听","g":"[countable]","lab":"British English","ex":{"en":"inquiries from prospective students about courses","cn":"未来学生对课程的询问"}},{"en":"the act of asking questions or collecting information about somebody/something","cn":"查询；探究；探索","g":"[uncountable]","ex":{"en":"scientific inquiry","cn":"科学研究"}},{"en":"a place where you can get information","cn":"问讯处","g":"[plural]","lab":"British English","ex":{"en":"Ask at inquiries to see if your bag has been handed in.","cn":"请通过询问处询问您的行李是否已上交。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"询问;查询;打听","en":"An inquiry is a question which you ask in order to get some information.","ex":{"en":"He made some inquiries and discovered she had gone to the Continent","cn":"他打听了一番，发现她已经去了欧陆。"}},{"pos":"N-COUNT 可数名词","cn":"(官方的)调查,查问","en":"An inquiry is an official investigation.","ex":{"en":"This is the most difficult and shocking murder inquiry I have had to open in the last 25 years","cn":"这是 25 年来我所展开的最困难、最令人震惊的谋杀调查。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"询问(或调查)过程","en":"Inquiry is the process of asking about or investigating something in order to find out more about it.","ex":{"en":"The investigation has suddenly switched to a new line of inquiry.","cn":"调查突然转向了一条新的线索。"}},{"pos":"PHRASE 短语","cn":"协助警方调查","en":"If you say that someone is helping the police with their inquiries, you mean that the police are questioning them about a crime, but have not yet charged them with it.","ex":{"en":"Two men were helping police with their inquiries at Salisbury last night.","cn":"两名男子昨天夜里在索尔兹伯里接受了警方盘问。"}}]},"media":{"uk":"media/ldoce/hwd/bre/8/enquiry0205.mp3","us":"media/ldoce/hwd/ame/e/inquiry.mp3"},"examples":[{"en":"We’re getting a lot of inquiries about our new London–Rio service.","cn":"许多人来打听我们新开设的伦敦－里约热内卢的航班情况。"},{"en":"I don’t know who sent the gift, but I’ll make some inquiries .","cn":"我不知道礼物是谁送的﹐但我会打听一下。"}]},"inches":{"oxford":{"phon":"ɪntʃ","pos":"noun","senses":[{"en":"a unit for measuring length, equal to 2.54 centimetres. There are 12 inches in a foot.","cn":"英寸（长度单位，等于 2.54 厘米，1 英尺等于 12 英寸）"},{"en":"a small amount or distance","cn":"少量；短距离"}]}},"invested":{"oxford":{"phon":"ɪnˈvest","pos":"verb","senses":[{"en":"to buy property, shares in a company, etc. in the hope of making a profit","cn":"投资"},{"en":"to spend money on sth in order to make it better or more successful （","cn":"把资金）投入"}]}},"instructed":{"oxford":{"phon":"ɪnˈstrʌkt","pos":"verb","senses":[{"en":"( formal ) to tell sb to do sth, especially in a formal or official way","cn":"指示；命令；吩咐"},{"en":"( formal ) to teach sb sth, especially a practical skill","cn":"教授，传授（技能等）"}]}},"invaded":{"oxford":{"phon":"ɪnˈveɪd","pos":"verb","senses":[{"en":"to enter a country, town, etc. using military force in order to take control of it","cn":"武装入侵；侵略；侵犯"},{"en":"to enter a place in large numbers, especially in a way that causes damage or confusion （","cn":"尤指造成损害或混乱地）涌入；侵袭"}]}},"interviews":{"oxford":{"phon":"ˈɪntəvjuː","pos":"noun","senses":[{"en":"a formal meeting at which sb is asked questions to see if they are suitable for a particular job, or for a course of study at a college, university, etc.","cn":"面试；面谈"},{"en":"a meeting (often a public one) at which a journalist asks sb questions in order to find out their opinions （","cn":"常指公开的）记者采访，访谈"}]}},"indulgences":{"oxford":{"phon":"ɪnˈdʌldʒəns","pos":"noun","senses":[{"en":"( usually disapproving ) the state or act of having or doing whatever you want; the state of allowing sb to have or do whatever they want","cn":"沉溺；放纵；纵容"},{"en":"something that you allow yourself to have even though it is not essential","cn":"嗜好；爱好；享受"}]}},"indicating":{"oxford":{"phon":"ˈɪndɪkeɪt","pos":"verb","senses":[{"en":"to show that sth is true or exists","cn":"表明；标示；显示"},{"en":"to be a sign of sth; to show that sth is possible or likely","cn":"象征；暗示"}]}},"individuals":{"oxford":{"phon":"ˌɪndɪˈvɪdʒuəl","pos":"adjective","senses":[{"en":"( often used after each","cn":"常用于 each 之后 ) considered separately rather than as part of a group 单独的；个别的"},{"en":"connected with one person; designed for one person","cn":"一个人的；供一人用的"}]}},"inhabitants":{"oxford":{"phon":"ɪnˈhæbɪtənt","pos":"noun","senses":[{"en":"a person or an animal that lives in a particular place （","cn":"某地的）居民，栖息动物"}]}},"interlacing":{"oxford":{"phon":"ˌɪntəˈleɪs","pos":"verb","senses":[{"en":"( formal ) to twist things together over and under each other; to be twisted together in this way （","cn":"使）编结，交错"}]}},"intends":{"oxford":{"phon":"ɪnˈtend","pos":"verb","senses":[{"en":"to have a plan, result or purpose in your mind when you do sth","cn":"打算；计划；想要"},{"en":"( rather formal ) to plan that sth should have a particular meaning","cn":"意指"}]}},"installed":{"oxford":{"phon":"ɪnˈstɔːl","pos":"verb","senses":[{"en":"to fix equipment or furniture into position so that it can be used","cn":"安装；设置"},{"en":"to put a new program into a computer","cn":"安装，建立（程序）"}]}},"incubators":{"oxford":{"phon":"ˈɪŋkjubeɪtə(r)","pos":"noun","senses":[{"en":"a piece of equipment in a hospital which new babies are placed in when they are weak or born too early, in order to help them survive （","cn":"体弱或早产婴儿）恒温箱"},{"en":"a machine like a box where eggs are kept warm until the young birds are born","cn":"孵化器"}]}},"inched":{"oxford":{"phon":"ɪntʃ","pos":"noun","senses":[{"en":"a unit for measuring length, equal to 2.54 centimetres. There are 12 inches in a foot.","cn":"英寸（长度单位，等于 2.54 厘米，1 英尺等于 12 英寸）"},{"en":"a small amount or distance","cn":"少量；短距离"}]}},"interrupting":{"oxford":{"phon":"ˌɪntəˈrʌpt","pos":"verb","senses":[{"en":"to say or do sth that makes sb stop what they are saying or doing","cn":"插嘴；打扰；打岔"},{"en":"to stop sth for a short time","cn":"使暂停；使中断"}]}},"infants":{"oxford":{"phon":"ˈɪnfənt","pos":"noun","senses":[{"en":"( formal or technical","cn":"术语 ) a baby or very young child 婴儿；幼儿"},{"en":"a child at school between the ages of four and seven","cn":"四岁到七岁之间的学童"}]}},"injunction":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(法院下的)强制令，禁制令","en":"An injunction is a court order, usually one telling someone not to do something.","ex":{"en":"He took out a court injunction against the newspaper demanding the return of the document.","cn":"他取得了法院强制令，要求报社归还那份文件。"}},{"pos":"N-COUNT 可数名词","cn":"命令;指令;训谕","en":"An injunction to do something is an order or strong request to do it.","ex":{"en":"We hear endless injunctions to build a sense of community among staff.","cn":"我们听到上面没完没了地讲要在员工中培养一种集体归属感。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an official statement that forbids something, based on a law or a government decision","cn":""},{"en":"official orders forbidding trade or dealings with a particular country, used as a way of punishing them or stopping them from doing something","cn":""},{"en":"an official order forbidding trade in a particular product with a particular country for political or economic reasons","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If your school begins building a swimming pool on land that does not belong to it, the city might issue an injunction to stop it. An injunction is an official order issued by a judge."}]},"collocations":{"phrases":["ADJ. interim, preliminary | temporary | permanent | court","VERB + INJUNCTION apply for, seek | get, obtain, take out, win She took out an injunction to prevent the press publishing the information. |","INJUNCTION + VERB order sth, require sth | ban sth, bar sth, forbid sth, prohibit sth, restrain sb/sth The court upheld an injunction barrin","PREP. ~ against/on They got an interim injunction against the union.","PHRASES a breach of an injunction 2 warning/order from sb in authority","ADJ. stern","VERB + INJUNCTION follow, obey The rank and file members will follow the injunction of the party leadership. | ignore"]},"media":{"uk":"media/ldoce/hwd/bre/e/injunction0205.mp3","us":"media/ldoce/hwd/ame/9/injunction.mp3"},"examples":[{"en":"The court granted an injunction against the defendants.","cn":"法庭对被告发出了禁制令。"},{"en":"to seek/obtain an injunction","cn":"请求/得到强制令"}],"oxford":{"phon":"ɪnˈdʒʌŋkʃn","pos":"noun","senses":[{"en":"an official order given by a court that demands that something must or must not be done","cn":"（法院的）强制令，禁制令","ex":{"en":"to seek/obtain an injunction","cn":"请求／得到强制令"}},{"en":"a warning or an order from somebody in authority","cn":"警告；指令；命令","lab":"formal","ex":{"en":"The ordinary members will follow the injunction of the party leadership.","cn":"普通党员要听从党的领导的指示。"}}]}},"incarnation":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(某种品质的)典型体现，化身","en":"If you say that someone is the incarnation of a particular quality, you mean that they represent that quality or are typical of it in an extreme form.","ex":{"en":"The regime was the very incarnation of evil","cn":"该政权正是罪恶的化身。"}},{"pos":"N-COUNT 可数名词","cn":"(在世间的)化身，前身","en":"An incarnation is an instance of being alive on earth in a particular form. Some religions believe that people have several incarnations in different forms.","ex":{"en":"She began recalling a series of previous incarnations","cn":"她开始回忆起前世的种种情形。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the state of living in the form of a particular person or animal. According to some religions, people have several different incarnations. 〔","cn":"某些宗教中的〕前世﹐今世﹐来世"},{"en":"a period of time when someone or something has a particular job, use etc 〔","cn":"某人做某项工作﹐某物作某项用途等的〕阶段"},{"en":"someone who has a lot of a particular quality, or represents it","cn":"某事物的化身"}]},"vocab":{"pos":"n","senses":[{"en":"Incarnation is the embodiment of a god on earth. Or — when it comes to re incarnation : if you are a garbage collector in this life, you might get to be royalty in your next incarnation ."}]},"collocations":{"phrases":["ADJ. current, latest, modern, new, present (figurative) In its new incarnation, the car has a more rounded body shape. | last | earlier, pre","PREP. ~ as her previous incarnation as a Norse explorer"]},"media":{"uk":"media/ldoce/hwd/bre/a/incarnation0205.mp3","us":"media/ldoce/hwd/ame/c/incarnation1.mp3"},"examples":[{"en":"( figurative ) I worked for her in her earlier incarnation (= her previous job) as a lawyer.","cn":"她先前当律师时我曾受雇于她。"},{"en":"He believed he had been a prince in a previous incarnation.","cn":"他相信他的前生是个王子。"}],"oxford":{"phon":"ˌɪnkɑːˈneɪʃn","pos":"noun","senses":[{"en":"a period of life in a particular form","cn":"（某一段时间内的）化身","g":"[countable]","lab":"figurative","ex":{"en":"one of the incarnations of Vishnu","cn":"守护神毗湿奴的化身之一"}},{"en":"a person who represents a particular quality, for example, in human form","cn":"代表某种品质的人；化身","g":"[countable]","ex":{"en":"the incarnation of evil","cn":"邪恶的化身"}},{"en":"the act of God coming to earth in human form as Jesus","cn":"道成肉身（上帝化身为耶稣来到人间）","g":"[singular, uncountable]"}]}},"intruder":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"侵入者;闯入者","en":"An intruder is a person who goes into a place where they are not supposed to be."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who illegally enters a building or area, usually in order to steal something","cn":"非法闯入者〔通常指小偷〕"},{"en":"someone who is in a place where they are not wanted","cn":"不请自来者﹐不速之客"}]},"collocations":{"phrases":["ADJ. unwanted, unwelcome | masked","VERB + INTRUDER catch, disturb, find, startle, surprise He surprised a masked intruder in the kitchen. | deter, keep away/out Dogs can deter","INTRUDER + VERB break into, force their way into Intruders had forced their way into the house.","INTRUDER + NOUN alarm","PREP. against ~s security measures against intruders"]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdeintruder.mp3","us":"media/ldoce/hwd/ame/1/intruder.mp3"},"examples":[{"en":"The people in the room seemed to regard her as an unwelcome intruder.","cn":"屋子里的人似乎把她当成不受欢迎的外人。"},{"en":"The police think the intruder got in through an unlocked window.","cn":"警察认为闯入者是从一扇没上锁的窗子进入的。"}],"oxford":{"phon":"ɪnˈtruːdə(r)","pos":"noun","senses":[{"en":"a person who enters a building or an area illegally","cn":"闯入者；侵入者","ex":{"en":"The intruder fired at least one more shot at the guard, then fled.","cn":"入侵者向警卫至少开了一枪，然后逃跑了。"}},{"en":"a person who is somewhere where they are not wanted","cn":"不受欢迎的人；不速之客","ex":{"en":"The people in the room seemed to regard her as an unwelcome intruder.","cn":"屋子里的人似乎把她当成不受欢迎的外人。"}}]}},"interpreter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"口译者;口译员","en":"An interpreter is a person whose job is to translate what someone is saying into another language.","ex":{"en":"Aristide spoke to the press through an interpreter.","cn":"阿里斯蒂德通过口译员向媒体发表讲话。"}},{"pos":"N-COUNT 可数名词","cn":"演奏者;表演者","en":"The interpreter of something such as a piece of music is the person who performs it.","ex":{"en":"Over the years Freni has been one of the supreme interpreters of Puccini's heroines.","cn":"多年来弗雷尼一直是普契尼歌剧女主角的最佳表演者之一。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who translates from one language to another","cn":""},{"en":"someone who immediately translates spoken language, for example when politicians from different countries are speaking to each other","cn":""},{"en":"someone who changes spoken words from one language into another, especially as their job","cn":"口译者"}]},"vocab":{"pos":"n","senses":[{"en":"An interpreter is someone who translates something to make it understandable, usually spoken language. When your class takes a trip to Russia, you’ll likely have an interpreter to translate Russian to English so you can understand what people are saying to you."}]},"collocations":{"phrases":["VERB + INTERPRETER act as | speak through Speaking through an interpreter, a Japanese fisherman gave his account of the tidal wave.","PREP. ~ for Susan acted as interpreter for us. • Note at JOB"]},"media":{"uk":"media/ldoce/hwd/bre/5/interpreter0205.mp3","us":"media/ldoce/hwd/ame/6/interpreter.mp3"},"examples":[{"en":"She is one of the finest interpreters of Debussy's music.","cn":"她是将德彪西的音乐演绎得最出色的演奏者之一。"},{"en":"Speaking through an interpreter , the President said that the talks were going well.","cn":"总统通过口译员说会谈进展良好。"}],"oxford":{"phon":"ɪnˈtɜːprətə(r)","pos":"noun","senses":[{"en":"a person whose job is to translate what somebody is saying into another language","cn":"口译工作者；口译译员；传译员","ex":{"en":"Speaking through an interpreter, the President said that the talks were going well.","cn":"总统通过口译员说会谈进展良好。"}},{"en":"a person who performs a piece of music or a role in a play in a way that clearly shows their ideas about its meaning","cn":"演绎（音乐、戏剧中人物等）的人","ex":{"en":"She is one of the finest interpreters of Debussy's music.","cn":"她是将德彪西的音乐演绎得最出色的演奏者之一。"}},{"en":"a computer program that changes the instructions of another program into a form that the computer can understand and use","cn":"解释程序；解释器","lab":"computing"}]}},"intricate":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"复杂精细的;错综复杂的","en":"You use intricate to describe something that has many small parts or details.","ex":{"en":"...intricate patterns and motifs.","cn":"复杂的式样与图案"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"consisting of a lot of different parts or details and therefore difficult to understand","cn":""},{"en":"a complex process, relationship etc is difficult to understand because it has a lot of parts that are all connected in different ways","cn":""},{"en":"having a lot of parts or details and very carefully planned, but often more complicated than is necessary","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Intricate things are complex and have many elements: they're not simple. Think of the intricate wiring of a computer's motherboard, or the intricate plot of a movie that you have a hard time following."}]},"collocations":{"phrases":["VERBS be","ADV. amazingly, extraordinarily, extremely, highly, very an amazingly intricate structure | quite"]},"media":{"uk":"media/ldoce/hwd/bre/e/intricate0205.mp3","us":"media/ldoce/hwd/ame/d/intricate.mp3"},"examples":[{"en":"an intricate network of loyalties and relationships","cn":"忠诚与人事的复杂关系"},{"en":"intricate patterns","cn":"复杂的图案"}],"oxford":{"phon":"ˈɪntrɪkət","pos":"adjective","senses":[{"en":"having a lot of different parts and small details that fit together","cn":"错综复杂的","ex":{"en":"intricate patterns","cn":"复杂的图案"}}]}},"investor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"投资者;投资机构","en":"An investor is a person or organization that buys stocks or shares, or pays money into a bank in order to receive a profit.","ex":{"en":"The main investor in the project is the French bank Credit National.","cn":"该项目的主要投资商是法国的国民信贷银行。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to let a company, business, or bank use your money for a period of time, especially because you expect that you will get back more money than you gave","cn":""},{"en":"to give money to a company or business in order to help that company develop and be successful, especially because you expect that you will make a profit","cn":""},{"en":"someone who puts money into a business, company, or bank in order to make a profit in the future","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An investor is someone who provides (or invests) money or resources for an enterprise, such as a corporation, with the expectation of financial or other gain."}]},"collocations":{"phrases":["ADJ. big, large, major | ordinary, small Many ordinary investors stand to lose money in this affair. | potential, prospective, would-be | bu","VERB + INVESTOR attract, encourage A stable firm is more likely to attract potential investors. | advise advising investors where to put the","INVESTOR + VERB buy sth, invest in sth Investors will be able to buy the shares from next week. | sell sth","INVESTOR + NOUN confidence the need to restore investor confidence | protection","PREP. ~ in investors in plantation forestry (figurative) encouraging companies to become investors in people"]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41investor.mp3","us":"media/ldoce/hwd/ame/7/investor.mp3"},"examples":[{"en":"small investors (= private people)","cn":"小额投资者"},{"en":"institutional investors","cn":"机构投资者"}],"oxford":{"phon":"ɪnˈvestə(r)","pos":"noun","senses":[{"en":"a person or an organization that invests money in something","cn":"投资者；投资机构","ex":{"en":"small investors (= private people)","cn":"小额投资者"}}]}},"inflexible":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不可改变的;不容变更的","en":"Something that is inflexible cannot be altered in any way, even if the situation changes.","ex":{"en":"Workers insisted the new system was too inflexible","cn":"工人们坚持认为新制度太不灵活。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"顽固的;僵化的","en":"If you say that someone is inflexible, you are criticizing them because they refuse to change their mind or alter their way of doing things.","ex":{"en":"His opponents viewed him as stubborn, dogmatic, and inflexible.","cn":"他的反对者们认为他固执、教条、僵化。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a system that is rigid is extremely difficult or impossible to change and is therefore annoying","cn":""},{"en":"difficult or impossible to change, even when a change would be better","cn":""},{"en":"not willing to change the way you think or the way you do something","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something inflexible does not bend easily. A stiff back can make you inflexible , or unable to fold over and touch your toes. A really busy schedule can make you inflexible or unable to bend or accommodate your plans for others."}]},"collocations":{"phrases":["VERBS be, prove, seem The rules seemed arbitrary and inflexible. | become | remain","ADV. highly, very | completely, totally The seven-year period is not totally inflexible. | rather, relatively, somewhat She's a good teacher"]},"media":{"uk":"media/ldoce/hwd/bre/6/inflexible0205.mp3","us":"media/ldoce/hwd/ame/e/inflexible.mp3"},"examples":[{"en":"He's completely inflexible on the subject.","cn":"他在这个问题上寸步不让。"},{"en":"an inflexible attitude/routine/system","cn":"死硬的态度；僵化的常规/体制"}],"oxford":{"phon":"ɪnˈfleksəbl","pos":"adjective","senses":[{"en":"that cannot be changed or made more suitable for a particular situation","cn":"缺乏弹性的；僵化的","lab":"disapproving","ex":{"en":"an inflexible attitude/routine/system","cn":"死硬的态度；僵化的常规／体制"}},{"en":"unwilling to change their opinions, decisions, etc., or the way they do things","cn":"固守己见的；死板的；顽固的","lab":"disapproving","ex":{"en":"He's completely inflexible on the subject.","cn":"他在这个问题上寸步不让。"}},{"en":"difficult or impossible to bend","cn":"不能弯曲的；硬的"}]}},"insane":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"精神错乱的;精神失常的;疯狂的","en":"Someone who is insane has a mind that does not work in a normal way, with the result that their behaviour is very strange.","ex":{"en":"Some people simply can't take it and they just go insane","cn":"一些人完全承受不了，结果就精神失常了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"蠢极的;荒唐的","en":"If you describe a decision or action as insane, you think it is very foolish or excessive.","ex":{"en":"I said, 'Listen, this is completely insane.'","cn":"我说：“听着,这简直荒唐之极。”"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very strange or not sensible – used about people, ideas, and behaviour","cn":""},{"en":"crazy","cn":""},{"en":"crazy","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"To be insane is to be mentally ill. This is also a slang word for acting wacky or wild."}]},"collocations":{"phrases":["VERBS be, look | become, go He later became insane and was confined to an asylum. He went almost insane when he heard that his daughter had ","ADV. completely, totally | almost, nearly | a little | dangerously | clinically | criminally He is criminally insane, unable to stop himself","VERBS be, seem It seems insane to cut the budget now.","ADV. quite, totally The whole idea is quite insane."]},"media":{"uk":"media/ldoce/hwd/bre/4/insane0205.mp3","us":"media/ldoce/hwd/ame/a/insane.mp3"},"examples":[{"en":"I must have been insane to agree to the idea.","cn":"我肯定是犯傻了，居然同意了这个想法。"},{"en":"The prisoners were slowly going insane.","cn":"囚犯正慢慢地变得精神错乱起来。"}],"oxford":{"phon":"ɪnˈseɪn","pos":"adjective","senses":[{"en":"very stupid, crazy or dangerous","cn":"十分愚蠢的；疯狂的；危险的","lab":"informal","ex":{"en":"I must have been insane to agree to the idea.","cn":"我肯定是犯傻了，居然同意了这个想法。"}},{"en":"extremely annoyed; angry","cn":"恼怒的；发火的","lab":"informal","ex":{"en":"This job is driving me insane.","cn":"这工作令我快气疯了。"}},{"en":"shocking or very impressive; extremely large, high, good, etc.","cn":"令人震惊或非常令人印象深刻；非常大、高、好等等。","lab":"especially North American English, informal，，","ex":{"en":"The prices are insane.","cn":"价格太疯狂了。"}},{"en":"having a serious mental illness that makes somebody unable to think or behave normally","cn":"精神失常的；精神错乱的","lab":"formal, law or old-fashioned, often offensive，，，，","ex":{"en":"Doctors certified him as insane.","cn":"医生证明他精神失常。"}},{"en":"people who are insane","cn":"精神失常的人；精神错乱的人","g":"[plural]","lab":"old-fashioned, offensive，，","ex":{"en":"a hospital for the insane","cn":"精神病院"}}]}},"invasion":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"武装入侵;侵略","en":"If there is an invasion of a country, a foreign army enters it by force.","ex":{"en":"...seven years after the Roman invasion of Britain","cn":"罗马人入侵英国7年以后"}},{"pos":"N-VAR 可变名词","cn":"(令人不快的或难以对付的人或事物的)大批进入，涌入","en":"If you refer to the arrival of a large number of people or things as an invasion, you are emphasizing that they are unpleasant or difficult to deal with.","ex":{"en":"...this year's annual invasion of flies, wasps and ants","cn":"今年，苍蝇、黄蜂和蚂蚁同往年一样的大批进犯"}},{"pos":"N-VAR 可变名词","cn":"侵扰;干扰","en":"If you describe an action as an invasion, you disapprove of it because it affects someone or something in a way that is not wanted.","ex":{"en":"Is reading a child's diary always a gross invasion of privacy?","cn":"偷看孩子的日记一定是对个人隐私的严重侵犯吗？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an act of using weapons against an enemy in a war","cn":""},{"en":"an occasion when an army enters a country and tries to take control of it","cn":""},{"en":"a short attack on a place by soldiers or planes, intended to cause damage but not take control","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An invasion is the movement of an army into a region, usually in a hostile attack that's part of a war or conflict. World history is full of descriptions of invasions ."}]},"collocations":{"phrases":["ADJ. full-scale | military Latest reports are of a full-scale military invasion.","VERB + INVASION carry out, launch, mount | repel, repulse | counter, resist","PHRASES an invasion of privacy Having all those photographers in the house was a terrible invasion of privacy. | fear of invasion, a threat "]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41invasion.mp3","us":"media/ldoce/hwd/ame/1/invasion.mp3"},"examples":[{"en":"The actress described the photographs of her as an invasion of privacy.","cn":"那位女演员认为她的这些照片是对隐私权的侵犯。"},{"en":"the German invasion of Poland in 1939","cn":"德国于 1939 年对波兰的侵略"}],"oxford":{"phon":"ɪnˈveɪʒn","pos":"noun","senses":[{"en":"the act of an army entering another country by force in order to take control of it","cn":"武装入侵；侵略；侵犯","ex":{"en":"the German invasion of Poland in 1939","cn":"德国于 1939 年对波兰的侵略"}},{"en":"the fact of a large number of people or things arriving somewhere, especially people or things that are unpleasant","cn":"（尤指令人不快的）涌入，侵入","ex":{"en":"the annual tourist invasion","cn":"一年一度游客的涌入"}},{"en":"an act or a process that affects somebody/something in a way that is not welcome","cn":"侵犯；干预","ex":{"en":"The actress described the photographs of her as an invasion of privacy.","cn":"那位女演员认为她的这些照片是对隐私权的侵犯。"}}]}},"inaccuracy":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"不精确;不准确","en":"The inaccuracy of a statement or measurement is the fact that it is not accurate or correct.","ex":{"en":"He was disturbed by the inaccuracy of the answers","cn":"很多答案都不准确,为此他感到很烦恼。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something incorrect that you accidentally do, say, or write","cn":""},{"en":"a mistake","cn":""},{"en":"a small mistake in something that is printed","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Inaccuracy is the quality of having errors. A travel guide to Iowa's capital, Pearis, population 413, home of the Dallas Cowboys baseball team, would be plagued by inaccuracy ."}]},"collocations":{"phrases":["ADJ. major, material, significant | factual, historical","VERB + INACCURACY contain | be fraught with, be full of Reference works on that country, when available, are full of inaccuracies. | correct","PREP. ~ in inaccuracies in reporting"]},"media":{"uk":"media/ldoce/hwd/bre/6/inaccuracy0205.mp3","us":"media/ldoce/hwd/ame/a/laadinaccuracy.mp3"},"examples":[{"en":"The writer is guilty of bias and inaccuracy.","cn":"这位作者失于偏颇，且叙述不实。"},{"en":"The article is full of inaccuracies.","cn":"这篇文章里的错误比比皆是。"}],"oxford":{"phon":"ɪnˈækjərəsi","pos":"noun","senses":[{"en":"the fact of not being exact or accurate or of having mistakes","cn":"不准确","g":"[uncountable]","ex":{"en":"The writer is guilty of bias and inaccuracy.","cn":"这个作者失于偏颇，且叙述不实。"}},{"en":"a mistake; something that is not exact or accurate","cn":"错误；不实之处，不准确处","g":"[countable]","lab":"especially British English","ex":{"en":"The article is full of inaccuracies.","cn":"这篇文章里不准确的地方比比皆是。"}}]}},"install":{"collins":{"senses":[{"pos":"VERB 动词","cn":"安装;设置","en":"If you install a piece of equipment, you fit it or put it somewhere so that it is ready to be used.","ex":{"en":"They had installed a new phone line in the apartment.","cn":"他们已经在公寓里装上了新的电话线。"}},{"pos":"VERB 动词","cn":"使就职;任命","en":"If someone is installed in a new job or important position, they are officially given the job or position, often in a special ceremony.","ex":{"en":"A new Catholic bishop was installed in Galway yesterday","cn":"昨天在戈尔韦任命了一位新的天主教主教。"}},{"pos":"VERB 动词","cn":"安顿;安置","en":"If you install yourself in a particular place, you settle there and make yourself comfortable.","ex":{"en":"Before her husband's death she had installed herself in a modern villa.","cn":"丈夫去世之前她已经在一所现代化别墅里安顿下来了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to put a piece of equipment somewhere and connect it so that it is ready to be used","cn":"安装﹐设置〔设备〕"},{"en":"to install something. Put in is more common in everyday English than install and is used especially about things that are not very complicated to install","cn":""},{"en":"to put a new part or piece of equipment into or onto something","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"Use the verb install to mean \"set up\" or \"put in place.\" You can install new software on your computer, or even install new officers to your honor society."}]},"collocations":{"phrases":["ADV. properly, safely Make sure the equipment is properly installed. (figurative) She saw her guests safely installed in their rooms and the","VERB + INSTALL be easy to, be simple to The switches are cheap to buy and easy to install.","PHRASES newly/recently installed a recently installed swimming pool"]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdeinstall.mp3","us":"media/ldoce/hwd/ame/6/install.mp3"},"examples":[{"en":"The hotel chain has recently installed a new booking system.","cn":"这家连锁旅馆最近安装了新的预订系统。"},{"en":"He was installed as President last May.","cn":"他于去年五月份正式就任总统。"}],"oxford":{"phon":"ɪnˈstɔːl","pos":"verb","senses":[{"en":"to fix equipment or furniture into position so that it can be used","cn":"安装","ex":{"en":"They're planning to install a new drainage system.","cn":"他们计划安装新的排水系统。"}},{"en":"to put a new program onto a computer","cn":"安装（程序）","ex":{"en":"to install software/an app","cn":"安装软件／应用程序"}},{"en":"to put somebody in a new position of authority, often with an official ceremony","cn":"（常以正式仪式）使就职，任命","ex":{"en":"He was installed as President last May.","cn":"他于去年五月份正式就任总统。"}},{"en":"to make somebody/yourself comfortable in a particular place or position","cn":"安顿；安置","ex":{"en":"We installed ourselves in the front row.","cn":"我们舒舒服服地坐进了前排。"}}]}},"incongruous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不合适的;不和谐的;不相称的","en":"Someone or something that is incongruous seems strange when considered together with other aspects of a situation.","ex":{"en":"She was small and fragile and looked incongruous in an army uniform","cn":"她又小又弱,穿一身军装看起来很不协调。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not having the right qualities for a particular person, purpose, or situation","cn":""},{"en":"not suitable for a particular situation or purpose – used especially about someone’s behaviour or language","cn":""},{"en":"not the right thing or person for a particular job or purpose","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that's incongruous is inconsistent or incompatible with something else. Remember that Sesame Street song \"One of these things is not like the other\"? They were talking about that one thing being incongruous ."}]},"collocations":{"phrases":["VERBS be, look, seem | find sth","ADV. entirely, utterly | doubly | a little, rather, somewhat I found the scene somewhat incongruous."]},"media":{"uk":"media/ldoce/hwd/bre/7/incongruous0205.mp3","us":"media/ldoce/hwd/ame/4/incongruous.mp3"},"examples":[{"en":"Such traditional methods seem incongruous in our technical age.","cn":"此类传统方法似乎同我们今天的科技时代格格不入。"},{"en":"She was struck by the incongruity of the situation.","cn":"这一局面煞是怪异，让她惊愕不已。"}],"oxford":{"phon":"ɪnˈkɒŋɡruəs","pos":"adjective","senses":[{"en":"strange, and not suitable in a particular situation","cn":"不合适的；不相称的；不协调的","ex":{"en":"Such traditional methods seem incongruous in our technical age.","cn":"此类传统方法似乎同我们今天的科技时代格格不入。"}}]}},"inedible":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不可食的;不适合食用的","en":"If you say that something is inedible, you mean you cannot eat it, for example because it tastes bad or is poisonous.","ex":{"en":"Detainees complained of being given food which is inedible.","cn":"被拘留者抱怨提供的食物不堪下咽。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"food, plants, and animals that are inedible cannot be eaten, especially because they have a bad taste","cn":""},{"en":"not suitable for people to eat -- used especially in official contexts","cn":""},{"en":"if something is inedible, you cannot eat it because it tastes bad or is poisonous","cn":"不宜食用的"}]},"vocab":{"pos":"adj","senses":[{"en":"The adjective inedible is good for describing a food that cannot be eaten, like your grandmother's burnt toast, or an object that shouldn't be eaten, like your snow boots."}]},"collocations":{"phrases":["VERBS be, look | become | make sth These chemicals make the fruit inedible.","ADV. totally The food was totally inedible. | almost"]},"media":{"uk":"media/ldoce/hwd/bre/f/inedible0205.mp3","us":"media/ldoce/hwd/ame/7/inedible.mp3"},"examples":[{"en":"The meat was so burnt that it was inedible.","cn":"肉烧得那么焦﹐不能吃了。"}],"oxford":{"phon":"ɪnˈedəbl","pos":"adjective","senses":[{"en":"that you cannot eat because it is of poor quality, or poisonous","cn":"不能吃的；不宜食用的","ex":{"en":"The waiters were rude, the food inedible.","cn":"服务员很粗鲁，食物难以下咽。"}}]}},"inmate":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"被收容者;监犯;(精神病院的)住院者","en":"The inmates of a prison or mental hospital are the prisoners or patients who are living there."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is kept in a prison as a punishment for a crime, or while they are waiting for their trial","cn":""},{"en":"someone who has been found guilty of a crime and sent to a prison. Convict is used especially about someone who is sent to prison for a long time. It is more commonly used in historical descriptions, or in the phrase an escaped convict","cn":""},{"en":"someone who is kept in a prison or a mental hospital","cn":""}]},"collocations":{"phrases":["ADJ. fellow | former a former inmate of Gloucester jail | young | male, female | camp, prison","VERB + INMATE move, transfer The inmates were moved to an undisclosed location.","INMATE + VERB escape","INMATE + NOUN population","PREP. among ~ drug and alcohol misuse among inmates"]},"media":{"uk":"media/ldoce/hwd/bre/2/inmate0205.mp3","us":"media/ldoce/hwd/ame/f/inmate.mp3"},"oxford":{"phon":"ˈɪnmeɪt","pos":"noun","senses":[{"en":"one of the people living in an institution such as a prison or a psychiatric hospital","cn":"囚犯；（精神病院等的）病人","ex":{"en":"The jail has 500 inmates.","cn":"这个监狱有 500 名犯人。"}}]}},"insulting":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"侮辱的;侮慢的;无礼的","en":"Something that is insulting is rude or offensive.","ex":{"en":"The article was insulting to the families of British citizens","cn":"那篇文章侮辱了英国公民家庭。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not following the rules of good social behaviour or treating other people with a lack of respect","cn":""},{"en":"not following the rules of good social behaviour. Impolite sounds rather formal","cn":""},{"en":"behaving in a way that is a little rude, especially when this is amusing or annoying – used especially about children","cn":""}]},"collocations":{"phrases":["VERBS be, seem, sound | become | find sth, regard sth as I find it insulting to be spoken to in that way.","ADV. highly, very | quite | almost He made the question sound almost insulting. | a little, rather, vaguely | deliberately Her tone was deli","PREP. to His opinions are highly insulting to women."]},"media":{"uk":"media/ldoce/hwd/bre/d/insulting0205.mp3","us":"media/ldoce/hwd/ame/2/laadinsulting.mp3"},"examples":[{"en":"She was really insulting to me.","cn":"她对我实在粗鲁无礼。"},{"en":"insulting remarks","cn":"侮辱性的话语"}],"oxford":{"phon":"ɪnˈsʌltɪŋ","pos":"adjective","senses":[{"en":"causing or intending to cause somebody to feel offended","cn":"侮辱的；有冒犯性的；无礼的","ex":{"en":"insulting remarks","cn":"侮辱性的话语"}}]}},"incision":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"切口;伤口","en":"An incision is a sharp cut made in something, for example by a surgeon who is operating on a patient.","ex":{"en":"The technique involves making a tiny incision in the skin.","cn":"这项技术需要在皮肤上切一个小口。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to cut into someone's body, using a special knife, during a medical operation","cn":""},{"en":"to cut a dead animal or person into pieces in order to study it","cn":""},{"en":"a neat cut made into something, especially during a medical operation","cn":"割口﹔〔尤指手术的〕切口﹐切痕"}]},"vocab":{"pos":"n","senses":[{"en":"An incision is a surgical cut. A doctor uses a scalpel to make an incision in a patient's skin."}]},"collocations":{"phrases":["ADJ. deep | small, tiny | abdominal, etc. | surgical","VERB + INCISION make The surgeon made a small incision in the patient's cornea."]},"media":{"uk":"media/ldoce/hwd/bre/5/incision0205.mp3","us":"media/ldoce/hwd/ame/d/incision.mp3"},"examples":[{"en":"Make a small incision below the ribs.","cn":"在肋骨下方切开一个小口。"}],"oxford":{"phon":"ɪnˈsɪʒn","pos":"noun","senses":[{"en":"a sharp cut made in something, particularly during a medical operation; the act of making a cut in something","cn":"割口；（尤指手术的）切口；切开","ex":{"en":"Make a small incision below the ribs.","cn":"在肋骨下方切开一个小口。"}}]}},"intermediary":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"调解人;中间人","en":"An intermediary is a person who passes messages or proposals between two people or groups.","ex":{"en":"She wanted him to act as an intermediary in the dispute with Moscow.","cn":"她想让他充当中间人来调解与莫斯科的争端。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a person or organization that tries to help two other people or groups to agree with each other","cn":"调解人﹐中间人"}]},"vocab":{"pos":"n","senses":[{"en":"An intermediary is someone who acts as a go-between or a mediator between two other people. Be careful when you're the intermediary between two friends who are fighting, because they might both end up mad at you!"}]},"collocations":{"phrases":["ADJ. financial","VERB + INTERMEDIARY act as","PREP. through an ~ They were approached indirectly through an intermediary. | via an ~ The product is then sold to the end-user via an inter"]},"media":{"uk":"media/ldoce/hwd/bre/4/intermediary0205.mp3","us":"media/ldoce/hwd/ame/2/intermediary.mp3"},"examples":[{"en":"All talks have so far been conducted through an intermediary.","cn":"到目前为止所有的谈判都是通过调停人进行的。"},{"en":"Financial institutions act as intermediaries between lenders and borrowers.","cn":"金融机构充当贷方和借方的中间人。"}],"oxford":{"phon":"ˌɪntəˈmiːdiəri","pos":"noun","senses":[{"en":"a person or an organization that helps other people or organizations to make an agreement by being a means of communication between them","cn":"中间人；调解人","ex":{"en":"Financial institutions act as intermediaries between lenders and borrowers.","cn":"金融机构充当贷方和借方的中间人。"}},{"en":"helping other people or organizations to make an agreement by being a means of communication between them","cn":"调解的","ex":{"en":"to play an intermediary role in the dispute","cn":"在纠纷中作居中调解"},"pos":"adjective"},{"en":"located or happening between two places, times or stages","cn":"中间的","ex":{"en":"an intermediary stage of development","cn":"发展的中间阶段"},"pos":"adjective"}]}},"instrumental":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有助益的;有帮助的;起作用的","en":"Someone or something that is instrumental in a process or event helps to make it happen.","ex":{"en":"In his first years as chairman he was instrumental in raising the company's wider profile","cn":"他任董事长的最初几年为提升公司的知名度起到了积极的推动作用。"}},{"pos":"ADJ 形容词","cn":"用乐器演奏(而非声乐)的;为器乐谱写的","en":"Instrumental music is performed by instruments and not by voices.","ex":{"en":"...a cassette recording of vocal and instrumental music.","cn":"有声乐也有器乐的磁带录音"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to be important in making important changes or achieving an important success","cn":""},{"en":"to be important in a process, event, or situation, especially by working very hard to achieve something","cn":""},{"en":"to be the most important person in changing or developing something because you have so much energy and determination","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Instrumental music involves just instruments — no singing. But you could also say that the conductor is instrumental to — or a critical part of — an orchestra's success."}]},"collocations":{"phrases":["VERBS be | become","ADV. highly | largely | partly","PREP. in They were highly instrumental in bringing the business to Newtown. 2 being only a means to an end","VERBS be","ADV. very | purely | merely | essentially"]},"media":{"uk":"media/ldoce/hwd/bre/3/instrumental_n0205.mp3","us":"media/ldoce/hwd/ame/f/instrumental.mp3"},"examples":[{"en":"He was instrumental in bringing about an end to the conflict.","cn":"他在终止冲突的过程中起了重要作用。"},{"en":"instrumental music","cn":"器乐曲"}],"oxford":{"phon":"ˌɪnstrəˈmentl","pos":"adjective","senses":[{"en":"important in making something happen","cn":"起重要作用","ex":{"en":"The Conservation Trust performs an instrumental role in the protection of rural environments.","cn":"保护信托基金在保护农村环境方面发挥着重要作用。"}},{"en":"made by or for musical instruments","cn":"用乐器演奏的；为乐器谱写的","ex":{"en":"instrumental music","cn":"器乐曲"}},{"en":"in the form that a noun, pronoun or adjective has when it refers to a thing that is used to do something","cn":"工具的","lab":"grammar","ex":{"en":"the instrumental case","cn":"工具格"}},{"en":"a piece of music (usually popular music) in which only musical instruments are used with no singing","cn":"器乐曲","pos":"noun"},{"en":"the form of a noun, pronoun or adjective when it refers to a thing that is used to do something","cn":"工具格；工具词","lab":"grammar","pos":"noun"}]}},"inconceivable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不能想象的;不可思议的","en":"If you describe something as inconceivable, you think it is very unlikely to happen or be true.","ex":{"en":"It was inconceivable to me that Toby could have been my attacker","cn":"真想不到托比竟会是袭击我的人。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is impossible cannot happen or be done","cn":""},{"en":"something that is impractical is too expensive, takes too much time, is too difficult etc and therefore it is not sensible to try to do it","cn":""},{"en":"used when saying that something is completely impossible, especially because it is not allowed","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If something is inconceivable , it doesn’t seem possible, it’s hard to imagine, or it can’t be true. It might seem inconceivable that a society would choose to pay bankers more than teachers, but it’s true."}]},"collocations":{"phrases":["VERBS appear, be, seem | become | find sth She found the idea quite inconceivable.","ADV. quite, totally, utterly, wholly | almost, practically, virtually","PREP. to The thought of leaving her family was inconceivable to her."]},"media":{"uk":"media/ldoce/hwd/bre/a/inconceivable0205.mp3","us":"media/ldoce/hwd/ame/5/inconceivable.mp3"},"examples":[{"en":"It is inconceivable that the minister was not aware of the problem.","cn":"令人难以置信的是那位大臣竟然没有意识到这个问题。"},{"en":"A few years ago a car fuelled by solar energy would have been inconceivable.","cn":"几年前太阳能汽车还是不可思议的事。"}],"oxford":{"phon":"ˌɪnkənˈsiːvəbl","pos":"adjective","senses":[{"en":"impossible to imagine or believe","cn":"难以想象的；无法相信的","ex":{"en":"It is inconceivable that the minister was not aware of the problem.","cn":"令人难以置信的是那位大臣竟然没有意识到这个问题。"}}]}},"insurrection":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"起义;造反;叛乱","en":"An insurrection is violent action that is taken by a large group of people against the rulers of their country, usually in order to remove them from office.","ex":{"en":"They were plotting to stage an armed insurrection.","cn":"他们正密谋发动武装起义。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an organized attempt to change the government or other authority, often by using violence","cn":""},{"en":"a successful attempt by the people of a country to change or destroy the government, often by using violence","cn":""},{"en":"an attempt, especially one that only continues for a short time, to change the government by using violence","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Insurrection is an uprising against a larger force that's in power. An insurrection can lead to revolution, but it is just as likely to be put down."}]},"collocations":{"phrases":["ADJ. armed Years of discontent turned into armed insurrection. | popular There was a popular insurrection against the police.","VERB + INSURRECTION plan, plot They were accused of plotting insurrection against the government. | lead | launch | crush, put down","PREP. ~ against insurrection against the monarchy"]},"media":{"uk":"media/ldoce/hwd/bre/2/insurrection0205.mp3","us":"media/ldoce/hwd/ame/f/insurrection.mp3"},"examples":[{"en":"an armed insurrection against the party in power","cn":"反对执政党的武装暴动"}],"oxford":{"phon":"ˌɪnsəˈrekʃn","pos":"noun","senses":[{"en":"a situation in which a large group of people try to take political control of their own country with violence","cn":"起义；叛乱；暴动","ex":{"en":"He led an armed insurrection against the regime.","cn":"他领导了一场反对政权的武装起义。"}}]}},"inkling":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"略知;模糊的概念","en":"If you have an inkling of something, you have a vague idea about it.","ex":{"en":"I had no inkling of his real purpose until much later","cn":"直到后来很久我才对他的真实目的略知一二。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a slight idea about something","cn":"略知﹔模糊的印象"}]},"vocab":{"pos":"n","senses":[{"en":"Is someone yapping on and on and you only have the vaguest idea of what they're talking about? Then you understood just an inkling — a glimmer, a fraction — of what they were saying."}]},"collocations":{"phrases":["ADJ. first The first inkling we had of Cliff's problem was when he didn't come to work. | faintest, slightest We didn't have the slightest i","VERB + INKLING have (no) | get | give (sb) She never gave us any inkling of what she was planning.","PREP. ~ of"]},"media":{"uk":"media/ldoce/hwd/bre/3/inkling0205.mp3","us":"media/ldoce/hwd/ame/f/inkling.mp3"},"examples":[{"en":"The first inkling I had that something was wrong was when I found the front door wide open.","cn":"我发现前门大开着时就隐约感觉到出了事。"},{"en":"He had no inkling of what was going on.","cn":"他对正在发生的事情一无所知。"}],"oxford":{"phon":"ˈɪŋklɪŋ","pos":"noun","senses":[{"en":"a slight knowledge of something that is happening or about to happen","cn":"（对正在或即将发生的事的）略知","ex":{"en":"He had no inkling of what was going on.","cn":"他对正在发生的事情一无所知。"}}]}},"insult":{"collins":{"senses":[{"pos":"VERB 动词","cn":"侮辱;辱骂","en":"If someone insults you, they say or do something that is rude or offensive.","ex":{"en":"I did not mean to insult you","cn":"我不是要故意侮辱你。"}},{"pos":"N-COUNT 可数名词","cn":"侮辱;凌辱;辱骂","en":"An insult is a rude remark, or something a person says or does which insults you.","ex":{"en":"Their behaviour was an insult to the people they represent","cn":"他们的行为是对他们代表的人民的一种侮辱。"}},{"pos":"PHRASE 短语","cn":"更为不公的是;更不可接受的是;更糟的是","en":"You say to add insult to injury when mentioning an action or fact that makes an unfair or unacceptable situation even worse.","ex":{"en":"The driver of the car that killed Smith got a £250 fine and five penalty points on his licence. To add insult to injury, he drove away from court in his own car.","cn":"撞死史密斯的汽车司机仅被罚款250英镑，驾照上扣了5分。更让人不可接受的是,他竟然开着自己的车从法院扬长而去。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be very rude and unpleasant to someone, either by saying rude things to them or by making them feel stupid or unimportant","cn":""},{"en":"to speak or behave towards someone in a way that offends them","cn":""},{"en":"to say a lot of rude, offensive, unpleasant things to someone, especially when you are angry with them","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"If you insult someone, you have offended that person — either intentionally or unintentionally — through your actions or words. You might insult your host if you refuse to try the dessert he made from pasta, nuts, and chocolate sauce."}]},"collocations":{"phrases":["ADJ. bad, terrible one of the worst insults you can throw at somebody | ultimate Whatever you do, don't call a &lsquo;railway enthusiast&rsq","VERB + INSULT hurl, offer (literary) , shout, throw They were hurling insults at the police. The king is unlikely to forgive the insult offe","INSULT + VERB fly Insults were flying back and forth.","PREP. ~ to It was an insult to his wife.","PHRASES add insult to injury Only 300 people came to the match and to add insult to injury (= to make things worse) , the floodlights went o"]},"media":{"uk":"media/ldoce/hwd/bre/0/insult_v0205.mp3","us":"media/ldoce/hwd/ame/2/insult1.mp3"},"examples":[{"en":"The questions were an insult to our intelligence (= too easy).","cn":"那些问题（简单得）有辱我们的智慧。"},{"en":"She felt insulted by the low offer.","cn":"那么低的出价使她觉得受到了侮辱。"}],"oxford":{"phon":"ˈɪnsʌlt","pos":"noun","senses":[{"en":"a remark or an action that is said or done in order to offend somebody","cn":"辱骂；侮辱；冒犯","ex":{"en":"The crowd were shouting insults at the police.","cn":"人群大声辱骂着警察。"}},{"en":"to say or do something that offends somebody","cn":"辱骂；侮辱；冒犯","ex":{"en":"I have never been so insulted in my life!","cn":"我一生中从未被如此侮辱过！"},"pos":"verb"}]}},"inconsistent":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)反复无常的,易变的","en":"If you describe someone as inconsistent, you are criticizing them for not behaving in the same way every time a similar situation occurs.","ex":{"en":"You are inconsistent and unpredictable.","cn":"你这人反复无常,真叫人难以捉摸。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不能始终如一的;时好时坏的","en":"Someone or something that is inconsistent does not stay the same, being sometimes good and sometimes bad.","ex":{"en":"We had a terrific start to the season, but recently we've been inconsistent","cn":"赛季之初我们有非常好的开局,但最近却时好时坏。"}},{"pos":"ADJ 形容词","cn":"不一致的;相排斥的","en":"If two statements are inconsistent, one cannot possibly be true if the other is true.","ex":{"en":"The evidence given in court was inconsistent with what he had previously told them.","cn":"法庭上的证词与他当初告诉他们的不一致。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"相抵触的;不相合的","en":"If something is inconsistent with a set of ideas or values, it does not fit in well with them or match them.","ex":{"en":"This legislation is inconsistent with what they call Free Trade","cn":"这项立法与他们所谓的自由贸易相抵触。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"feelings or conditions that are changeable change frequently so that it is difficult to know what they will be like in a short time","cn":""},{"en":"behaviour, processes, or services that are erratic change suddenly in an unexpected and surprising way, when it would be better if they remained the same","cn":""},{"en":"a volatile situation or character is likely to change suddenly and unexpectedly","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Inconsistent describes something that's varied or irregular. So if you're supposed to floss every day, but you only remember every now and then, your commitment to oral hygiene could be called inconsistent ."}]},"collocations":{"phrases":["VERBS appear, be, seem","ADV. highly, very | quite, totally, wholly | not necessarily | rather, somewhat | apparently | clearly, plainly | internally, logically Her ","PREP. in The company is inconsistent in the way it disciplines staff. | with His statement was inconsistent with other accounts of the event"]},"media":{"uk":"media/ldoce/hwd/bre/7/inconsistent0205.mp3","us":"media/ldoce/hwd/ame/4/inconsistent.mp3"},"examples":[{"en":"Children find it difficult if a parent is inconsistent.","cn":"如果做父母的不始终如一，孩子会觉得无所适从。"},{"en":"There is some inconsistency between the witnesses' evidence and their earlier statements.","cn":"证人的证词与他们先前的陈述有些出入。"}],"oxford":{"phon":"ˌɪnkənˈsɪstənt","pos":"adjective","senses":[{"en":"if two statements, etc. are inconsistent, or one is inconsistent with the other, they cannot both be true because they give the facts in a different way","cn":"不一致；相矛盾","g":"[not usually before noun]","ex":{"en":"The report is inconsistent with the financial statements.","cn":"这个报告与财务报表内容不一致。"}},{"en":"not matching a set of standards, ideas, etc.","cn":"不符合（某套标准、思想等）","ex":{"en":"Her behaviour was clearly inconsistent with her beliefs.","cn":"她的行为显然违背了她的信仰。"}},{"en":"tending to change too often; not staying the same","cn":"反复无常的；没有常性的","lab":"disapproving","ex":{"en":"inconsistent results","cn":"变幻无常的结果"}}]}},"inept":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无能的;笨拙的","en":"If you say that someone is inept, you are criticizing them because they do something with a complete lack of skill.","ex":{"en":"He was inept and lacked the intelligence to govern","cn":"他没有什么能力,缺乏管理才干。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not good at doing something","cn":"无能的﹔笨拙的"},{"en":"OPP capable , skilful : inept leadership","cn":"拙劣的领导 He was criticized for his inept handling of the problem. 他因处理这个问题不力而遭到批评。 politically/socially inept Blake was int"}]},"vocab":{"pos":"adj","senses":[{"en":"A clumsy, incompetent person — or an ineffective action — is inept . When you're inept , you don't know what you're doing or just can't get it done."}]},"collocations":{"phrases":["VERBS be, prove | become","ADV. very | quite | rather | politically, socially It would be politically inept to cut these training programmes now.","PREP. at He was rather inept at word games."]},"media":{"uk":"media/ldoce/hwd/bre/9/inept0205.mp3","us":"media/ldoce/hwd/ame/7/inept.mp3"},"examples":[{"en":"She was left feeling inept and inadequate.","cn":"她被弄得感到笨拙无能。"},{"en":"an inept remark","cn":"笨拙的发言"}],"oxford":{"phon":"ɪˈnept","pos":"adjective","senses":[{"en":"acting or done with no skill","cn":"缺乏技巧的；无能的；笨拙的","ex":{"en":"She was left feeling inept and inadequate.","cn":"她被弄得感到笨拙无能。"}}]}},"inflict":{"collins":{"senses":[{"pos":"VERB 动词","cn":"予以(打击);使遭受(损伤、苦痛等)","en":"To inflict harm or damage on someone or something means to make them suffer it.","ex":{"en":"Rebels say they have inflicted heavy casualties on government forces","cn":"反叛武装称他们使政府军遭受重创。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if you impose your ideas and beliefs on other people, you try to force them to have the same ideas and beliefs as you","cn":""},{"en":"to force someone to accept something that causes them harm or suffering","cn":""},{"en":"to get rid of a thing or piece of work that you do not want by giving it to someone else","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you force an undesirable or harmful event on someone, you inflict it on them. You might prefer that someone inflict some physical pain on you rather than inflict you with the boredom of another trip to the annual flower show."}]},"collocations":{"phrases":["ADV. deliberately When someone deliberately inflicts damage, it is a matter for the police. | maliciously, negligently (both law) He was cha","PREP. on/upon They inflicted a humiliating defeat on their rivals."]},"media":{"uk":"media/ldoce/hwd/bre/7/inflict0205.mp3","us":"media/ldoce/hwd/ame/0/inflict.mp3"},"examples":[{"en":"She inflicted her nephew on them for the weekend.","cn":"她把侄儿打发到他们那儿去度周末，真是添乱。"},{"en":"They inflicted a humiliating defeat on the home team.","cn":"他们使主队吃了一场很没面子的败仗。"}],"oxford":{"phon":"ɪnˈflɪkt","pos":"verb","senses":[{"en":"to make somebody/something suffer something unpleasant","cn":"使遭受（不好的事情）；施加（打击、痛苦等）","lab":"humorous","ex":{"en":"They inflicted a humiliating defeat on the home team.","cn":"他们使主队吃了一场很没面子的败仗。"}}]}},"indignation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"愤怒;愤慨;义愤","en":"Indignation is the feeling of shock and anger which you have when you think that something is unjust or unfair.","ex":{"en":"She was filled with indignation at the conditions under which miners were forced to work","cn":"矿工们被迫在如此恶劣的条件下工作,她感到异常愤怒。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strong emotion that you feel because someone has behaved badly or because a situation seems bad or unfair","cn":""},{"en":"slight anger or impatience","cn":""},{"en":"a feeling of being annoyed and impatient, especially because something keeps happening or someone keeps saying something","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Call your anger at an unjust situation indignation . If recess gets canceled for everyone because two students get into a fight, the rest of the student body will respond with indignation ."}]},"collocations":{"phrases":["ADJ. considerable, great, high His response was one of high indignation. | widespread | public | moral, righteous | mock","VERB + INDIGNATION be filled with, be full of, feel They were full of righteous indignation at the thought of being cheated. | express, show","INDIGNATION + VERB grow, rise Indignation grew as more nightclubs opened. She could feel her indignation rising.","PREP. in ~ She turned to him in indignation. | with ~ He refused it with some indignation. | ~ about/at/over The government expressed its in"]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41indignation.mp3","us":"media/ldoce/hwd/ame/9/indignation.mp3"},"examples":[{"en":"Some benefits apply only to men, much to the indignation of working women.","cn":"对职业女性大为不平的是有些福利只提供给男性。"},{"en":"Joe quivered with indignation that Paul should speak to him like that.","cn":"乔认为保罗竟然那样对他说话，气得直发抖。"}],"oxford":{"phon":"ˌɪndɪɡˈneɪʃn","pos":"noun","senses":[{"en":"a feeling of anger and surprise caused by something that you think is unfair or unreasonable","cn":"愤慨；愤怒；义愤","ex":{"en":"The rise in train fares has aroused public indignation.","cn":"火车票提价激起了公愤。"}}]}},"innocence":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"天真;单纯","en":"Innocence is the quality of having no experience or knowledge of the more complex or unpleasant aspects of life.","ex":{"en":"...the sweet innocence of youth","cn":"青春时代的可爱与单纯"}},{"pos":"N-UNCOUNT 不可数名词","cn":"清白;无罪","en":"If someone proves their innocence, they prove that they are not guilty of a crime.","ex":{"en":"He claims he has evidence which could prove his innocence.","cn":"他声称有证据证明自己是无辜的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to say publicly and officially in a court of law, that you are innocent of a crime","cn":""},{"en":"to say repeatedly that you are innocent, especially when other people think that you are guilty","cn":""},{"en":"the fact of being not guilty of a crime","cn":"清白﹐无罪"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Innocence means you’ve done nothing wrong. You’ve broken no laws, committed no sins, and are not guilty of any morally evil act. Well done."}]},"collocations":{"phrases":["ADJ. total","VERB + INNOCENCE declare, proclaim The prisoners passionately proclaimed their innocence in front of the jury. | claim She claimed total inn","PHRASES in all innocence I asked her the question in all innocence. I didn't know it was going to upset her. | the presumption of innocence ","ADJ. childlike, wide-eyed | lost | injured She replied to her father's accusations in tones of injured innocence. | apparent | mock","VERB + INNOCENCE lose He had lost the innocence of childhood. | retain | take advantage of She had taken advantage of his innocence.","PREP. in your ~ In his innocence he had allowed the salesman in to discuss vacuum cleaners. | with &hellip; ~ He grinned with apparent innoc","PHRASES an air of innocence There was a touching air of innocence about the boy. | a look of innocence, the picture of innocence &lsquo;You "]},"media":{"uk":"media/ldoce/hwd/bre/e/innocence0205.mp3","us":"media/ldoce/hwd/ame/7/laadinnocence.mp3"},"examples":[{"en":"I asked if she was married in all innocence (= without knowing it was likely to offend or upset her).","cn":"我问她结婚了没有，完全没有恶意。"},{"en":"Children lose their innocence as they grow older.","cn":"儿童随着年龄的增长而失去其天真。"}],"oxford":{"phon":"ˈɪnəsns","pos":"noun","senses":[{"en":"the fact of not being guilty of a crime, etc.","cn":"清白；无辜；无罪","ex":{"en":"She protested her innocence (= said repeatedly that she was innocent).","cn":"她一再申明自己是无辜的。"}},{"en":"lack of knowledge and experience of the world, especially of evil or unpleasant things","cn":"天真；纯真；单纯","ex":{"en":"Children lose their innocence as they grow older.","cn":"儿童随着年龄的增长而失去其天真。"}}]}},"insanity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"精神错乱;精神失常;疯狂","en":"Insanity is the state of being insane.","ex":{"en":"The film is a powerful study of a woman's descent into insanity","cn":"那部电影深入剖析了一个女人堕入疯狂的过程。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"极端的愚蠢(行为);荒唐(事)","en":"If you describe a decision or an action as insanity, you think it is very foolish.","ex":{"en":"It was a period of collective insanity, of legalized murder and mayhem.","cn":"那是个集体丧失理智、谋杀与暴力合法化的时期。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an illness of the mind","cn":""},{"en":"serious and permanent mental illness - used especially in literature, but not used in official or medical contexts","cn":""},{"en":"serious and permanent mental illness - use this especially in legal contexts or in descriptions of people who lived in the past","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Insanity is an ongoing state of extreme mental illness, which may cause abnormal or antisocial behaviors. If you bark at cats and meow at dogs, you might suffer from insanity ."}]},"collocations":{"phrases":["ADJ. total","VERB + INSANITY plead At the murder trial, he pleaded insanity."]},"media":{"uk":"media/ldoce/hwd/bre/7/insanity0205.mp3","us":"media/ldoce/hwd/ame/b/insanity.mp3"},"examples":[{"en":"It would be sheer insanity to attempt the trip in such bad weather.","cn":"天气这么糟糕还要去旅行，太荒唐了。"},{"en":"He was found not guilty, by reason of insanity.","cn":"他以精神失常为理由获判无罪。"}],"oxford":{"phon":"ɪnˈsænəti","pos":"noun","senses":[{"en":"the state of being insane","cn":"精神失常；精神错乱；精神病","g":"[uncountable]","lab":"formal, law or old-fashioned, often offensive，，，，","ex":{"en":"He was found not guilty, by reason of insanity.","cn":"他因精神失常而获判无罪。"}},{"en":"actions that are very stupid and possibly dangerous","cn":"十分愚蠢的行为；荒唐的行为","g":"[uncountable]","ex":{"en":"It would be sheer insanity to attempt the trip in such bad weather.","cn":"天气这么糟糕还要去旅行，太荒唐了。"}}]}},"invoice":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"发货单;发票","en":"An invoice is a document that lists goods that have been supplied or services that have been done, and says how much money you owe for them.","ex":{"en":"We will then send you an invoice for the total course fees","cn":"然后我们会把全部课程费用的发票寄给你。"}},{"pos":"VERB 动词","cn":"开发票给…","en":"If you invoice someone, you send them a bill for goods or services you have provided them with.","ex":{"en":"The agency invoices the client.","cn":"代理处为客户开具发票。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of paper that tells you how much you must pay","cn":""},{"en":"a bill that tells you how much you must pay in a restaurant","cn":""},{"en":"a document that lists the goods that a company has sent, or the services they have provided, and tells you how much you must pay. It is often sent from one company to another company","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"An invoice is an itemized statement of the money that's owed for goods or services. If you buy books online, they will usually arrive with an invoice telling what books you bought and how much they cost."}]},"collocations":{"phrases":["ADJ. original | final Please pay the final invoice within two weeks. | tax, VAT The seller has to issue a tax invoice.","VERB + INVOICE issue, raise, send | get, receive | pay","INVOICE + NOUN price, value The shipping costs can be as high as 50% of the invoice value of the goods."]},"media":{"uk":"media/ldoce/hwd/bre/4/invoice_n0205.mp3","us":"media/ldoce/hwd/ame/c/invoice1.mp3"},"examples":[{"en":"You will be invoiced for these items at the end of the month.","cn":"你将于月底收到这些项目的费用清单。"},{"en":"Invoice the goods to my account.","cn":"请把货品的发票开到我的账上。"}],"oxford":{"phon":"ˈɪnvɔɪs","pos":"noun","senses":[{"en":"a list of goods that have been sold, work that has been done, etc., showing what you must pay","cn":"发票；（发货或服务）费用清单","lab":"North American English","ex":{"en":"to send/issue/settle an invoice for the goods","cn":"送出／开具／结清商品费用清单"}},{"en":"to write or send somebody a bill for work you have done or goods you have provided","cn":"开发票（或清单）；发出发票（或清单）","ex":{"en":"You will be invoiced for these items at the end of the month.","cn":"你将于月底收到这些项目的费用清单。"},"pos":"verb"}]}},"indecent":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"下流的;有伤风化的;猥亵的","en":"If you describe something as indecent, you mean that it is shocking and offensive, usually because it relates to sex or nakedness.","ex":{"en":"He accused Mrs Moore of making an indecent suggestion.","cn":"他指责摩尔夫人做下流的性暗示。"}},{"pos":"ADJ 形容词","cn":"(速度或数量)不合常规的，离谱的","en":"If you describe the speed or amount of something as indecent, you are indicating, often in a humorous way, that it is much quicker or larger than is usual or desirable.","ex":{"en":"The opposition says the legislation was drafted with indecent haste.","cn":"反对人士认为该法律的起草太过草率。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"obscene words or pictures are about sex and are very offensive","cn":""},{"en":"dirty books, jokes, films etc are about sex - use this especially to show that you think these are unpleasant","cn":""},{"en":"clothes that are indecent show parts of the body that are usually covered; actions or movements that are indecent are sexual, but in a way many people think is not pleasant or acceptable","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Things that are indecent are obscene, indelicate, or offensive in some way. If you run around the mall naked, you’ll get in trouble for indecent exposure!"}]},"collocations":{"phrases":["VERBS be | class sth as, consider sth, regard sth as, think sth photographs that are classed as indecent","ADV. grossly, positively That skirt of hers is positively indecent. 2 not morally right","VERBS be, seem","ADV. positively The rush to get hold of their father's money seemed positively indecent. | almost She started a new relationship with almost"]},"media":{"uk":"media/ldoce/hwd/bre/5/indecent0205.mp3","us":"media/ldoce/hwd/ame/8/indecent.mp3"},"examples":[{"en":"They left the funeral with almost indecent haste (= too quickly).","cn":"他们离开葬礼时仓促得近乎失礼。"},{"en":"That skirt of hers is positively indecent.","cn":"她的那条裙子太暴露了。"}],"oxford":{"phon":"ɪnˈdiːsnt","pos":"adjective","senses":[{"en":"thought to be morally offensive, especially because it involves sex or wearing no clothes","cn":"下流的；有伤风化的；猥亵的","ex":{"en":"indecent conduct/photos","cn":"下流的行为；淫秽的照片"}},{"en":"showing parts of the body that are usually covered","cn":"过分暴露的","ex":{"en":"Those shorts are positively indecent.","cn":"那些短裤确实不雅。"}},{"en":"not appropriate or suitable","cn":"不适当的","ex":{"en":"They left the funeral with almost indecent haste (= too quickly).","cn":"他们离开葬礼时仓促得近乎失礼。"}}]}},"instruct":{"collins":{"senses":[{"pos":"VERB 动词","cn":"指示;吩咐;命令","en":"If you instruct someone to do something, you formally tell them to do it.","ex":{"en":"The family has instructed solicitors to sue Thomson for compensation","cn":"那家人已经指示律师起诉汤姆森,要求赔偿。"}},{"pos":"VERB 动词","cn":"教授;讲授;指导","en":"Someone who instructs people in a subject or skill teaches it to them.","ex":{"en":"He instructed family members in nursing techniques.","cn":"他教给家人护理技巧。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to tell someone that they must do something, using your official power or authority","cn":""},{"en":"to say to someone that they must do something","cn":""},{"en":"to tell someone exactly what they must do","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"This website is designed to instruct visitors about the meaning of words and their correct usage. To instruct is to give instructions, to teach."}]},"collocations":{"phrases":["ADV. carefully | explicitly, specifically You were explicitly instructed to wait here.","PHRASES as instructed I took the pills as instructed."]},"media":{"uk":"media/ldoce/hwd/bre/6/instruct0205.mp3","us":"media/ldoce/hwd/ame/2/instruct.mp3"},"examples":[{"en":"‘Put it there,’ she instructed (them). “","cn":"把它放在那儿。”她吩咐（他们）道。"},{"en":"You will be instructed where to go as soon as the plane is ready.","cn":"飞机一准备好就会通知你去何处。"}],"oxford":{"phon":"ɪnˈstrʌkt","pos":"verb","senses":[{"en":"to tell somebody to do something, especially in a formal or official way","cn":"指示；命令；吩咐","lab":"formal","ex":{"en":"The letter instructed him to report to headquarters immediately.","cn":"那封信指示他立即向总部汇报。"}},{"en":"to teach somebody something, especially a practical skill","cn":"教授，传授（技能等）","lab":"formal","ex":{"en":"All our staff have been instructed in sign language.","cn":"我们的员工都接受过手语训练。"}},{"en":"to give somebody information about something","cn":"告知；通知","g":"[usually passive]","lab":"formal","ex":{"en":"We have been instructed that a decision will not be made before the end of the week.","cn":"我们已获悉周末前不会作出决定。"}},{"en":"to employ somebody to represent you in a legal situation, especially as a lawyer","cn":"委托（律师）；托办","lab":"law"}]}},"indefensible":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"站不住脚的;无可辩解的","en":"If you say that a statement, action, or idea is indefensible, you mean that it cannot be justified or supported because it is completely wrong or unacceptable.","ex":{"en":"His action was indefensible","cn":"他的行为是不可原谅的。"}},{"pos":"ADJ 形容词","cn":"无法防御的;无法保卫的","en":"Places or buildings that are indefensible cannot be defended if they are attacked.","ex":{"en":"The checkpoint was abandoned as militarily indefensible.","cn":"检查站因为军事上无法防御而被舍弃。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"too bad to be excused or defended","cn":"不可原谅的﹔无法辩解的"},{"en":"impossible or very difficult to defend from military attack 〔","cn":"对武装攻击〕无法防御的﹐无法保卫的"}]},"collocations":{"phrases":["VERBS be | find sth I find such behaviour indefensible.","ADV. totally | morally, politically It would be morally indefensible for her to desert her father now."]},"media":{"uk":"media/ldoce/hwd/bre/a/indefensible0205.mp3","us":"media/ldoce/hwd/ame/9/indefensible.mp3"},"examples":[{"en":"The Prime Minister was accused of defending the indefensible.","cn":"首相被指责庇护不可原谅的行为。"},{"en":"indefensible behaviour","cn":"不可原谅的行为"}],"oxford":{"phon":"ˌɪndɪˈfensəbl","pos":"adjective","senses":[{"en":"that cannot be defended or excused because it is morally unacceptable","cn":"（道德上）无可辩解的，不能原谅的","ex":{"en":"indefensible behaviour","cn":"不可原谅的行为"}},{"en":"impossible to defend from military attack","cn":"无法防守的"}]}},"inconvenience":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"不便;麻烦;困难","en":"If someone or something causes inconvenience, they cause problems or difficulties.","ex":{"en":"We apologize for any inconvenience caused during the repairs","cn":"我们为维修期间造成的任何不便道歉。"}},{"pos":"VERB 动词","cn":"给…带来不便;麻烦;打扰","en":"If someone inconveniences you, they cause problems or difficulties for you.","ex":{"en":"He promised to be quick so as not to inconvenience them any further.","cn":"他许诺尽快完成，以免给他们带来更多不便。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to cause problems for someone by making them do something that is inconvenient for them","cn":""},{"en":"to make someone have to do something that is inconvenient for them by asking them to do something for you","cn":""},{"en":"to cause someone problems or more work than usual","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"An inconvenience is an annoying occurrence that makes you go out of your way, like the inconvenience of a detour that takes you off your usual route, or the inconvenience of the door bell ringing just as you are about to take a dish out of the oven."}]},"collocations":{"phrases":["ADJ. considerable, great, serious | minor | public The rail strike is likely to cause considerable public inconvenience. | administrative","VERB + INCONVENIENCE have, suffer | avoid I chose a different route to avoid the inconvenience of going through the town centre. | cause (sb","INCONVENIENCE + VERB arise from sth inconvenience arising from errors in the timetable","PREP. ~ to Every effort will be made to minimize inconvenience to customers while work is in progress.","PHRASES with a minimum of inconvenience The club management will try to ensure that the building work is carried out with the minimum of inc"]},"media":{"uk":"media/ldoce/hwd/bre/a/inconvenience_0205.mp3","us":"media/ldoce/hwd/ame/1/inconvenience1.mp3"},"examples":[{"en":"We apologize for the delay and regret any inconvenience it may have caused.","cn":"我们对此次延误以及因此有可能造成的所有不便表示道歉。"},{"en":"I have already been put to considerable inconvenience.","cn":"我已经遇到了相当的麻烦了。"}],"oxford":{"phon":"ˌɪnkənˈviːniəns","pos":"noun","senses":[{"en":"trouble or problems, especially in connection with what you need or would like yourself","cn":"不便；麻烦","g":"[uncountable]","ex":{"en":"We apologize for the delay and regret any inconvenience it may have caused.","cn":"我们谨为此次延误以及可能因此造成的不便致歉。"}},{"en":"a person or thing that causes problems or difficulties","cn":"带来不便者；麻烦的人（或事物）","g":"[countable]","ex":{"en":"I can put up with minor inconveniences.","cn":"我能忍受些小的不便。"}},{"en":"to cause trouble or difficulty for somebody","cn":"给（某人）造成不便（或带来麻烦）","ex":{"en":"I hope that we haven't inconvenienced you.","cn":"我希望我们没有给你添麻烦。"},"pos":"verb"}]}},"involvement":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"参与;介入;卷入","en":"Your involvement in something is the fact that you are taking part in it.","ex":{"en":"You have no proof of my involvement in anything","cn":"你没有证据证明我参与了任何活动。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(投入的)感情;(倾注的)热情","en":"Involvement is the enthusiasm that you feel when you care deeply about something.","ex":{"en":"Ben has always felt a deep involvement with animals.","cn":"本对动物总是有着深厚的感情。"}},{"pos":"N-VAR 可变名词","cn":"暧昧关系;恋爱关系","en":"An involvement is a close relationship between two people, especially if they are not married to each other.","ex":{"en":"They were very good friends but there was no romantic involvement","cn":"他们是非常要好的朋友，却没有任何暧昧关系。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the act of taking part in an activity or event, or the way in which you take part in it","cn":"参与﹔卷入﹔牵连"},{"en":"something that you take part in or spend time doing","cn":"参与的事物﹔投入时间的事物"},{"en":"the feeling of excitement and satisfaction that you get from an activity","cn":"满足﹔兴奋"}]},"vocab":{"pos":"1 n 2 n 3 n 4 n","senses":[{"en":"Involvement is the act of participating in something. Even if you do nothing but drive the getaway car, you will be held to account for your involvement in a crime."}]},"collocations":{"phrases":["ADJ. active, direct | close, deep, intense | full | day-to-day When she was promoted, she missed the day-to-day involvement with customers. ","VERB + INVOLVEMENT accuse sb of | suspect sb of | admit, deny Winters denies any involvement in the robbery.","PREP. ~ by The success of the venture may lead to involvement by other foreign companies. | ~ from The project needs full involvement from a"]},"media":{"uk":"media/ldoce/hwd/bre/b/involvement0205.mp3","us":"media/ldoce/hwd/ame/7/laadinvolvement.mp3"},"examples":[{"en":"He spoke openly about his involvement with the singer.","cn":"他公开讲述了他和那个歌手的私情。"},{"en":"her growing involvement with contemporary music","cn":"她对现代音乐的日益投入"}],"oxford":{"phon":"ɪnˈvɒlvmənt","pos":"noun","senses":[{"en":"the act of taking part in something or dealing with somebody","cn":"参与；加入；插手","g":"[uncountable]","ex":{"en":"US involvement in European wars","cn":"美国对欧洲战争的干预"}},{"en":"the act of giving a lot of time and attention to something you care about","cn":"耗费时间；投入；沉迷","g":"[uncountable, countable]","ex":{"en":"The new album came out of her growing involvement with contemporary music.","cn":"新专辑是她对当代音乐日益投入的成果。"}},{"en":"a close relationship with somebody, especially a romantic or sexual relationship with somebody that you are not married to","cn":"恋爱；性爱","g":"[countable, uncountable]","ex":{"en":"He spoke openly about his involvement with the singer.","cn":"他公开讲述了他和那个歌手的私情。"}}]}},"incidence":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(疾病等的)发生，发生率","en":"The incidence of something bad, such as a disease, is the frequency with which it occurs, or the occasions when it occurs.","ex":{"en":"The incidence of breast cancer increases with age.","cn":"乳腺癌的发病率随年龄增长而递增。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"use this when you are talking generally about how often something bad happens","cn":""},{"en":"use this to talk about the exact amount of a particular problem at one time, even though this amount may go up or down at other times","cn":""},{"en":"use this to talk about the number of times something happens within a certain period of time, especially when talking about crime, social problems etc","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Incidence means the frequency with which something bad occurs. You’ll hear of “ incidences of cancer” or “ incidences of war.\" You hope the incidence is decreasing, not increasing."}]},"collocations":{"phrases":["ADJ. great, high There is a greater incidence of cancer in the families of radiation workers. | low | increased/increasing, rising | actual ","VERB + INCIDENCE have, show The country had the lowest incidence of Aids cases proportional to its population. The medical histories of our ","INCIDENCE + VERB increase | decrease, fall","INCIDENCE + NOUN rate an incidence rate of 4 or 5 per 10,000 of the population","PREP. ~ among The report analyses the incidence of cancer among people aged 0?24. | ~ in The study noted an increased incidence of heart dis","PHRASES a decrease/an increase/a variation in the incidence of sth"]},"media":{"uk":"media/ldoce/hwd/bre/f/incidence0205.mp3","us":"media/ldoce/hwd/ame/6/incidence.mp3"},"examples":[{"en":"an area with a high incidence of crime","cn":"犯罪率高的地区"},{"en":"the angle of incidence","cn":"入射角"}],"oxford":{"phon":"ˈɪnsɪdəns","pos":"noun","senses":[{"en":"the extent to which something happens or has an effect","cn":"发生范围；影响程度；发生率","g":"[countable, usually singular]","lab":"formal","ex":{"en":"an area with a high incidence of crime","cn":"犯罪率高的地区"}},{"en":"the way in which light meets a surface","cn":"入射（角）","g":"[uncountable]","lab":"physics","ex":{"en":"the angle of incidence","cn":"入射角"}}]}},"indictment":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"控诉;谴责","en":"If you say that one thing is an indictment of another thing, you mean that it shows how bad the other thing is.","ex":{"en":"It's a sad indictment of society that policemen are regarded as easy targets by thugs.","cn":"警察很容易就成了暴徒下手袭击的对象,这是一个社会的悲哀。"}},{"pos":"N-VAR 可变名词","cn":"控告;告发;起诉","en":"An indictment is a formal accusation that someone has committed a crime.","ex":{"en":"Prosecutors may soon seek an indictment on racketeering and fraud charges","cn":"检举官可能不久就会以敲诈勒索与欺诈罪名提起诉讼。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a statement saying that you believe someone is guilty of a crime or of doing something bad","cn":""},{"en":"a public statement accusing someone of doing something although it has not been proved","cn":""},{"en":"an official statement by the police accusing someone of a crime and saying that they must go to court, or a statement saying that someone has done something bad, made by anyone","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An indictment , or a legal document charging you with a crime, is something you don't want to be the recipient of, so try not to rob any banks or start any money laundering schemes, and you'll probably be okay."}]},"collocations":{"phrases":["ADJ. powerful | damning, scathing, terrible Her speech was a scathing indictment of the government's record on crime. | sad 2 accusing sb of","ADJ. criminal | fresh","VERB + INDICTMENT issue, bring A New York jury brought criminal indictments against the founder of the organization. | be charged on, be con","INDICTMENT + VERB charge (sb/sth with sth) an indictment charging theft","PREP. in a/the ~ Two men were named in the indictment. | on ~ a trial on indictment | ~ against They issued an indictment against them. | ~ "]},"media":{"uk":"media/ldoce/hwd/bre/4/indictment0205.mp3","us":"media/ldoce/hwd/ame/0/indictment.mp3"},"examples":[{"en":"The poverty in our cities is a damning indictment of modern society.","cn":"我们的城市中的贫民苦况是现代社会的一大败象。"},{"en":"This led to his indictment on allegations of conspiracy.","cn":"这件事最终使他被控犯有共谋罪。"}],"oxford":{"phon":"ɪnˈdaɪtmənt","pos":"noun","senses":[{"en":"a sign that a system, society, etc. is very bad or very wrong","cn":"（制度、社会等的）衰败迹象，腐败迹象","g":"[countable, usually singular]","ex":{"en":"The poverty in our cities is a damning indictment of modern society.","cn":"我们的城市中贫民的苦况是现代社会的一大败象。"}},{"en":"an official statement accusing somebody of a crime","cn":"刑事起诉书；公诉书","g":"[countable]","lab":"especially North American English","ex":{"en":"She was convicted on an indictment for conspiracy.","cn":"她被控合谋，罪名成立。"}},{"en":"the act of officially accusing somebody of a crime","cn":"控告；起诉","g":"[uncountable]","lab":"especially North American English","ex":{"en":"This led to his indictment on allegations of conspiracy.","cn":"这件事最终使他被控犯有共谋罪。"}}]}},"infirm":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(常指因年迈而)体弱的,虚弱的","en":"A person who is infirm is weak or ill, and usually old.","ex":{"en":"...her aging, infirm husband.","cn":"她年迈体弱的丈夫"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not physically strong, sometimes because you are ill","cn":""},{"en":"weak and thin, especially because you are old","cn":""},{"en":"feeling weak in your legs and only able to walk slowly and unsteadily","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"To be infirm is to be physically weak. If your great grandmother can't get around without a walker or a wheelchair, you might describe her as infirm ."}]},"collocations":{"phrases":["VERBS be | become","ADV. mentally, physically"]},"media":{"uk":"media/ldoce/hwd/bre/1/infirm0205.mp3","us":"media/ldoce/hwd/ame/0/infirm.mp3"},"examples":[{"en":"care for the elderly and infirm","cn":"对年老体弱者的照顾"},{"en":"Her grandmother is elderly and infirm.","cn":"她的祖母年迈体弱。"}],"oxford":{"phon":"ɪnˈfɜːm","pos":"adjective","senses":[{"en":"ill and weak, especially over a long period or as a result of being old","cn":"（长期）病弱的；年老体弱的","ex":{"en":"to grow old and infirm","cn":"年老体弱"}},{"en":"people who are weak and ill for a long period","cn":"病弱的人；体弱的人","g":"[plural]","ex":{"en":"care for the elderly and infirm","cn":"对年老体弱者的照顾"}}]}},"interminable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无休止的;没完没了的;冗长不堪的","en":"If you describe something as interminable, you are emphasizing that it continues for a very long time and indicating that you wish it was shorter or would stop.","ex":{"en":"...an interminable meeting.","cn":"冗长乏味的会议"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"continuing for too long – used about speeches, answers, explanations etc","cn":""},{"en":"very long and boring","cn":"冗长乏味的﹐没完没了的"},{"en":"used about a process that continues for much too long","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Use interminable to describe something that has or seems to have no end. Your math class. Your sister's violin recital. A babysitting job where five kids are going through your purse and the parents didn't leave a number."}]},"collocations":{"phrases":["VERBS be, seem The journey seemed interminable.","ADV. seemingly For several seemingly interminable seconds no one spoke."]},"media":{"uk":"media/ldoce/hwd/bre/6/interminable0205.mp3","us":"media/ldoce/hwd/ame/1/interminable.mp3"},"examples":[{"en":"The drive seemed interminable.","cn":"这次开车好像没有尽头。"},{"en":"The meeting dragged on interminably.","cn":"会议没完没了地拖延着。"}],"oxford":{"phon":"ɪnˈtɜːmɪnəbl","pos":"adjective","senses":[{"en":"lasting a very long time and therefore boring or annoying","cn":"冗长的；没完没了的","ex":{"en":"an interminable speech/wait/discussion","cn":"无休止的讲话／等待／讨论"}}]}},"incite":{"collins":{"senses":[{"pos":"VERB 动词","cn":"鼓动;煽动","en":"If someone incites people to behave in a violent or illegal way, they encourage people to behave in that way, usually by making them excited or angry.","ex":{"en":"He incited his fellow citizens to take their revenge","cn":"他鼓动他的同胞们报仇雪恨。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to deliberately encourage people to cause trouble, fight, argue etc","cn":""},{"en":"if something provokes an angry situation or a reaction, they cause it, usually deliberately","cn":""},{"en":"to deliberately try to cause arguments, fighting etc between people","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To incite is to cause to act or occur. Violent words can incite violent actions which, in turn, might incite public outcry against violence."}]},"collocations":{"phrases":["ADV. deliberately","PREP. to deliberately inciting the crowd to violence"]},"media":{"uk":"media/ldoce/hwd/bre/6/incite0205.mp3","us":"media/ldoce/hwd/ame/5/incite.mp3"},"examples":[{"en":"They were accused of inciting the crowd to violence.","cn":"他们被控煽动群众暴乱。"},{"en":"He incited the workforce to come out on strike.","cn":"他煽动工人罢工。"}],"oxford":{"phon":"ɪnˈsaɪt","pos":"verb","senses":[{"en":"to encourage somebody to do something violent, illegal or unpleasant, especially by making them angry or excited","cn":"煽动；鼓动","ex":{"en":"to incite crime/racial hatred/violence","cn":"教唆犯罪；煽动种族仇恨／暴力"}}]}},"insensitive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不敏感的;感觉迟钝的;麻木不仁的","en":"If you describe someone as insensitive, you are criticizing them for being unaware of or unsympathetic to other people's feelings.","ex":{"en":"I feel my husband is very insensitive about my problem.","cn":"我感觉丈夫对我的问题麻木不仁。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"漠视的;不在乎的;毫不在意的","en":"Someone who is insensitive to a situation or to a need does not think or care about it.","ex":{"en":"Women's and Latino organizations that say he is insensitive to civil rights.","cn":"指责他漠视人权的女性组织与拉美裔组织"}},{"pos":"ADJ 形容词","cn":"(对体感)没有感觉的,麻木的","en":"Someone who is insensitive to a physical sensation is unable to feel it.","ex":{"en":"He had become insensitive to cold.","cn":"他对寒冷已经没有感觉了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not thinking about the effects of your actions on other people","cn":""},{"en":"someone who is tactless carelessly says or does things that are likely to upset someone, without realizing what they are doing","cn":""},{"en":"behaving in a way that is likely to upset someone, or not seeming to care about someone’s feelings. Insensitive is rather a formal word","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When you're insensitive , you're not feeling something. You can be insensitive to the weather or other people's problems."}]},"collocations":{"phrases":["VERBS appear, be, seem | become, grow | make sb | think sb I don't want to be thought insensitive, but I do think we should go ahead despite","ADV. extremely, highly, incredibly, remarkably, very | totally | a bit, rather, somewhat","PREP. to Years of abuse at boarding school had made him insensitive to others' suffering. 2 not able to feel/be influenced by sth","VERBS be | remain","ADV. completely, totally | almost | largely | fairly, relatively","PREP. to The machine is relatively insensitive to changes in the atmosphere."]},"media":{"uk":"media/ldoce/hwd/bre/8/insensitive0205.mp3","us":"media/ldoce/hwd/ame/1/insensitive.mp3"},"examples":[{"en":"The government seems totally insensitive to the mood of the country.","cn":"政府似乎对全国民众的心情完全懵然不知。"},{"en":"He seems completely insensitive to criticism.","cn":"他似乎对批评麻木不仁。"}],"oxford":{"phon":"ɪnˈsensətɪv","pos":"adjective","senses":[{"en":"not realizing or caring how other people feel, and therefore likely to hurt or offend them","cn":"（对他人的感受）未意识到的，漠不关心的","ex":{"en":"an insensitive remark","cn":"冷漠的言论"}},{"en":"not aware of changing situations, and therefore of the need to react to them","cn":"（对变化）懵然不知的，麻木不仁的","ex":{"en":"The government seems totally insensitive to the mood of the country.","cn":"政府似乎对全国民众的心情完全懵然不知。"}},{"en":"not able to feel or react to something","cn":"（对某事物）无感觉，无反应","ex":{"en":"insensitive to pain/cold","cn":"感觉不到疼痛／寒冷"}}]}},"indigenous":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"当地的;本土的;土生土长的","en":"Indigenous people or things belong to the country in which they are found, rather than coming there or being brought there from another country.","ex":{"en":"...the country's indigenous population.","cn":"该国的本土人口"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"indigenous people or things have always been in the place where they are, rather than being brought there from somewhere else","cn":"土生土长的﹐本地的"}]},"vocab":{"pos":"adj","senses":[{"en":"Use indigenous to describe a plant, animal or person that is native or original to an area. Though Switzerland is known for its chocolates, chocolate, which comes from the cocoa plant, is indigenous to South America."}]},"collocations":{"phrases":["VERBS be","ADV. truly examples of truly indigenous music","PREP. to The tree is indigenous to China."]},"media":{"uk":"media/ldoce/hwd/bre/4/indigenous0205.mp3","us":"media/ldoce/hwd/ame/e/indigenous.mp3"},"examples":[{"en":"the indigenous peoples/languages of the area","cn":"该地区的本地人/语言"},{"en":"The kangaroo is indigenous to Australia.","cn":"袋鼠原产于澳大利亚。"}],"oxford":{"phon":"ɪnˈdɪdʒənəs","pos":"adjective","senses":[{"en":"coming from a particular place and having lived there for a long time before other people came there; relating to, belonging to or developed by these people","cn":"本地的；当地的；土生土长的","ex":{"en":"the indigenous peoples/languages of an area","cn":"一个地区的土著人民/语言"}},{"en":"having originally developed in a particular place, rather than having been brought there from somewhere else","cn":"最初是在某个特定地方发展起来的，而不是从其他地方带到那里的","ex":{"en":"The kangaroo is indigenous to Australia.","cn":"袋鼠原产于澳大利亚。"}}]}},"indigestion":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"消化不良症","en":"If you have indigestion, you have pains in your stomach and chest that are caused by difficulties in digesting food."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"pain in your stomach or near your stomach","cn":""},{"en":"pain or uncomfortable feelings that you get when your stomach cannot break down food that you have eaten","cn":""},{"en":"a stomach illness caused by eating food that contains harmful bacteria, so that you vomit","cn":""}]},"collocations":{"phrases":["ADJ. serious, severe | acute, chronic | slight","VERB + INDIGESTION get, have, suffer from | give sb Rich food always gives me indigestion.","INDIGESTION + NOUN tablet •"]},"media":{"uk":"media/ldoce/hwd/bre/e/indigestion0205.mp3","us":"media/ldoce/hwd/ame/f/indigestion.mp3"},"oxford":{"phon":"ˌɪndɪˈdʒestʃən","pos":"noun","senses":[{"en":"pain caused by difficulty in digesting food","cn":"消化不良（症）","ex":{"en":"Rich food always gives me indigestion.","cn":"油腻的食物总会让我消化不良。"}}]}},"incomprehensible":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不能理解的;晦涩难懂的;费解的","en":"Something that is incomprehensible is impossible to understand.","ex":{"en":"Her speech was almost incomprehensible.","cn":"她的演讲几乎无人能懂。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a puzzling situation makes you feel confused, because you have tried to understand it or explain it, but you cannot","cn":""},{"en":"extremely difficult or impossible to understand, and therefore making you feel extremely confused","cn":""},{"en":"impossible to understand","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If your poetry is incomprehensible, it's difficult to understand, and it might be impossible to explain. Could be you're a genius! Could be you're just not very good at poetry."}]},"collocations":{"phrases":["VERBS be, seem | remain | find sth She found his accent virtually incomprehensible.","ADV. completely, quite, totally, utterly | almost, nearly, virtually | largely | pretty","PREP. to Latin verse remained completely incomprehensible to me."]},"media":{"uk":"media/ldoce/hwd/bre/a/incomprehensib0205.mp3","us":"media/ldoce/hwd/ame/7/incomprehensible.mp3"},"examples":[{"en":"He found his son's actions totally incomprehensible.","cn":"他感觉他儿子的行为完全理解不了。"},{"en":"Some application forms can be incomprehensible to ordinary people.","cn":"有些申请表格一般人可能看不懂。"}],"oxford":{"phon":"ɪnˌkɒmprɪˈhensəbl","pos":"adjective","senses":[{"en":"impossible to understand","cn":"无法理解的；难懂的","ex":{"en":"Some application forms can be incomprehensible to ordinary people.","cn":"有些申请表格一般人可能看不懂。"}}]}},"inconvenient":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不方便的;打扰的;令人为难的","en":"Something that is inconvenient causes problems or difficulties for someone.","ex":{"en":"Can you come at 10.30? I know it's inconvenient for you, but I must see you","cn":"你能 10 点半来吗？我知道你不方便,但是我必须见你。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not having the right qualities for a particular person, purpose, or situation","cn":""},{"en":"not suitable for a particular situation or purpose – used especially about someone’s behaviour or language","cn":""},{"en":"not the right thing or person for a particular job or purpose","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Inconvenient things are difficult or annoying to do. If someone asks you to help move a couch on a Saturday when you have tickets to a game, that's an inconvenient request."}]},"collocations":{"phrases":["VERBS be, prove | become | find sth","ADV. extremely, highly, most, terribly, very She called at a most inconvenient time. | a bit, rather, somewhat | politically Further environ","PREP. for Would this afternoon be inconvenient for you? | to This is a time of the evening that is inconvenient to many viewers."]},"media":{"uk":"media/ldoce/hwd/bre/2/inconvenient0205.mp3","us":"media/ldoce/hwd/ame/2/inconvenient.mp3"},"examples":[{"en":"an inconvenient time/place","cn":"不方便的时间/地点"},{"en":"Monday’s a bit inconvenient for me. How about Wednesday?","cn":"周一我不太方便﹐周三如何？"}],"oxford":{"phon":"ˌɪnkənˈviːniənt","pos":"adjective","senses":[{"en":"causing trouble or problems, especially in connection with what you need or would like yourself","cn":"不方便的；引起麻烦的","ex":{"en":"an inconvenient time/place","cn":"不方便的时间／地点"}}]}},"intensify":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"加强;强化;加剧","en":"If you intensify something or if it intensifies, it becomes greater in strength, amount, or degree.","ex":{"en":"Britain is intensifying its efforts to secure the release of the hostages","cn":"英国正加紧努力确保人质的获释。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to increase your efforts or activities, especially in order to improve a situation that is not as good as you want it to be","cn":""},{"en":"to increase something so that it covers a wider area or range of activities","cn":""},{"en":"to increase something such as knowledge, experience, or your range of activities","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To intensify is to increase the intensity, force, or power of something. For some people, Burning Man isn't intense enough on its own: they need to intensify it with drugs."}]},"collocations":{"phrases":["ADV. greatly | sharply The fighting in the area has intensified sharply. | further","VERB + INTENSIFY appear to, seem to The extreme cold seemed, if anything, to intensify. | tend to | be likely to | serve to The reforms serv"]},"media":{"uk":"media/ldoce/hwd/bre/3/intensify0205.mp3","us":"media/ldoce/hwd/ame/1/intensify.mp3"},"examples":[{"en":"The opposition leader has intensified his attacks on the government.","cn":"反对派领袖加强了对政府的攻击。"},{"en":"Violence intensified during the night.","cn":"在夜间暴力活动加剧了。"}],"oxford":{"phon":"ɪnˈtensɪfaɪ","pos":"verb","senses":[{"en":"to increase in degree or strength; to make something increase in degree or strength","cn":"（使）加强，增强，加剧","ex":{"en":"Violence intensified during the night.","cn":"在夜间暴力活动加剧了。"}}]}},"intolerance":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"不容忍;不容异己;偏狭","en":"Intolerance is unwillingness to let other people act in a different way or hold different opinions from you.","ex":{"en":"...his intolerance of any opinion other than his own.","cn":"他不能容忍自己观点以外的任何观点"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an unreasonable dislike and distrust of people who are different from you in some way, especially because of their race, sex, religion etc","cn":""},{"en":"the practice of treating one group of people differently from another in an unfair way","cn":""},{"en":"an unreasonable refusal to accept beliefs, customs, and ways of thinking that are different from your own","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Intolerance — or an unwillingness to accept the beliefs or behavior of someone different from you — is not a quality you want to have. Intolerance is what leads to hate crimes and discrimination."}]},"collocations":{"phrases":["ADJ. racial, religious","VERB + INTOLERANCE display, show","PREP. ~ of The town began to show increasing intolerance of immigrants. | ~ to the professor's intolerance to any views other than his own |","ADJ. food | glucose, lactose, etc.","PREP. ~ of intolerance of potatoes | ~ to an intolerance to milk products"]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41intolerance.mp3","us":"media/ldoce/hwd/ame/1/ld41intolerance.mp3"},"examples":[{"en":"religious intolerance","cn":"宗教上的不宽容"},{"en":"an intolerance to dairy products","cn":"对乳制品过敏"}],"oxford":{"phon":"ɪnˈtɒlərəns","pos":"noun","senses":[{"en":"the fact of not being willing to accept ideas or ways of behaving that are different from your own","cn":"不容忍的；褊狭的；不容异说的；偏执的","lab":"disapproving","ex":{"en":"religious intolerance","cn":"宗教上的不宽容"}},{"en":"the fact of not being able to eat particular foods, use particular medicines, etc. without becoming ill","cn":"（对食物、药物等）不耐受的，不耐的","lab":"specialist","ex":{"en":"glucose/lactose intolerance","cn":"葡萄糖/乳糖不耐症"}}]}},"inducement":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"诱惑;引诱物","en":"If someone is offered an inducement to do something, they are given or promised gifts or benefits in order to persuade them to do it.","ex":{"en":"They offer every inducement to foreign businesses to invest in their states","cn":"他们为外国企业提供种种优厚条件，以吸引这些企业到他们所在的州投资。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that encourages you to work harder, start new activities etc","cn":""},{"en":"something that is offered to someone to make a deal or plan seem more attractive, so that they will accept it","cn":""},{"en":"a reward that is offered to someone to encourage them to do something","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The act of persuading someone to do something is called inducement . If you're training a dog, you might use food as an inducement to make the dog do what you want. This works with some humans too."}]},"collocations":{"phrases":["ADJ. big, massive, powerful, strong | sufficient | extra, further | positive | cash, financial","VERB + INDUCEMENT offer (sb/sth as), provide (sb/sth as) The higher payments were offered as an inducement. | receive","PREP. ~ for The reduced tax is a major inducement for first-time buyers. | ~ to an inducement to crime and violence inducements to employees"]},"media":{"uk":"media/ldoce/hwd/bre/2/inducement0205.mp3","us":"media/ldoce/hwd/ame/8/inducement.mp3"},"examples":[{"en":"Government officials have been accused of accepting inducements (= bribes ) from local businessmen.","cn":"政府官员被指控接受了当地商人的贿赂。"},{"en":"There is little inducement for them to work harder.","cn":"没有什么动力能促使他们加把劲工作。"}],"oxford":{"phon":"ɪnˈdjuːsmənt","pos":"noun","senses":[{"en":"something that is given to somebody to persuade them to do something","cn":"引诱；刺激；诱因","ex":{"en":"financial inducements to mothers to stay at home","cn":"促使母亲守在家里的经济诱因"}}]}},"insoluble":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(问题等)不能解决的","en":"An insoluble problem is so difficult that it is impossible to solve.","ex":{"en":"I pushed the problem aside; at present it was insoluble","cn":"我把问题抛在一边，目前它还无法解决。"}},{"pos":"ADJ 形容词","cn":"不溶解的","en":"If a substance is insoluble, it does not dissolve in a liquid.","ex":{"en":"Carotenes are insoluble in water and soluble in oils and fats.","cn":"胡萝卜素不溶于水,但可溶于油类和脂肪。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unresolved problem still exists because it has not been dealt with successfully","cn":""},{"en":"an insoluble problem is very difficult or impossible to solve","cn":""},{"en":"an intractable problem is one that is so difficult and complicated that it is impossible to solve it however hard you try","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Let a bottle of salad dressing stand on the table for a few hours and you will notice that it has separated into layers. That's because oil is insoluble or is not capable of being dissolved."}]},"collocations":{"phrases":["VERBS be, seem | remain","ADV. absolutely | almost | apparently, seemingly 2 impossible to dissolve in a liquid","VERBS be","ADV. highly | practically, virtually","PREP. ~ in These chemicals are practically insoluble in water."]},"media":{"uk":"media/ldoce/hwd/bre/2/insoluble_las2_br.mp3","us":"media/ldoce/hwd/ame/c/insoluble.mp3"},"examples":[{"en":"insoluble conflicts within the department","cn":"部门内难以调和的冲突"}],"oxford":{"phon":"ɪnˈsɒljəbl","pos":"adjective","senses":[{"en":"that cannot be solved or explained","cn":"无法解决的；不能解释的","ex":{"en":"The problem seemed insoluble.","cn":"问题似乎难以解决。"}},{"en":"that does not dissolve in a liquid","cn":"不能溶解的；不溶的","ex":{"en":"These chemicals are practically insoluble in water.","cn":"这些化学物质几乎不溶于水。"}}]}},"inexperience":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"缺乏经验;无经验","en":"If you refer to someone's inexperience, you mean that they have little knowledge or experience of a particular situation or activity.","ex":{"en":"Critics attacked the youth and inexperience of his staff.","cn":"批评家们抨击他的员工年纪太轻，缺乏经验。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the fact of having little or no experience in a job or activity","cn":""},{"en":"the fact of not having enough experience in a job or activity","cn":""},{"en":"lack of experience","cn":"缺乏经验"}]},"collocations":{"phrases":["ADJ. relative | youthful | political","VERB + INEXPERIENCE reveal, show She showed her inexperience by asking lots of trivial questions. | be down to The team's defensive errors w","INEXPERIENCE + VERB show Her inexperience in politics did not show as she debated with the other candidates.","PREP. because of/from/through ~ They made mistakes through inexperience. | ~ in inexperience in teaching"]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41inexperience.mp3","us":"media/ldoce/hwd/ame/b/inexperience.mp3"},"examples":[{"en":"His mistake was due to youth and inexperience.","cn":"他失误的原因是年轻没有经验。"},{"en":"youthful inexperience","cn":"少不更事"}],"oxford":{"phon":"ˌɪnɪkˈspɪəriəns","pos":"noun","senses":[{"en":"lack of knowledge and experience","cn":"缺乏经验；经验不足","ex":{"en":"His mistake was due to youth and inexperience.","cn":"他失误的原因是年轻没有经验。"}}]}},"inaugurate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"为…举行就职典礼;使正式就任","en":"When a new leader is inaugurated, they are formally given their new position at an official ceremony.","ex":{"en":"The new President will be inaugurated on January 20.","cn":"新总统将于 1 月 20 号举行就职典礼。"}},{"pos":"VERB 动词","cn":"为…举行落成仪式;为…举行成立典礼","en":"When a new building or institution is inaugurated, it is declared open in a formal ceremony.","ex":{"en":"A new centre for research on toxic waste was inaugurated today at Imperial College.","cn":"新建的有毒废物研究中心今天在皇家学院举行落成典礼。"}},{"pos":"VERB 动词","cn":"开创;开展","en":"If you inaugurate a new system or service, you start it.","ex":{"en":"Pan Am inaugurated the first scheduled international flight.","cn":"泛美航空公司开通了第一条国际定期航班线路。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to start a company or organization, especially one that exists for a long time","cn":""},{"en":"to start a new company or organization. Set up is less formal than establish , and is the usual phrase to use in everyday English","cn":""},{"en":"to start a business that provides services to the public, such as a shop, restaurant, or hotel","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To inaugurate means to start something, to give it a kick off. The opening day pep rally inaugurates the high school football season."}]},"collocations":{"phrases":["ADV. formally, officially The assembly was formally inaugurated on December 13."]},"media":{"uk":"media/ldoce/hwd/bre/0/inaugurate0205.mp3","us":"media/ldoce/hwd/ame/b/inaugurate.mp3"},"examples":[{"en":"The new theatre was inaugurated by the mayor.","cn":"新落成的剧院由市长主持了开幕典礼。"},{"en":"The moon landing inaugurated a new era in space exploration.","cn":"登陆月球开创了太空探索的新纪元。"}],"oxford":{"phon":"ɪˈnɔːɡjəreɪt","pos":"verb","senses":[{"en":"to introduce a new public official or leader at a special ceremony","cn":"为（某人）举行就职典礼","ex":{"en":"He will be inaugurated (as) President in January.","cn":"他将于一月份就任总统。"}},{"en":"to officially open a building or start an organization with a special ceremony","cn":"为…举行落成仪式（或创建仪式）","ex":{"en":"The new theatre was inaugurated by the mayor.","cn":"新落成的剧院由市长主持了开幕典礼。"}},{"en":"to introduce a new development or an important change","cn":"引进；开创；开始","lab":"formal","ex":{"en":"The moon landing inaugurated a new era in space exploration.","cn":"登陆月球开创了太空探索的新纪元。"}}]}},"incapacitate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使无能力;使伤残","en":"If something incapacitates you, it weakens you in some way, so that you cannot do certain things.","ex":{"en":"A serious fall incapacitated the 68-year-old congressman.","cn":"一次严重跌伤使这位 68 岁的国会议员丧失了行动能力。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make you too ill or weak to live and work normally","cn":"使无能力〔正常生活和工作〕"},{"en":"to stop a system, piece of equipment etc from working properly","cn":"使〔系统﹑设备等〕停止正常工作﹐使瘫痪"}]},"vocab":{"pos":"v","senses":[{"en":"If you are incapacitated , you can’t do what you normally do, what you’re being asked to do — or perhaps, much of anything. To incapacitate someone is to cause him or her to be unable to function normally, like a bad cold that incapacitates you."}]},"collocations":{"phrases":["ADV. severely | totally By this time my father was totally incapacitated by his illness. | temporarily | mentally, physically"]},"media":{"uk":"media/ldoce/hwd/bre/c/incapacitate0205.mp3","us":"media/ldoce/hwd/ame/9/incapacitate.mp3"},"examples":[{"en":"Her mother has been incapacitated by a fall.","cn":"她母亲摔了一跤后﹐失去了正常生活能力。"},{"en":"A successful attack would incapacitate military training camps.","cn":"一次成功的攻击能使军事训练营陷入瘫痪。"}],"oxford":{"phon":"ˌɪnkəˈpæsɪteɪt","pos":"verb","senses":[{"en":"to make somebody/something unable to live or work normally","cn":"使失去正常生活（或工作）能力","ex":{"en":"He was incapacitated by old age and sickness.","cn":"年老多病使他失去了正常生活能力。"}}]}},"indication":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"迹象;暗示","en":"An indication is a sign which suggests, for example, what people are thinking or feeling.","ex":{"en":"All the indications are that we are going to receive reasonable support from abroad","cn":"所有迹象都表明，我们将从国外获得有力支持。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an event, fact etc that shows that something is happening or that something is true or exists","cn":""},{"en":"a sign. Indication is more formal than sign","cn":""},{"en":"facts or signs that show clearly that something exists or is true, especially something that you are trying to prove","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An indication is a sign––it indicates , or suggests, some conclusion. The way you blush furiously when a certain someone talks to you is an indication that you have a crush on them."}]},"collocations":{"phrases":["ADJ. firm, good, great, strong | accurate, reliable, true | clear, definite, sure | important | useful, valuable | sufficient | approximate,","VERB + INDICATION be, constitute, serve as The popularity of the government building project served as an indication of public support. | ha","INDICATION + VERB show sth, suggest sth Indications show that at least 2,000 more businesses will go bankrupt before the end of the year.","PREP. amid ~s of Amid indications of growing disorder in the capital, the president is to make a speech on television tonight. | ~ as to He ","PHRASES (all) the indications are that &hellip; All the indications are that she will make a full recovery. | there is every indication that"]},"media":{"uk":"media/ldoce/hwd/bre/0/indication0205.mp3","us":"media/ldoce/hwd/ame/8/indication.mp3"},"examples":[{"en":"All the indications are that the deal will go ahead as planned.","cn":"从所有的迹象看，交易将按计划进行。"},{"en":"They gave no indication of how the work should be done.","cn":"他们根本没说明这项工作该怎样做。"}],"oxford":{"phon":"ˌɪndɪˈkeɪʃn","pos":"noun","senses":[{"en":"a remark or sign that shows that something is happening or what somebody is thinking or feeling","cn":"表明；标示；显示；象征","g":"[countable, uncountable]","ex":{"en":"They gave no indication of how the work should be done.","cn":"他们根本没说明这项工作该怎样做。"}},{"en":"a symptom that suggests that particular medical treatment is necessary","cn":"症状","g":"[countable]","lab":"medical","ex":{"en":"There was no clinical indication for such a test.","cn":"没有进行这种检测的临床指征。"}}]}},"interlude":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"插曲;间歇;幕间表演","en":"An interlude is a short period of time when an activity or situation stops and something else happens.","ex":{"en":"It was a happy interlude in the Kents' life","cn":"那是肯特一家的生活中一段幸福的插曲。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short time between school classes when children can play, eat something etc","cn":""},{"en":"a planned pause during a play, concert, or film","cn":""},{"en":"a planned pause during a play or concert, when music is often played","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"An interlude is a brief period of time that comes in the middle of something. You might enjoy a relaxing lemonade interlude in the middle of a tough day at your road-paving job."}]},"collocations":{"phrases":["ADJ. brief | romantic | peaceful, pleasant | musical a musical interlude between two the acts of the play","PREP. ~ between a peaceful interlude between periods of intense activity | ~ in He'd had two romantic interludes in a rather lonely life. | "]},"media":{"uk":"media/ldoce/hwd/bre/b/interlude0205.mp3","us":"media/ldoce/hwd/ame/b/interlude.mp3"},"examples":[{"en":"Apart from a brief interlude of peace, the war lasted nine years.","cn":"除了一段短暂的和平，那场战争持续了九年。"},{"en":"There will now be a short interlude.","cn":"现在有一段短时间的幕间休息。"}],"oxford":{"phon":"ˈɪntəluːd","pos":"noun","senses":[{"en":"a period of time between two events during which something different happens","cn":"（两事件之间的）间歇；插入事件","ex":{"en":"a romantic interlude (= a short romantic relationship)","cn":"短暂的恋爱"}},{"en":"a short period of time between the parts of a play, film, etc.","cn":"（戏剧、电影等的）幕间休息","ex":{"en":"There will now be a short interlude.","cn":"现在有一段短时间的幕间休息。"}},{"en":"a short piece of music or a talk, etc. played or given between the parts of a play or film or between other pieces of music","cn":"幕间乐曲（或节目、演说）","ex":{"en":"a musical interlude between two the acts of the play","cn":"戏剧两幕之间的音乐插曲"}}]}},"incapable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无能力的;不能的","en":"Someone who is incapable of doing something is unable to do it.","ex":{"en":"She seemed incapable of taking decisions","cn":"她似乎无法作出决定。"}},{"pos":"ADJ 形容词","cn":"软弱无能的;蠢笨的","en":"An incapable person is weak or stupid.","ex":{"en":"He lost his job for allegedly being incapable.","cn":"据说他由于软弱无能而丢掉了工作。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"- use this especially in the past or future tense","cn":""},{"en":"to not be able to do something, especially something important that you want to do or need to do","cn":""},{"en":"the fact that someone is unable to do something, used especially when you are annoyed with them because you think they are too weak, lazy etc to do it","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When — even when you want to go to your friends' party — you're incapable of telling your mother you are going to miss her birthday dinner, it means you just can't do it, and that you're a good person. Incapable means \"unable.\""}]},"collocations":{"phrases":["VERBS appear, be, feel, prove, seem | become | make sb, render sb The wine had made him incapable of thinking clearly. | adjudge sb, deem sb","ADV. absolutely, completely, quite, totally, utterly, wholly | almost | largely | clearly | inherently | constitutionally, temperamentally S","PREP. of Computers are incapable of creative thought."]},"media":{"uk":"media/ldoce/hwd/bre/0/incapable0205.mp3","us":"media/ldoce/hwd/ame/7/incapable.mp3"},"examples":[{"en":"If people keep telling you you're incapable, you begin to lose confidence in yourself.","cn":"如果人们不断地对你说你无能，你就开始失去自信心了。"},{"en":"The children seem to be totally incapable of working by themselves.","cn":"孩子们好像完全不能靠自己做功课。"}],"oxford":{"phon":"ɪnˈkeɪpəbl","pos":"adjective","senses":[{"en":"not able to do something","cn":"没有能力（做某事）","ex":{"en":"incapable of speech","cn":"不会说话"}},{"en":"not able to control yourself or your affairs; not able to do anything well","cn":"不能克制自己的；不能自理的；什么事也做不好的","ex":{"en":"If people keep telling you you're incapable, you begin to lose confidence in yourself.","cn":"如果人们不断地对你说你无能，你就开始失去自信心了。"}}]}},"informative":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"提供有用消息(或资料)的;增长知识的;增长见闻的","en":"Something that is informative gives you useful information.","ex":{"en":"The adverts are not very informative","cn":"这些广告并没有包含太多有用信息。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"providing a lot of new or useful information","cn":""},{"en":"providing a lot of new or useful information","cn":""},{"en":"providing many useful facts or ideas","cn":"资料丰富的﹔增进知识的"}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective informative to describe something that gives you some kind of useful information, like an informative book about identifying the mushrooms you find growing wild in the woods near your house."}]},"collocations":{"phrases":["VERBS be, prove | find sth","ADV. extremely, highly, most, particularly, very, wonderfully The survey proved most informative. | quite","PREP. about The book is extremely informative about life in Roman times."]},"media":{"uk":"media/ldoce/hwd/bre/d/informative0205.mp3","us":"media/ldoce/hwd/ame/f/l3informative.mp3"},"examples":[{"en":"The talk was both informative and entertaining.","cn":"这次谈话既长见识又饶有趣味。"},{"en":"an informative and entertaining book","cn":"一本资料丰富且饶有趣味的书"}],"oxford":{"phon":"ɪnˈfɔːmətɪv","pos":"adjective","senses":[{"en":"giving useful information","cn":"提供有用信息的；给予知识的","ex":{"en":"The talk was both informative and entertaining.","cn":"这次谈话既长见识又饶有趣味。"}}]}},"inflammation":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"发炎;炎症","en":"An inflammation is a painful redness or swelling of a part of your body that results from an infection, injury, or illness.","ex":{"en":"The drug can cause inflammation of the liver.","cn":"该药会引起肝脏炎症。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"swelling and pain in part of your body, which is often red and feels hot","cn":"发炎﹐炎症"}]},"vocab":{"pos":"n","senses":[{"en":"An inflammation means \"setting something on fire.\" Maybe it's a political movement that suddenly takes hold, romantic feelings, the heat making your shoes feel tight, or someone lighting a campfire."}]},"collocations":{"phrases":["ADJ. painful, severe | mild | acute, chronic | colonic, intestinal, etc.","VERB + INFLAMMATION reduce Steroids often help reduce the inflammation and itching in the skin.","PREP. ~ of inflammation of the stomach","PHRASES signs of inflammation"]},"media":{"uk":"media/ldoce/hwd/bre/b/inflammation0205.mp3","us":"media/ldoce/hwd/ame/d/inflammation.mp3"},"examples":[{"en":"inflammation of the colon","cn":"结肠炎"}],"oxford":{"phon":"ˌɪnfləˈmeɪʃn","pos":"noun","senses":[{"en":"a condition in which a part of the body becomes red, painful and swollen (= larger than normal) because of infection or injury","cn":"炎症","ex":{"en":"inflammation of the ear","cn":"耳朵发炎"}}]}},"inherit":{"collins":{"senses":[{"pos":"VERB 动词","cn":"继承(金钱或财产)","en":"If you inherit money or property, you receive it from someone who has died.","ex":{"en":"He has no son to inherit his land.","cn":"他没有儿子来继承田产。"}},{"pos":"VERB 动词","cn":"(从前人、前任等)接过,得到","en":"If you inherit something such as a task, problem, or attitude, you get it from the people who used to have it, for example because you have taken over their job or been influenced by them.","ex":{"en":"The government inherited an impossible situation from its predecessors","cn":"这届政府从前任那里接过了一个非常棘手的烂摊子。"}},{"pos":"VERB 动词","cn":"经遗传获得(特征、特质等)","en":"If you inherit a characteristic or quality, you are born with it, because your parents or ancestors also had it.","ex":{"en":"We inherit from our parents many of our physical characteristics","cn":"我们的许多身体特征都是从父母那里遗传而来的。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to get something by finding it, asking for it, or paying for it","cn":""},{"en":"to get something","cn":""},{"en":"to get something – used about knowledge, skills, or something big or expensive","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When your grandmother dies, you might inherit her tea set. Regardless of her death, you might inherit her sense of humor or rather large nose. To inherit is to receive from a predecessor."}]},"collocations":{"phrases":["VERB + INHERIT stand to He stood to inherit (= was likely to inherit) property worth &pound; 5 million.","PREP. from She inherited some money from her mother.","PHRASES be genetically inherited How many of these traits are genetically inherited?"]},"media":{"uk":"media/ldoce/hwd/bre/4/inherit0205.mp3","us":"media/ldoce/hwd/ame/d/inherit.mp3"},"examples":[{"en":"She inherited a fortune from her father.","cn":"她从她父亲那里继承了一大笔财富。"},{"en":"He has inherited his mother's patience.","cn":"这种耐心是母亲遗传给他的。"}],"oxford":{"phon":"ɪnˈherɪt","pos":"verb","senses":[{"en":"to receive money, property, etc. from somebody when they die","cn":"继承（金钱、财产等）","g":"[transitive, intransitive]","ex":{"en":"She inherited a fortune from her father.","cn":"她从她父亲那里继承了一大笔财富。"}},{"en":"to have qualities, physical features, etc. that are similar to those of your parents, grandparents, etc.","cn":"经遗传获得（品质、身体特征等）","g":"[transitive]","ex":{"en":"He has inherited his mother's patience.","cn":"这种耐心是母亲遗传给他的。"}},{"en":"if you inherit a particular situation from somebody, you are now responsible for dealing with it, especially because you have replaced that person in their job","cn":"接替（责任等）；继任","g":"[transitive]","ex":{"en":"policies inherited from the previous administration","cn":"因袭上届政府的政策"}}]}},"intellect":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"智力;理解力;领悟力;思维能力","en":"Intellect is the ability to understand or deal with ideas and information.","ex":{"en":"Do the emotions develop in parallel with the intellect?","cn":"情感与智力是并行发展的吗？"}},{"pos":"N-VAR 可变名词","cn":"非凡的才智;出众的才华","en":"Intellect is the quality of being very intelligent or clever.","ex":{"en":"Her intellect is famed far and wide","cn":"她的非凡才智闻名遐迩。"}},{"pos":"N-COUNT 可数名词","cn":"英才;才智非凡的人","en":"If you describe someone as an intellect, you mean that they are very intelligent.","ex":{"en":"My boss isn't a great intellect.","cn":"我的老板才智并不出众。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the ability to learn quickly, think clearly, and understand ideas well","cn":""},{"en":"the ability to think quickly and well, remember a lot of facts, and be good at studying","cn":""},{"en":"a very high level of intelligence and ability","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Intellect is how much intelligence you have. Einstein was known for having a great intellect . Mickey Mouse's friend Goofy has almost no intellect to speak of."}]},"collocations":{"phrases":["ADJ. brilliant, considerable, formidable, keen, powerful, superior, sharp | limited, low, weak | creative, rational, scientific | human","VERB + INTELLECT have She has a formidable intellect. | exercise He enjoyed exercising his intellect in analysing the controversies of his d"]},"media":{"uk":"media/ldoce/hwd/bre/1/intellect0205.mp3","us":"media/ldoce/hwd/ame/5/intellect.mp3"},"examples":[{"en":"She was one of the most formidable intellects of her time.","cn":"她是当时的一名盖世英才。"},{"en":"a man of considerable intellect","cn":"相当有才智的人"}],"oxford":{"phon":"ˈɪntəlekt","pos":"noun","senses":[{"en":"the ability to think in a logical way and understand things, especially at an advanced level; your mind","cn":"（尤指高等的）智力，逻辑思维领悟力","g":"[uncountable, countable]","ex":{"en":"a man of considerable intellect","cn":"相当有才智的人"}},{"en":"a very intelligent person","cn":"智力高的人；才智超群的人","g":"[countable]","ex":{"en":"She was one of the most formidable intellects of her time.","cn":"她是当时的一名盖世英才。"}}]}},"inadequacy":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"不足;不完备","en":"The inadequacy of something is the fact that there is not enough of it, or that it is not good enough.","ex":{"en":"...the inadequacy of the water supply","cn":"水供应不足"}},{"pos":"N-UNCOUNT 不可数名词","cn":"不够格;能力不足;无法胜任","en":"If someone has feelings of inadequacy, they feel that they do not have the qualities and abilities necessary to do something or to cope with life in general.","ex":{"en":"The feeling of inadequacy was overpowering.","cn":"无法胜任的感觉非常强烈。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a feeling that you are not as good, clever, skilled etc as other people 〔","cn":"人〕不够好﹐不胜任"},{"en":"the fact of not being good enough in quality, ability, size etc for a particular purpose 〔","cn":"质量﹑能力﹑大小等〕不足﹐欠缺"},{"en":"a fault or weakness","cn":"缺点﹐不足之处"}]},"vocab":{"pos":"n","senses":[{"en":"An inadequacy is something that is not enough. If you get a bad grade, it may reveal an inadequacy in your approach to studying."}]},"collocations":{"phrases":["ADJ. total | fundamental | glaring, obvious | personal | sexual, social | theoretical","VERB + INADEQUACY demonstrate, expose, highlight, point out/to, reveal, show (up) She rightly points to the inadequacy of the argument. The ","INADEQUACY + VERB arise from sth, stem from sth","PREP. ~ in inadequacies in educational facilities","PHRASES a feeling/sense of inadequacy"]},"media":{"uk":"media/ldoce/hwd/bre/2/inadequacy_las2_br.mp3","us":"media/ldoce/hwd/ame/6/inadequacy.mp3"},"examples":[{"en":"He had to face up to his own inadequacies as a father.","cn":"他不得不正视自身作为父亲的不足。"},{"en":"gross inadequacies in the data","cn":"数据资料的极端匮乏"}],"oxford":{"phon":"ɪnˈædɪkwəsi","pos":"noun","senses":[{"en":"the state of not being enough or good enough","cn":"不充分；不足；不够","g":"[uncountable]","ex":{"en":"the inadequacy of our resources","cn":"我们的资源的贫乏"}},{"en":"a state of not being able or confident to deal with a situation","cn":"不胜任；缺乏信心","g":"[uncountable]","ex":{"en":"a feeling/sense of inadequacy","cn":"不称职之感"}},{"en":"a weakness; a lack of something","cn":"弱点；缺陷；某事物的缺乏","g":"[countable, usually plural]","ex":{"en":"gross inadequacies in the data","cn":"数据资料的极端匮乏"}}]}},"inflammable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易燃的;易着火的","en":"An inflammable material or chemical catches fire and burns easily.","ex":{"en":"...a highly inflammable liquid.","cn":"高度易燃的液体"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"inflammable materials or substances will start to burn very easily","cn":"易燃的"},{"en":"easily becoming angry or violent, or making people angry or violent","cn":"易发怒的﹔易激动的﹔让人生气的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something that is inflammable can be set on fire easily. You dared not light a match after you accidentally spilled gasoline on yourself because you knew you were inflammable ."}]},"collocations":{"phrases":["VERBS be","ADV. highly, very These gases are highly inflammable."]},"media":{"uk":"media/ldoce/hwd/bre/5/inflammable0205.mp3","us":"media/ldoce/hwd/ame/9/inflammable.mp3"},"examples":[{"en":"inflammable material","cn":"易燃物"},{"en":"Petrol is highly inflammable .","cn":"汽油高度易燃。"}],"oxford":{"phon":"ɪnˈflæməbl","pos":"adjective","senses":[{"en":"that can burn easily","cn":"易燃的；可燃的","ex":{"en":"inflammable material","cn":"易燃物"}}]}},"interrogation":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"讯问;审问","en":"An interrogation is the act of interrogating someone.","ex":{"en":"...the right to silence in police interrogations.","cn":"在警方讯问时保持沉默的权利"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a meeting in which someone is asked questions, to find out if they are suitable for a job, or to help the police find out about a crime. Also used about someone being asked questions on TV, in a newspaper, in a magazine etc","cn":""},{"en":"an occasion when someone is asked a lot of questions for a long time in order to get information, sometimes using threats, usually by the police or the army","cn":""},{"en":"an occasion when someone is asked questions about what they have just said, in order to see if they are telling the truth, especially in a court of law","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An interrogation is a question or an intense questioning session. Police do interrogations of suspects all the time."}]},"collocations":{"phrases":["ADJ. police | further","VERB + INTERROGATION conduct The interrogation was conducted by senior police officers.","INTERROGATION + NOUN cell, room | methods, procedures, techniques","PREP. during ~ She revealed the name of her accomplice during interrogation. | under ~ Under interrogation, he refused to say anything at fi","PHRASES power/powers of interrogation The committee has no power of interrogation."]},"media":{"uk":"media/ldoce/hwd/bre/6/ldoce6interrogatio.mp3","us":"media/ldoce/hwd/ame/6/ldoce6interrogatio.mp3"},"examples":[{"en":"She hated her parents' endless interrogations about where she'd been.","cn":"她讨厌父母没完没了地盘问她去哪里了。"},{"en":"He confessed after four days under interrogation.","cn":"他在受讯问四天之后招认了。"}],"oxford":{"phon":"ɪnˌterəˈɡeɪʃn","pos":"noun","senses":[{"en":"the act of asking somebody a lot of questions over a long period of time, especially in an aggressive way","cn":"讯问；审问；盘问","ex":{"en":"He confessed after four days under interrogation.","cn":"他在受讯问四天之后招认了。"}},{"en":"the process of obtaining information from a computer or other machine","cn":"（在计算机或其他机器上）查询，询问","lab":"specialist","ex":{"en":"the interrogation of raw data","cn":"原始数据的询问"}}]}},"intake":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"(食物、饮料、空气等的)摄取量,吸入量","en":"Your intake of a particular kind of food, drink, or air is the amount that you eat, drink, or breathe in.","ex":{"en":"Your intake of alcohol should not exceed two units per day","cn":"每天的饮酒量不应超过两个计量单位。"}},{"pos":"N-COUNT 可数名词","cn":"(组织或地方的)新纳入者，新招收者","en":"The people who are accepted into an organization or place at a particular time are referred to as a particular intake .","ex":{"en":"...one of this year's intake of students","cn":"今年新招学生中的一个"}},{"pos":"PHRASE 短语","cn":"(通常因震惊而)倒吸的一口冷气","en":"When someone takes an intake of breath, they breathe in quickly and noisily, usually because they are shocked at something.","ex":{"en":"I heard, even over the babble of the crowd, a sharp, shocked intake of breath.","cn":"即便人声鼎沸,我还是听到有人猛地倒抽一口冷气。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the amount of food, drink etc that you take into your body 〔","cn":"食物﹑饮料等的〕摄入量﹐摄取量﹐吸入量"},{"en":"the number of people who join a school, profession etc at a particular time 〔","cn":"学校﹑职业等某一时间的〕加入人数"},{"en":"a tube, pipe etc through which air, gas, or liquid enters a machine 〔","cn":"机器上空气﹑气体或液体注入的〕管道﹐进口"}]},"vocab":{"pos":"n","senses":[{"en":"The act of consuming food can be called intake . A veterinarian might advise you to limit your dog's intake of pizza crusts, for example."}]},"collocations":{"phrases":["ADJ. high | moderate | low | increased | total | good | excessive | adequate | balanced | normal | average | (recommended) daily | regular |","VERB + INTAKE have Make sure you have a balanced intake of vitamins A, B, C and D. | maintain You should maintain a low intake of fat. | inc","ADJ. high | low | new | annual | graduate, student","VERB + INTAKE have The school has an annual intake of 20 to 30. | cut, reduce | increase 3 where liquid/air enters a machine","ADJ. air, water | pump","VERB + INTAKE clog (up) Algae has clogged the intake to the water turbine. 4 of breath","ADJ. harsh, sharp She gave a sharp intake of breath.","VERB + INTAKE give"]},"media":{"uk":"media/ldoce/hwd/bre/b/intake0205.mp3","us":"media/ldoce/hwd/ame/e/intake.mp3"},"examples":[{"en":"to reduce your daily intake of salt","cn":"减少每天的食盐量"},{"en":"the annual student intake","cn":"每年招收的新生人数"}],"oxford":{"phon":"ˈɪnteɪk","pos":"noun","senses":[{"en":"the amount of food, drink, etc. that you take into your body","cn":"（食物、饮料等的）摄取量，吸入量","g":"[uncountable, countable]","ex":{"en":"high fluid intake","cn":"高流质摄取量"}},{"en":"the number of people who are allowed to enter a school, college, profession, etc. during a particular period","cn":"（一定时期内）纳入的人数","g":"[countable + singular or plural verb, uncountable]","ex":{"en":"the annual student intake","cn":"每年招收的新生人数"}},{"en":"a place where liquid, air, etc. enters a machine","cn":"（机器上的液体、空气等的）进口","g":"[countable]","ex":{"en":"the air/fuel intake","cn":"进气口；加燃料口"}},{"en":"an act of taking something in, especially breath","cn":"吸收；吸入；（尤指）吸气","g":"[countable, usually singular]","ex":{"en":"She gave a sharp intake of breath.","cn":"她猛地吸了一口气。"}}]}},"inhabitant":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"居民","en":"The inhabitants of a place are the people who live there.","ex":{"en":"...the inhabitants of Glasgow.","cn":"格拉斯哥市居民"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"all the people in a country or town or area, or the number of people who live in it","cn":""},{"en":"someone who lives in a particular area of a town, a particular street or building etc","cn":""},{"en":"one of the people who live in a place, especially in a town or city or in an area of a country","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Someone who usually lives in a specific place — whether it's a mansion, a cave, or a beach house — is its inhabitant ."}]},"collocations":{"phrases":["ADJ. local | old He is Brixham's oldest inhabitant. | younger | present | permanent | early The island's earliest inhabitants came from Indi","VERB + INHABITANT have London has over seven million inhabitants.","INHABITANT + VERB live 77% of the inhabitants lived in the countryside.","PREP. of/with &hellip; ~ towns of about 10,000 inhabitants"]},"media":{"uk":"media/ldoce/hwd/bre/0/inhabitant0205.mp3","us":"media/ldoce/hwd/ame/d/inhabitant.mp3"},"examples":[{"en":"a town of 11 000 inhabitants","cn":"有 11 000 名居民的城镇"},{"en":"the oldest inhabitant of the village","cn":"这个村最早的居民"}],"oxford":{"phon":"ɪnˈhæbɪtənt","pos":"noun","senses":[{"en":"a person or an animal that lives in a particular place","cn":"（某地的）居民，栖息动物","ex":{"en":"the oldest inhabitant of the village","cn":"这个村最老的居民"}}]}},"intricacy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"复杂精细;错综复杂","en":"Intricacy is the state of being made up of many small parts or details.","ex":{"en":"The price depends on the intricacy of the work.","cn":"价格取决于做工的复杂精细度。"}},{"pos":"N-PLURAL 复数名词","cn":"错综复杂的细节;纷繁复杂之处","en":"The intricacies of something are its complicated details.","ex":{"en":"Rose explained the intricacies of the job.","cn":"罗斯解释了这项工作的繁琐复杂之处。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the complicated details of something","cn":"某事错综复杂的细节"},{"en":"the state of containing a large number of parts or details","cn":"错综复杂﹔盘根错节"}]},"vocab":{"pos":"n","senses":[{"en":"The noun intricacy means a quality of being complex or elaborately detailed. You could compliment the intricacy of your friend's complicated hairdo."}]},"collocations":{"phrases":["VERB + INTRICACY learn, master, understand I've never mastered the intricacies of cricket. | guide/steer sb through, steer sb through"]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41intricacy.mp3","us":"media/ldoce/hwd/ame/5/intricacy.mp3"},"examples":[{"en":"the intricacies of economic policy","cn":"经济政策的错综复杂"},{"en":"the intricacy of the design","cn":"设计的复杂性"}],"oxford":{"phon":"ˈɪntrɪkəsi","pos":"noun","senses":[{"en":"the complicated parts or details of something","cn":"错综复杂的事物（或细节）","g":"[plural]","ex":{"en":"the intricacies of economic policy","cn":"经济政策的错综复杂"}},{"en":"the fact of having complicated parts, details or patterns","cn":"错综复杂","g":"[uncountable]","ex":{"en":"the intricacy of the design","cn":"设计的复杂性"}}]}},"influenza":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同 flu","en":"Influenza is the same as flu ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an infectious disease that is like a very bad cold","cn":"流行性感冒"}]},"vocab":{"pos":"n","senses":[{"en":"An influenza is a contagious viral infection. Influenzas tend to spread during the winter, and they're more commonly known as the flu."}]},"collocations":{"phrases":["QUANT. attack, bout","VERB + INFLUENZA have, suffer from | catch, contract","INFLUENZA + NOUN epidemic | virus •"]},"media":{"uk":"media/ldoce/hwd/bre/7/influenza0205.mp3","us":"media/ldoce/hwd/ame/8/influenza.mp3"},"oxford":{"phon":"ˌɪnfluˈenzə","pos":"noun","senses":[{"en":"flu","cn":"流行性感冒；流感","ex":{"en":"the influenza strain known as H7","cn":"被称作 H7 的流感毒株"}}]}},"inadvisable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不明智的;不可取的;失策的","en":"A course of action that is inadvisable should not be carried out because it is not wise or sensible.","ex":{"en":"For three days, it was inadvisable to leave the harbour.","cn":"三天之内最好不要驶离海港。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an action that is inadvisable is not sensible 〔","cn":"行动〕不可取的﹐不明智的﹐失策的"}]},"collocations":{"phrases":["VERBS be, seem | become | make sth Her condition made surgery inadvisable. | feel sth, think sth","ADV. highly It was thought highly inadvisable for young women to go there alone."]},"media":{"uk":"media/ldoce/hwd/bre/1/inadvisable0205.mp3","us":"media/ldoce/hwd/ame/9/laadinadvisable.mp3"},"examples":[{"en":"It is inadvisable to bring children on this trip.","cn":"这次旅行带孩子不妥当。"},{"en":"Changes in the patient’s condition may make surgery inadvisable.","cn":"病人病情的变化可能会使其不宜做手术。"}],"oxford":{"phon":"ˌɪnədˈvaɪzəbl","pos":"adjective","senses":[{"en":"not sensible or wise; that you would advise against","cn":"不明智；不可取","ex":{"en":"It is inadvisable to bring children on this trip.","cn":"这次旅行带孩子不妥当。"}}]}},"intuition":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"直觉","en":"Your intuition or your intuitions are unexplained feelings you have that something is true even when you have no evidence or proof of it.","ex":{"en":"Her intuition was telling her that something was wrong","cn":"她的直觉告诉她一定出了什么问题。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a natural ability to know what you should do without having to learn it or be told it","cn":""},{"en":"the ability to understand or know things by using your feelings instead of considering the facts","cn":""},{"en":"to feel that you know something, without understanding why you feel this","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If you know the definition of this noun by quick insight without relying on reason, you know what intuition means!"}]},"collocations":{"phrases":["ADJ. feminine, women's Her feminine intuition told her that he was unhappy.","QUANT. flash It came upon him in a flash of intuition.","VERB + INTUITION have She had an intuition that her mother wasn't very well. | rely on, trust, use She learned to trust her intuitions about","INTUITION + VERB suggest sth, tell sb sth Intuition told me we were going in the wrong direction.","PREP. by ~ By intuition, he sensed what was wrong. | ~ about an intuition about where to find wild strawberries | ~ behind the intuition beh"]},"media":{"uk":"media/ldoce/hwd/bre/2/intuition0205.mp3","us":"media/ldoce/hwd/ame/2/intuition.mp3"},"examples":[{"en":"I had an intuition that something awful was about to happen.","cn":"我直觉感到要出乱子了。"},{"en":"Intuition told her it was unwise to argue.","cn":"直觉告诉她争吵是不理智的。"}],"oxford":{"phon":"ˌɪntjuˈɪʃn","pos":"noun","senses":[{"en":"the ability to know something by using your feelings rather than considering the facts","cn":"直觉力","g":"[uncountable]","ex":{"en":"Intuition told her that he had spoken the truth.","cn":"直觉告诉她，他说的是实话。"}},{"en":"an idea or a strong feeling that something is true although you cannot explain why","cn":"（一种）直觉","g":"[countable]","ex":{"en":"I had an intuition that something awful was about to happen.","cn":"我直觉感到要出乱子了。"}}]}},"incidental":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"附带的;伴随的;次要的","en":"If one thing is incidental to another, it is less important than the other thing or is not a major part of it.","ex":{"en":"The playing of music proved to be incidental to the main business of the evening","cn":"音乐演奏成了当晚唱主角的商业活动的陪衬。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"less important than the main subject, problem etc","cn":""},{"en":"a subsidiary idea, question, subject etc is less important than the main one but it is connected with it","cn":""},{"en":"happening or existing in connection with or as a result of something else that is more important","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"Incidental means secondary in time or importance. If you lose weight because you moved and must walk further to school, the weight loss was incidental to the move."}]},"collocations":{"phrases":["VERBS be | become | consider sth, declare sth, deem sth The fact that the concert made a profit was considered incidental.","ADV. completely, entirely, purely Any resemblance of a character in this book to a living person is purely incidental. | merely Information ","PREP. to It's just a risk incidental to the job."]},"media":{"uk":"media/ldoce/hwd/bre/d/incidental_adj0205.mp3","us":"media/ldoce/hwd/ame/5/incidental1.mp3"},"examples":[{"en":"You'll need money for incidentals such as tips and taxis.","cn":"你将需要准备好付小费和乘出租车之类的杂项开销。"},{"en":"The discovery was incidental to their main research.","cn":"这一发现是他们主要研究中的附带收获。"}],"oxford":{"phon":"ˌɪnsɪˈdentl","pos":"adjective","senses":[{"en":"happening in connection with something else, but not as important as it, or not intended","cn":"附带发生的；次要的；非有意的","ex":{"en":"The discovery was incidental to their main research.","cn":"这一发现是他们主要研究中的附带收获。"}},{"en":"happening as a natural result of something","cn":"作为自然结果的；伴随而来的；免不了的","lab":"specialist","ex":{"en":"These risks are incidental to the work of a firefighter.","cn":"这些风险是担任消防员不可避免的。"}},{"en":"something that happens in connection with something else, but is less important","cn":"附带的次要事情","ex":{"en":"You'll need money for incidentals such as tips and taxis.","cn":"你将需要准备好付小费和乘出租车之类的杂项开销。"},"pos":"noun"}]}},"inquest":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(调查死因的)讯问","en":"When an inquest is held, a public official hears evidence about someone's death in order to find out the cause.","ex":{"en":"The inquest into their deaths opened yesterday in Enniskillen.","cn":"对他们死因的讯问昨天在恩尼斯基林进行。"}},{"pos":"N-COUNT 可数名词","cn":"(失败原因的)调查,查究","en":"You can refer to an investigation by the people involved into the causes of a defeat or failure as an inquest .","ex":{"en":"His plea came last night as party chiefs held an inquest into the election disaster.","cn":"昨晚政党领袖就选举惨败原因进行调查时,他提出了申辩。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a process in which the police or another organization try to find out the truth about a crime or accident","cn":""},{"en":"an official process to find out why something happened, which usually takes several months or years","cn":""},{"en":"a matter that police or officials are trying to find out information about, especially so that it can be dealt with in a court of law","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An inquest is when a court of law or a coroner investigates the circumstances of a person's death. If a person in your family dies suddenly, you might attend an inquest at the courthouse."}]},"collocations":{"phrases":["ADJ. full | fresh | coroner's","VERB + INQUEST conduct, hold | order The court ordered a fres h inquest into the tragedy. | open | adjourn | attend","INQUEST + VERB open | hear sth An elderly woman froze to death, an inquest heard yesterday. | decide sth, find sth An inquest found that the","INQUEST + NOUN jury | verdict","PREP. at a/the ~ A verdict o f suicide was recorded at th e inquest. | ~ into an inquest int o the team's poor performance | ~ on an inquest"]},"media":{"uk":"media/ldoce/hwd/bre/f/inquest0205.mp3","us":"media/ldoce/hwd/ame/c/inquest.mp3"},"examples":[{"en":"An inquest was held on the team's poor performance.","cn":"对该队在比赛中的差劲表现进行了检讨。"},{"en":"An inquest was held to discover the cause of death.","cn":"对死亡原因进行了调查。"}],"oxford":{"phon":"ˈɪŋkwest","pos":"noun","senses":[{"en":"an official investigation to find out the cause of somebody’s death, especially when it has not happened naturally","cn":"死因审理；验尸；勘验","ex":{"en":"An inquest was held to discover the cause of death.","cn":"对死亡原因进行了调查。"}},{"en":"a discussion about something that has failed","cn":"（对失败的事进行的）讨论","ex":{"en":"An inquest was held on the team's poor performance.","cn":"对该队在比赛中的差劲表现进行了检讨。"}}]}},"inhibited":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"受抑制的;受约束的;拘谨的","en":"If you say that someone is inhibited, you mean they find it difficult to behave naturally and show their feelings, and that you think this is a bad thing.","ex":{"en":"We are rather inhibited about touching each other.","cn":"我们对身体接触感觉很不自在。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is reserved tries not to show their feelings to other people and does not talk a lot","cn":""},{"en":"not wanting to talk to anyone, especially because you are upset or unhappy","cn":""},{"en":"someone who is introverted thinks too much about their own interests or problems and it is difficult for them to talk to people","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If something is inhibited it is held back from doing something, the way the presence of your grandmother might inhibit you from cursing."}]},"collocations":{"phrases":["VERBS be, feel | become","ADV. very | rather, slightly | emotionally","PREP. about He was rather inhibited about discussing politics. | by She felt very inhibited by her own lack of experience. | from No one sho"]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdeinhibited.mp3","us":"media/ldoce/hwd/ame/7/inhibited.mp3"},"examples":[{"en":"Boys are often more inhibited than girls about discussing their problems.","cn":"男孩子往往不如女孩子敢于谈论自己的问题。"},{"en":"Many people are inhibited about discussing sexual matters.","cn":"很多人谈论性时都很拘束。"}],"oxford":{"phon":"ɪnˈhɪbɪtɪd","pos":"adjective","senses":[{"en":"unable to relax or express your feelings in a natural way","cn":"拘束的；拘谨的","ex":{"en":"She felt very inhibited by her own lack of experience.","cn":"她因为自己缺乏经验而觉得很拘谨。"}}]}},"inscribe":{"collins":{"senses":[{"pos":"VERB 动词","cn":"写;刻;雕","en":"If you inscribe words on an object, you write or carve the words on the object.","ex":{"en":"Some galleries commemorate donors by inscribing their names on the walls","cn":"一些美术馆把捐赠者的姓名镌刻在墙上以示纪念。"}},{"pos":"VERB 动词","cn":"题写;题献;题赠","en":"If you inscribe something in the front of a book or on a photograph, you write it there, often before giving it to someone.","ex":{"en":"On the back I had inscribed the words: 'Here's to Great Ideas! John'","cn":"在背后我题写了这样的话：“愿奇思妙想不绝！约翰”。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to carefully cut, print, or write words on something, especially on the surface of a stone or coin 〔","cn":"尤指在石头或硬币表面〕雕刻﹐印制﹐题写"}]},"vocab":{"pos":"1 v 2 v 3 v 4 v 5 v","senses":[{"en":"To inscribe means to write in a permanent way for example by carving. When someone tells you that they’re going to inscribe your name somewhere, be sure they get the spelling right because it’s going to be there a long time."}]},"collocations":{"phrases":["ADV. personally The volume had been personally inscribed by the author. | suitably He sent me a number of his books, all suitably inscribed.","PREP. on Her name was inscribed on the watch. | with The watch was inscribed with her name."]},"media":{"uk":"media/ldoce/hwd/bre/0/inscribe0205.mp3","us":"media/ldoce/hwd/ame/2/inscribe.mp3"},"examples":[{"en":"She signed the book and inscribed the words ‘with grateful thanks’ on it.","cn":"她在书上签了名，并在上面写道“谨致由衷感谢”。"},{"en":"His name was inscribed on the trophy.","cn":"他的名字刻在奖杯上。"}],"oxford":{"phon":"ɪnˈskraɪb","pos":"verb","senses":[{"en":"to write or cut words, your name, etc. onto something","cn":"在…上写（词语、名字等）；题；刻","lab":"figurative","ex":{"en":"His name was inscribed on the trophy.","cn":"他的名字刻在奖杯上。"}}]}},"inhuman":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不人道的;野蛮的;残酷的","en":"If you describe treatment or an action as inhuman, you mean that it is extremely cruel.","ex":{"en":"The detainees are often held in cruel and inhuman conditions","cn":"被拘留者的关押环境常常恶劣严酷、很不人道。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"非人类的;怪异可怕的","en":"If you describe someone or something as inhuman, you mean that they are strange or bad because they do not seem human in some way.","ex":{"en":"...inhuman shrieks that chilled my heart.","cn":"让我心惊胆寒的、异常恐怖的尖叫声"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"intended to upset someone or make them suffer","cn":""},{"en":"extremely cruel, in a way that shocks people","cn":""},{"en":"very cruel and not showing any of the pity or concern that normal people feel when they see other people suffering","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If someone behaves in a way that shows no compassion, you could describe that person and his or her actions as inhuman . A teacher who assigns six hours of homework every night might be seen as inhuman ."}]},"collocations":{"phrases":["VERBS be | consider sth, regard sth as We regard their treatment of the prisoners as inhuman.","ADV. positively What she proposes is positively inhuman! | totally, utterly | almost"]},"media":{"uk":"media/ldoce/hwd/bre/d/inhuman0205.mp3","us":"media/ldoce/hwd/ame/b/inhuman.mp3"},"examples":[{"en":"There was a strange inhuman sound.","cn":"有一种不像人发出的奇怪声音。"},{"en":"inhuman and degrading treatment","cn":"不人道的羞辱性对待"}],"oxford":{"phon":"ɪnˈhjuːmən","pos":"adjective","senses":[{"en":"not showing sympathy or kind feelings for people who are suffering; very cruel","cn":"没有人性的；残忍的","ex":{"en":"inhuman and degrading treatment","cn":"不人道的羞辱性对待"}},{"en":"not human; not seeming to be produced by a human and therefore frightening","cn":"非人的；（似非人所为而）恐怖的","ex":{"en":"There was a strange inhuman sound.","cn":"有一种不像人发出的奇怪声音。"}}]}},"inconclusive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无最后结果的;无结论的","en":"If research or evidence is inconclusive, it has not proved anything.","ex":{"en":"Research has so far proved inconclusive","cn":"目前研究尚无定论。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(竞赛、冲突)胜负不明的,无最后结果的","en":"If a contest or conflict is inconclusive, it is not clear who has won or who is winning.","ex":{"en":"The past two elections were inconclusive.","cn":"之前的两次选举都没有结果。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not leading to a clear decision or result","cn":"非结论性的﹐无确定结果的"}]},"vocab":{"pos":"adj","senses":[{"en":"If something's inconclusive , that means it doesn't lead to a conclusion or a resolution. Inconclusive often describes scientific results. If your data about a flu outbreak is inconclusive , then your results don't prove anything."}]},"collocations":{"phrases":["VERBS be, prove | remain","ADV. largely | fairly, rather, somewhat | apparently | ultimately | curiously the curiously inconclusive finish to the symphony"]},"media":{"uk":"media/ldoce/hwd/bre/5/inconclusive0205.mp3","us":"media/ldoce/hwd/ame/4/inconclusive.mp3"},"examples":[{"en":"The last meeting had ended inconclusively.","cn":"上一次会议没有结果。"},{"en":"inconclusive evidence/results/tests","cn":"没有说服力的证据；无定论的结果/试验"}],"oxford":{"phon":"ˌɪnkənˈkluːsɪv","pos":"adjective","senses":[{"en":"not leading to a definite decision or result","cn":"非决定性的；无定论的；不确定的","ex":{"en":"inconclusive evidence/results/tests","cn":"没有说服力的证据；无定论的结果／试验"}}]}},"initiation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"开始;创始;发起","en":"The initiation of something is the starting of it.","ex":{"en":"They announced the initiation of a rural development programme","cn":"他们宣布启动一项农村发展计划。"}},{"pos":"N-VAR 可变名词","cn":"(常包含特殊仪式的)入会，加入","en":"Someone's initiation into a particular group is the act or process by which they officially become a member, often involving special ceremonies.","ex":{"en":"After initiation, the youths started to interact with the older members","cn":"入会仪式后,这些小伙子与老成员开始互动。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the process of officially introducing someone into a club or group, or of introducing a young person to adult life, often with a special ceremony 〔","cn":"常指通过特别仪式的〕入会﹔〔青年男女的〕成年"},{"en":"the act of starting something such as an official process, a new plan etc 〔","cn":"正式程序﹑新计划等的〕发起﹐实施"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"The initiation of something is the beginning. It's what sets events in motion, gets the party underway, or kicks off a new program."}]},"collocations":{"phrases":["INITIATION + NOUN ceremony, rite, ritual an initiation ceremony for new members of the organization","PREP. ~ into It was my initiation into the world of high fashion.","PHRASES a ceremony/rite of initiation"]},"media":{"uk":"media/ldoce/hwd/bre/1/initiation0205.mp3","us":"media/ldoce/hwd/ame/8/laadinitiation.mp3"},"examples":[{"en":"her initiation into the world of marketing","cn":"她的初次涉足营销界"},{"en":"the initiation of criminal proceedings","cn":"提起刑事诉讼"}],"oxford":{"phon":"ɪˌnɪʃiˈeɪʃn","pos":"noun","senses":[{"en":"the act of somebody becoming a member of a group, often with a special ceremony; the act of introducing somebody to an activity or skill","cn":"（常指通过特别仪式的）入会；介绍某人初试某活动（或技艺）","ex":{"en":"There was an established initiation ceremony for new boys.","cn":"对于新来的男孩，有一种既定的入会仪式。"}},{"en":"the act of starting something","cn":"开始；创始；发起","lab":"formal","ex":{"en":"It is generally the police who deal with the initiation of criminal proceedings.","cn":"通常由警察负责启动刑事诉讼。"}}]}},"incompatible":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不能和谐相处的;不协调的;不一致的","en":"If one thing or person is incompatible with another, they are very different in important ways, and do not suit each other or agree with each other.","ex":{"en":"They feel strongly that their religion is incompatible with the political system","cn":"他们强烈感受到他们的宗教信仰与政治体制不相称。"}},{"pos":"ADJ 形容词","cn":"不兼容的;不相容的;互斥的","en":"If one type of computer or computer system is incompatible with another, they cannot use the same programs or be linked up together.","ex":{"en":"This made its mini-computers incompatible with its mainframes","cn":"这就使得它的微型计算机与它的大型主机不兼容。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not having the right qualities for a particular person, purpose, or situation","cn":""},{"en":"not suitable for a particular situation or purpose – used especially about someone’s behaviour or language","cn":""},{"en":"not the right thing or person for a particular job or purpose","cn":""}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"Use the adjective incompatible to describe things or people that are too different to get along. When paired with someone you can't work with, don't criticize or get mad. Just say, \"We are incompatible .\""}]},"collocations":{"phrases":["VERBS appear, be, prove, seem | become | consider sth, see sth as","ADV. completely, entirely, quite, totally, wholly | increasingly | by no means, not entirely, not necessarily Scepticism and trust are not n","PREP. with This behaviour is completely incompatible with his role as a teacher."]},"media":{"uk":"media/ldoce/hwd/bre/b/incompatible0205.mp3","us":"media/ldoce/hwd/ame/f/incompatible.mp3"},"examples":[{"en":"New computer software is often incompatible with older computers.","cn":"新的计算机软件往往和旧式计算机不兼容。"},{"en":"The hours of the job are incompatible with family life.","cn":"这份工作的上班时间和家庭生活有冲突。"}],"oxford":{"phon":"ˌɪnkəmˈpætəbl","pos":"adjective","senses":[{"en":"two actions, ideas, etc. that are incompatible are not acceptable or possible together because of basic differences","cn":"（与某事物）不一致，不相配","ex":{"en":"The hours of the job are incompatible with family life.","cn":"这份工作的上班时间和家庭生活有冲突。"}},{"en":"two people who are incompatible are very different from each other and so are not able to live or work happily together","cn":"（与某人）合不来，不能和睦相处","ex":{"en":"She and her husband soon proved to be totally incompatible.","cn":"她和她的丈夫很快就被证明是完全不相容的。"}},{"en":"two things that are incompatible are of different types so that they cannot be used or mixed together","cn":"（与某物）不匹配；配伍禁忌的；不兼容；互斥","ex":{"en":"New computer software is often incompatible with older computers.","cn":"新的计算机软件往往和旧式计算机不兼容。"}}]}},"intercom":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"内部通话系统(或设备);对讲机","en":"An intercom is a small box with a microphone which is connected to a loudspeaker in another room. You use it to talk to the people in the other room."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a communication system by which people in different parts of a building, aircraft etc can speak to each other 〔","cn":"楼房﹑飞机等的〕内部通话系统"}]},"collocations":{"phrases":["INTERCOM + VERB buzz, sound","INTERCOM + NOUN system","PREP. on the ~ I spoke to her on the intercom and said I'd call round later. | over the ~ Mr Jack's arrival was announced over the intercom."]},"media":{"uk":"media/ldoce/hwd/bre/f/intercom0205.mp3","us":"media/ldoce/hwd/ame/3/intercom.mp3"},"examples":[{"en":"They called him on the intercom.","cn":"他们用内部通话系统呼叫他。"},{"en":"to announce sth over the intercom","cn":"通过内部通话系统宣布"}],"oxford":{"phon":"ˈɪntəkɒm","pos":"noun","senses":[{"en":"a system of communication by phone or radio inside an office, plane, etc.; the device you press or switch on to start using this system","cn":"内部通话系统（或设备）","ex":{"en":"to announce something over the intercom","cn":"通过内部通话系统宣布"}}]}},"indecency":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"下流;有伤风化;猥亵","en":"If you talk about the indecency of something or someone, you are indicating that you find them morally or sexually offensive.","ex":{"en":"...the indecency of their language.","cn":"他们言语粗俗"}},{"pos":"N-UNCOUNT 不可数名词","cn":"非法性行为","en":"In law, an act of indecency is an illegal sexual act.","ex":{"en":"They were found guilty of acts of gross indecency.","cn":"他们因存在严重猥亵行为而被判有罪。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"behaviour that is sexually offensive, especially indecent exposure","cn":"猥亵﹐下流〔尤指猥亵露体〕"},{"en":"an action that is shocking or offensive","cn":"下流的动作"}]},"collocations":{"phrases":["ADJ. gross | public","PHRASES an act of indecency • Note at CRIME (for verbs)"]},"media":{"uk":"media/ldoce/hwd/bre/3/indecency0205.mp3","us":"media/ldoce/hwd/ame/d/laadindecency.mp3"},"examples":[{"en":"an act of gross indecency (= a sexual act that is a criminal offence)","cn":"严重猥亵（罪）"}],"oxford":{"phon":"ɪnˈdiːsnsi","pos":"noun","senses":[{"en":"behaviour that is thought to be morally or sexually offensive","cn":"下流的行为；猥亵","g":"[uncountable]","ex":{"en":"He was appalled by the indecency of their songs.","cn":"他对他们歌曲的不雅行为感到震惊。"}},{"en":"an indecent act, expression, etc.","cn":"下流的动作（或表情等）","g":"[countable, usually singular]","ex":{"en":"He shouted indecencies at anyone who passed.","cn":"他对任何经过的人大喊下流话。"}}]}},"inquisitive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"爱打听的;好探问的;过于好奇的","en":"An inquisitive person likes finding out about things, especially secret things.","ex":{"en":"Barrow had an inquisitive nature","cn":"巴罗天生就爱打听别人隐私。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"wanting to find out about someone or something because you are very interested in them","cn":""},{"en":"the desire to find out about things","cn":""},{"en":"always wanting to find out about what people are doing, how things work, what is happening etc","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you are inquisitive that means you love to inquire; you’re always asking questions. Don’t become a private detective if you don’t have an inquisitive personality."}]},"collocations":{"phrases":["VERBS appear, be, seem | become","ADV. highly, very a highly inquisitive mind | naturally Children are naturally inquisitive. | incurably","PREP. about We try not to be too inquisitive about what he's doing."]},"media":{"uk":"media/ldoce/hwd/bre/1/inquisitive0205.mp3","us":"media/ldoce/hwd/ame/4/inquisitive.mp3"},"examples":[{"en":"Don't be so inquisitive. It's none of your business!","cn":"别这么追根问底的。这与你无关！"},{"en":"an inquisitive mind","cn":"勤学好问的精神"}],"oxford":{"phon":"ɪnˈkwɪzətɪv","pos":"adjective","senses":[{"en":"asking too many questions and trying to find out about what other people are doing, etc.","cn":"过分打听他人私事的","lab":"disapproving","ex":{"en":"Don't be so inquisitive. It's none of your business!","cn":"别这么追根问底的。这与你无关！"}},{"en":"very interested in learning about many different things","cn":"好学的；好奇的；兴趣广泛的","ex":{"en":"a highly inquisitive mind","cn":"非常好学的头脑"}}]}},"inspect":{"collins":{"senses":[{"pos":"VERB 动词","cn":"检查;审视","en":"If you inspect something, you look at every part of it carefully in order to find out about it or check that it is all right.","ex":{"en":"Elaine went outside to inspect the playing field","cn":"伊莱恩走到外面查看操场。"}},{"pos":"VERB 动词","cn":"视察;检阅","en":"When an official inspects a place or a group of people, they visit it and check it carefully, for example in order to find out whether regulations are being obeyed.","ex":{"en":"The Public Utilities Commission inspects us once a year","cn":"公共事业委员会每年到我们这里视察一次。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to look at something carefully and thoroughly because you want to find out more about it","cn":""},{"en":"to quickly examine something to find out what is wrong with it or to find out more about it. Have a look at is less formal than examine , and is the usual phrase to use in everyday English","cn":""},{"en":"to examine something carefully to make sure that it is correct, safe, or working properly, especially when it is your job to do this","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you inspect something, you look at it carefully. When you're buying a used car, you should inspect it inside and out, and if you don't know much about what goes on under the hood, you should have a mechanic inspect it, too."}]},"collocations":{"phrases":["ADV. carefully, closely, thoroughly | regularly","VERB + INSPECT allow sb to, be entitled to Each party in the case is entitled to inspect the documents held by the other.","PREP. for He inspected the water tank carefully for cracks."]},"media":{"uk":"media/ldoce/hwd/bre/c/inspect0205.mp3","us":"media/ldoce/hwd/ame/2/inspect.mp3"},"examples":[{"en":"Public health officials were called in to inspect the premises.","cn":"公共卫生官员奉召来视察了建筑物。"},{"en":"Make sure you inspect the goods before signing for them.","cn":"要确保在签收货物之前进行检验。"}],"oxford":{"phon":"ɪnˈspekt","pos":"verb","senses":[{"en":"to look closely at something/somebody, especially to check that everything is as it should be","cn":"检查；查看；审视","ex":{"en":"The teacher walked around inspecting their work.","cn":"老师走来走去检查他们的作业。"}},{"en":"to officially visit a school, factory, etc. in order to check that rules are being obeyed and that standards are acceptable","cn":"视察","ex":{"en":"Public health officials were called in to inspect the premises.","cn":"公共卫生官员奉召来视察了建筑物。"}}]}},"ingenuity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"心灵手巧;善于创造发明","en":"Ingenuity is skill at working out how to achieve things or skill at inventing new things.","ex":{"en":"Inspecting the nest may require some ingenuity.","cn":"探查鸟巢是需要些技巧的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"skill at inventing things and thinking of new ideas","cn":"心灵手巧﹐善于创造发明﹔足智多谋"}]},"vocab":{"pos":"n","senses":[{"en":"Ingenuity is the ability to think creatively about a situation or to solve problems in a clever way. If you want to build a boat out of toothpicks and yarn, you’ll need a lot of ingenuity ."}]},"collocations":{"phrases":["ADJ. considerable, great | intellectual, technical | human","QUANT. amount, degree Getting out of this mess was going to require a fair degree of ingenuity.","VERB + INGENUITY have someone who has the ingenuity to solve problems | apply, use There is always a solution, so long as you are prepared t","PREP. with ~ They adapted the available materials with great ingenuity. | ~ in We have to admire his ingenuity in redesigning the machinery."]},"media":{"uk":"media/ldoce/hwd/bre/b/ingenuity0205.mp3","us":"media/ldoce/hwd/ame/3/ingenuity.mp3"},"oxford":{"phon":"ˌɪndʒəˈnjuːəti","pos":"noun","senses":[{"en":"the ability to invent things or solve problems in clever new ways","cn":"独创力；聪明才智；心灵手巧","ex":{"en":"The problem tested the ingenuity of even the most imaginative students.","cn":"即使是最有想象力的学生，这个问题也考验着他们的聪明才智。"}}]}},"indiscretion":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"不慎重;轻率;言行失检","en":"If you talk about someone's indiscretion, you mean that they have done or said something that is risky, careless, or likely to upset people.","ex":{"en":"Occasionally they paid for their indiscretion with their lives.","cn":"有时候他们因自己的轻率而搭上性命。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something you do or decide that is not at all sensible and causes you a lot of problems","cn":""},{"en":"a mistake caused by planning something badly, and being wrong about the expected result","cn":""},{"en":"a mistake caused by judging a situation or person wrongly","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If you commit an indiscretion you are doing something wrong that shows a lack of judgment. Perhaps stealing candy was your first indiscretion . Likely it will not be your last."}]},"collocations":{"phrases":["ADJ. serious | minor, slight, small | personal | political | youthful | dietary, sexual","VERB + INDISCRETION commit He had committed a minor sexual indiscretion. | regret I instantly regretted my indiscretion and asked her to kee"]},"media":{"uk":"media/ldoce/hwd/bre/f/indiscretion0205.mp3","us":"media/ldoce/hwd/ame/a/indiscretion.mp3"},"examples":[{"en":"He talked to the press in a moment of indiscretion.","cn":"他一时冲动对新闻界发表了讲话。"},{"en":"youthful indiscretions","cn":"年轻人的不检点行为"}],"oxford":{"phon":"ˌɪndɪˈskreʃn","pos":"noun","senses":[{"en":"an act or remark that reveals something secret or that could be embarrassing or offensive","cn":"不慎的言行；粗鲁的言行","g":"[countable]","ex":{"en":"youthful indiscretions","cn":"年轻人的不检点行为"}},{"en":"the act of saying or doing something without thinking about the effect it may have, especially when this reveals something secret or something that could be embarrassing or offensive","cn":"轻率；鲁莽","g":"[uncountable]","ex":{"en":"He talked to the press in a moment of indiscretion.","cn":"他一时冲动对新闻界发表了讲话。"}}]}},"insecure":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"缺乏自信的;对自己无把握的","en":"If you are insecure, you lack confidence because you think that you are not good enough or are not loved.","ex":{"en":"In effect she is punishing her parents for making her feel threatened and insecure","cn":"实质上她是在惩罚父母,因为他们让她感觉受到威胁,没有安全感。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不安全的;无保障的;有危险的","en":"Something that is insecure is not safe or protected.","ex":{"en":"...low-paid, insecure jobs","cn":"报酬低、无保障的工作"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to not be confident about your abilities or appearance","cn":""},{"en":"not confident about meeting or speaking to people who you do not know","cn":""},{"en":"not confident about yourself or your relationships, especially because you are worried that you are not good enough","cn":""}]},"vocab":{"pos":"1 adj 2 adj 3 adj","senses":[{"en":"Insecure means either lacking self-confidence or lacking security. An insecure person might constantly doubt their own intelligence. An insecure building is an easy target for even the most bumbling burglar."}]},"collocations":{"phrases":["VERBS appear, be, look, seem | become | remain","ADV. extremely, very | increasingly | a little, rather, somewhat | financially men who are worried about losing their jobs and becoming fina","VERBS be, feel | become, grow","ADV. deeply, extremely, profoundly, really, very | increasingly | a bit, a little, quite, rather | basically | notoriously a star who is not","PREP. about He felt a bit insecure about being left alone."]},"media":{"uk":"media/ldoce/hwd/bre/3/insecure0205.mp3","us":"media/ldoce/hwd/ame/2/insecure.mp3"},"examples":[{"en":"As an artist he was always financially insecure.","cn":"作为一名艺术家，他在经济上总是没有保障。"},{"en":"Jobs nowadays are much more insecure than they were ten years ago.","cn":"当今的工作比十年前要不稳固得多了。"}],"oxford":{"phon":"ˌɪnsɪˈkjʊə(r)","pos":"adjective","senses":[{"en":"not confident about yourself or your relationships with other people","cn":"缺乏信心的；无把握的","ex":{"en":"He's very insecure about his appearance.","cn":"他对自己的长相很没信心。"}},{"en":"not safe or protected","cn":"不安全的；无保障的；不牢靠的","ex":{"en":"Jobs nowadays are much more insecure than they were ten years ago.","cn":"当今的工作比十年前要不安稳得多了。"}},{"en":"likely to move, fall down, etc.","cn":"摇摇欲坠的；不稳固的","ex":{"en":"an insecure ladder/footbridge","cn":"不牢固的梯子／人行桥"}}]}},"indestructible":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不可摧毁的;不可毁坏的","en":"If something is indestructible, it is very strong and cannot be destroyed.","ex":{"en":"This type of plastic is almost indestructible.","cn":"这种塑料几乎牢不可破。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not easily broken or damaged","cn":""},{"en":"strong – used especially about something that can be used a lot without damaging it or making it weaker","cn":""},{"en":"extremely strong – used about materials, tools, machines etc that are made especially to be used a lot without being easily damaged","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that's indestructible can't be broken or destroyed. Your indestructible winter boots last year after year, stomping through snow and ice and salt without ever falling apart."}]},"collocations":{"phrases":["VERBS be, prove, seem","ADV. completely | almost, virtually Their shells are so hard they are virtually indestructible. | seemingly"]},"media":{"uk":"media/ldoce/hwd/bre/9/indestructible0205.mp3","us":"media/ldoce/hwd/ame/a/indestructible.mp3"},"examples":[{"en":"plastic containers that are virtually indestructible","cn":"几乎不可毁坏的塑料容器"},{"en":"an indestructible bond of friendship","cn":"坚不可摧的友谊纽带"}],"oxford":{"phon":"ˌɪndɪˈstrʌktəbl","pos":"adjective","senses":[{"en":"that is very strong and cannot easily be destroyed","cn":"不可摧毁的；破坏不了的","ex":{"en":"plastic containers that are virtually indestructible","cn":"几乎不可毁坏的塑料容器"}}]}},"intervene":{"collins":{"senses":[{"pos":"VERB 动词","cn":"干涉;干预;介入","en":"If you intervene in a situation, you become involved in it and try to change it.","ex":{"en":"The situation calmed down when police intervened","cn":"警方干预后，局势平息下来。"}},{"pos":"VERB 动词","cn":"插话;打岔","en":"If you intervene, you interrupt a conversation in order to add something to it.","ex":{"en":"Hattie intervened and told me to stop it","cn":"哈蒂打断我，叫我停下来。"}},{"pos":"VERB 动词","cn":"干扰;阻挠;打扰","en":"If an event intervenes, it happens suddenly in a way that stops, delays, or prevents something from happening.","ex":{"en":"The South African mailboat arrived on Friday mornings unless bad weather intervened","cn":"除非受恶劣天气干扰,南非邮船一般在星期五上午抵达。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to do something to deal with a problem, especially one that is urgent","cn":""},{"en":"to do something to stop a bad situation from happening or continuing - use this to talk about people who have a clear plan for dealing with a problem","cn":""},{"en":"to use your power or authority to deal with an urgent problem","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"From the Latin \"intervenire,\" meaning “to come between,” the verb intervene means just that: to get involved, to jump in the middle of something, to interfere."}]},"collocations":{"phrases":["ADV. actively, directly | personally | decisively | effectively, successfully | militarily Intervening militarily will not bring peace.","VERB + INTERVENE be forced to, have to Eventually, the army was forced to intervene. | be reluctant to | be powerless to Local people feel s","PREP. against They would not intervene against the rebels themselves. | between She went over to intervene between the two men. | in She was"]},"media":{"uk":"media/ldoce/hwd/bre/f/intervene0205.mp3","us":"media/ldoce/hwd/ame/c/intervene.mp3"},"examples":[{"en":"They were planning to get married and then the war intervened.","cn":"他们正准备结婚，不巧却因爆发战事而受阻。"},{"en":"‘But,’ she intervened, ‘what about the others?’ “","cn":"但是，”她插嘴说，“其他的怎么办呢？”"}],"oxford":{"phon":"ˌɪntəˈviːn","pos":"verb","senses":[{"en":"to become involved in a situation in order to improve or help it","cn":"出面；介入","g":"[intransitive]","ex":{"en":"She might have been killed if the neighbours hadn't intervened.","cn":"要不是邻居介入，她可能会没命了。"}},{"en":"to interrupt somebody when they are speaking in order to say something","cn":"插嘴；打断（别人的话）","g":"[transitive, intransitive]","ex":{"en":"‘But,’ she intervened, ‘what about the others?’","cn":"“但是，”她插嘴说，“其他的怎么办呢？”"}},{"en":"to happen in a way that delays something or prevents it from happening","cn":"阻碍；阻挠；干扰","g":"[intransitive]","ex":{"en":"They were planning to get married and then the war intervened.","cn":"他们当时正准备结婚，却因爆发战事而受阻。"}},{"en":"to exist between two events or places","cn":"介于…之间","g":"[intransitive]","lab":"formal","ex":{"en":"I saw nothing of her during the years that intervened.","cn":"这期间的几年中我根本没有见过她。"}}]}},"inaccurate":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不精确的;不准确的","en":"If a statement or measurement is inaccurate, it is not accurate or correct.","ex":{"en":"The book is both inaccurate and exaggerated","cn":"这本书不但不准确,而且夸大其词。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not correct or right – used about facts, answers etc, or people","cn":""},{"en":"something that is incorrect is wrong because someone has made a mistake. Incorrect is more formal than wrong","cn":""},{"en":"something that is inaccurate is not exactly right and contains mistakes","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If what you tell me is not exactly right, it is inaccurate . If you measured the amount of rainfall incorrectly, your data about the climate would be inaccurate ."}]},"collocations":{"phrases":["VERBS be, prove | become","ADV. extremely, grossly, hopelessly, seriously, terribly, very, wildly a wildly inaccurate account of events | quite, totally, wholly | a bi"]},"media":{"uk":"media/ldoce/hwd/bre/6/inaccurate0205.mp3","us":"media/ldoce/hwd/ame/c/inaccurate.mp3"},"examples":[{"en":"The writer is guilty of bias and inaccuracy.","cn":"这位作者失于偏颇，且叙述不实。"},{"en":"All the maps we had were wildly inaccurate.","cn":"我们所有的地图误差都非常大。"}],"oxford":{"phon":"ɪnˈækjərət","pos":"adjective","senses":[{"en":"not exact or accurate; with mistakes","cn":"不精确的；不准确的；有错误的","ex":{"en":"an inaccurate statement","cn":"不确切的说法"}}]}},"intrusion":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"打扰;侵扰","en":"If someone disturbs you when you are in a private place or having a private conversation, you can call this event an intrusion .","ex":{"en":"I hope you don't mind this intrusion, Jon.","cn":"乔恩,希望你别介意这次打扰。"}},{"pos":"N-VAR 可变名词","cn":"干扰;影响","en":"An intrusion is something that disturbs your mood or your life in a way you do not like.","ex":{"en":"...intrusion into private grief","cn":"对个人不幸的搅扰"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when someone does something, or something happens, that affects your private life or activities in an unwanted way 〔","cn":"讨厌的事或人的〕干扰﹐侵扰"},{"en":"when something comes into a place or situation and has an unwanted effect 〔","cn":"对某种情况或地区的〕闯入﹐侵入"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"An intrusion is a deliberate move into someone else's territory — either literal or figurative. When your sister interrupts your conversation with that girl from math class, that's an intrusion . If someone breaks into your home, that's also an intrusion ."}]},"collocations":{"phrases":["ADJ. media, press | unnecessary, unwanted, unwarranted, unwelcome","VERB + INTRUSION resent","PREP. ~ in I really resented his intrusion in a family matter. | ~ into media intrusion into the lives of celebrities | ~ on/upon an unwarra"]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41intrusion.mp3","us":"media/ldoce/hwd/ame/4/intrusion.mp3"},"examples":[{"en":"They claim the noise from the new airport is an intrusion on their lives.","cn":"他们声称新机场的噪音侵扰了他们的生活。"},{"en":"This was another example of press intrusion into the affairs of the royals.","cn":"这是新闻界侵扰王室成员私事的又一实例。"}],"oxford":{"phon":"ɪnˈtruːʒn","pos":"noun","senses":[{"en":"something that affects a situation or people’s lives in a way that they do not want","cn":"侵扰性的事物；扰乱；侵犯","ex":{"en":"They claim the noise from the new airport is an intrusion on their lives.","cn":"他们声称新机场的噪声侵扰了他们的生活。"}},{"en":"the act of entering a place that is private or where you may not be wanted","cn":"闯入；侵入","lab":"formal","ex":{"en":"She apologized for the intrusion but said she had an urgent message.","cn":"她为径自闯进来道歉，但说她有紧急消息。"}}]}},"incest":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"乱伦罪","en":"Incest is the crime of two members of the same family having sexual intercourse, for example a father and daughter, or a brother and sister."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"sex between people who are closely related in a family","cn":"乱伦"}]},"vocab":{"pos":"n","senses":[{"en":"Incest is a word for any kind of sex between family members: parent and child, brother and sister, or cousin and cousin."}]},"collocations":{"phrases":["ADJ. brother-sister, father-daughter, etc.","VERB + INCEST criminalize, forbid, prohibit taboos forbidding incest","INCEST + NOUN survivor, victim | taboo","PREP. ~ between incest between brother and sister • Note at CRIME (for more verbs)"]},"media":{"uk":"media/ldoce/hwd/bre/c/incest0205.mp3","us":"media/ldoce/hwd/ame/8/incest.mp3"},"examples":[{"en":"Abortions would only be allowed in cases of rape or incest.","cn":"只有被强奸或乱伦受孕才允许堕胎。"}],"oxford":{"phon":"ˈɪnsest","pos":"noun","senses":[{"en":"sexual activity between two people who are very closely related in a family, for example, a brother and sister, or a father and daughter","cn":"乱伦；血亲相奸","ex":{"en":"incest between brother and sister","cn":"兄妹／姐弟之间的乱伦"}}]}},"inhale":{"collins":{"senses":[{"pos":"VERB 动词","cn":"吸气;吸入(烟等)","en":"When you inhale, you breathe in. When you inhale something such as smoke, you take it into your lungs when you breathe in.","ex":{"en":"He took a long slow breath, inhaling deeply","cn":"他缓缓地深吸了一口气。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to take air, smoke etc into your lungs, through your nose or mouth","cn":""},{"en":"to breathe in once","cn":""},{"en":"to take air, smoke, or gas into your lungs, through your nose or mouth - used especially in technical and medical contexts","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To inhale is to breathe in. It is the opposite of \"exhale,\" which is to breathe out."}]},"collocations":{"phrases":["ADV. deeply | sharply Janet inhaled sharply when she saw him. | slowly"]},"media":{"uk":"media/ldoce/hwd/bre/0/inhale0205.mp3","us":"media/ldoce/hwd/ame/3/inhale.mp3"},"examples":[{"en":"Local residents needed hospital treatment after inhaling fumes from the fire.","cn":"当地居民吸入了大火的浓烟，需要入院治疗。"},{"en":"Hundreds of children were treated for smoke inhalation.","cn":"数以百计的儿童因吸入浓烟而接受了治疗。"}],"oxford":{"phon":"ɪnˈheɪl","pos":"verb","senses":[{"en":"to take air, smoke, gas, etc. into your lungs as you breathe","cn":"吸入；吸气","ex":{"en":"She closed her eyes and inhaled deeply.","cn":"她合上双眼，深深吸了一口气。"}}]}},"instantaneous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"瞬间的;即刻的","en":"Something that is instantaneous happens immediately and very quickly.","ex":{"en":"Death was instantaneous because both bullets hit the heart.","cn":"因为两颗子弹都击中了心脏,所以死亡是瞬间发生的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"happening immediately, without any delay or doubt","cn":""},{"en":"very nearly at the same time as something else happens, and often as a result of it","cn":""},{"en":"happening immediately","cn":"即刻的﹐即时的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something instantaneous is happening right now, without delay. In today's society, the technology we carry in our pockets means people often expect an instantaneous or immediate response to emails and text messages."}]},"collocations":{"phrases":["VERBS be Her death was almost instantaneous.","ADV. almost, virtually"]},"media":{"uk":"media/ldoce/hwd/bre/2/instantaneous0205.mp3","us":"media/ldoce/hwd/ame/0/instantaneous.mp3"},"examples":[{"en":"Death was almost instantaneous.","cn":"当时生命垂危。"},{"en":"an instantaneous response","cn":"即时的反应"}],"oxford":{"phon":"ˌɪnstənˈteɪniəs","pos":"adjective","senses":[{"en":"happening immediately","cn":"立即的；立刻的；瞬间的","ex":{"en":"an instantaneous response","cn":"即时的反应"}}]}},"ingredient":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"成分;(烹调的)原料","en":"Ingredients are the things that are used to make something, especially all the different foods you use when you are cooking a particular dish.","ex":{"en":"Mix in the remaining ingredients.","cn":"混入其余的原料。"}},{"pos":"N-COUNT 可数名词","cn":"要素;因素","en":"An ingredient of a situation is one of the essential parts of it.","ex":{"en":"The meeting had all the ingredients of high political drama","cn":"这次会议具备了作为高度戏剧性的政治事件的一切要素。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small part of an object or area","cn":""},{"en":"one of several different parts that must be joined together to make something","cn":""},{"en":"one of the separate parts of a machine or a system, that is necessary to make the machine or system work","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An ingredient is one part of a mixture. For example, if you're making chocolate chip cookies, flour is just one ingredient you'll need."}]},"collocations":{"phrases":["ADJ. excellent, good It always pays to use the best ingredients when cooking. | main, major, principal the principal ingredient of smog | im","VERB + INGREDIENT use I only use natural ingredients. | add, pour in/on/over Mix the marinade ingredients and pour over the goose. | blend, ","PHRASES a list of ingredients All food products should carry a list of ingredients on the packet. •","ADJ. crucial, essential, fundamental, important, key, vital Hard work is a vital ingredient for success. | main, major, principal | basic, n","VERB + INGREDIENT have The Australian team had the added ingredient of perseverance. | provide, supply She hopes the change of career will s","PREP. ~ for Tolerance is an essential ingredient for a happy marriage. | ~ in Individualism has been the secret ingredient in developing his","PHRASES an ingredient for success"]},"media":{"uk":"media/ldoce/hwd/bre/1/ingredient0205.mp3","us":"media/ldoce/hwd/ame/f/ingredient.mp3"},"examples":[{"en":"It has all the ingredients of a good mystery story.","cn":"它具备一个好的玄幻故事的所有要素。"},{"en":"Coconut is a basic ingredient for many curries.","cn":"椰子是多种咖喱菜的基本成分。"}],"oxford":{"phon":"ɪnˈɡriːdiənt","pos":"noun","senses":[{"en":"one of the things from which something is made, especially one of the foods that are used together to make a particular dish","cn":"成分；（尤指烹饪）材料","ex":{"en":"Mix all the ingredients in a bowl.","cn":"将原料放在盆里调匀。"}},{"en":"one of the things or qualities that are necessary to make something successful","cn":"（成功的）因素，要素","ex":{"en":"It has all the ingredients of a good mystery story.","cn":"它具备一个好的悬疑小说的所有要素。"}}]}},"intestine":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"肠","en":"Your intestines are the tubes in your body through which food passes when it has left your stomach.","ex":{"en":"This area is always tender to the touch if the intestines are not functioning properly","cn":"如果肠功能不正常,这个部位碰一下就会感到疼痛。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the long tube in your body through which food passes after it leaves your stomach","cn":"肠"}]},"collocations":{"phrases":["ADJ. large, small","PREP. along the ~, in the ~ bacteria in the small intestine | through the ~","PHRASES the wall of the intestine"]},"media":{"img":["media/ldoce/img/body.jpg"],"uk":"media/ldoce/hwd/bre/8/intestine0205.mp3","us":"media/ldoce/hwd/ame/2/intestine.mp3"},"oxford":{"phon":"ɪnˈtestɪn","pos":"noun","senses":[{"en":"a long tube in the body between the stomach and the anus. Food passes from the stomach to the small intestine and from there to the large intestine.","cn":"肠","ex":{"en":"bacteria in the small intestine","cn":"小肠中的细菌"}}]}},"inexplicable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无法说明的;费解的","en":"If something is inexplicable, you cannot explain why it happens or why it is true.","ex":{"en":"His behaviour was extraordinary and inexplicable","cn":"他的行为不同寻常,让人费解。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"difficult to explain or understand, and often strange or slightly frightening","cn":""},{"en":"difficult to explain or understand","cn":""},{"en":"impossible to understand, so that you feel very confused","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something inexplicable can't be explained. It doesn't make sense. You don't want to come to the beach on the most beautiful day of the year? That's inexplicable !"}]},"collocations":{"phrases":["VERBS be, seem | remain | find sth","ADV. completely, quite, totally Their actions are completely inexplicable. | apparently | otherwise This theory makes sense of an otherwise "]},"media":{"uk":"media/ldoce/hwd/bre/1/inexplicable0205.mp3","us":"media/ldoce/hwd/ame/b/inexplicable.mp3"},"examples":[{"en":"For some inexplicable reason he gave up a fantastic job.","cn":"由于某种莫名其妙的原因，他放弃了一份很不错的工作。"},{"en":"She inexplicably withdrew the offer.","cn":"她不可思议地撤回了提议。"}],"oxford":{"phon":"ˌɪnɪkˈsplɪkəbl","pos":"adjective","senses":[{"en":"that cannot be understood or explained","cn":"费解的；无法解释的","ex":{"en":"inexplicable behaviour","cn":"令人费解的行为"}}]}},"inheritance":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"遗产;继承物","en":"An inheritance is money or property which you receive from someone who has died.","ex":{"en":"She feared losing her inheritance to her stepmother.","cn":"她担心她继承的遗产会被继母夺走。"}},{"pos":"N-COUNT 可数名词","cn":"转接物;沿袭物","en":"If you get something such as job, problem, or attitude from someone who used to have it, you can refer to this as an inheritance .","ex":{"en":"...the situation that was Truman's inheritance as President.","cn":"杜鲁门继任总统时面临的状况"}},{"pos":"N-SING 单数名词","cn":"得自遗传的特征","en":"Your inheritance is the particular characteristics or qualities which your family or ancestors had and which you are born with.","ex":{"en":"Eye colour shows your genetic inheritance.","cn":"眼睛的颜色显示你的基因遗传特征。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"money, property etc that you receive from someone who has died 〔","cn":"钱财等〕继承物﹐遗产"},{"en":"physical or mental qualities that you inherit from your family","cn":"遗传特征"},{"en":"ideas, skills, literature etc from the past that influence people in the present","cn":"遗产〔指对现在的人有影响的过去的思想﹑技艺﹑文学等〕"}]},"vocab":{"pos":"n","senses":[{"en":"Any money or property you receive after the death of a friend or relative is an inheritance . Your grandmother might have left you a small inheritance , but she left the bulk of her estate to her Chihuahua, Killer."}]},"collocations":{"phrases":["ADJ. large | small | rightful (literary) He accused his younger brother of trying to steal his rightful inheritance. | shared","VERB + INHERITANCE leave sb She left him an inheritance of &pound; 100,000. | come into, enter (into/on/upon) (literary) , receive When he w","INHERITANCE + NOUN tax | law","PREP. ~ by The system involved inheritance by the eldest son. | ~ through inheritance through marriage 2 sth from the past/your family","PREP. common a common inheritance of language and culture | cultural | genetic, physical | classical the influence of the classical inherita"]},"media":{"uk":"media/ldoce/hwd/bre/4/inheritance0205.mp3","us":"media/ldoce/hwd/ame/c/inheritance.mp3"},"examples":[{"en":"She spent all her inheritance in a year.","cn":"她在一年之内用完了所有继承的遗产。"},{"en":"Physical characteristics are determined by genetic inheritance.","cn":"身体的特征取决于基因遗传。"}],"oxford":{"phon":"ɪnˈherɪtəns","pos":"noun","senses":[{"en":"the money, property, etc. that you receive from somebody when they die; the fact of receiving something when somebody dies","cn":"继承物（如金钱、财产等）；遗产；继承","g":"[countable, uncountable]","lab":"informal","ex":{"en":"She spent all her inheritance in a year.","cn":"她在一年之内花光了所有继承的遗产。"}},{"en":"something from the past or from your family that affects the way you behave, look, etc.","cn":"遗传特征；遗产","g":"[uncountable, countable, usually singular]","ex":{"en":"We are proud of our cultural inheritance.","cn":"我们为我们的文化传承感到自豪。"}}]}},"inexhaustible":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"用不完的;无穷无尽的","en":"If there is an inexhaustible supply of something, there is so much of it that it cannot all be used up.","ex":{"en":"She has an inexhaustible supply of enthusiasm","cn":"她有用不完的热情。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an inexhaustible supply etc is never all used or seems impossible to use all of","cn":""},{"en":"a supply of something that seems as if it will never all be used - use this especially when you know that it could all be used up soon","cn":""},{"en":"something that is inexhaustible exists in such large amounts that it can never be finished or used up","cn":"无穷无尽的﹐用不完的"}]},"collocations":{"phrases":["VERBS be, seem Her energy seemed inexhaustible.","ADV. virtually | apparently, seemingly"]},"media":{"uk":"media/ldoce/hwd/bre/5/inexhaustible0205.mp3","us":"media/ldoce/hwd/ame/2/inexhaustible.mp3"},"examples":[{"en":"an inexhaustible supply of good jokes","cn":"讲不完的精彩笑话"},{"en":"Her energy is inexhaustible.","cn":"她有无穷的精力。"}],"oxford":{"phon":"ˌɪnɪɡˈzɔːstəbl","pos":"adjective","senses":[{"en":"that cannot be exhausted (= finished); very great","cn":"用之不竭的；无穷无尽的","ex":{"en":"an inexhaustible supply of good jokes","cn":"讲不完的精彩笑话"}}]}},"incompetent":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无能力的;不称职的;不合格的","en":"If you describe someone as incompetent, you are criticizing them because they are unable to do their job or a task properly.","ex":{"en":"The court declared him incompetent to manage his financial affairs","cn":"法庭宣布他不具备管理自己财务的能力。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very bad at doing something, or doing something very badly","cn":""},{"en":"very bad at doing something","cn":""},{"en":"use this about someone who is so bad at doing something that you have no respect for them","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"If you are incompetent , you are not able to complete a task, like if you only ever made peanut butter and jelly sandwiches — you would be incompetent in the kitchen of a fancy French restaurant."}]},"collocations":{"phrases":["VERBS appear, be | adjudge sb/sth, consider sb/sth I know my boss considers me incompetent.","ADV. grossly, hopelessly, singularly a grossly incompetent piece of reporting | completely, totally, utterly | managerially, socially, techn","PREP. at He is utterly incompetent at his job."]},"media":{"uk":"media/ldoce/hwd/bre/0/incompetent0205.mp3","us":"media/ldoce/hwd/ame/4/incompetent.mp3"},"examples":[{"en":"his incompetent handling of the affair","cn":"他在处理这件事上的无能表现"},{"en":"The Prime Minister was attacked as incompetent to lead.","cn":"首相被抨击缺乏领导能力。"}],"oxford":{"phon":"ɪnˈkɒmpɪtənt","pos":"adjective","senses":[{"en":"not having the skill or ability to do your job or a task as it should be done","cn":"无能力的；不胜任的；不称职的","ex":{"en":"an incompetent teacher","cn":"不称职的教师"}},{"en":"a person who does not have the skill or ability to do their job or a task as it should be done","cn":"不称职（或不能胜任、无能）的人","ex":{"en":"He’s a hopeless incompetent.","cn":"他是一个无可救药的无能者。"},"pos":"noun"}]}},"incomplete":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"未完成的;未结束的","en":"Something that is incomplete is not yet finished, or does not have all the parts or details that it needs.","ex":{"en":"The clearing of rubbish and drains is still incomplete","cn":"垃圾与污水的清理工作还未完成。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"only containing or including part of what is necessary to be complete","cn":""},{"en":"if something is patchy , it does not include enough information, or important details are missing","cn":""},{"en":"not finished, because not all of the work has been done on something, or because it does not have all the parts that it should have","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something incomplete is missing a part or unfinished. Incomplete things are not whole. A football pass that falls short is incomplete and so is an outfit without a shirt. A bridge to nowhere? Incomplete ."}]},"collocations":{"phrases":["VERBS be | remain Her collection remained incomplete. | leave sth The building was left incomplete.","ADV. seriously, very, woefully Any view of Shostakovich is seriously incomplete without knowledge of these recordings. | somewhat | inevitab"]},"media":{"uk":"media/ldoce/hwd/bre/f/incomplete_adj0205.mp3","us":"media/ldoce/hwd/ame/e/incomplete.mp3"},"examples":[{"en":"The causes of the phenomenon are still incompletely understood.","cn":"造成这种现象的原因尚未彻底弄清。"},{"en":"Spoken language contains many incomplete sentences.","cn":"口语中有很多不完整的句子。"}],"oxford":{"phon":"ˌɪnkəmˈpliːt","pos":"adjective","senses":[{"en":"not having everything that it should have; not finished or complete","cn":"不完整的；不完全的；不完善的","ex":{"en":"an incomplete set of figures","cn":"一组不完整的数字"}},{"en":"the grade that a student gets for a course of education when they have not completed all the work for that course","cn":"（学业成绩评分）未修毕，未完成","pos":"noun"}]}},"instalment":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(分期付款的)一期付款","en":"If you pay for something in instalments, you pay small sums of money at regular intervals over a period of time, rather than paying the whole amount at once.","ex":{"en":"The first instalment of £1 per share is payable on application.","cn":"每股1英镑的首期付款应在申请时交付。"}},{"pos":"N-COUNT 可数名词","cn":"(故事、计划等的)部分;(分期出版的)分册","en":"An instalment of a story or plan is one of its parts that are published or carried out separately one after the other.","ex":{"en":"...the disappointing third instalment of the Highlander series.","cn":"“挑战者”系列令人失望的第三部"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an amount of money that you pay for something, especially when it is only one part of the total amount you have to pay","cn":""},{"en":"a regular payment you make to pay back money that you have borrowed or to pay for things that you have already received","cn":""},{"en":"part of the cost of something that you pay before you get it, so that it will not be sold to anyone else","cn":""}]},"collocations":{"phrases":["ADJ. fixed | equal a loan repaid in equal annual instalments | first, initial | second, third, etc. | final, last | next | annual, monthly, ","VERB + INSTALMENT pay (off), pay (sth) by/in, pay sth off in She sold the car before she had paid the instalments. The tenants agreed to pay","INSTALMENT + VERB be/become due, be payable by/in The next instalment is not due until July.","INSTALMENT + NOUN payment | plan, terms We offer an instalment plan.","PREP. by ~ The amounts are repayable by instalment. | in ~ Repayment is in ten instalments. 2 part of a story","ADJ. first, second, etc. | final, last | daily, weekly | next","VERB + INSTALMENT publish (sth in) The &lsquo;Screwtape Letters&rsquo; were published in instalments from May to November 1941.","PREP. ~ in the final instalment in the trilogy"]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdeinstalment.mp3","us":"media/ldoce/hwd/ame/2/installment.mp3"},"examples":[{"en":"They were unable to keep up (= continue to pay regularly) the instalments.","cn":"他们未能继续按时交付这笔分期付款。"},{"en":"The final instalment on the loan is due next week.","cn":"贷款的最后一期付款下个星期到期。"}],"oxford":{"phon":"ɪnˈstɔːlmənt","pos":"noun","senses":[{"en":"one of a number of payments that are made regularly over a period of time until something has been paid for","cn":"（分期付款的）一期付款","lab":"British English","ex":{"en":"We paid for the car by/in instalments.","cn":"我们以分期付款买了这辆车。"}},{"en":"one of the parts of a story that appears regularly over a period of time in a newspaper, on television, etc.","cn":"（报章连载小说的）一节；（电视连续剧的）一集","ex":{"en":"The ‘Screwtape Letters’ were published in instalments from May to November 1941.","cn":"《斯克鲁塔普书简》从1941年5 月到11 月连载发表。"}}]}},"intimidate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"恫吓;恐吓;威胁","en":"If you intimidate someone, you deliberately make them frightened enough to do what you want them to do.","ex":{"en":"Jones had set out to intimidate and dominate Paul","cn":"琼斯开始恐吓并控制保罗。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone feel afraid","cn":""},{"en":"to frighten someone. Scare is less formal than frighten , and is the usual word to use in everyday English","cn":""},{"en":"to make someone feel extremely frightened","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"You can see \"timid\" in the middle of intimidate, and to be timid is to be frightened or to pull back from something. When you intimidate , you frighten or make someone afraid. A pet rat might intimidate your sister's friends, keeping them out of your fort."}]},"collocations":{"phrases":["VERB + INTIMIDATE try to","PREP. into The police had tried to intimidate him into signing a confession.","PHRASES an attempt to intimidate sb, be easily intimidated He was not a man to be easily intimidated. | feel intimidated She did not feel in"]},"media":{"uk":"media/ldoce/hwd/bre/1/intimidate0205.mp3","us":"media/ldoce/hwd/ame/1/intimidate.mp3"},"examples":[{"en":"They were accused of intimidating people into voting for them.","cn":"他们被控胁迫选民投他们的票。"},{"en":"She refused to be intimidated by their threats.","cn":"她没有被他们的威胁吓倒。"}],"oxford":{"phon":"ɪnˈtɪmɪdeɪt","pos":"verb","senses":[{"en":"to frighten or threaten somebody so that they will do what you want","cn":"恐吓；威胁","ex":{"en":"They were accused of intimidating people into voting for them.","cn":"他们被控胁迫选民投他们的票。"}}]}},"inscription":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"刻印文字;铭文;碑文","en":"An inscription is writing carved into something made of stone or metal, for example a gravestone or medal.","ex":{"en":"Above its doors was a Latin inscription: Non omnia possumus omnes","cn":"门的上方刻有拉丁文铭“人非万能”。"}},{"pos":"N-COUNT 可数名词","cn":"题词;题赠","en":"An inscription is something written by hand in the front of a book or on a photograph.","ex":{"en":"The inscription reads: 'To Emma, with love from Harry'.","cn":"题赠写着：“献给爱玛,爱你的哈里”。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"writing, especially a small amount of writing","cn":""},{"en":"the written part of a book, newspaper etc, not including notes, pictures etc","cn":""},{"en":"a copy of a book which is written by hand or typed, often before it is printed","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Inscription is a fancy word for “writing” — the act of writing or a small bit of writing. You weren't excited when you received the card, but the inscription inside made you weep with emotion. Here, have a tissue."}]},"collocations":{"phrases":["ADJ. faded | famous | dedicatory, funerary, memorial, monumental | Greek, Latin, etc.","VERB + INSCRIPTION bear, carry, have The monument carries the inscription: &lsquo;To the fallen in two world wars&rsquo;. | carve, engrave a","INSCRIPTION + VERB bear sth, read sth, record sth, say sth, show sth, tell sb sth The inscription bears the date 1655. The simple inscriptio"]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41inscription.mp3","us":"media/ldoce/hwd/ame/2/inscription.mp3"},"examples":[{"en":"a Latin inscription on the memorial stone","cn":"纪念碑上的拉丁语碑文"}],"oxford":{"phon":"ɪnˈskrɪpʃn","pos":"noun","senses":[{"en":"words written in the front of a book or cut in stone or metal","cn":"（书首页的）题词；（石头或金属上）刻写的文字，铭刻，碑文","ex":{"en":"There was an inscription carved over the doorway.","cn":"门口刻着一段铭文。"}}]}},"indicator":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"指示物;指标","en":"An indicator is a measurement or value which gives you an idea of what something is like.","ex":{"en":"...vital economic indicators, such as inflation, growth and the trade gap","cn":"重要的经济指标,例如通货膨胀、增长与贸易逆差"}},{"pos":"N-COUNT 可数名词","cn":"(汽车上的)转向指示灯，转向灯","en":"A car's indicators are the flashing lights that tell you when it is going to turn left or right."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an event, fact etc that shows that something is happening or that something is true or exists","cn":""},{"en":"a sign. Indication is more formal than sign","cn":""},{"en":"facts or signs that show clearly that something exists or is true, especially something that you are trying to prove","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"If you're familiar with the verb to \"indicate,\" then indicator should be no problem. An indicator points to, suggests, or shows something. The arrow on a street sign is an indicator telling you which way to go."}]},"collocations":{"phrases":["ADJ. good, reliable, sure | poor, unreliable Level of education is actually quite a poor indicator of ability to run a business well. | sens","VERB + INDICATOR be, serve as These warts can serve as an indicator of other infections. | provide (sb with) | regard sth as, see sth as, ta","INDICATOR + VERB show sth, suggest sth Economic indicators suggest that a recovery is on the way.","PREP. ~ for an indicator for the presence of minerals"]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdeindicator.mp3","us":"media/ldoce/hwd/ame/f/indicator.mp3"},"examples":[{"en":"The economic indicators are better than expected.","cn":"经济指标比预期的好。"},{"en":"a depth indicator","cn":"深度指示器"}],"oxford":{"phon":"ˈɪndɪkeɪtə(r)","pos":"noun","senses":[{"en":"a sign that shows you what something is like or how a situation is changing","cn":"指示信号；标志；迹象","ex":{"en":"The economic indicators are better than expected.","cn":"经济指标比预期的好。"}},{"en":"a device on a machine that shows speed, pressure, etc.","cn":"指示器；指针","ex":{"en":"a depth indicator","cn":"深度指示器"}},{"en":"a light on a vehicle that flashes to show that the vehicle is going to turn left or right","cn":"转向灯；方向灯","lab":"British English","ex":{"en":"Her right-hand indicator was flashing.","cn":"她右手边的指示灯闪烁。"}}]}},"insurmountable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无法解决的;难以克服的;不可逾越的","en":"A problem that is insurmountable is so great that it cannot be dealt with successfully.","ex":{"en":"The crisis doesn't seem like an insurmountable problem.","cn":"这次危机似乎并不难以克服。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an insurmountable difficulty or problem is too large or difficult to deal with 〔","cn":"困难〕难以克服的﹐不可逾越的﹔〔问题〕难以处理的"}]},"vocab":{"pos":"adj","senses":[{"en":"The adjective insurmountable describes some barrier that is incapable of being overcome. The Great Wall of China was meant to be an insurmountable deterrent to would-be invaders."}]},"collocations":{"phrases":["VERBS appear, be, prove, seem The age barrier appeared insurmountable. | become | remain","ADV. nearly, virtually | apparently, seemingly They were now faced with seemingly insurmountable technical problems."]},"media":{"uk":"media/ldoce/hwd/bre/0/insurmountable0205.mp3","us":"media/ldoce/hwd/ame/0/insurmountable.mp3"},"examples":[{"en":"The language difference proved an insurmountable barrier .","cn":"结果语言差异是难以克服的障碍。"}],"oxford":{"phon":"ˌɪnsəˈmaʊntəbl","pos":"adjective","senses":[{"en":"that cannot be dealt with successfully","cn":"无法克服的；难以解决的；不可逾越的","ex":{"en":"The age barrier appeared insurmountable.","cn":"年龄障碍看来是难以逾越的。"}}]}},"inertia":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"惰性;迟钝;怠惰","en":"If you have a feeling of inertia, you feel very lazy and unwilling to move or be active.","ex":{"en":"...her inertia, her lack of energy","cn":"她的怠惰和缺乏活力"}},{"pos":"N-UNCOUNT 不可数名词","cn":"惯性","en":"Inertia is the tendency of a physical object to remain still or to continue moving, unless a force is applied to it."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when no one wants to do anything to change a situation","cn":"惰性﹐保守"},{"en":"the force that keeps an object in the same position or keeps it moving until it is moved or stopped by another force","cn":"惯性"},{"en":"a lack of energy and a feeling that you do not want to do anything","cn":"缺乏活力﹐懒惰"}]},"vocab":{"pos":"n","senses":[{"en":"Inertia is resistance to change. You hate looking at people's feet and yet you stay in your job as a shoe salesman year after year. Why? Inertia ."}]},"collocations":{"phrases":["ADJ. sheer | bureaucratic, institutional, organizational, political","VERB + INERTIA lapse into She lapsed into inertia and lay there as if asleep. | overcome The forces for change in the government are not suf","PREP. out of ~ He stayed where he was, not because he really wanted to, but out of inertia. | through ~ Projects were frequently abandoned t","PHRASES a state of inertia"]},"media":{"uk":"media/ldoce/hwd/bre/9/inertia0205.mp3","us":"media/ldoce/hwd/ame/9/inertia.mp3"},"examples":[{"en":"I can't seem to throw off this feeling of inertia.","cn":"我好像无法摆脱这种无力的感觉。"},{"en":"the forces of institutional inertia in the school system","cn":"学校体制内的惰性"}],"oxford":{"phon":"ɪˈnɜːʃə","pos":"noun","senses":[{"en":"lack of energy; lack of desire or ability to move or change","cn":"缺乏活力；惰性；保守","lab":"usually disapproving","ex":{"en":"I can't seem to throw off this feeling of inertia.","cn":"我好像无法摆脱这种无力的感觉。"}},{"en":"a property (= characteristic) of matter (= a substance) by which it stays still or, if moving, continues moving in a straight line unless it is acted on by a force outside itself","cn":"惯性","lab":"physics"}]}},"inert":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不动的;静止的","en":"Someone or something that is inert does not move at all.","ex":{"en":"He covered the inert body with a blanket.","cn":"他用毯子把那具一动不动的尸体盖上。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无生气的;呆滞的","en":"If you describe something as inert, you are criticizing it because it is not very lively or interesting.","ex":{"en":"The novel itself remains oddly inert.","cn":"小说本身异常平淡，了无生气。"}},{"pos":"ADJ 形容词","cn":"惰性的;不活泼的","en":"An inert substance is one which does not react with other substances.","ex":{"en":"...inert gases like neon and argon.","cn":"像氖和氩这样的惰性气体"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not producing a chemical reaction when combined with other substances","cn":"惰性的﹐不活泼的"},{"en":"not moving, or not having the strength or power to move","cn":"不动的﹔无行动能力的﹔无力活动的"},{"en":"not willing to do anything","cn":"呆滞的﹐迟缓的"}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"Something that's unable to move or moving without much energy can be described as inert . Wind up in a body cast and you’ll find yourself not only itchy, but totally inert ."}]},"collocations":{"phrases":["VERBS be, lie, remain | become","ADV. completely She lay completely inert on her bed. | relatively | chemically chemically inert radioactive waste"]},"media":{"uk":"media/ldoce/hwd/bre/5/inert0205.mp3","us":"media/ldoce/hwd/ame/6/inert.mp3"},"examples":[{"en":"He lay inert with half-closed eyes.","cn":"他半睁着双眼一动不动地躺着。"},{"en":"He lay, inert, in his bed.","cn":"他一动不动地躺在床上。"}],"oxford":{"phon":"ɪˈnɜːt","pos":"adjective","senses":[{"en":"without power to move or act","cn":"无活动能力的；无行动力的","lab":"formal","ex":{"en":"He lay inert with half-closed eyes.","cn":"他半睁着双眼一动不动地躺着。"}},{"en":"without active chemical or other properties (= characteristics)","cn":"惰性的；不活泼的","lab":"chemistry","ex":{"en":"chemically inert radioactive waste","cn":"具有化学惰性的放射性废物"}}]}},"inclusion":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"包括;包含","en":"Inclusion is the act of making a person or thing part of a group or collection.","ex":{"en":"...a confident performance which justified his inclusion in the team.","cn":"证明他入选该队当之无愧的自信表现"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the act of including someone or something in a larger group or set, or the fact of being included in one","cn":"包含﹐包括"},{"en":"someone or something that has been included in a larger group","cn":"包括在整体中的某人[某物]"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Inclusion is the act of including someone in something, like a school, club, or team."}]},"collocations":{"phrases":["ADJ. possible We welcome readers' letters for possible inclusion on this page.","VERB + INCLUSION be worthy of, justify, merit, warrant Some words are too infrequent to be worthy of inclusion in the dictionary. | be eligi","PREP. for ~ an article for inclusion in the newsletter","PHRASES criteria for inclusion There are strict criteria for inclusion in the competition."]},"media":{"uk":"media/ldoce/hwd/bre/a/inclusion0205.mp3","us":"media/ldoce/hwd/ame/2/inclusion.mp3"},"examples":[{"en":"His inclusion in the team is in doubt.","cn":"他是否能被选入这个队还未定案。"},{"en":"There were some surprising inclusions in the list.","cn":"名单中包括一些意想不到的人。"}],"oxford":{"phon":"ɪnˈkluːʒn","pos":"noun","senses":[{"en":"the fact of including somebody/something; the fact of being included","cn":"（被）包括，包含","g":"[uncountable]","ex":{"en":"His inclusion in the team is in doubt.","cn":"他是否能被选入这个队还未确定。"}},{"en":"a person or thing that is included","cn":"被包括的人（或事物）","g":"[countable]","ex":{"en":"There were some surprising inclusions in the list.","cn":"名单中包括一些意想不到的人。"}},{"en":"the fact or policy of providing equal opportunities and resources for people who might otherwise not get them, for example people who are disabled or belong to minority groups","cn":"包容：为可能无法获得的人（例如，残疾人或少数群体）提供平等机会和资源的事实或政策","g":"[uncountable]","ex":{"en":"The company is actively promoting diversity and inclusion.","cn":"公司正在积极促进多元化和包容性。"}}]}},"invalid":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"病人;病弱者;伤残者","en":"An invalid is someone who needs to be cared for because they have an illness or disability.","ex":{"en":"I hate being treated as an invalid.","cn":"我讨厌被人当作伤病号对待。"}},{"pos":"ADJ 形容词","cn":"无效的;作废的","en":"If an action, procedure, or document is invalid, it cannot be accepted, because it breaks the law or some official rule.","ex":{"en":"The trial was stopped and the results declared invalid","cn":"审判被中止,判决结果被宣布无效。"}},{"pos":"ADJ 形容词","cn":"(论据、结论)站不住脚的,错误的","en":"An invalid argument or conclusion is wrong because it is based on a mistake.","ex":{"en":"We think that those arguments are rendered invalid by the hard facts on the ground.","cn":"我们认为那些论点当场即被确凿的事实驳倒了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a ticket, passport etc that is invalid cannot legally be used and it will not be officially accepted","cn":""},{"en":"a ticket, passport etc that is out of date cannot be used because the time during which it could be used has passed","cn":""},{"en":"a document such as a contract that is null and void has no legal force and cannot be used for any purpose - used in legal contexts","cn":""}]},"vocab":{"pos":"1 adj 2 n v","senses":[{"en":"A person who is very sick or injured and needs frequent care is an invalid . Also, something no longer current or useful is invalid ."}]},"collocations":{"phrases":["VERBS be | became | make sth, render sth This action would render the agreement invalid. | consider sth, declare sth, deem sth, regard sth a"]},"media":{"uk":"media/ldoce/hwd/bre/d/invalid_adj0205.mp3","us":"media/ldoce/hwd/ame/c/l3invalid.mp3"},"examples":[{"en":"She had been a delicate child and her parents had treated her as an invalid.","cn":"她小时候很虚弱，父母就把她当个病人照料。"},{"en":"The treaty was declared invalid because it had not been ratified.","cn":"条约还没得到批准，因此被宣布无效。"}],"oxford":{"phon":"ɪnˈvælɪd","pos":"adjective","senses":[{"en":"not legally or officially acceptable","cn":"（法律上或官方）不承认的；无效的","ex":{"en":"The treaty was declared invalid because it had not been ratified.","cn":"条约没有得到批准，因此被宣布无效。"}},{"en":"not based on all the facts, and therefore not correct","cn":"无充分事实的；站不住脚的","ex":{"en":"an invalid argument","cn":"站不住脚的论点"}},{"en":"of a type that the computer cannot recognize","cn":"不能识别的；无效的","lab":"computing","ex":{"en":"An error code will be displayed if any invalid information has been entered.","cn":"输入了无效信息将显示错误代码。"}},{"en":"a person who needs other people to take care of them, because of illness that they have had for a long time","cn":"病弱者；久病衰弱者","ex":{"en":"She had been a delicate child and her parents had treated her as an invalid.","cn":"她小时候很虚弱，父母就把她当个病人照料。"},"pos":"noun"},{"en":"to force somebody to leave the armed forces because of an illness or injury","cn":"（因伤病）令…退役","ex":{"en":"He was invalided out of the army in 1943.","cn":"他于 1943 年因伤病退役。"},"pos":"verb"}]}},"intuitive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"直觉的;凭直觉获知的","en":"If you have an intuitive idea or feeling about something, you feel that it is true although you have no evidence or proof of it.","ex":{"en":"A positive pregnancy test soon confirmed her intuitive feelings.","cn":"阳性孕检结果很快证实了她的直觉。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"based on instinct rather than on knowledge or thought","cn":""},{"en":"an intuitive understanding, judgement, or idea is completely based on feelings, not on facts or reasons, but is still correct","cn":""},{"en":"an intuitive idea is based on a feeling rather than on knowledge or facts 〔","cn":"想法〕（出于）直觉的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you're intuitive, you can probably guess what this word means just by looking at it. No? Maybe you're not so intuitive, after all. Intuitive means having the ability to understand or know something without any direct evidence or reasoning process."}]},"collocations":{"phrases":["VERBS be","ADV. extremely, highly, very a highly intuitive thinker | purely | almost | fairly, quite"]},"media":{"uk":"media/ldoce/hwd/bre/a/intuitive0205.mp3","us":"media/ldoce/hwd/ame/d/intuitive.mp3"},"examples":[{"en":"He had an intuitive sense of what the reader wanted.","cn":"他能直觉地感到读者需要什么。"},{"en":"Intuitively, she knew that he was lying.","cn":"她凭直觉知道他在说谎。"}],"oxford":{"phon":"ɪnˈtjuːɪtɪv","pos":"adjective","senses":[{"en":"obtained by using your feelings rather than by considering the facts","cn":"凭直觉得到的；直觉的","ex":{"en":"He had an intuitive sense of what the reader wanted.","cn":"他能直觉地感到读者需要什么。"}},{"en":"able to understand something by using feelings rather than by considering the facts","cn":"有直觉力的","ex":{"en":"I don't think that women are necessarily more intuitive than men.","cn":"我认为女人未必比男人更有直觉。"}},{"en":"easy to understand and to use","cn":"易懂的；使用简便的"}]}},"inflate":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)充气;(使)膨胀;(使)胀大","en":"If you inflate something such as a balloon or tyre, or if it inflates, it becomes bigger as it is filled with air or a gas.","ex":{"en":"Stuart jumped into the sea and inflated the liferaft","cn":"斯图尔特跳到海里给救生艇充气。"}},{"pos":"V-ERG 及物/不及物动词","cn":"抬高(物价);(使)(物价)涨高","en":"If you say that someone inflates the price of something, or that the price inflates, you mean that the price increases.","ex":{"en":"The promotion of a big release can inflate a film's final cost","cn":"大规模发行所需的广告宣传会增加一部电影的最终成本。"}},{"pos":"VERB 动词","cn":"夸张;夸大;吹嘘","en":"If someone inflates the amount or effect of something, they say it is bigger, better, or more important than it really is, usually so that they can profit from it.","ex":{"en":"They inflated clients' medical treatment to defraud insurance companies","cn":"他们夸大客户伤势的严重性和治疗情形以欺骗保险公司。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to fill something with air or gas, for example a tyre or a balloon","cn":""},{"en":"if you inflate something such as a tyre or balloon or it inflates , you fill it with air","cn":""},{"en":"to fill something with air using a pump (=a machine that forces air into something)","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Using your own breath or an air pump, you can inflate a balloon — or anything else you need to pump air into. When you inflate something you fill it with air (or any other gas) to make it expand."}]},"collocations":{"phrases":["ADV. fully | partially","PREP. with The balloon was kept fully inflated with hydrogen."]},"media":{"img":["media/ldoce/img/fixed.jpg"],"uk":"media/ldoce/hwd/bre/1/inflate0205.mp3","us":"media/ldoce/hwd/ame/0/inflate.mp3"},"examples":[{"en":"The principal effect of the demand for new houses was to inflate prices.","cn":"对新住宅需求的主要结果是促使价格上涨。"},{"en":"Food prices are no longer inflating at the same rate as last year.","cn":"食物价格的上涨率已不再像去年那样高了。"}],"oxford":{"phon":"ɪnˈfleɪt","pos":"verb","senses":[{"en":"to fill something or become filled with gas or air","cn":"使充气；膨胀","g":"[transitive, intransitive]","ex":{"en":"Inflate your life jacket by pulling sharply on the cord.","cn":"猛拽绳扣使你的救生衣充气。"}},{"en":"to make something appear to be more important or impressive than it really is","cn":"鼓吹；吹捧","g":"[transitive]","ex":{"en":"The media have grossly inflated the significance of this meeting.","cn":"媒体对这次会议的重要性大肆吹捧。"}},{"en":"to increase the price of something; to increase in price","cn":"（使）涨价","g":"[transitive, intransitive]","ex":{"en":"The principal effect of the demand for new houses was to inflate prices.","cn":"对新住宅需求的主要结果是促使价格上涨。"}}]}},"inclusive":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"包括一切费用在内的;包含(邮费和包装费)的","en":"If a price is inclusive, it includes all the charges connected with the goods or services offered. If a price is inclusive of postage and packing, it includes the charge for this.","ex":{"en":"...all prices are inclusive of delivery.","cn":"所有的价格都包括运费在内。"}},{"pos":"ADJ 形容词","cn":"首末项包括在内的;包括一切项目在内的","en":"After stating the first and last item in a set of things, you can add inclusive to make it clear that the items stated are included in the set.","ex":{"en":"Training will commence on 5 October, running from Tuesday to Saturday inclusive.","cn":"培训将于 10 月 5 日开始,从星期二(含)到星期六(含)。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"包容性强的;各种人都有的","en":"If you describe a group or organization as inclusive, you mean that it allows all kinds of people to belong to it, rather than just one kind of person.","ex":{"en":"The academy is far more inclusive now than it used to be.","cn":"该学会的包容性比过去强了很多。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a price you pay for something includes something else, you do not have to pay more for that thing","cn":""},{"en":"if something that you buy comes with another thing, the second thing is always included when you buy the first","cn":""},{"en":"an inclusive price or cost includes everything 〔","cn":"价钱或费用〕包括一切的"}]},"vocab":{"pos":"adj","senses":[{"en":"Call something inclusive when it's designed or inclined to include. An exclusive club might let you in, but an inclusive one will ask you to join, no strings attached."}]},"collocations":{"phrases":["VERBS be","ADV. fully a fully inclusive price","PREP. of The charge is inclusive of food.","PHRASES all inclusive The price is all inclusive."]},"media":{"uk":"media/ldoce/hwd/bre/6/inclusive0205.mp3","us":"media/ldoce/hwd/ame/a/inclusive.mp3"},"examples":[{"en":"The park is open from 1 May to 31 October.","cn":"公园从 5 月 1 日到 10 月 31 日开放。"},{"en":"We are offering free holidays for children aged two to eleven inclusive.","cn":"我们提供的度假活动，两岁至十一岁的儿童免费。"}],"oxford":{"phon":"ɪnˈkluːsɪv","pos":"adjective","senses":[{"en":"having the total cost, or the cost of something that is mentioned, contained in the price","cn":"包含全部费用的；包括所提到的费用在内的","ex":{"en":"The fully inclusive fare for the trip is £52.","cn":"这次旅行的全部费用是 52 英镑。"}},{"en":"including all the days, months, numbers, etc. mentioned","cn":"（表示范围的首尾亦包括在内）","lab":"British English","ex":{"en":"We are offering free holidays for children aged two to eleven inclusive.","cn":"我们提供的度假活动，两岁至十一岁的儿童免费。"}},{"en":"deliberately including people, things, ideas, etc. from all sections of society, points of view, etc.","cn":"包容不同的人（或事物、观点等）的","ex":{"en":"The party must adopt more inclusive strategies and a broader vision.","cn":"这个政党必须采用更包容的政策，并把目光放远一点。"}}]}},"indulgence":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"纵容;迁就","en":"Indulgence means treating someone with special kindness, often when it is not a good thing.","ex":{"en":"The king's indulgence towards his sons angered the business community","cn":"国王对儿子们的纵容令商界恼火。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the habit of allowing yourself to do or have whatever you want, or allowing someone else to do or have whatever they want","cn":"沉溺﹔放纵﹔纵容"},{"en":"something that you do or have for pleasure, not because you need it","cn":"嗜好﹐爱好"},{"en":"willingness to ignore someone’s faults or weaknesses","cn":"宽容﹐包涵"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"An indulgence is doing something that you enjoy even if it has negative consequences. Buying yourself something that you don't need, be it a cookie, video game, or diamond necklace, is an indulgence ."}]},"collocations":{"phrases":["ADJ. excessive | personal, self- guilty of self-indulgence | sexual","PREP. ~ in She allowed herself only a few moments' indulgence in self-pity.","PHRASES a life of indulgence 2 sth you allow yourself","ADJ. expensive, private, small","VERB + INDULGENCE allow yourself As a relief from work she allowed herself a few small indulgences. 3 acceptance of change to the normal way","VERB + INDULGENCE ask, beg, request He begged the audience's indulgence to read some passages from his latest book. | grant (law) , show (sb"]},"media":{"uk":"media/ldoce/hwd/bre/1/indulgence0205.mp3","us":"media/ldoce/hwd/ame/b/indulgence.mp3"},"examples":[{"en":"Avoid excessive indulgence in sweets and canned drinks.","cn":"避免食用过多的甜食和罐装饮料。"},{"en":"There is no limit to the indulgence he shows to his grandchildren.","cn":"他无度地溺爱娇惯孙子孙女。"}],"oxford":{"phon":"ɪnˈdʌldʒəns","pos":"noun","senses":[{"en":"the state or act of having or doing whatever you want; the state of allowing somebody to have or do whatever they want","cn":"沉溺；放纵；纵容","g":"[uncountable]","lab":"usually disapproving","ex":{"en":"to lead a life of indulgence","cn":"过着放纵的生活"}},{"en":"something that you allow yourself to have even though it is not essential","cn":"嗜好；爱好；享受","g":"[countable]","ex":{"en":"The holiday was an extravagant indulgence.","cn":"那个假期是一次奢华的享受。"}},{"en":"the quality of being willing to ignore the weaknesses in somebody/something","cn":"宽容；包涵","g":"[uncountable]","lab":"formal","ex":{"en":"They begged the audience's indulgence.","cn":"他们恳求观众包涵。"}}]}},"inevitability":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"不可避免;无法规避;必然发生","en":"The inevitability of something is the fact that it is certain to happen and cannot be prevented or avoided.","ex":{"en":"We are all bound by the inevitability of death","cn":"我们早晚都会有一死。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the fact that something is certain to happen, or something that is certain to happen","cn":"必然性﹔必然发生的事﹐不可避免的事"}]},"vocab":{"pos":"n","senses":[{"en":"Whether you’re referring to someone else’s downfall, to your fate, or to the sunrise, you can use the noun inevitability to say that something is just bound to happen."}]},"collocations":{"phrases":["ADJ. terrible, tragic | a certain | historical","VERB + INEVITABILITY have | accept She was learning to accept the inevitability of death.","PREP. ~ about The tragedy had a certain inevitability about it.","PHRASES a feeling/sense of inevitability"]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41inevitability.mp3","us":"media/ldoce/hwd/ame/9/ld41inevitability.mp3"},"examples":[{"en":"There was an inevitability about their defeat.","cn":"他们的失败自有其必然。"},{"en":"the inevitability of death","cn":"死亡的必然性"}],"oxford":{"phon":"ɪnˌevɪtəˈbɪləti","pos":"noun","senses":[{"en":"the fact that something cannot be avoided or prevented","cn":"不可避免的；不能防止的","ex":{"en":"the inevitability of death","cn":"死亡的必然性"}}]}},"informer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"告密者;线人","en":"An informer is a person who tells the police that someone has done something illegal.","ex":{"en":"...two men suspected of being police informers.","cn":"被怀疑是警方线人的两名男子"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to find out secret information about another country","cn":""},{"en":"someone who works for a government or police department in order to get secret information about another country or organization","cn":""},{"en":"someone who finds out an enemy country’s secrets for their own country but who also gives secrets to the enemy","cn":""}]},"collocations":{"phrases":["ADJ. police He later became a police informer.","VERB + INFORMER become, turn One of the gang members had turned informer.","PHRASES a network of informers"]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdeinformer.mp3","us":"media/ldoce/hwd/ame/d/informer.mp3"},"oxford":{"phon":"ɪnˈfɔːmə(r)","pos":"noun","senses":[{"en":"a person who gives information to the police or other authority","cn":"（向警方或其他当局）提供消息的线人","ex":{"en":"The bomber turned (= became) police informer to escape prison.","cn":"炸弹袭击者为了越狱而变成（=成为）警方线人。"}}]}},"infringement":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(对他人权利等的)侵犯,侵害","en":"An infringement is an action or situation that interferes with your rights and the freedom you are entitled to.","ex":{"en":"...infringement of privacy","cn":"对隐私的侵犯"}},{"pos":"N-VAR 可变名词","cn":"(对法律、规则等的)违反,违背","en":"An infringement of a law or rule is the act of breaking it or disobeying it.","ex":{"en":"There might have been an infringement of the rules","cn":"可能存在违反规章制度的现象。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to do something that is a crime, or that is a particular type of crime","cn":""},{"en":"if something a company or government does contravenes a particular law, it breaks that law, especially unintentionally - used especially in legal or official contexts","cn":""},{"en":"to do something that is not allowed by the rules of an organization, game etc","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An infringement is a minor offense that involves breaking a rule or a law. If your sister takes a chapter from your book and publishes it as her own, you could sue her for copyright infringement ."}]},"collocations":{"phrases":["ADJ. serious | minor | clear | alleged | possible | copyright, patent, trademark","VERB + INFRINGEMENT be, constitute The committee ruled that the US ban constituted an infringement of free trade. | commit sympathy for peop","PHRASES an infringement of copyright/the law"]},"media":{"uk":"media/ldoce/hwd/bre/4/infringe0205.mp3","us":"media/ldoce/hwd/ame/4/infringe.mp3"},"examples":[{"en":"copyright infringement","cn":"对版权的侵犯"},{"en":"an infringement of liberty","cn":"对自由的侵犯"}],"oxford":{"phon":"ɪnˈfrɪndʒmənt","pos":"noun","senses":[{"en":"an act of breaking a law or rule","cn":"违背，触犯（法规）","ex":{"en":"copyright infringement","cn":"侵犯版权"}},{"en":"an act of limiting somebody's legal rights","cn":"侵犯，侵害（合法权益）","ex":{"en":"an infringement of liberty","cn":"对自由的侵犯"}}]}},"infinity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"无穷大","en":"Infinity is a number that is larger than any other number and can never be given an exact value.","ex":{"en":"These permutations multiply towards infinity","cn":"这些排列可以增加到无穷大。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"无限远的距离","en":"Infinity is a point that is further away than any other point and can never be reached.","ex":{"en":"...the darkness of a starless night stretching to infinity.","cn":"没有星星的夜晚，黑暗无边无际"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a space or distance without limits or an end 〔","cn":"空间或距离的〕无限﹐无穷"},{"en":"a number that is too large to be calculated 〔","cn":"数学上的〕无穷大"}]},"vocab":{"pos":"n","senses":[{"en":"Infinity is forever. You might hope that your relationship with your high school boyfriend will last into infinity, but, realistically, you know that's not likely to happen."}]},"collocations":{"phrases":["VERB + INFINITY extend into/to, stretch into/to Theoretically, a line can extend into infinity.","PREP. at ~ Parallel lines meet at infinity. | into ~ In this weather the cliff face was a foggy drop into infinity. 2 number larger than any","VERB + INFINITY approach, tend to/towards As x approaches infinity y approaches zero.","PREP. at ~ The usual convention is to choose the reference point at infinity."]},"media":{"uk":"media/ldoce/hwd/bre/e/infinity0205.mp3","us":"media/ldoce/hwd/ame/8/infinity.mp3"},"examples":[{"en":"The landscape seemed to stretch into infinity.","cn":"风景似乎延伸到了无穷远处。"},{"en":"an infinity of stars","cn":"数不清的星星"}],"oxford":{"phon":"ɪnˈfɪnəti","pos":"noun","senses":[{"en":"the state of having no end or limit","cn":"无限；无穷","g":"[uncountable]","ex":{"en":"the infinity/infinities of space","cn":"太空的无垠"}},{"en":"a point far away that can never be reached","cn":"无限远的点；无穷远","g":"[uncountable]","ex":{"en":"The landscape seemed to stretch into infinity.","cn":"风景似乎延伸到了无穷远处。"}},{"en":"a number larger than any other","cn":"无穷大（的数）","g":"[uncountable, countable]","lab":"mathematics","ex":{"en":"The number tends towards infinity.","cn":"数字趋于无穷大。"}},{"en":"a large amount that is impossible to count","cn":"无法计算的量；无限大的量","g":"[singular]","ex":{"en":"an infinity of stars","cn":"数不清的星星"}}]}},"intolerant":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不容忍的;不容异己的;偏狭的","en":"If you describe someone as intolerant, you mean that they do not accept behaviour and opinions that are different from their own.","ex":{"en":"He was intolerant of both suggestions and criticisms.","cn":"他对建议与批评都不能容忍。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is prejudiced dislikes people of a different race, sex, social class etc. Laws, systems etc that are prejudiced have the effect of treating people of a particular race, sex, class etc unfairly","cn":""},{"en":"believing that people of your race are naturally better, more intelligent etc than people of other races and therefore treating people of other races unfairly","cn":""},{"en":"behaving in a way that is unfair to people who belong to a particular sex. Sexist is usually used about people being unfair to women, and treating them unequally","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When you're intolerant , you can't or won't put up with something. Usually, that means you're not very open-minded."}]},"collocations":{"phrases":["VERBS be | become","ADV. deeply, extremely, highly, very | utterly","PREP. of They are deeply intolerant of all opposition."]},"media":{"uk":"media/ldoce/hwd/bre/2/intolerant0205.mp3","us":"media/ldoce/hwd/ame/8/intolerant.mp3"},"examples":[{"en":"recipes for people who are gluten intolerant","cn":"谷蛋白过敏人士的食谱"},{"en":"religious intolerance","cn":"宗教上的不宽容"}],"oxford":{"phon":"ɪnˈtɒlərənt","pos":"adjective","senses":[{"en":"not willing to accept ideas or ways of behaving that are different from your own","cn":"不容忍的；褊狭的；不容异说的；偏执的","lab":"disapproving","ex":{"en":"She was intolerant of others who were less efficient than her.","cn":"她不能容忍其他比她效率低的人。"}},{"en":"not able to eat particular foods, use particular medicines, etc. without becoming ill","cn":"（对食物、药物等）不耐受的，不耐的","lab":"specialist","ex":{"en":"recipes for people who are gluten intolerant","cn":"对谷蛋白不耐受人士的食谱"}}]}},"insignificance":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"不重要;无足轻重","en":"Insignificance is the quality of being insignificant.","ex":{"en":"The cost pales into insignificance when compared with the damage done to his reputation","cn":"与对他声誉造成的损伤相比,这一代价就变得微不足道了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not important","cn":""},{"en":"not important, or not very important. These phrases sound a little more formal than unimportant","cn":""},{"en":"small and not very likely to have an important effect – used especially about changes, problems, injuries, damage, or differences","cn":""}]},"collocations":{"phrases":["ADJ. comparative, relative","VERB + INSIGNIFICANCE pale into, fade into Her achievements fade into insignificance beside those of her sisters."]},"media":{"uk":"media/ldoce/hwd/bre/4/insignificant0205.mp3","us":"media/ldoce/hwd/ame/6/insignificant.mp3"},"examples":[{"en":"Her own problems paled into insignificance beside this terrible news.","cn":"跟这个可怕的消息相比，她自己的问题显得无关紧要了。"}],"oxford":{"phon":"ˌɪnsɪɡˈnɪfɪkəns","pos":"noun","senses":[{"en":"the fact of not being big or valuable enough to be considered important","cn":"微不足道的；无足轻重的","ex":{"en":"Her own problems paled into insignificance beside this terrible news.","cn":"和这个可怕的消息相比，她自己的问题显得无足轻重。"}}]}},"intriguing":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有趣的;引人入胜的;奇怪的","en":"If you describe something as intriguing, you mean that it is interesting or strange.","ex":{"en":"This intriguing book is both thoughtful and informative.","cn":"这本引人入胜的书既有思想性又富知识性。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"keeping your attention and making you want to know more","cn":""},{"en":"very interesting","cn":""},{"en":"giving you new ideas or experiences in a way that is interesting and enjoyable","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Intriguing things or people arouse curiosity and have an indescribable draw. If you find the night sky intriguing and enjoy pondering the limitlessness of the universe, you should consider becoming an astronomer."}]},"collocations":{"phrases":["VERBS be, sound It all sounds very intriguing. | find sth I found the story rather intriguing.","ADV. extraordinarily, extremely, highly, most, very | quite, rather"]},"media":{"uk":"media/ldoce/hwd/bre/a/intriguing0205.mp3","us":"media/ldoce/hwd/ame/f/intriguing.mp3"},"examples":[{"en":"These discoveries raise intriguing questions.","cn":"这些发现带来了非常有趣的问题。"},{"en":"He found her intriguing.","cn":"他觉得她很迷人。"}],"oxford":{"phon":"ɪnˈtriːɡɪŋ","pos":"adjective","senses":[{"en":"very interesting because of being unusual or not having an obvious answer","cn":"非常有趣的；引人入胜的；神秘的","ex":{"en":"These discoveries raise intriguing questions.","cn":"这些发现带来了非常有趣的问题。"}}]}},"industrialist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"工业家;实业家","en":"An industrialist is a powerful businessman who owns or controls large industrial companies or factories.","ex":{"en":"...prominent Japanese industrialists.","cn":"杰出的日本实业家"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a person who owns or runs a factory or industrial company","cn":"工业家﹐实业家"}]},"collocations":{"phrases":["ADJ. leading, prominent, top | local | wealthy"]},"media":{"uk":"media/ldoce/hwd/bre/b/industrialist0205.mp3","us":"media/ldoce/hwd/ame/8/industrialist.mp3"},"oxford":{"phon":"ɪnˈdʌstriəlɪst","pos":"noun","senses":[{"en":"a person who owns or runs a large factory or industrial company","cn":"工业家；实业家；工厂主","ex":{"en":"He was the son of a wealthy industrialist.","cn":"他是一个殷富实业家的儿子。"}}]}},"inattention":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"疏忽;不注意","en":"A person's inattention is their lack of attention.","ex":{"en":"Vital evidence had been lost through a moment's inattention.","cn":"关键证据由于一时的疏忽而丢失了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"lack of attention","cn":"不注意﹔疏忽﹔失神"}]},"collocations":{"phrases":["ADJ. momentary","PREP. ~ to He was dismissed for inattention to his duty.","PHRASES a moment of inattention One moment of inattention when driving could be fatal."]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41inattention.mp3","us":"media/ldoce/hwd/ame/0/inattention.mp3"},"examples":[{"en":"The accident was the result of a moment's inattention.","cn":"这次事故是一时不小心造成的。"},{"en":"a moment of inattention","cn":"片刻的失神"}],"oxford":{"phon":"ˌɪnəˈtenʃn","pos":"noun","senses":[{"en":"lack of attention","cn":"不注意；不经心","ex":{"en":"The accident was the result of a moment's inattention.","cn":"这次事故是一时不小心造成的。"}}]}},"influx":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"流入;涌进","en":"An influx of people or things into a place is their arrival there in large numbers.","ex":{"en":"...problems caused by the influx of refugees.","cn":"大批难民涌入产生的问题"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if a lot of people pour in or flood in , they all enter a place at the same time","cn":""},{"en":"if a lot of people crowd in , they all enter a place, especially a place that is not big enough for so many people","cn":""},{"en":"if a group of people troop in they enter a place, often in a tired or unwilling way","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If there is a forceful flowing inward or coming in, you can say there is an influx . Every fall, the college town sees an influx of students and the population jumps 30 percent."}]},"collocations":{"phrases":["ADJ. great, huge, large, massive, vast | small | new | sudden | continuing | steady | daily the daily influx of sightseers to the city","VERB + INFLUX have, receive The hotel has received a large influx of guests. | prevent The country sealed its borders to prevent the influx ","PREP. ~ into/to a massive influx of foreign tourists into London"]},"media":{"uk":"media/ldoce/hwd/bre/9/influx0205.mp3","us":"media/ldoce/hwd/ame/e/influx.mp3"},"examples":[{"en":"the influx of wealth into the region","cn":"财富大量涌入这个地区"},{"en":"a massive/sudden influx of visitors","cn":"游客的大量/突然涌入"}],"oxford":{"phon":"ˈɪnflʌks","pos":"noun","senses":[{"en":"the fact of a lot of people, money or things arriving somewhere","cn":"（人、资金或事物的）涌入，流入","ex":{"en":"a massive/sudden influx of visitors","cn":"游客的大量／突然涌入"}}]}},"inventive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"善于发明的;有创造才能的","en":"An inventive person is good at inventing things or has clever and original ideas.","ex":{"en":"...Stroman's ceaselessly inventive choreography","cn":"斯特罗曼永远求新的舞蹈设计"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"good at using your imagination to think of new ideas or to produce new things","cn":""},{"en":"use this about someone who is very good at thinking of new and unusual ways of doing things","cn":""},{"en":"to have a lot of new ideas and to want to tell people all about them","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"To be inventive is to be creative. Inventive people are good at using their imaginations."}]},"collocations":{"phrases":["VERBS be","ADV. brilliantly, highly, very | quite"]},"media":{"uk":"media/ldoce/hwd/bre/2/inventive0205.mp3","us":"media/ldoce/hwd/ame/4/inventive.mp3"},"examples":[{"en":"She has a highly inventive mind.","cn":"她的头脑非常善于创新。"},{"en":"one of the most talented and inventive drummers in modern music","cn":"现代音乐界最有才华﹑最有创造力的鼓手之一"}],"oxford":{"phon":"ɪnˈventɪv","pos":"adjective","senses":[{"en":"able to think of new and interesting ideas","cn":"善于创新的；有创意的","ex":{"en":"She has a highly inventive mind.","cn":"她的头脑非常善于创新。"}},{"en":"new and interesting","cn":"有新意的；有创意的","ex":{"en":"This is a courageous and inventive piece of film-making.","cn":"这部电影的拍摄手法大胆创新。"}}]}},"inhibit":{"collins":{"senses":[{"pos":"VERB 动词","cn":"抑制;约束","en":"If something inhibits an event or process, it prevents it or slows it down.","ex":{"en":"Wine or sugary drinks inhibit digestion","cn":"葡萄酒或含糖饮料抑制消化。"}},{"pos":"VERB 动词","cn":"禁止;阻止","en":"To inhibit someone from doing something means to prevent them from doing it, although they want to do it or should be able to do it.","ex":{"en":"It could inhibit the poor from getting the medical care they need","cn":"那会使穷人得不到他们所需要的医疗保健。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to prevent something from growing or developing well","cn":"阻止﹐阻碍﹐抑制"},{"en":"to make someone feel embarrassed or nervous so that they cannot do or say what they want to","cn":"使羞于﹐使怯于"}]},"vocab":{"pos":"v","senses":[{"en":"When you inhibit something, you block it or hold it back. If you put plants in a dark room, you inhibit their growth. A teacher who mocks their students for giving wrong answers inhibits their willingness to speak up in class."}]},"collocations":{"phrases":["ADV. seriously, severely, significantly Alcohol significantly inhibits the action of the drug. | completely | slightly","VERB + INHIBIT tend to A large service sector and a small manufacturing sector would tend to inhibit growth in the economy.","PREP. from The fear of dismissal inhibited employees from raising problems."]},"media":{"uk":"media/ldoce/hwd/bre/7/inhibit0205.mp3","us":"media/ldoce/hwd/ame/9/inhibit.mp3"},"examples":[{"en":"The managing director's presence inhibited them from airing their problems.","cn":"总经理的在场使他们不便畅谈他们的问题。"},{"en":"A lack of oxygen may inhibit brain development in the unborn child.","cn":"缺氧可能阻碍胎儿的大脑发育。"}],"oxford":{"phon":"ɪnˈhɪbɪt","pos":"verb","senses":[{"en":"to prevent something from happening or make it happen more slowly or less frequently than normal","cn":"阻止；阻碍；抑制","lab":"formal","ex":{"en":"A lack of oxygen may inhibit brain development in the unborn child.","cn":"缺氧可能阻碍胎儿的大脑发育。"}},{"en":"to make somebody nervous or embarrassed so that they are unable to do something","cn":"使拘束；使尴尬","ex":{"en":"The managing director's presence inhibited them from airing their problems.","cn":"总经理的在场使他们不便畅谈他们的问题。"}}]}},"incompetence":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"无能力;不称职;不合格","en":"If you refer to someone's incompetence, you are criticizing them because they are unable to do their job or a task properly.","ex":{"en":"The incompetence of government officials is appalling.","cn":"政府官员的无能令人震惊。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"lack of the ability or skill to do a job properly","cn":"不胜任﹐不称职"},{"en":"OPP competence managerial/professional etc incompetence allegations of professional incompetence","cn":"对专业方面不称职的指责 The report blamed police incompetence for the tragedy. 报道指责警方的无能导致了这场悲剧。"}]},"vocab":{"pos":"n","senses":[{"en":"Can't finish a simple task? Having a hard time figuring something out? Lack the ability to get things done? Then you might be suffering from incompetence ."}]},"collocations":{"phrases":["ADJ. gross, monumental | sheer | alleged | economic, professional, technical | government, managerial, police","VERB + INCOMPETENCE display He displayed his incompetence by turning in a report that was full of errors. | tolerate I will not tolerate you","PREP. ~ at/in incompetence in writing | ~ on the part of Several officers had alleged incompetence on the part of the general."]},"media":{"uk":"media/ldoce/hwd/bre/4/incompetence0205.mp3","us":"media/ldoce/hwd/ame/0/incompetence.mp3"},"examples":[{"en":"He was dismissed for incompetence.","cn":"他因不称职而被解雇。"},{"en":"professional incompetence","cn":"专业方面不称职"}],"oxford":{"phon":"ɪnˈkɒmpɪtəns","pos":"noun","senses":[{"en":"the lack of skill or ability to do your job or a task as it should be done","cn":"无能力；不胜任；不称职","ex":{"en":"professional incompetence","cn":"专业方面不称职"}}]}},"interpretation":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"解释;说明;阐明","en":"An interpretation of something is an opinion about what it means.","ex":{"en":"The opposition Conservative Party put a different interpretation on the figures","cn":"反对党保守党对这些数字提出一番不同的解释。"}},{"pos":"N-COUNT 可数名词","cn":"表演;演绎;演奏","en":"A performer's interpretation of something such as a piece of music or a role in a play is the particular way in which they choose to perform it.","ex":{"en":"...her full-bodied interpretation of the role of Micaela.","cn":"她对米凯拉这个角色全身心的演绎"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone's opinion about the probable meaning of a statement, result, someone's actions etc","cn":""},{"en":"someone's opinion about the meaning of a piece of writing or an action, used especially when they realize that there are other possible meanings","cn":""},{"en":"someone's opinion about the meaning of a statement, an event, or a situation after considering all the available information","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When your favorite band covers a classic tune, their version is there interpretation — their translation — of the music. Is it better than the original? That's up for interpretation ."}]},"collocations":{"phrases":["ADJ. correct, right, true, valid | erroneous, false, wrong | plausible, reasonable | simplistic | literal, narrow, strict | free, generous, ","VERB + INTERPRETATION give sth, make In practice, this law is often given a wide interpretation by the police. Scientists made an interpreta","PHRASES put an interpretation on sth It is possible to put an entirely different interpretation on her behaviour."]},"media":{"uk":"media/ldoce/hwd/bre/f/interpretation0205.mp3","us":"media/ldoce/hwd/ame/f/interpretation.mp3"},"examples":[{"en":"Her evidence suggests a different interpretation of the events.","cn":"她的证据显示这些事件可能有另外一种解释。"},{"en":"It is not possible for everyone to put their own interpretation on the law.","cn":"不可能让每个人自行阐释法律。"}],"oxford":{"phon":"ɪnˌtɜːprəˈteɪʃn","pos":"noun","senses":[{"en":"the particular way in which something is understood or explained","cn":"理解；解释；说明","ex":{"en":"Her evidence suggests a different interpretation of the events.","cn":"她的证据显示这些事件可能有另外一种解释。"}},{"en":"the particular way in which somebody chooses to perform a piece of music, a role in a play, etc.","cn":"演绎；演奏方式；表演方式","ex":{"en":"a modern interpretation of ‘King Lear’","cn":"《李尔王》的现代演绎"}}]}},"inquiringly":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an inquiring look or expression shows that you want to ask about something","cn":""},{"en":"someone who has an inquiring mind is very interested in finding out more about everything","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdeinquiring.mp3","us":"media/ldoce/hwd/ame/4/inquiring.mp3"},"examples":[{"en":"She raised an inquiring eyebrow towards Murray.","cn":""},{"en":"As a child, he had a lively inquiring mind.","cn":""}],"oxford":{"phon":"ɪnˈkwaɪərɪŋli","pos":"adverb","senses":[{"en":"in a way that asks for information","cn":"询问地：以询问信息的方式","ex":{"en":"She looked at him inquiringly.","cn":"她询问地看着他。"}}]}},"inch":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"英寸(约等于 2.54 厘米)","en":"An inch is an imperial unit of length, approximately equal to 2.54 centimetres. There are twelve inches in a foot.","ex":{"en":"...a candy tin 6 inches high and 8 inches in diameter.","cn":"高 6 英寸、直径 8 英寸的糖果罐子"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)缓慢移动","en":"To inch somewhere or to inch something somewhere means to move there very slowly and carefully, or to make something do this.","ex":{"en":"...a climber inching up a vertical wall of rock","cn":"沿一面陡直石壁慢慢往上爬的人"}},{"pos":"PHRASE 短语","cn":"(某个地方的)全部，每一寸地方","en":"If you talk about every inch of an area, you are emphasizing that you mean the whole of it.","ex":{"en":"Every inch of shelf space was crammed with books","cn":"书架上全都塞满了书。"}},{"pos":"PHRASE 短语","cn":"在各方面;完全;彻底","en":"If you say that someone looks every inch a certain type of person, you are emphasizing that they look exactly like that kind of person.","ex":{"en":"He looks every inch the City businessman","cn":"他完全是一副伦敦金融城商界人士的派头。"}},{"pos":"PHRASE 短语","cn":"一点一点地;缓慢地","en":"If someone or something moves inch by inch, they move very slowly and carefully.","ex":{"en":"The car moved forward inch by inch","cn":"汽车一点一点地向前移动。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to almost do something or almost be in a particular state","cn":""},{"en":"to very nearly do something, especially something dangerous or unpleasant","cn":""},{"en":"to avoid something unpleasant or dangerous, although you almost do not avoid it","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/inch_n0205.mp3","us":"media/ldoce/hwd/ame/8/inch1.mp3"},"examples":[{"en":"In his first game the young player already looked every inch a winner.","cn":"那位年轻的选手在第一场比赛就已经被认为胜券在握。"},{"en":"( figurative ) If they try to fire me I'll fight them every inch of the way.","cn":"他们要是想解雇我，我就和他们抗争到底。"}],"oxford":{"phon":"ɪntʃ","pos":"noun","senses":[{"en":"a unit for measuring length or height, equal to 2.54 centimetres. There are 12 inches in a foot.","cn":"英寸（长度单位，等于 2.54 厘米，1 英尺等于 12 英寸）","ex":{"en":"She's a few inches taller than me.","cn":"她比我高几英寸。"}},{"en":"a small amount or distance","cn":"少量；短距离","ex":{"en":"He escaped death by an inch.","cn":"他差点儿丧了命。"}},{"en":"to move or make something move slowly and carefully in a particular direction","cn":"（使朝某方向）谨慎移动","ex":{"en":"She moved forward, inching towards the rope.","cn":"她小心翼翼地慢慢向绳子挪过去。"},"pos":"verb"}]}},"inspiring":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"鼓舞人心的;有激励作用的","en":"Something or someone that is inspiring is exciting and makes you feel strongly interested and enthusiastic...","ex":{"en":"She was one of the most inspiring people I've ever met","cn":"她是我曾见过的最能鼓舞人心的人之一。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"giving people a feeling of excitement and a desire to do something great","cn":"鼓舞人心的﹔启发灵感的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you find something inspiring , it is stimulating your spirit and making you feel hopeful and ready to do something. Do you find documentaries about overcoming struggle inspiring , or is a sale at the mall more inspiring to you?"}]},"collocations":{"phrases":["VERBS be, seem None of the leaders seems very inspiring. | find sth/sb People find her inspiring.","ADV. deeply, really, very a very inspiring sight | far from, hardly, less than, not particularly A pile of ironing is hardly inspiring."]},"media":{"uk":"media/ldoce/hwd/bre/8/inspiring0205.mp3","us":"media/ldoce/hwd/ame/8/inspiring.mp3"},"examples":[{"en":"( informal ) The book is less than inspiring.","cn":"那本书不大吸引人。"},{"en":"The book is less than inspiring.","cn":""}],"oxford":{"phon":"ɪnˈspaɪərɪŋ","pos":"adjective","senses":[{"en":"exciting and encouraging you to do or feel something","cn":"鼓舞人心的；激励的；启发灵感的","lab":"informal","ex":{"en":"an inspiring teacher","cn":"启发能力强的教师"}}]}},"instructor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"教练;指导者;(美国英语亦指)教师，大学讲师","en":"An instructor is someone who teaches a skill such as driving or skiing. In American English, instructor can also be used to refer to a schoolteacher or to a university teacher of low rank.","ex":{"en":"...tuition from an approved driving instructor.","cn":"有正式资格的驾驶教练的指导"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who teaches as their job, especially in a school","cn":""},{"en":"the teacher who is in charge of a school or college","cn":""},{"en":"someone who gives private lessons to one student or a small group of students. In Britain, a tutor is also a teacher in a university","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An instructor is a teacher. One can be an instructor of just about anything, but it usually applies to teaching hands-on skills, like a water-skiing instructor or the instructor of the knitting class held at the community center."}]},"collocations":{"phrases":["ADJ. qualified, trained | experienced | chief, senior | driving, flying, parachute, riding, ski, swimming, etc.","INSTRUCTOR + VERB teach sb/sth • Note at JOB"]},"media":{"uk":"media/ldoce/hwd/bre/4/instructor0205.mp3","us":"media/ldoce/hwd/ame/4/instructor.mp3"},"examples":[{"en":"a driving instructor","cn":"驾驶教练"},{"en":"ski instructors","cn":"滑雪教练"}],"oxford":{"phon":"ɪnˈstrʌktə(r)","pos":"noun","senses":[{"en":"a person whose job is to teach somebody a practical skill or sport","cn":"教练；导师","ex":{"en":"a fitness/driving/ski instructor","cn":"健身／驾驶／滑雪教练"}},{"en":"a teacher below the rank of assistant professor at a college or university","cn":"（大学）讲师","lab":"North American English"}]}},"ineligible":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无资格的;不合格的","en":"If you are ineligible for something, you are not qualified for it or entitled to it.","ex":{"en":"...a ruling that he would be ineligible for any social security benefits","cn":"他无资格申领任何社会保险福利的裁定"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"use this when a law or rule does not allow someone to do something","cn":""},{"en":"to be unable to do something because your job does not give you the authority or right to do it","cn":""},{"en":"to be unable to do something because you do not have the authority or the moral right to do it","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"To be ineligible is to not qualify for something."}]},"collocations":{"phrases":["VERBS be | become | make sb/sth | consider sb/sth, declare sb/sth, deem sb/sth The country had been declared ineligible for World Bank lendi","PREP. for The new rules have made thousands more people ineligible for legal aid."]},"media":{"uk":"media/ldoce/hwd/bre/f/ineligible0205.mp3","us":"media/ldoce/hwd/ame/0/ineligible.mp3"},"examples":[{"en":"ineligible for financial assistance","cn":"无资格得到财政援助"},{"en":"ineligible to vote","cn":"无投票资格"}],"oxford":{"phon":"ɪnˈelɪdʒəbl","pos":"adjective","senses":[{"en":"not having the necessary qualifications to have or to do something","cn":"不合格的；不符合资格的","ex":{"en":"ineligible for financial assistance","cn":"无资格得到财政援助"}}]}},"innocuous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无害的;无冒犯之意的","en":"Something that is innocuous is not at all harmful or offensive.","ex":{"en":"Both mushrooms look innocuous but are in fact deadly","cn":"这两种蘑菇看起来似乎都无害,实际上却是致命的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not harmful - use this especially when people have said or believe that something or someone is harmful","cn":""},{"en":"if an action, activity, experience etc does no harm , it does not harm someone or something and may even help","cn":""},{"en":"used especially about products in shops, meaning that they do not harm the environment etc","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that's innocuous isn't harmful or likely to cause injury. Public figures like mayors and governors have to expect they'll get critical or even hurtful emails and phone calls, as well as more innocuous feedback."}]},"collocations":{"phrases":["VERBS appear, be, look, seem","ADV. perfectly, totally, wholly His comment seemed perfectly innocuous. | fairly, pretty, quite, relatively The liquid looked fairly innocuo"]},"media":{"uk":"media/ldoce/hwd/bre/3/innocuous0205.mp3","us":"media/ldoce/hwd/ame/d/innocuous.mp3"},"examples":[{"en":"It seemed a perfectly innocuous remark.","cn":"那像是一句毫无恶意的话。"},{"en":"an innocuous substance","cn":"无害物质"}],"oxford":{"phon":"ɪˈnɒkjuəs","pos":"adjective","senses":[{"en":"not intended or likely to offend or upset anyone","cn":"无恶意的；无意冒犯的","ex":{"en":"It seemed a perfectly innocuous remark.","cn":"那像是一句毫无恶意的话。"}},{"en":"not harmful or dangerous","cn":"无害的；无危险的","ex":{"en":"an innocuous substance","cn":"无害物质"}}]}},"indicative":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"指示的;象征的;暗示的","en":"If one thing is indicative of another, it suggests what the other thing is likely to be.","ex":{"en":"The result was indicative of a strong retail market","cn":"结果表明零售业市场繁荣。"}},{"pos":"N-SING 单数名词","cn":"陈述语气","en":"In grammar, a clause that is in the indicative, or in the indicative mood, has a subject followed by a verb group. Examples are 'I'm hungry' and 'She was followed'. Clauses of this kind are typically used to make statements."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to show that something is probably true, even though there is no definite proof","cn":""},{"en":"if scientific facts, tests, official figures etc indicate something, they show that it is likely to be true","cn":""},{"en":"to make people think that a particular situation exists, even though this may not actually be true","cn":""}]},"vocab":{"pos":"1 adj 2 adj n","senses":[{"en":"Use the word indicative when you want to show that something is suggestive or serves as a sign of something. Your willingness to help out with the charity is indicative of your generous nature."}]},"collocations":{"phrases":["VERBS be | consider sth, interpret sth as, regard sth as, see sth as, take sth as The rise in unemployment is seen as indicative of a new ec","ADV. clearly | (not) necessarily Recurrent dreams are not necessarily indicative of psychological problems.","PREP. of"]},"media":{"uk":"media/ldoce/hwd/bre/c/indicative_n0205.mp3","us":"media/ldoce/hwd/ame/6/indicative1.mp3"},"examples":[{"en":"In ‘Ben likes school’, the verb ‘like’ is in the indicative.","cn":"在 Ben likes school 中，动词 like 是陈述语气。"},{"en":"Their failure to act is indicative of their lack of interest.","cn":"他们未采取行动，这表示他们没有兴趣。"}],"oxford":{"phon":"ɪnˈdɪkətɪv","pos":"adjective","senses":[{"en":"showing or suggesting something","cn":"表明；标示；显示；暗示","g":"[not usually before noun]","lab":"formal","ex":{"en":"Their failure to act is indicative of their lack of interest.","cn":"他们未采取行动，这表示他们没有兴趣。"}},{"en":"stating a fact","cn":"陈述的；指示的","g":"[only before noun]","lab":"grammar"},{"en":"the form of a verb that states a fact","cn":"（动词形式）陈述语气","ex":{"en":"In ‘Ben likes school’, the verb ‘like’ is in the indicative.","cn":"在 Ben likes school 中，动词 like 是陈述语气。"},"pos":"noun"}]}},"infrequent":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不频发的;很少发生的;罕见的","en":"If something is infrequent, it does not happen often.","ex":{"en":"...John's infrequent visits to London.","cn":"约翰仅有的几次伦敦之行"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not existing in large numbers or in large amounts","cn":""},{"en":"not available in large enough numbers or amounts at a particular time – used especially about things people need","cn":""},{"en":"fairly rare","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that's infrequent doesn't happen very often. Your family might take infrequent trips to Disney World, traveling there every two or three years."}]},"collocations":{"phrases":["VERBS be | become","ADV. very | comparatively, fairly, rather, relatively Disturbances are relatively infrequent in British prisons."]},"media":{"uk":"media/ldoce/hwd/bre/c/infrequent0205.mp3","us":"media/ldoce/hwd/ame/8/infrequent.mp3"},"examples":[{"en":"Muggings are relatively infrequent in this area.","cn":"在这个地区行凶抢劫事件相对少见。"},{"en":"This happens not infrequently (= often).","cn":"这种事常常发生。"}],"oxford":{"phon":"ɪnˈfriːkwənt","pos":"adjective","senses":[{"en":"not happening often","cn":"不常发生的；罕见的","ex":{"en":"her infrequent visits home","cn":"她少有的探望家人"}}]}},"ingrained":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"根深蒂固的;难以根除的","en":"Ingrained habits and beliefs are difficult to change or remove.","ex":{"en":"Morals tend to be deeply ingrained","cn":"道德观念往往根深蒂固。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"ingrained attitudes or behaviour are firmly established and therefore difficult to change 〔","cn":"态度或行为〕根深蒂固的﹐难以改变的"},{"en":"ingrained dirt is under the surface of something and very difficult to remove 〔","cn":"污物〕嵌入而难以清除的"}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective ingrained to describe the strong beliefs of someone who has thought that way for a very long time, such as the ingrained patriotism of a 20-year military veteran."}]},"collocations":{"phrases":["VERBS be | become | remain","ADV. deeply Prejudice remains deeply ingrained in many organizations.","PREP. in"]},"media":{"uk":"media/ldoce/hwd/bre/3/ingrained0205.mp3","us":"media/ldoce/hwd/ame/4/ingrained.mp3"},"examples":[{"en":"ingrained prejudices","cn":"很深的成见"},{"en":"The idea of doing our duty is deeply ingrained in most people.","cn":"恪尽职守这一信念在大多数人的心里根深蒂固。"}],"oxford":{"phon":"ɪnˈɡreɪnd","pos":"adjective","senses":[{"en":"that has existed for a long time and is therefore difficult to change","cn":"根深蒂固的；日久难改的","ex":{"en":"ingrained prejudices","cn":"很深的成见"}},{"en":"under the surface of something and therefore difficult to get rid of","cn":"深嵌并难以清除的"}]}},"india":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a large country in southern Asia. Population: 1,220,800,359 (2014). Capital: New Delhi. India was ruled by the British from 1757 until 1947, and is now the largest democracy in the world. The official languages are Hindi and English, and most people belong to ","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/p028-000006411.mp3","us":"media/ldoce/hwd/ame/6/p028-000006411.mp3"},"oxford":{"phon":"ˈɪndiə","pos":"","senses":[{"en":"a country in South Asia which used to be part of the British Empire. It became independent and a member of the Commonwealth in 1947.","cn":"印度（南亚国家）"}]}},"inventory":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"详细目录;清单","en":"An inventory is a written list of all the objects in a particular place.","ex":{"en":"Before starting, he made an inventory of everything that was to stay.","cn":"开始之前,他把所有要留下的东西列了详细的清单。"}},{"pos":"N-VAR 可变名词","cn":"储备;存货","en":"An inventory is a supply or stock of something.","ex":{"en":"...one inventory of twelve sails for each yacht.","cn":"每艘快艇 12 张帆的储备"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a set of names, places, jobs you need to do etc, which are written one below the other","cn":""},{"en":"a list of things you need or things you have to do which you keep in order to help you remember them","cn":""},{"en":"a list of the most suitable people for a job or prize, chosen from a larger group of people","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"An inventory is an itemized list of everything you have. So you better take inventory of what’s in the fridge before going grocery shopping. Otherwise you'll end up with more jars of mustard that you don't need."}]},"collocations":{"phrases":["ADJ. complete, comprehensive, detailed, full","VERB + INVENTORY compile, draw up, make, produce, take The manager is compiling an inventory of all the hotel furniture. | list sth on","INVENTORY + VERB list sth The inventory lists many rare items.","PREP. in an/the ~ There were no forks in the inventory. | on an/the ~ That lamp isn't listed on the inventory."]},"media":{"uk":"media/ldoce/hwd/bre/9/inventory0205.mp3","us":"media/ldoce/hwd/ame/3/inventory.mp3"},"examples":[{"en":"The inventory will be disposed of over the next twelve weeks.","cn":"在未来的十二个星期中将进行清仓处理。"},{"en":"I've inventoried my father's collection of prints.","cn":"我把父亲收藏的图片列成了清单。"}],"oxford":{"phon":"ˈɪnvəntri","pos":"noun","senses":[{"en":"a written list of all the objects, furniture, etc. in a particular building","cn":"（建筑物里的物品、家具等的）清单；财产清单","g":"[countable]","ex":{"en":"an inventory of the museum’s contents","cn":"博物馆馆藏清单"}},{"en":"all the goods in a store","cn":"（商店的）存货，库存","g":"[uncountable]","lab":"North American English","ex":{"en":"The inventory will be disposed of over the next twelve weeks.","cn":"在未来的十二个星期将进行库存清仓。"}},{"en":"all of the stock of a business, including materials, components, work in progress and finished products","cn":"(会计中)企业的所有存货，包括材料、组件、在制品和成品","ex":{"en":"Business inventories rose 0.7% in October.","cn":"10 月份商业库存增长 0.7%。"}},{"en":"to make a complete list of something; to include something in a list","cn":"开列清单；把…列入清单","ex":{"en":"I've inventoried my father's collection of prints.","cn":"我把父亲收藏的版画列成了清单。"},"pos":"verb"}]}},"indebted":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"感激的;感恩的","en":"If you say that you are indebted to someone for something, you mean that you are very grateful to them for something.","ex":{"en":"I am deeply indebted to him for his help.","cn":"我非常感激他对我的帮助。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"负债的","en":"Indebted countries, organizations, or people are ones that owe money to other countries, organizations, or people.","ex":{"en":"America's treasury secretary identified the most heavily indebted countries.","cn":"美国财政部长指出了负债最多的那些国家。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to be very grateful to someone for the help they have given you","cn":"对某人（十分）感激"},{"en":"owing money to someone","cn":"负债的"}]},"vocab":{"pos":"adj","senses":[{"en":"When you’re indebted to someone, you owe that person something. It could be that you owe money, or it could be you’re just grateful for a nice thing the person did."}]},"collocations":{"phrases":["VERBS be, feel | remain","ADV. deeply, greatly, much, profoundly","PREP. to I am deeply indebted to all the doctors and nurses who treated me. 2 owing money to sb","VERBS be | remain","ADV. heavily, highly, severely The company is heavily indebted. highly indebted countries","PREP. to indebted to the bank"]},"media":{"uk":"media/ldoce/hwd/bre/5/indebted0205.mp3","us":"media/ldoce/hwd/ame/4/indebted.mp3"},"examples":[{"en":"I am deeply indebted to my family for all their help.","cn":"我深深感激我的家人给我所有的帮助。"},{"en":"a list of the fifteen most heavily indebted nations","cn":"十五个负债最重的国家的名单"}],"oxford":{"phon":"ɪnˈdetɪd","pos":"adjective","senses":[{"en":"grateful to somebody for helping you","cn":"感激的；蒙恩的","lab":"formal","ex":{"en":"I am deeply indebted to my family for all their help.","cn":"我深深感激我的家人给我的所有帮助。"}},{"en":"owing money to other countries or organizations","cn":"负债的","ex":{"en":"a list of the fifteen most heavily indebted nations","cn":"十五个负债最重的国家的名单"}}]}},"insist":{"collins":{"senses":[{"pos":"VERB 动词","cn":"坚持;坚决认为(或主张、要求)","en":"If you insist that something should be done, you say so very firmly and refuse to give in about it. If you insist on something, you say firmly that it must be done or provided.","ex":{"en":"My family insisted that I should not give in, but stay and fight","cn":"家里人坚持认为我不应让步,而应该留下来继续抗争。"}},{"pos":"VERB 动词","cn":"坚称;坚持说","en":"If you insist that something is the case, you say so very firmly and refuse to say otherwise, even though other people do not believe you.","ex":{"en":"The president insisted that he was acting out of compassion, not opportunism","cn":"总统坚持说他如此做是出于同情而不是为了投机。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say firmly that someone should do something or that something should happen","cn":"坚持主张﹐坚决要求"},{"en":"to say very strongly and sometimes angrily that you want something or that something must happen （","cn":"坚决）要求"},{"en":"if you are required to do something, a rule or law says that you must do it 〔","cn":"法规〕要求﹐规定"}]},"vocab":{"pos":"v","senses":[{"en":"To insist on something is to demand or swear to it. You can insist that you didn't eat the last piece of cake, and then insist that your brother show your mom the bits of frosting on his fingers."}]},"collocations":{"phrases":["ADV. firmly, strongly | stubbornly He stubbornly insisted on doing it all himself. | absolutely I'm paying for this?no, I absolutely insist.","VERB + INSIST continue to | try to | be entitled to Employers are entitled to insist that employees honour the terms of their agreement.","PREP. on/upon He insists on speaking to you personally"]},"media":{"uk":"media/ldoce/hwd/bre/1/insist0205.mp3","us":"media/ldoce/hwd/ame/0/insist.mp3"},"examples":[{"en":"‘Please come with us.’ ‘Very well then, if you insist. ’ “","cn":"请和我们一起来吧。” “好吧，你一定要我来，我就来。”"},{"en":"They insisted upon being given every detail of the case.","cn":"他们坚持要求说明事情的整个来龙去脉。"}],"oxford":{"phon":"ɪnˈsɪst","pos":"verb","senses":[{"en":"to demand that something happen or that somebody agree to do something","cn":"坚决要求；坚持","g":"[intransitive, transitive]","lab":"formal","ex":{"en":"I didn't really want to go but he insisted.","cn":"我不大想去，但他硬要我去。"}},{"en":"to state clearly that something is true, especially when other people do not believe you","cn":"坚持说；固执己见","g":"[intransitive, transitive]","ex":{"en":"He insisted on his innocence.","cn":"他坚持说他是无辜的。"}}]}},"informed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有知识的;了解情况的;见多识广的","en":"Someone who is informed knows about a subject or what is happening in the world.","ex":{"en":"Informed people know the company is shaky.","cn":"了解情况的人知道该公司状况不佳。"}},{"pos":"ADJ 形容词","cn":"(消息来源)可靠的，有根据的","en":"When journalists talk about informed sources, they mean people who are likely to give correct information because of their private or special knowledge.","ex":{"en":"According to informed sources, those taken into custody include at least one major-general.","cn":"据可靠消息,那些被拘捕者当中至少有一位少将。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(猜测或决策)明智的,有见识的","en":"An informed guess or decision is one that likely to be good, because it is based on definite knowledge or information.","ex":{"en":"An informed guess at his personal wealth was $1.25 billion","cn":"据合理猜测，他的个人财产有 12.5 亿美元。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to give someone regular information about decisions, events etc, so that they know exactly what is happening","cn":""},{"en":"to give someone regular information about what has been happening most recently","cn":""},{"en":"to tell someone about things that have happened recently, which they do not know about because they have not talked to you for quite a long time or they have been somewhere else","cn":""}]},"collocations":{"phrases":["VERBS be | keep | keep sb","ADV. closely, well The kids are much better informed than I was at their age. | fully, properly Consumers must be fully informed of the serv","PREP. about They were poorly informed about their rights. | of We will keep you informed of any developments. | on Keep me informed on progr"]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdeinformed.mp3","us":"media/ldoce/hwd/ame/7/informed.mp3"},"examples":[{"en":"They are not fully informed about the changes.","cn":"他们不完全了解这些改变。"},{"en":"Keep me informed of any developments.","cn":"随时通知我进展情况。"}],"oxford":{"phon":"ɪnˈfɔːmd","pos":"adjective","senses":[{"en":"having or showing a lot of knowledge about a particular subject or situation","cn":"有学问的；有见识的","ex":{"en":"an informed critic","cn":"有见地的批评家"}},{"en":"based on an understanding of the facts of a situation","cn":"了解清楚情况后作出的","ex":{"en":"an informed choice/decision/opinion","cn":"知情的选择／决定／看法"}}]}},"intrusive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"打扰的;侵扰的","en":"Something that is intrusive disturbs your mood or your life in a way you do not like.","ex":{"en":"The cameras were not an intrusive presence","cn":"那些摄像机的存在并不令人反感。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"affecting someone’s private life or interrupting them in an unwanted and annoying way","cn":"干涉的﹔打扰的"}]},"vocab":{"pos":"1 adj 2 adj 3 adj","senses":[{"en":"Something intrusive is getting in your face or invading your space. Nosey questions, a poke in the ribs, and a hovering mother are all intrusive ."}]},"collocations":{"phrases":["VERBS be, prove, seem | become | find sth","ADV. extremely, very | increasingly | rather, somewhat | visually Planning permission was refused on the grounds that the proposed building "]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41intrusive.mp3","us":"media/ldoce/hwd/ame/8/intrusive.mp3"},"examples":[{"en":"The constant presence of the media was very intrusive.","cn":"媒体一直在场十分令人讨厌。"},{"en":"intrusive questions","cn":"唐突的问题"}],"oxford":{"phon":"ɪnˈtruːsɪv","pos":"adjective","senses":[{"en":"too direct, easy to notice, etc. in a way that is annoying or upsetting","cn":"侵入的；闯入的；侵扰的；烦扰的","ex":{"en":"intrusive questions","cn":"唐突的问题"}},{"en":"produced in order to link two words together when speaking, for example the /r/ sound produced at the end of law by some English speakers in the phrase ‘law and order’. Some people do not consider intrusive ‘r’ a feature of standard English.","cn":"添加的；插入的","lab":"phonetics"}]}},"inflamed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"发炎的;变红肿的","en":"If part of your body is inflamed, it is red or swollen, usually as a result of an infection, injury, or illness.","ex":{"en":"Symptoms include red, itchy and inflamed skin","cn":"症状包括皮肤发红、发痒、发炎。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a part of your body that is inflamed is red and swollen, because it is injured or infected 〔","cn":"身体部位〕红肿的﹐发炎的"}]},"collocations":{"phrases":["VERBS be | become, get","ADV. highly, severely, very Her joints are severely inflamed. | further | acutely | chronically"]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdeinflamed.mp3","us":"media/ldoce/hwd/ame/5/inflamed.mp3"},"examples":[{"en":"an inflamed eye","cn":"发炎红肿的眼睛"}],"oxford":{"phon":"ɪnˈfleɪmd","pos":"adjective","senses":[{"en":"red, painful and hot because of infection or injury","cn":"发炎的；红肿的","ex":{"en":"an inflamed and swollen finger","cn":"手指发炎肿胀"}},{"en":"very angry or excited","cn":"愤怒的；非常激动的","ex":{"en":"an inflamed crowd","cn":"愤怒的人群"}}]}},"inference":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"推断结果;结论","en":"An inference is a conclusion that you draw about something by using information that you already have about it.","ex":{"en":"There were two inferences to be drawn from her letter.","cn":"由她的信可以得出两个结论。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"推论;推理;推断","en":"Inference is the act of drawing conclusions about something on the basis of information that you already have.","ex":{"en":"It had an extremely tiny head and, by inference, a tiny brain.","cn":"它的头极小，由此推断其脑容量也非常小。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that you think is true, based on information that you have","cn":"推论﹐推断的结果"},{"en":"when someone infers something","cn":"推理﹐推断"}]},"vocab":{"pos":"n","senses":[{"en":"An inference is an idea or conclusion that's drawn from evidence and reasoning. An inference is an educated guess."}]},"collocations":{"phrases":["ADJ. fair, logical, reasonable | obvious","VERB + INFERENCE draw, make","INFERENCE + VERB be based on sth inferences based on their answers to a number of set questions","PREP. ~ about In the absence of detailed documentary evidence, we can only make inferences about Minoan religion. | ~ from The value of data"]},"media":{"uk":"media/ldoce/hwd/bre/4/inference0205.mp3","us":"media/ldoce/hwd/ame/3/inference.mp3"},"examples":[{"en":"If he is guilty then, by inference, so is his wife (= it is logical to think so, from the same evidence).","cn":"如果他有罪，那么由此可以推断他的妻子也同样有罪。"},{"en":"The clear inference is that the universe is expanding.","cn":"显然结论是宇宙在扩大。"}],"oxford":{"phon":"ˈɪnfərəns","pos":"noun","senses":[{"en":"something that you can find out indirectly from what you already know","cn":"推断的结果；结论","g":"[countable]","ex":{"en":"to draw/make inferences from the data","cn":"根据资料推论出结果"}},{"en":"the act or process of forming an opinion, based on what you already know","cn":"推断；推理；推论","g":"[uncountable]","ex":{"en":"He hid vital information from the press and, by inference, from the people (= it is logical to say so, from the same evidence).","cn":"他向媒体隐瞒了重要信息，并由此推断，向人民隐瞒了重要信息（根据相同的证据，这样说是合乎逻辑的）。"}}]}},"interim":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"暂时的;临时的;过渡期间的","en":"Interim is used to describe something that is intended to be used until something permanent is done or established.","ex":{"en":"She was sworn in as head of an interim government in March.","cn":"她3月份宣誓就任过渡政府首脑。"}},{"pos":"PHRASE 短语","cn":"在过渡期间;在间歇期","en":"In the interim means until a particular thing happens or until a particular thing happened.","ex":{"en":"But, in the interim, we obviously have a duty to maintain law and order","cn":"但是,在过渡期间,我们显然有责任维护治安。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"continuing, or intended to continue, for only a short time","cn":""},{"en":"a provisional arrangement is temporary and can be changed or replaced in the future","cn":""},{"en":"an interim report, measure, arrangement etc is one that is used temporarily until a final or complete one is ready","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"An interim is a period of time between one event and another, maybe the interim between the arrival of your party guests and the cleanup you have to do after they leave."}]},"collocations":{"phrases":["INTERIM + NOUN period The value of the property almost doubled during the interim period. | measure | agreement, arrangement | payment | awa","PREP. in the ~ Her job was done by her deputy in the interim before she returned to work.","PHRASES on an interim basis The company uses the agency when a vacancy needs to be filled on an interim basis."]},"media":{"uk":"media/ldoce/hwd/bre/6/interim_adj0205.mp3","us":"media/ldoce/hwd/ame/2/interim1.mp3"},"examples":[{"en":"Her new job does not start until May and she will continue in the old job in the interim.","cn":"她的新工作要到五月份才开始，在这期间她将继续原有的工作。"},{"en":"Despite everything that had happened in the interim, they had remained good friends.","cn":"不管在此间所发生的一切，他们还是好朋友。"}],"oxford":{"phon":"ˈɪntərɪm","pos":"adjective","senses":[{"en":"intended to last for only a short time until somebody/something more permanent is found","cn":"暂时的；过渡的","ex":{"en":"an interim government/measure/report","cn":"过渡政府；临时措施／报告"}},{"en":"calculated before the final results of something are known","cn":"期中的","lab":"finance","ex":{"en":"interim figures/profits/results","cn":"期中数字／利润／结果"}}]}},"increased":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to become larger in number, amount, or degree","cn":""},{"en":"to increase. Go up is less formal than increase , and is the usual verb to use in everyday English","cn":""},{"en":"to increase. Rise sounds a little formal and is often used when talking about the level of something increasing","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Anything described as increased has become bigger or more numerous. After an increased amount of rain, there could be flooding. A person riding a motorcycle without a helmet has an increased risk of bonking her head."}]},"media":{"uk":"media/ldoce/hwd/bre/b/increase_v0205.mp3","us":"media/ldoce/hwd/ame/7/l3increase.mp3"},"examples":[{"en":"increased demand","cn":"增加的需求"},{"en":"The population increased dramatically in the first half of the century.","cn":""}],"oxford":{"phon":"ɪnˈkriːst","pos":"adjective","senses":[{"en":"greater in amount, number, value, size, etc.","cn":"（使）增长，增多；增加","ex":{"en":"increased demand","cn":"增长的需求"}}]}},"intrigue":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"阴谋;诡计","en":"Intrigue is the making of secret plans to harm or deceive people.","ex":{"en":"...political intrigue.","cn":"政治阴谋"}},{"pos":"VERB 动词","cn":"(尤指奇怪的事物)迷住，激起…的好奇心","en":"If something, especially something strange, intrigues you, it interests you and you want to know more about it.","ex":{"en":"The novelty of the situation intrigued him.","cn":"周围环境的独具一格令他着迷。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something interests you, it makes you feel interested","cn":""},{"en":"to make someone interested in a subject or activity, especially by trying to make it seem attractive or enjoyable","cn":""},{"en":"if something fascinates you, it makes you very interested, so that you want to spend a lot of time thinking about it, watching it etc","cn":""}]},"vocab":{"pos":"1 n v 2 v","senses":[{"en":"An intrigue is a secret plot. If you ever become the monarch of a small island kingdom, keep watch for signs of any intrigue against you."}]},"collocations":{"phrases":["ADJ. international, political | court a tale of treachery and court intrigue","VERB + INTRIGUE carry on, engage in","PREP. ~ against The prime minister engaged in political intrigues against the king.","PHRASES a web of intrigue"]},"media":{"uk":"media/ldoce/hwd/bre/a/intrigue_v0205.mp3","us":"media/ldoce/hwd/ame/0/l3intrigue.mp3"},"examples":[{"en":"The young heroine steps into a web of intrigue in the academic world.","cn":"年轻的女主人公陷入了学术界钩心斗角的罗网。"},{"en":"I soon learnt about all the intrigues and scandals that went on in the little town.","cn":"我很快便知道了小镇上流传的种种阴谋与丑闻。"}],"oxford":{"phon":"ɪnˈtriːɡ","pos":"verb","senses":[{"en":"to make somebody very interested and want to know more about something","cn":"激起…的兴趣；引发…的好奇心","g":"[transitive]","ex":{"en":"The idea intrigued her.","cn":"这个想法引起了她的兴趣。"}},{"en":"to secretly plan with other people to harm somebody","cn":"秘密策划（加害他人）；密谋","g":"[intransitive]","lab":"formal"},{"en":"the activity of making secret plans in order to achieve an aim, often by tricking people","cn":"密谋策划；阴谋","g":"[uncountable]","ex":{"en":"political intrigue","cn":"政治阴谋"},"pos":"noun"},{"en":"a secret plan or relationship, especially one that involves somebody else being tricked","cn":"密谋；秘密关系；阴谋诡计","g":"[countable]","ex":{"en":"I soon learnt about all the intrigues and scandals that went on in the little town.","cn":"我很快便知道了小镇上流传的种种阴谋与丑闻。"},"pos":"noun"},{"en":"the atmosphere of interest and excitement that surrounds something secret or important","cn":"神秘气氛；引人入胜的复杂情节","g":"[uncountable]","ex":{"en":"North was a man who added to the intrigue of meetings.","cn":"诺斯是一个给会议增添趣味的人。"},"pos":"noun"}]}},"incense":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(常用于宗教仪式的)香","en":"Incense is a substance that is burned for its sweet smell, often as part of a religious ceremony."},{"pos":"VERB 动词","cn":"使愤怒;激怒","en":"If you say that something incenses you, you mean that it makes you extremely angry.","ex":{"en":"This proposal will incense conservation campaigners.","cn":"这项提议会激怒环保人士。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a substance that has a pleasant smell when you burn it 〔","cn":"燃烧时发出怡人香味的〕香"},{"en":"to make someone very angry","cn":"使非常愤怒"}]},"vocab":{"pos":"1 v 2 n v","senses":[{"en":"Incense means both \"to make angry\" and a stick that burns slowly and emits a strong smell. If your new college roommate burns incense in your tiny dorm room, you might get incensed and storm out."}]},"collocations":{"phrases":["ADJ. fragrant","VERB + INCENSE burn","INCENSE + NOUN stick | burner","PHRASES a scent/smell of incense"]},"media":{"uk":"media/ldoce/hwd/bre/6/incense_n0205.mp3","us":"media/ldoce/hwd/ame/2/l3incense.mp3"},"examples":[{"en":"The decision incensed the workforce.","cn":"这个决定激怒了劳工大众。"},{"en":"a church filled with the smell of incense","cn":"充满焚香气味的教堂"}],"oxford":{"phon":"ˈɪnsens","pos":"noun","senses":[{"en":"a substance that produces a pleasant smell when you burn it, used particularly in religious ceremonies","cn":"香（尤指宗教礼仪用的）","ex":{"en":"Incense burned in a corner of the room.","cn":"香在房间的一个角落里点着。"}},{"en":"to make somebody very angry","cn":"激怒；使大怒","ex":{"en":"The decision incensed the workforce.","cn":"这个决定激怒了全体员工。"},"pos":"verb"}]}},"interchangeable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"可交换的;可互换的;可交替的","en":"Things that are interchangeable can be exchanged with each other without it making any difference.","ex":{"en":"His greatest innovation was the use of interchangeable parts","cn":"他最大的革新在于使用了可互换的零件。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"things that are interchangeable can be used instead of each other","cn":"可以互换的"}]},"vocab":{"pos":"adj","senses":[{"en":"Things that are interchangeable can replace each other easily. Interchangeable objects or people can be substituted, and no one would know the difference."}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. fully, totally | almost, virtually","PREP. with These parts are fully interchangeable with those in other machines."]},"media":{"uk":"media/ldoce/hwd/bre/4/interchangeabl0205.mp3","us":"media/ldoce/hwd/ame/1/interchangeable.mp3"},"examples":[{"en":"The two words are virtually interchangeable (= have almost the same meaning).","cn":"这两个词大体上可以交换使用。"},{"en":"The V8 engines are all interchangeable with each other. * V8","cn":"型的发动机都可以相互替换。"}],"oxford":{"phon":"ˌɪntəˈtʃeɪndʒəbl","pos":"adjective","senses":[{"en":"that can be exchanged, especially without affecting the way in which something works","cn":"可交换的；可互换的；可交替的","ex":{"en":"The two words are virtually interchangeable (= have almost the same meaning).","cn":"这两个词大体上可以通用。"}}]}},"inconsistency":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(行为的)反复无常,易变","en":"If you refer to someone's inconsistency, you are criticizing them for not behaving in the same way every time a similar situation occurs.","ex":{"en":"His worst fault was his inconsistency","cn":"他最大的缺点就是反复无常。"}},{"pos":"N-VAR 可变名词","cn":"前后矛盾;不一致","en":"If there are inconsistencies in two statements, one cannot be true if the other is true.","ex":{"en":"We were asked to investigate the alleged inconsistencies in his evidence.","cn":"我们被要求对他证词中的前后矛盾之处进行调查。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when someone keeps changing their behaviour, reactions etc so that other people become confused 〔","cn":"行为﹑反应等的〕反复无常﹐变化不定"},{"en":"a situation in which two statements are different and cannot both be true 〔","cn":"两个说法的〕不一致﹐互相矛盾"}]},"vocab":{"pos":"n","senses":[{"en":"When there's inconsistency , things are not the same. An example of inconsistency in parenting might be when parents give different allowances to kids who are the same age."}]},"collocations":{"phrases":["ADJ. serious | glaring | apparent | internal Researchers have found that internal inconsistencies in hospital case notes are common. | logic","VERB + INCONSISTENCY contain | be filled with The script is filled with logical inconsistencies. | lead to, result in The lack of a clear se","INCONSISTENCY + VERB emerge | creep in, creep into sth Inconsistencies began to creep into his testimony.","PREP. ~ in inconsistencies in the evidence"]},"media":{"uk":"media/ldoce/hwd/bre/d/inconsistency0205.mp3","us":"media/ldoce/hwd/ame/4/laadinconsistency.mp3"},"examples":[{"en":"There is some inconsistency between the witnesses' evidence and their earlier statements.","cn":"证人的证词与他们先前的陈述有些出入。"},{"en":"I noticed a few minor inconsistencies in her argument.","cn":"我注意到她的论证中有几处小矛盾。"}],"oxford":{"phon":"ˌɪnkənˈsɪstənsi","pos":"noun","senses":[{"en":"if there is inconsistency between two statements, etc, they cannot both be true because they give the facts in a different way","cn":"不一致；相矛盾","g":"[uncountable, countable]","ex":{"en":"There is some inconsistency between the witnesses' evidence and their earlier statements.","cn":"证人的证词与他们先前的陈述有些出入。"}},{"en":"the fact of not matching a set of standards, ideas, etc.","cn":"不符合（某套标准、思想等）","g":"[countable, uncountable]","ex":{"en":"I noticed a few minor inconsistencies in her argument.","cn":"我注意到她的论证中有几处小矛盾。"}},{"en":"the fact of tending to change too often and not stay the same","cn":"反复无常的；没有常性的","g":"[uncountable]","lab":"disapproving","ex":{"en":"Farmed salmon avoids the inconsistency of ocean fish.","cn":"养殖三文鱼避免了海洋鱼的不一致。"}}]}},"interchange":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(思想、信息等的)交换，交流","en":"If there is an interchange of ideas or information among a group of people, each person talks about his or her ideas or gives information to the others.","ex":{"en":"What made the meeting exciting was the interchange of ideas from different disciplines","cn":"会议上令人兴奋的是来自不同学科的思想交流。"}},{"pos":"V-RECIP-ERG","cn":"把…(与…)交换位置;互换;交替","en":"If you interchange one thing with another, or you interchange two things, each thing takes the place of the other or is exchanged for the other. You can also say that two things interchange .","ex":{"en":"She likes to interchange her furnishings at home with the stock in her shop","cn":"她想要把家里的家具与店里的存货调换一下。"}},{"pos":"N-COUNT 可数名词","cn":"(公路或高速公路的)互通式立交桥，交换道","en":"An interchange on a motorway, freeway, or road is a place where it joins a main road or another motorway or freeway."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when you give something to someone and receive a similar thing from them at the same time","cn":""},{"en":"the useful exchange of ideas or information between people or organizations, especially when this happens continuously over a long period of time","cn":""},{"en":"when you give something to someone and receive a similar thing from them, usually someone you know","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/interchange_n0205.mp3","us":"media/ldoce/hwd/ame/5/l3interchange.mp3"},"examples":[{"en":"to interchange the front and rear tyres of a car","cn":"将汽车的前后轮胎对调"},{"en":"The front and rear tyres interchange (= can be exchanged).","cn":"前后轮胎可互换。"}],"oxford":{"phon":"ˈɪntətʃeɪndʒ","pos":"noun","senses":[{"en":"the act of sharing or exchanging something, especially ideas or information","cn":"（思想、信息等的）交换，互换","g":"[countable, uncountable]","ex":{"en":"a continuous interchange of ideas","cn":"持续的思想交流"}},{"en":"a place where a road joins a major road such as a motorway or interstate, designed so that vehicles leaving or joining the road do not have to cross other lines of traffic","cn":"（进出高速公路的）互通式立交，立体交叉道","g":"[countable]"},{"en":"to share or exchange ideas, information, etc.","cn":"交换，互换（思想、信息等）","g":"[transitive]","ex":{"en":"Data is interchanged between browser and server without any change in display.","cn":"数据在浏览器和服务器之间交换，显示没有任何变化。"},"pos":"verb"},{"en":"to put each of two things or people in the other’s place; to move or be moved from one place to another in this way","cn":"将…交换；（使）互换位置","g":"[transitive, intransitive]","ex":{"en":"to interchange the front and rear tyres of a car","cn":"将汽车的前后轮胎对调"},"pos":"verb"}]}}});
